// â”€â”€ buildAllowedDevOrigins - Tailscale/LAN HMR allowlist (Prompt 9J) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// > Lives next to next.config.ts so Next can import without @ path drama.
// > Hostnames only - no protocol, no port. Wildcard: `*.ts.net` per Next docs.

const DEFAULT_DEV_HOSTS = [
  "localhost",
  "127.0.0.1",
  "10.0.0.186",
  "100.111.32.31",
  "admin.sourc3code.dev",
  "*.ts.net",
] as const;

/**
 * Merge baked-in homelab defaults with `NEXT_ALLOWED_DEV_ORIGINS` (comma-separated).
 */
export function buildAllowedDevOrigins(
  env: Record<string, string | undefined> = process.env,
): string[] {
  const raw = env.NEXT_ALLOWED_DEV_ORIGINS?.trim();
  const extra = raw
    ? raw
        .split(",")
        .map((s) => s.trim())
        .filter(Boolean)
    : [];
  return [...new Set([...DEFAULT_DEV_HOSTS, ...extra])];
}

import { NextResponse } from "next/server";
import type { NextRequest } from "next/server";

export function middleware(_request: NextRequest) {
  void _request;
  // Passthrough for now - auth, rate limiting, homelab headers go here later
  return NextResponse.next();
}

export const config = {
  matcher: [
    "/api/spirit",
    "/api/spirit/:path*",
    "/api/oracle",
    "/api/oracle/:path*",
    "/api/admin",
    "/api/admin/:path*",
    "/studio",
    "/studio/:path*",
  ],
};

import type { NextConfig } from "next";
import { realpathSync } from "node:fs";

import { buildAllowedDevOrigins } from "./allowed-dev-origins";

/* â”€â”€ Homelab dev - HMR allowlist + webpack watch ignore (big artifacts) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
 * Next parses `Origin` to hostname only - no `http://` entries.
 * Tailscale / LAN: set `NEXT_ALLOWED_DEV_ORIGINS` (comma-separated hostnames), restart dev.
 */
const nextConfig: NextConfig = {
  turbopack: {
    root: realpathSync(process.cwd()),
  },

  allowedDevOrigins: buildAllowedDevOrigins(),

  async headers() {
    return [
      {
        source: "/coding",
        headers: [
          {
            key: "Cache-Control",
            value: "no-cache, must-revalidate",
          },
        ],
      },
    ];
  },

  webpack: (config, { dev, isServer }) => {
    if (dev) {
      config.cache = false;
      config.watchOptions = {
        ...(config.watchOptions ?? {}),
        ignored: [
          "**/node_modules/**",
          "**/.git/**",
          "**/.next/**",
          "**/models/**",
          "**/backend/**",
          "**/.cursor/**",
          "**/repomix-output*.xml",
          "**/oldSpiritOS.xml",
          "**/*.gguf",
        ],
      };
    }
    return config;
  },
};

export default nextConfig;

const config = {
  plugins: {
    "@tailwindcss/postcss": {},
  },
};

export default config;

#!/usr/bin/env python3
"""Authorized anime episode importer for SpiritFlix/Jellyfin.

This tool is intentionally a placement/import wrapper. It does not bypass DRM,
site protections, or copyright restrictions. Use it only with files or URLs you
own, created, or have permission/license to download and process.
"""

from __future__ import annotations

import argparse
import csv
import datetime as dt
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
from pathlib import Path
from typing import Any
from urllib.parse import urlparse


DEFAULT_ANIME_ROOT = Path(os.environ.get("SPIRITFLIX_ANIME_ROOT", "/mnt/spirit-8tb/media/anime"))
DEFAULT_ANIME_INBOX_ROOT = Path(
    os.environ.get("SPIRITFLIX_ANIME_INBOX_ROOT", "/mnt/spirit-8tb/media-inbox/anime")
)
DEFAULT_RECEIPT_DIR = ".spiritos-import-receipts"
BLOCKED_SOURCE_HOSTS = {
    "hianime.ad",
    "hianime.to",
    "aniwatch.to",
    "zoro.to",
}
VIDEO_EXTENSIONS = {".mkv", ".mp4", ".webm", ".mov", ".m4v"}


def utc_now() -> str:
    return dt.datetime.now(dt.UTC).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def sanitize_segment(value: str, fallback: str = "untitled") -> str:
    cleaned = re.sub(r'[<>:"/\\|?*\x00-\x1f]+', "", value.strip())
    cleaned = re.sub(r"\s+", " ", cleaned).strip(" .")
    return cleaned[:140] or fallback


def ensure_under_root(root: Path, target: Path) -> Path:
    resolved_root = root.resolve()
    resolved_target = target.resolve()
    try:
        resolved_target.relative_to(resolved_root)
    except ValueError as exc:
        raise SystemExit(f"Refusing to write outside anime root: {resolved_target}") from exc
    return resolved_target


def parse_episode_range(value: str | None, fallback_episode: int | None) -> list[int]:
    if value:
        episodes: list[int] = []
        for part in value.split(","):
            part = part.strip()
            if not part:
                continue
            if "-" in part:
                start_raw, end_raw = part.split("-", 1)
                start = int(start_raw)
                end = int(end_raw)
                if end < start:
                    raise SystemExit(f"Invalid episode range: {part}")
                episodes.extend(range(start, end + 1))
            else:
                episodes.append(int(part))
        return sorted(dict.fromkeys(episodes))

    if fallback_episode is not None:
        return [fallback_episode]

    return [1]


def reject_blocked_url(source_url: str) -> None:
    host = urlparse(source_url).hostname or ""
    host = host.lower().removeprefix("www.")
    if host in BLOCKED_SOURCE_HOSTS:
        raise SystemExit(
            f"Refusing source host {host}. Use only authorized direct media or yt-dlp-supported URLs."
        )


def command_exists(name: str) -> bool:
    return shutil.which(name) is not None


def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def ffprobe(path: Path) -> dict[str, Any]:
    if not command_exists("ffprobe"):
        return {}
    result = subprocess.run(
        [
            "ffprobe",
            "-v",
            "error",
            "-print_format",
            "json",
            "-show_streams",
            "-show_format",
            str(path),
        ],
        check=False,
        capture_output=True,
        text=True,
    )
    if result.returncode != 0:
        return {"error": result.stderr.strip()}
    try:
        return json.loads(result.stdout or "{}")
    except json.JSONDecodeError:
        return {}


def video_height(probe: dict[str, Any]) -> int | None:
    for stream in probe.get("streams", []):
        if stream.get("codec_type") == "video" and stream.get("height"):
            try:
                return int(stream["height"])
            except (TypeError, ValueError):
                return None
    return None


def audio_languages(probe: dict[str, Any]) -> list[str]:
    languages: list[str] = []
    for stream in probe.get("streams", []):
        if stream.get("codec_type") != "audio":
            continue
        tags = stream.get("tags") or {}
        language = str(tags.get("language") or "und").lower()
        if language not in languages:
            languages.append(language)
    return languages


def make_file_name(
    series: str,
    season: int,
    episode: int,
    episode_title: str | None,
    quality: str | None,
    extension: str,
) -> str:
    stem = f"{sanitize_segment(series)} - S{season:02d}E{episode:02d}"
    if episode_title:
        stem += f" - {sanitize_segment(episode_title)}"
    if quality:
        stem += f" [{sanitize_segment(quality)}]"
    return f"{stem}{extension}"


def find_existing_episode(season_dir: Path, series: str, season: int, episode: int) -> Path | None:
    if not season_dir.exists():
        return None
    safe_series = re.escape(sanitize_segment(series))
    pattern = re.compile(rf"^{safe_series} - S{season:02d}E{episode:02d}(?:\b|[ ._-]).*", re.IGNORECASE)
    matches = sorted(
        path for path in season_dir.iterdir()
        if path.is_file() and path.suffix.lower() in VIDEO_EXTENSIONS and pattern.match(path.name)
    )
    return matches[0] if matches else None


def write_receipt(receipt_dir: Path, payload: dict[str, Any]) -> Path:
    receipt_dir.mkdir(parents=True, exist_ok=True)
    receipt_path = receipt_dir / f"{dt.datetime.now(dt.UTC).strftime('%Y%m%d')}.jsonl"
    with receipt_path.open("a", encoding="utf-8") as handle:
        handle.write(json.dumps(payload, sort_keys=True) + "\n")
    return receipt_path


def download_with_ytdlp(source_url: str, staging_dir: Path) -> Path:
    if not command_exists("yt-dlp"):
        raise SystemExit("yt-dlp is not installed on this host. Install it before URL imports.")

    output_template = str(staging_dir / "%(title).120B.%(ext)s")
    subprocess.run(
        [
            "yt-dlp",
            "--no-playlist",
            "--continue",
            "--restrict-filenames",
            "--merge-output-format",
            "mkv",
            "-f",
            "bv*+ba/best",
            "-o",
            output_template,
            source_url,
        ],
        check=True,
    )
    candidates = sorted(
        [path for path in staging_dir.iterdir() if path.is_file() and path.suffix.lower() in VIDEO_EXTENSIONS],
        key=lambda path: path.stat().st_mtime,
        reverse=True,
    )
    if not candidates:
        raise SystemExit("yt-dlp completed but no video file was found in staging.")
    return candidates[0]


def load_manifest(manifest_path: Path) -> list[dict[str, Any]]:
    if not manifest_path.exists():
        raise SystemExit(f"Manifest does not exist: {manifest_path}")

    if manifest_path.suffix.lower() == ".json":
        data = json.loads(manifest_path.read_text(encoding="utf-8"))
        if not isinstance(data, list):
            raise SystemExit("JSON manifest must be an array of episode objects.")
        return [dict(item) for item in data]

    if manifest_path.suffix.lower() == ".jsonl":
        rows: list[dict[str, Any]] = []
        for line_number, line in enumerate(manifest_path.read_text(encoding="utf-8").splitlines(), start=1):
            stripped = line.strip()
            if not stripped or stripped.startswith("#"):
                continue
            try:
                parsed = json.loads(stripped)
            except json.JSONDecodeError as exc:
                raise SystemExit(f"Invalid JSONL manifest line {line_number}: {exc}") from exc
            rows.append(dict(parsed))
        return rows

    with manifest_path.open("r", encoding="utf-8-sig", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


def row_value(row: dict[str, Any], *keys: str) -> str | None:
    for key in keys:
        value = row.get(key)
        if value is None:
            continue
        text = str(value).strip()
        if text:
            return text
    return None


def args_for_manifest_row(base_args: argparse.Namespace, row: dict[str, Any], row_number: int) -> argparse.Namespace:
    row_args = argparse.Namespace(**vars(base_args))

    row_args.series = row_value(row, "series", "series_title", "show") or base_args.series
    season = row_value(row, "season", "season_number") or (str(base_args.season) if base_args.season else None)
    episode = row_value(row, "episode", "episode_number", "ep")
    row_args.source_url = row_value(row, "source_url", "url", "link")
    row_args.source_file = row_value(row, "source_file", "file", "path")
    row_args.episode_title = row_value(row, "episode_title", "title", "name") or base_args.episode_title
    row_args.audio = row_value(row, "audio") or base_args.audio
    row_args.quality = row_value(row, "quality") or base_args.quality

    if not row_args.series:
        raise SystemExit(f"Manifest row {row_number} is missing series and no --series fallback was provided.")
    if not season:
        raise SystemExit(f"Manifest row {row_number} is missing season and no --season fallback was provided.")
    if not episode:
        raise SystemExit(f"Manifest row {row_number} is missing episode.")
    if not row_args.source_url and not row_args.source_file:
        raise SystemExit(f"Manifest row {row_number} is missing source_url/link or source_file/path.")
    if row_args.source_url and row_args.source_file:
        raise SystemExit(f"Manifest row {row_number} has both source_url and source_file; choose one.")
    if row_args.audio not in {"dub", "sub", "original"}:
        raise SystemExit(f"Manifest row {row_number} has invalid audio value: {row_args.audio}")

    try:
        row_args.season = int(season)
        row_args.episode = int(episode)
    except ValueError as exc:
        raise SystemExit(f"Manifest row {row_number} has non-numeric season/episode.") from exc

    return row_args


def import_episode(args: argparse.Namespace, episode: int) -> dict[str, Any]:
    anime_root = DEFAULT_ANIME_INBOX_ROOT if args.send_to_converter else Path(args.target_root)
    allowed_roots = {str(DEFAULT_ANIME_ROOT)}
    if args.send_to_converter:
        allowed_roots.add(str(DEFAULT_ANIME_INBOX_ROOT))
    if str(anime_root) not in allowed_roots and not args.allow_custom_root:
        raise SystemExit(
            f"Refusing custom target root {anime_root}. Pass --allow-custom-root for an explicit test root."
        )

    anime_root.mkdir(parents=True, exist_ok=True)
    series_dir = ensure_under_root(anime_root, anime_root / sanitize_segment(args.series))
    season_dir = ensure_under_root(series_dir, series_dir / f"Season {args.season:02d}")
    receipt_dir = ensure_under_root(anime_root, anime_root / DEFAULT_RECEIPT_DIR)

    source_path: Path | None = None
    staging_parent: tempfile.TemporaryDirectory[str] | None = None
    source_kind = "source-file" if args.source_file else "source-url"

    if args.source_file:
        source_path = Path(args.source_file)
        if not source_path.exists():
            raise SystemExit(f"Source file does not exist: {source_path}")
    elif args.source_url:
        reject_blocked_url(args.source_url)
        staging_parent = tempfile.TemporaryDirectory(prefix="spiritflix-anime-import-")
        source_path = download_with_ytdlp(args.source_url, Path(staging_parent.name))
    else:
        raise SystemExit("Provide --source-file or --source-url.")

    probe = ffprobe(source_path)
    height = video_height(probe)
    quality = args.quality or (f"{height}p" if args.include_detected_quality and height else None)
    target_name = make_file_name(
        args.series,
        args.season,
        episode,
        args.episode_title,
        quality,
        source_path.suffix.lower() or ".mkv",
    )
    target_path = ensure_under_root(season_dir, season_dir / target_name)

    season_dir.mkdir(parents=True, exist_ok=True)
    existing_episode_path = find_existing_episode(season_dir, args.series, args.season, episode)
    status = "planned"
    if existing_episode_path and not args.force:
        target_path = existing_episode_path
        status = "skipped_existing"
    elif args.dry_run:
        status = "dry_run"
    else:
        if source_path.resolve() == target_path.resolve():
            status = "skipped_existing"
        else:
            temp_path = target_path.with_suffix(target_path.suffix + ".part")
            if temp_path.exists():
                temp_path.unlink()
            shutil.copy2(source_path, temp_path)
            temp_path.replace(target_path)
            status = "imported"

    receipt = {
        "at": utc_now(),
        "status": status,
        "series": args.series,
        "season": args.season,
        "episode": episode,
        "audio": args.audio,
        "sourceKind": source_kind,
        "source": args.source_url or str(source_path),
        "targetPath": str(target_path),
        "targetMode": "converter-inbox" if args.send_to_converter else "final-library",
        "targetExists": target_path.exists(),
        "quality": quality,
        "audioLanguages": audio_languages(probe),
        "sha256": sha256_file(target_path) if target_path.exists() and not args.no_hash else None,
        "authorization": {
            "affirmed": True,
            "note": args.authorization_note,
        },
    }
    receipt["receiptPath"] = str(write_receipt(receipt_dir, receipt))

    if staging_parent:
        staging_parent.cleanup()

    return receipt


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description="Import authorized anime episodes into SpiritFlix/Jellyfin anime folders.")
    parser.add_argument("--series", help="Series folder/title, for example 'Rurouni Kenshin (1996)'. Required unless every manifest row has series.")
    parser.add_argument("--season", type=int, help="Season number. Required unless every manifest row has season.")
    parser.add_argument("--episode", type=int, help="Single episode number. Defaults to 1.")
    parser.add_argument("--episodes", help="Episode list/range, for example '1' or '1-27'.")
    parser.add_argument("--episode-title", help="Optional episode title for the target filename.")
    parser.add_argument("--audio", default="dub", choices=["dub", "sub", "original"], help="Receipt audio lane.")
    parser.add_argument("--quality", help="Override quality label in the target filename, for example 1080p.")
    parser.add_argument("--include-detected-quality", action="store_true", help="Append detected height such as [1080p] to new filenames.")
    parser.add_argument("--source-file", help="Authorized local media file to place.")
    parser.add_argument("--source-url", help="Authorized URL to download with yt-dlp.")
    parser.add_argument("--manifest", help="CSV, JSON, or JSONL manifest with series, season, episode, and source_url/source_file columns.")
    parser.add_argument("--target-root", default=str(DEFAULT_ANIME_ROOT), help="Anime root. Defaults to SpiritFlix anime root.")
    parser.add_argument(
        "--send-to-converter",
        action="store_true",
        help="Place files in the media-inbox anime tree so media-ingest-worker converts them before final library placement.",
    )
    parser.add_argument("--allow-custom-root", action="store_true", help="Allow target roots other than the default anime root.")
    parser.add_argument("--affirm-authorized", action="store_true", help="Required: affirm you own or have rights to process this media.")
    parser.add_argument("--authorization-note", default="User affirmed authorized media import.", help="Receipt authorization note.")
    parser.add_argument("--stop-after", type=int, default=None, help="Stop after N imported/planned episodes.")
    parser.add_argument("--dry-run", action="store_true", help="Plan and write receipts without copying/downloading final files.")
    parser.add_argument("--force", action="store_true", help="Overwrite an existing target file.")
    parser.add_argument("--no-hash", action="store_true", help="Skip SHA-256 hash calculation in receipts.")
    return parser


def main() -> int:
    parser = build_parser()
    args = parser.parse_args()

    if not args.affirm_authorized:
        parser.error("--affirm-authorized is required for all imports.")

    if args.manifest:
        rows = load_manifest(Path(args.manifest))
        if args.stop_after is not None:
            rows = rows[: max(args.stop_after, 0)]
        receipts = [
            import_episode(row_args, row_args.episode)
            for row_number, row in enumerate(rows, start=1)
            for row_args in [args_for_manifest_row(args, row, row_number)]
        ]
        print(json.dumps({"ok": True, "count": len(receipts), "receipts": receipts}, indent=2))
        return 0

    if not args.series:
        parser.error("--series is required without --manifest.")
    if args.season is None:
        parser.error("--season is required without --manifest.")
    if not args.source_url and not args.source_file:
        parser.error("--source-url or --source-file is required without --manifest.")

    episodes = parse_episode_range(args.episodes, args.episode)
    if args.stop_after is not None:
        episodes = episodes[: max(args.stop_after, 0)]

    receipts = [import_episode(args, episode) for episode in episodes]
    print(json.dumps({"ok": True, "count": len(receipts), "receipts": receipts}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env node
import { spawn } from "node:child_process";
import fs from "node:fs/promises";
import path from "node:path";

const ROOT = process.env.MEDIA_INGEST_ROOT || "/mnt/spirit-8tb";
const INBOX_ROOT = process.env.MEDIA_INGEST_INBOX || path.join(ROOT, "media-inbox");
const MEDIA_ROOT = process.env.MEDIA_INGEST_MEDIA || path.join(ROOT, "media");
const LIBRARY_WATCH_ROOTS = (process.env.MEDIA_INGEST_LIBRARY_WATCH_ROOTS || path.join(MEDIA_ROOT, "yes"))
  .split(path.delimiter)
  .map((entry) => entry.trim())
  .filter(Boolean);
const ORIGINALS_ROOT =
  process.env.MEDIA_INGEST_ORIGINALS || path.join(ROOT, "media-originals", "keep-for-30-days");
const PROCESSING_ROOT = process.env.MEDIA_INGEST_PROCESSING || path.join(ROOT, "media-processing");
const ACTIVE_ROOT = path.join(PROCESSING_ROOT, "active");
const FAILED_ROOT = path.join(PROCESSING_ROOT, "failed");
const LOG_ROOT = path.join(PROCESSING_ROOT, "logs");
const STATE_PATH = path.join(LOG_ROOT, "media-ingest-state.json");
const LOCK_PATH = path.join(LOG_ROOT, "media-ingest-worker.lock");
const POLL_MS = Number(process.env.MEDIA_INGEST_POLL_MS || 30000);
const STABLE_MS = Number(process.env.MEDIA_INGEST_STABLE_MS || 120000);
const EXTENSIONS = new Set([".mkv", ".mp4", ".mov", ".m4v", ".webm"]);
const ENCODER = process.env.MEDIA_INGEST_ENCODER || "cpu-x265";
const MAC_ENCODER_SCRIPT =
  process.env.MEDIA_INGEST_MAC_ENCODER_SCRIPT ||
  path.resolve("scripts/media/mac_videotoolbox_encode.py");
const MAC_VIDEO_BITRATE = process.env.MEDIA_INGEST_MAC_VIDEO_BITRATE || "500k";
const MAC_MAXRATE = process.env.MEDIA_INGEST_MAC_MAXRATE || "900k";
const MAC_BUFSIZE = process.env.MEDIA_INGEST_MAC_BUFSIZE || "1800k";
const MAC_PROFILE = process.env.MEDIA_INGEST_MAC_PROFILE || "main10";
const DELETE_LIBRARY_ORIGINALS = process.env.MEDIA_INGEST_DELETE_LIBRARY_ORIGINALS === "1";
const STOP_AFTER_DONE = Number(process.env.MEDIA_INGEST_STOP_AFTER_DONE || 0);
const MAX_QUEUED = Number(process.env.MEDIA_INGEST_MAX_QUEUED || 0);
const INCLUDE_REGEX = process.env.MEDIA_INGEST_INCLUDE_REGEX ? new RegExp(process.env.MEDIA_INGEST_INCLUDE_REGEX) : null;
const SORT_BY_SIZE = process.env.MEDIA_INGEST_SORT_BY_SIZE === "1";
const FACE_SCAN_ON_INGEST = process.env.MEDIA_INGEST_FACE_SCAN_ON_INGEST !== "0";
const FACE_ORGANIZER_PYTHON = process.env.MEDIA_INGEST_FACE_ORGANIZER_PYTHON || ".venv-face-organizer/bin/python";
const FACE_ORGANIZER_SCRIPT = process.env.MEDIA_INGEST_FACE_ORGANIZER_SCRIPT || "scripts/media/face_organizer.py";
const FACE_ORGANIZER_SOURCE = process.env.MEDIA_INGEST_FACE_ORGANIZER_SOURCE || LIBRARY_WATCH_ROOTS[0] || path.join(MEDIA_ROOT, "yes");
const FACE_ORGANIZER_CTX_ID = process.env.MEDIA_INGEST_FACE_ORGANIZER_CTX_ID || "0";
const FACE_ORGANIZER_FRAME_COUNT = process.env.MEDIA_INGEST_FACE_ORGANIZER_FRAME_COUNT || "12";
const CPU_ENCODER_THREADS = Math.max(1, Number(process.env.MEDIA_INGEST_CPU_THREADS || 2));
const CPU_ENCODER_NICE = Number(process.env.MEDIA_INGEST_CPU_NICE || 12);
const CPU_ENCODER_CPUSET = process.env.MEDIA_INGEST_CPUSET ?? (process.platform === "linux" ? "0,1" : "");
const POST_PROCESS_THREADS = String(Math.max(1, Number(process.env.MEDIA_INGEST_POST_THREADS || CPU_ENCODER_THREADS)));
const POST_PROCESS_NICE = Number(process.env.MEDIA_INGEST_POST_NICE || CPU_ENCODER_NICE);
const POST_PROCESS_CPUSET = process.env.MEDIA_INGEST_POST_CPUSET ?? CPU_ENCODER_CPUSET;

const state = {
  version: 2,
  queueState: "running",
  jobs: [],
};

class NotWorthConvertingError extends Error {
  constructor(message) {
    super(message);
    this.name = "NotWorthConvertingError";
  }
}

function now() {
  return new Date().toISOString();
}

function log(message) {
  const line = `[${now()}] ${message}`;
  console.log(line);
  return fs.appendFile(path.join(LOG_ROOT, "worker.log"), `${line}\n`).catch(() => {});
}

function jobLog(job, message) {
  job.logs.push({ at: now(), message });
  job.updatedAt = now();
  return log(`Job ${job.id}: ${message}`);
}

async function ensureDirs() {
  await fs.mkdir(INBOX_ROOT, { recursive: true });
  await fs.mkdir(MEDIA_ROOT, { recursive: true });
  for (const root of LIBRARY_WATCH_ROOTS) {
    await fs.mkdir(root, { recursive: true });
  }
  await fs.mkdir(ORIGINALS_ROOT, { recursive: true });
  await fs.mkdir(ACTIVE_ROOT, { recursive: true });
  await fs.mkdir(FAILED_ROOT, { recursive: true });
  await fs.mkdir(LOG_ROOT, { recursive: true });
}

async function writeState() {
  await fs.writeFile(STATE_PATH, `${JSON.stringify(state, null, 2)}\n`);
}

function run(command, args) {
  return new Promise((resolve, reject) => {
    const child = spawn(command, args, { stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk;
    });
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0) {
        resolve({ stdout, stderr });
      } else {
        reject(new Error(`${command} exited ${code}: ${stderr || stdout}`));
      }
    });
  });
}

function quoteCommandArg(arg) {
  return arg.includes(" ") ? JSON.stringify(arg) : arg;
}

function buildBackgroundCommand(baseCommand, args, options = {}) {
  const nice = options.nice ?? CPU_ENCODER_NICE;
  const cpuset = options.cpuset ?? CPU_ENCODER_CPUSET;
  let command = baseCommand;
  let spawnArgs = args;
  let display = [baseCommand, ...args];

  if (cpuset && process.platform === "linux") {
    command = "taskset";
    spawnArgs = ["-c", cpuset, baseCommand, ...spawnArgs];
    display = ["taskset", "-c", cpuset, ...display];
  }

  if (Number.isFinite(nice) && nice !== 0 && process.platform !== "win32") {
    spawnArgs = ["-n", String(nice), command, ...spawnArgs];
    display = ["nice", "-n", String(nice), ...display];
    command = "nice";
  }

  return { command, spawnArgs, display };
}

function buildCpuEncoderCommand(args) {
  return buildBackgroundCommand("ffmpeg", args, { nice: CPU_ENCODER_NICE, cpuset: CPU_ENCODER_CPUSET });
}

function runPostProcess(command, args) {
  return new Promise((resolve, reject) => {
    const background = buildBackgroundCommand(command, args, { nice: POST_PROCESS_NICE, cpuset: POST_PROCESS_CPUSET });
    const child = spawn(background.command, background.spawnArgs, {
      stdio: ["ignore", "pipe", "pipe"],
      env: {
        ...process.env,
        OMP_NUM_THREADS: process.env.OMP_NUM_THREADS || POST_PROCESS_THREADS,
        OPENBLAS_NUM_THREADS: process.env.OPENBLAS_NUM_THREADS || POST_PROCESS_THREADS,
        MKL_NUM_THREADS: process.env.MKL_NUM_THREADS || POST_PROCESS_THREADS,
        NUMEXPR_NUM_THREADS: process.env.NUMEXPR_NUM_THREADS || POST_PROCESS_THREADS,
      },
    });
    let stdout = "";
    let stderr = "";
    child.stdout.on("data", (chunk) => {
      stdout += chunk;
    });
    child.stderr.on("data", (chunk) => {
      stderr += chunk;
    });
    child.on("error", reject);
    child.on("close", (code) => {
      if (code === 0) {
        resolve({ stdout, stderr, command: background.display });
      } else {
        reject(new Error(`${background.display.join(" ")} exited ${code}: ${stderr || stdout}`));
      }
    });
  });
}

async function runFaceOrganizerScan(finalPath) {
  const sidecarPath = `${finalPath}.face-meta.json`;
  const hasSidecar = await exists(sidecarPath);
  if (!FACE_SCAN_ON_INGEST && hasSidecar) {
    return {
      enabled: false,
      status: "skipped",
      reason: "sidecar already exists and MEDIA_INGEST_FACE_SCAN_ON_INGEST=0",
      at: now(),
      sidecarPath,
    };
  }
  const args = [
    FACE_ORGANIZER_SCRIPT,
    "--scan-video",
    finalPath,
    "--source",
    FACE_ORGANIZER_SOURCE,
    "--apply",
    "--force",
    "--frame-count",
    FACE_ORGANIZER_FRAME_COUNT,
    "--ctx-id",
    FACE_ORGANIZER_CTX_ID,
  ];
  try {
    const result = await runPostProcess(FACE_ORGANIZER_PYTHON, args);
    return {
      enabled: true,
      status: "ok",
      at: now(),
      command: result.command,
      stdout: result.stdout.slice(-4000),
      stderr: result.stderr.slice(-4000),
      sidecarPath: `${finalPath}.face-meta.json`,
    };
  } catch (error) {
    return {
      enabled: true,
      status: "failed",
      at: now(),
      command: buildBackgroundCommand(FACE_ORGANIZER_PYTHON, args, { nice: POST_PROCESS_NICE, cpuset: POST_PROCESS_CPUSET }).display,
      error: error instanceof Error ? error.message : String(error),
      sidecarPath: `${finalPath}.face-meta.json`,
    };
  }
}

async function refreshOrganizerPages() {
  if (process.env.MEDIA_INGEST_REFRESH_ORGANIZER_ON_INGEST === "0") {
    return {
      status: "skipped",
      reason: "MEDIA_INGEST_REFRESH_ORGANIZER_ON_INGEST=0",
      at: now(),
    };
  }
  const args = [
    FACE_ORGANIZER_SCRIPT,
    "--organizer-quick-refresh",
    "--source",
    FACE_ORGANIZER_SOURCE,
    "--ctx-id",
    FACE_ORGANIZER_CTX_ID,
    "--apply",
  ];
  try {
    const result = await runPostProcess(FACE_ORGANIZER_PYTHON, args);
    return {
      status: "ok",
      at: now(),
      command: result.command,
      stdout: result.stdout.slice(-2000),
      stderr: result.stderr.slice(-2000),
    };
  } catch (error) {
    return {
      status: "failed",
      at: now(),
      command: buildBackgroundCommand(FACE_ORGANIZER_PYTHON, args, { nice: POST_PROCESS_NICE, cpuset: POST_PROCESS_CPUSET }).display,
      error: error instanceof Error ? error.message : String(error),
    };
  }
}

async function ffprobe(file) {
  const { stdout } = await run("ffprobe", [
    "-v",
    "error",
    "-print_format",
    "json",
    "-show_format",
    "-show_streams",
    file,
  ]);
  return JSON.parse(stdout);
}

function videoCodec(probe) {
  return probe.streams?.find((stream) => stream.codec_type === "video")?.codec_name || "unknown";
}

async function walk(dir) {
  const entries = await fs.readdir(dir, { withFileTypes: true }).catch(() => []);
  const files = [];
  for (const entry of entries) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      files.push(...(await walk(full)));
    } else if (entry.isFile() && EXTENSIONS.has(path.extname(entry.name).toLowerCase())) {
      files.push(full);
    }
  }
  if (SORT_BY_SIZE) {
    const withSizes = await Promise.all(
      files.map(async (file) => ({ file, size: (await fs.stat(file)).size })),
    );
    return withSizes.sort((a, b) => a.size - b.size || a.file.localeCompare(b.file)).map((entry) => entry.file);
  }
  return files.sort();
}

function receiptPathFor(file) {
  return `${file}.media-ingest.json`;
}

function skipReceiptPathFor(file) {
  return `${file}.media-ingest-skip.json`;
}

async function exists(file) {
  return fs.access(file).then(() => true).catch(() => false);
}

async function movePath(source, target) {
  try {
    await fs.rename(source, target);
  } catch (error) {
    if (error?.code !== "EXDEV") {
      throw error;
    }
    await fs.copyFile(source, target);
    await fs.rm(source, { force: true });
  }
}

async function hasIngestReceipt(file) {
  return (await exists(receiptPathFor(file))) || (await exists(skipReceiptPathFor(file)));
}

async function chooseFinalPath(relativeOutput, activePath) {
  const requested = path.join(MEDIA_ROOT, relativeOutput);
  const activeOriginalFinalPath = path.join(MEDIA_ROOT, relativeOutput.replace(/\.mkv$/, path.extname(activePath)));
  if (!(await exists(requested)) || requested === activeOriginalFinalPath) {
    return requested;
  }

  const parsed = path.parse(relativeOutput);
  for (let attempt = 1; attempt <= 100; attempt += 1) {
    const suffix = attempt === 1 ? ".optimized" : `.optimized-${attempt}`;
    const candidate = path.join(MEDIA_ROOT, parsed.dir, `${parsed.name}${suffix}${parsed.ext}`);
    if (!(await exists(candidate))) {
      return candidate;
    }
  }

  throw new Error(`Could not choose a non-conflicting final output path for ${relativeOutput}.`);
}

function libraryCategoryAndRelative(file, root) {
  const relativeToMedia = path.relative(MEDIA_ROOT, file);
  if (!relativeToMedia.startsWith("..") && !path.isAbsolute(relativeToMedia)) {
    const [category, ...rest] = relativeToMedia.split(path.sep);
    return {
      category: category || path.basename(root),
      relativeInCategory: rest.join(path.sep) || path.basename(file),
    };
  }

  const relativeToRoot = path.relative(root, file);
  return {
    category: path.basename(root) || "yes",
    relativeInCategory: relativeToRoot || path.basename(file),
  };
}

async function isStable(file) {
  const first = await fs.stat(file);
  const age = Date.now() - first.mtimeMs;
  if (age < STABLE_MS) {
    await log(`Not stable: ${file}; age ${(age / 1000).toFixed(1)}s is below ${STABLE_MS / 1000}s.`);
    return false;
  }
  await new Promise((resolve) => setTimeout(resolve, 1000));
  const second = await fs.stat(file);
  return first.size === second.size && first.mtimeMs === second.mtimeMs;
}

function makeInboxJob(file) {
  const rel = path.relative(INBOX_ROOT, file);
  const [category, ...rest] = rel.split(path.sep);
  const relativeInCategory = rest.join(path.sep);
  return makeJob({
    file,
    category: category || "other",
    relativeInCategory: relativeInCategory || path.basename(file),
    sourceKind: "inbox",
    deleteOriginalOnSuccess: false,
  });
}

function makeLibraryJob(file, root) {
  const { category, relativeInCategory } = libraryCategoryAndRelative(file, root);
  return makeJob({
    file,
    category,
    relativeInCategory,
    sourceKind: "library",
    deleteOriginalOnSuccess: DELETE_LIBRARY_ORIGINALS,
  });
}

function makeJob({ file, category, relativeInCategory, sourceKind, deleteOriginalOnSuccess }) {
  const id = `mi-${Date.now().toString(36)}-${Math.random().toString(16).slice(2, 10)}`;
  return {
    id,
    sourcePath: file,
    sourceKind,
    deleteOriginalOnSuccess,
    category,
    relativeInCategory,
    profile: "balanced_1080p",
    status: "queued",
    createdAt: now(),
    updatedAt: now(),
    logs: [{ at: now(), message: `Queued stable file ${file}` }],
  };
}

async function enqueueStableCandidates(files, makeCandidateJob) {
  for (const file of files) {
    if (INCLUDE_REGEX && !INCLUDE_REGEX.test(file)) {
      continue;
    }
    if (state.jobs.some((job) => job.sourcePath === file && job.status !== "failed")) {
      await log(`Skipped duplicate: ${file}`);
      continue;
    }
    if (await hasIngestReceipt(file)) {
      await log(`Skipped already-ingested output: ${file}`);
      continue;
    }
    await log(`Discovered candidate: ${file}`);
    await log(`Checking stability: ${file}`);
    if (!(await isStable(file))) {
      await log(`Not stable yet: ${file}`);
      continue;
    }
    await log(`Stable: ${file}`);
    const job = makeCandidateJob(file);
    state.jobs.push(job);
    await log(`Queued job ${job.id}: ${file}`);
    await writeState();
    if (MAX_QUEUED > 0 && state.jobs.filter((existingJob) => existingJob.status === "queued").length >= MAX_QUEUED) {
      await log(`Max queued target reached: ${MAX_QUEUED} queued job(s).`);
      break;
    }
  }
}

async function scan() {
  const inboxFiles = await walk(INBOX_ROOT);
  await log(`Polling scan found ${inboxFiles.length} filesystem entries under ${INBOX_ROOT}.`);
  await enqueueStableCandidates(inboxFiles, makeInboxJob);

  for (const root of LIBRARY_WATCH_ROOTS) {
    const libraryFiles = await walk(root);
    await log(`Polling scan found ${libraryFiles.length} filesystem entries under library watch root ${root}.`);
    await enqueueStableCandidates(libraryFiles, (file) => makeLibraryJob(file, root));
  }
}

async function processJob(job) {
  job.status = "running";
  job.startedAt = now();
  await jobLog(job, "Moving source into active processing.");

  const activeDir = path.join(ACTIVE_ROOT, job.id);
  await fs.mkdir(activeDir, { recursive: true });
  const activePath = path.join(activeDir, path.basename(job.relativeInCategory));
  await movePath(job.sourcePath, activePath);
  job.activePath = activePath;
  await jobLog(job, `Moved to active: ${activePath}`);

  await jobLog(job, "Running ffprobe on source.");
  job.probe = await ffprobe(activePath);
  job.originalSize = Number(job.probe.format?.size || (await fs.stat(activePath)).size);
  await jobLog(job, `Source codec: ${videoCodec(job.probe)}`);

  const outputRelative = job.relativeInCategory.replace(/\.[^.]+$/, ".mkv");
  const tempOutputPath = path.join(activeDir, path.basename(outputRelative).replace(/\.mkv$/, ".tmp.mkv"));
  job.tempOutputPath = tempOutputPath;
  if (ENCODER === "mac-videotoolbox-hevc") {
    await jobLog(job, `Encoding with Mac VideoToolbox HEVC. bitrate=${MAC_VIDEO_BITRATE}`);
    const args = [
      MAC_ENCODER_SCRIPT,
      "--source",
      activePath,
      "--output",
      tempOutputPath,
      "--video-bitrate",
      MAC_VIDEO_BITRATE,
      "--maxrate",
      MAC_MAXRATE,
      "--bufsize",
      MAC_BUFSIZE,
      "--profile",
      MAC_PROFILE,
      "--force",
    ];
    job.command = ["python3", ...args];
    await jobLog(job, `python3 ${args.map((arg) => (arg.includes(" ") ? JSON.stringify(arg) : arg)).join(" ")}`);
    const { stdout } = await run("python3", args);
    try {
      job.macEncode = JSON.parse(stdout);
      await jobLog(job, `Mac encode completed in ${job.macEncode.elapsedSeconds}s.`);
    } catch {
      await jobLog(job, "Mac encode completed; receipt JSON could not be parsed.");
    }
    job.progressPercent = 90;
  } else {
    await jobLog(job, "Encoding with profile balanced_1080p.");

    const args = [
      "-y",
      "-hide_banner",
      "-progress",
      "pipe:1",
      "-nostats",
      "-i",
      activePath,
      "-map",
      "0",
      "-c:v",
      "libx265",
      "-preset",
      "medium",
      "-crf",
      "22",
      "-pix_fmt",
      "yuv420p10le",
      "-threads",
      String(CPU_ENCODER_THREADS),
      "-x265-params",
      `pools=${CPU_ENCODER_THREADS}`,
      "-c:a",
      "copy",
      "-c:s",
      "copy",
      tempOutputPath,
    ];
    const cpuEncoder = buildCpuEncoderCommand(args);
    job.command = cpuEncoder.display;
    await jobLog(job, cpuEncoder.display.map(quoteCommandArg).join(" "));

    await new Promise((resolve, reject) => {
      const child = spawn(cpuEncoder.command, cpuEncoder.spawnArgs, { stdio: ["ignore", "pipe", "pipe"] });
      let progress = 0;
      child.stdout.on("data", (chunk) => {
        const text = chunk.toString();
        const timeMatch = text.match(/out_time_ms=(\d+)/);
        const duration = Number(job.probe.format?.duration || 0);
        if (timeMatch && duration > 0) {
          const next = Math.max(10, Math.min(90, Math.round(Number(timeMatch[1]) / 1000000 / duration * 100)));
          if (next > progress) {
            progress = next;
            job.progressPercent = next;
            void jobLog(job, `Encoding progress ${next}%`).then(writeState);
          }
        }
      });
      child.stderr.on("data", () => {});
      child.on("error", reject);
      child.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`ffmpeg exited ${code}`))));
    });
  }

  await jobLog(job, "FFmpeg completed.");
  await jobLog(job, "Verifying encoded output.");
  await ffprobe(tempOutputPath);
  const outputSize = (await fs.stat(tempOutputPath)).size;
  const savings = job.originalSize ? (1 - outputSize / job.originalSize) * 100 : 0;
  if (savings < 5) {
    job.notWorthConverting = true;
    job.skipReceiptPath = skipReceiptPathFor(job.sourcePath);
    job.skipReceipt = {
      at: now(),
      jobId: job.id,
      sourceKind: job.sourceKind,
      sourcePath: job.sourcePath,
      originalSize: job.originalSize,
      outputSize,
      savingsPercent: Number(savings.toFixed(2)),
      profile: job.profile,
      encoder: ENCODER,
      skipped: true,
      reason: "Converted output was not meaningfully smaller.",
    };
    throw new NotWorthConvertingError(`Converted output was not meaningfully smaller. Savings: ${savings.toFixed(2)}%.`);
  }
  await jobLog(job, `Accepted output. Savings: ${savings.toFixed(2)}%.`);

  const finalPath = await chooseFinalPath(path.join(job.category, outputRelative), activePath);
  const originalHoldingPath = path.join(ORIGINALS_ROOT, job.category, job.id, job.relativeInCategory);
  await fs.mkdir(path.dirname(finalPath), { recursive: true });
  await fs.mkdir(path.dirname(originalHoldingPath), { recursive: true });
  await jobLog(job, "Moving output and handling original.");
  await movePath(tempOutputPath, finalPath);
  const receipt = {
    at: now(),
    jobId: job.id,
    sourceKind: job.sourceKind,
    sourcePath: job.sourcePath,
    finalPath,
    originalSize: job.originalSize,
    outputSize,
    savingsPercent: Number(savings.toFixed(2)),
    profile: job.profile,
    encoder: ENCODER,
    deletedOriginal: Boolean(job.deleteOriginalOnSuccess),
  };
  await fs.writeFile(receiptPathFor(finalPath), `${JSON.stringify(receipt, null, 2)}\n`);
  await jobLog(job, "Running face organizer scan for uploaded video.");
  receipt.faceOrganizerScan = await runFaceOrganizerScan(finalPath);
  await fs.writeFile(receiptPathFor(finalPath), `${JSON.stringify(receipt, null, 2)}\n`);
  await jobLog(job, `Face organizer scan ${receipt.faceOrganizerScan.status}.`);
  await jobLog(job, "Refreshing organizer verification/enrollment HTML pages.");
  receipt.organizerPageRefresh = await refreshOrganizerPages();
  await fs.writeFile(receiptPathFor(finalPath), `${JSON.stringify(receipt, null, 2)}\n`);
  await jobLog(job, `Organizer page refresh ${receipt.organizerPageRefresh.status}.`);
  if (job.deleteOriginalOnSuccess) {
    await fs.rm(activePath, { force: true });
    job.originalDeleted = true;
  } else {
    await movePath(activePath, originalHoldingPath);
    job.originalHoldingPath = originalHoldingPath;
  }
  await fs.rm(activeDir, { recursive: true, force: true });
  job.finalPath = finalPath;
  job.receiptPath = receiptPathFor(finalPath);
  job.status = "done";
  job.progressPercent = 100;
  job.completedAt = now();
  await jobLog(
    job,
    job.deleteOriginalOnSuccess
      ? `Completed. Final: ${finalPath}. Original deleted after successful conversion.`
      : `Completed. Final: ${finalPath}. Original: ${originalHoldingPath}`,
  );
  await jobLog(job, "Jellyfin scan not triggered: set JELLYFIN_URL and JELLYFIN_API_KEY to enable it.");
}

async function failJob(job, error) {
  job.status = "failed";
  job.failedAt = now();
  job.error = error instanceof Error ? error.message : String(error);
  if (job.notWorthConverting && job.skipReceiptPath && job.skipReceipt) {
    await fs.mkdir(path.dirname(job.sourcePath), { recursive: true });
    if (job.activePath && !(await exists(job.sourcePath))) {
      await movePath(job.activePath, job.sourcePath);
    }
    await fs.writeFile(job.skipReceiptPath, `${JSON.stringify(job.skipReceipt, null, 2)}\n`);
    job.status = "skipped";
    await fs.rm(path.dirname(job.activePath), { recursive: true, force: true }).catch(() => {});
    await jobLog(job, `SKIPPED: ${job.error}. Original restored: ${job.sourcePath}`);
    return;
  }
  if (job.activePath) {
    const failedDir = path.join(FAILED_ROOT, job.id);
    await fs.mkdir(failedDir, { recursive: true });
    await fs.rename(path.dirname(job.activePath), failedDir).catch(() => {});
  }
  await jobLog(job, `FAILED: ${job.error}`);
}

async function main() {
  await ensureDirs();
  await fs.writeFile(LOCK_PATH, `${process.pid}\n`, { flag: "wx" }).catch((error) => {
    throw new Error(`Worker lock exists at ${LOCK_PATH}: ${error.message}`);
  });
  process.on("exit", () => {
    fs.rm(LOCK_PATH, { force: true }).catch(() => {});
  });

  await log(`Media ingest worker started. inbox=${INBOX_ROOT}`);
  await log(`Library watch roots: ${LIBRARY_WATCH_ROOTS.join(", ") || "(none)"}`);
  if (STOP_AFTER_DONE > 0) {
    await log(`Stop-after mode enabled: worker exits after ${STOP_AFTER_DONE} completed job(s).`);
  }
  if (MAX_QUEUED > 0) {
    await log(`Max-queued mode enabled: scan queues up to ${MAX_QUEUED} job(s).`);
  }
  while (true) {
    await scan();
    const next = state.jobs.find((job) => job.status === "queued");
    if (next) {
      try {
        await processJob(next);
      } catch (error) {
        await failJob(next, error);
      }
      await writeState();
      if (STOP_AFTER_DONE > 0 && state.jobs.filter((job) => job.status === "done").length >= STOP_AFTER_DONE) {
        await log(`Stop-after target reached: ${STOP_AFTER_DONE} completed job(s). Exiting.`);
        break;
      }
      continue;
    }
    await writeState();
    await new Promise((resolve) => setTimeout(resolve, POLL_MS));
  }
}

main().catch(async (error) => {
  await log(`FATAL: ${error instanceof Error ? error.stack || error.message : String(error)}`);
  process.exitCode = 1;
});

#!/usr/bin/env bash # â”€â”€ SpiritFlix admin smoke dev â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ # Temporary localhost Next dev for /spiritflix/admin browser smoke. # NEVER touches tmux-managed ports 3000, 8787, or 3001.
set -euo pipefail
ROOT="${SPIRITOS_ROOT:-$HOME/SpiritOS}" PORT="${SPIRITFLIX_ADMIN_DEV_PORT:-3030}" LOG="${SPIRITFLIX_ADMIN_DEV_LOG:-$HOME/spiritflix-admin-dev.log}" ACTION="${1:-start}"
cd "$ROOT"
kill_smoke_ports() { local port_pids pid for port in 3020 3030; do port_pids="$(lsof -ti "tcp:${port}" 2>/dev/null || true)" [[ -z "$port_pids" ]] && continue printf 'stopping smoke dev on :%s pid(s): %s\n' "$port" "${port_pids//$'\n'/ }" while IFS= read -r pid; do [[ -z "$pid" ]] && continue kill -TERM "$pid" 2>/dev/null || true done <<< "$port_pids" done sleep 1 for port in 3020 3030; do port_pids="$(lsof -ti "tcp:${port}" 2>/dev/null || true)" [[ -z "$port_pids" ]] && continue while IFS= read -r pid; do [[ -z "$pid" ]] && continue kill -KILL "$pid" 2>/dev/null || true done <<< "$port_pids" done }
case "$ACTION" in start) kill_smoke_ports rm -f .next/dev/lock 2>/dev/null || true API_KEY="$(docker exec spirit-jellyfin cat /config/config/system.xml 2>/dev/null | sed -n 's:.*<ApiKey>\([^<]*\)</ApiKey>.*:\1:p' | head -1 || true)" printf 'starting SpiritFlix admin smoke dev on 127.0.0.1:%s (production :3000/:8787/:3001 untouched)\n' "$PORT" exec env \ JELLYFIN_API_KEY="${API_KEY:-}" \ JELLYFIN_URL="${JELLYFIN_URL:-http://127.0.0.1:8096}" \ npx next dev -H 127.0.0.1 --port "$PORT" --webpack >>"$LOG" 2>&1 ;; stop) kill_smoke_ports printf 'SpiritFlix admin smoke dev stopped.\n' ;; *) printf 'usage: %s [start|stop]\n' "$0" >&2 exit 2 ;; esac

#!/usr/bin/env bash set -euo pipefail
ROOT="${SPIRITOS_ROOT:-$HOME/SpiritOS}" SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)" # shellcheck source=runtime-port-guard.sh source "$SCRIPT_DIR/runtime-port-guard.sh" LOG="${SPIRITFLIX_STABLE_WATCHDOG_LOG:-$HOME/spiritflix-stable-3001-watchdog.log}" WORKDIR="${SPIRITFLIX_STABLE_WORKDIR:-/tmp/spiritos-spiritflix-stable-3001}" PORT="${SPIRITFLIX_STABLE_PORT:-3001}" HEALTH_URL="${SPIRITFLIX_STABLE_HEALTH_URL:-http://127.0.0.1:3001/spiritflix}" RESTART_DELAY="${SPIRITFLIX_STABLE_RESTART_DELAY:-8}" HEALTH_INTERVAL="${SPIRITFLIX_STABLE_HEALTH_INTERVAL:-30}" HEALTH_FAILURE_LIMIT="${SPIRITFLIX_STABLE_HEALTH_FAILURE_LIMIT:-3}"
log() { printf '[%s] %s\n' "$(date -Is)" "$*" | tee -a "$LOG" }
health_check() { local code code="$(curl -sS -o /dev/null -w '%{http_code}' --max-time 12 "$HEALTH_URL" 2>/dev/null || echo 000)" [[ "$code" =~ ^[23] ]] }
if [[ ! -d "$WORKDIR" ]]; then log "missing SpiritFlix stable workdir: $WORKDIR" exit 1 fi
cd "$WORKDIR" log "SpiritFlix stable watchdog starting on :$PORT ($WORKDIR)"
while true; do port_pids="$(listener_pids_on_port "$PORT")" if [[ -n "$port_pids" ]]; then while IFS= read -r pid; do [[ -z "$pid" ]] && continue kill -TERM "$pid" 2>/dev/null || true done <<< "$port_pids" wait_for_port_free "$PORT" 8 || true fi
log "starting SpiritFlix stable: npm run start -- -H 0.0.0.0 -p $PORT" npm run start -- -H 0.0.0.0 -p "$PORT" >> "${WORKDIR}.log" 2>> "${WORKDIR}.err.log" & app_pid=$! failures=0
while kill -0 "$app_pid" 2>/dev/null; do if health_check; then failures=0 else failures=$((failures + 1)) log "SpiritFlix :$PORT health failed $failures/$HEALTH_FAILURE_LIMIT" if (( failures >= HEALTH_FAILURE_LIMIT )); then log "SpiritFlix :$PORT unreachable; restarting" kill -TERM "$app_pid" 2>/dev/null || true wait_for_port_free "$PORT" 5 || true kill -KILL "$app_pid" 2>/dev/null || true break fi fi sleep "$HEALTH_INTERVAL" done
if kill -0 "$app_pid" 2>/dev/null; then : else wait "$app_pid" || true log "SpiritFlix :$PORT exited; restarting in ${RESTART_DELAY}s" fi sleep "$RESTART_DELAY" done

#!/usr/bin/env python3
"""Sync Jellyfin playlists that behave like shuffled folder queues.

This script uses the local Jellyfin database only to reuse the active local
Jellyfin Web device token. It does not print or store the token, and it does
not modify media files.
"""

from __future__ import annotations

import json
import sqlite3
import sys
import time
import urllib.error
import urllib.parse
import urllib.request
from dataclasses import dataclass


JELLYFIN_URL = "http://127.0.0.1:8096"
JELLYFIN_DB = "/mnt/spirit-8tb/services/jellyfin/config/data/jellyfin.db"

FOLDER_PLAYLISTS = {
    "YES Folder Queue": "/media/yes",
    "Other Folder Queue": "/media/other",
    "Optimized Test Queue": "/media/optimized-test",
}


@dataclass(frozen=True)
class JellyfinSession:
    user_id: str
    token: str


def hyphenless(item_id: str) -> str:
    return item_id.replace("-", "").lower()


def get_session() -> JellyfinSession:
    conn = sqlite3.connect(JELLYFIN_DB)
    row = conn.execute(
        """
        select UserId, AccessToken
        from Devices
        where AccessToken is not null and AccessToken != ''
        order by DateLastActivity desc
        limit 1
        """
    ).fetchone()
    conn.close()
    if not row:
        raise RuntimeError("No Jellyfin device token found in the local database.")
    return JellyfinSession(user_id=row[0], token=row[1])


class JellyfinApi:
    def __init__(self, session: JellyfinSession) -> None:
        self.session = session
        self.headers = {
            "X-Emby-Token": session.token,
            "Content-Type": "application/json",
        }

    def request(
        self,
        method: str,
        path: str,
        params: dict[str, str] | None = None,
        body: dict | None = None,
    ) -> tuple[int, str]:
        url = JELLYFIN_URL + path
        if params:
            url += "?" + urllib.parse.urlencode(params, doseq=True)
        data = None if body is None else json.dumps(body).encode("utf-8")
        request = urllib.request.Request(url, data=data, method=method, headers=self.headers)
        try:
            with urllib.request.urlopen(request, timeout=60) as response:
                return response.status, response.read().decode("utf-8")
        except urllib.error.HTTPError as exc:
            return exc.code, exc.read().decode("utf-8", errors="replace")

    def json_request(
        self,
        method: str,
        path: str,
        params: dict[str, str] | None = None,
        body: dict | None = None,
    ) -> dict:
        status, text = self.request(method, path, params=params, body=body)
        if status < 200 or status >= 300:
            raise RuntimeError(f"{method} {path} failed with HTTP {status}: {text[:500]}")
        return json.loads(text) if text else {}


def load_folder_video_ids(folder_path: str) -> list[str]:
    conn = sqlite3.connect(JELLYFIN_DB)
    rows = conn.execute(
        """
        select Id
        from BaseItems
        where MediaType = 'Video'
          and IsFolder = 0
          and RunTimeTicks is not null
          and (
            Path like ?
            or Path = ?
          )
        order by SortName, Name, Path
        """,
        (folder_path.rstrip("/") + "/%", folder_path),
    ).fetchall()
    conn.close()
    return [hyphenless(row[0]) for row in rows]


def existing_playlists(api: JellyfinApi) -> dict[str, str]:
    data = api.json_request(
        "GET",
        f"/Users/{api.session.user_id}/Items",
        {"IncludeItemTypes": "Playlist", "Recursive": "true"},
    )
    return {item["Name"]: item["Id"] for item in data.get("Items", [])}


def clear_playlist(api: JellyfinApi, playlist_id: str) -> None:
    data = api.json_request(
        "GET",
        f"/Playlists/{playlist_id}/Items",
        {"UserId": api.session.user_id},
    )
    entry_ids = [
        item.get("PlaylistItemId") or item.get("Id")
        for item in data.get("Items", [])
        if item.get("PlaylistItemId") or item.get("Id")
    ]
    if entry_ids:
        status, text = api.request(
            "DELETE",
            f"/Playlists/{playlist_id}/Items",
            {"EntryIds": ",".join(entry_ids)},
        )
        if status < 200 or status >= 300:
            raise RuntimeError(f"Clearing playlist failed with HTTP {status}: {text[:500]}")


def add_playlist_items(api: JellyfinApi, playlist_id: str, item_ids: list[str]) -> None:
    for start in range(0, len(item_ids), 100):
        chunk = item_ids[start : start + 100]
        status, text = api.request(
            "POST",
            f"/Playlists/{playlist_id}/Items",
            {"Ids": ",".join(chunk), "UserId": api.session.user_id},
        )
        if status < 200 or status >= 300:
            raise RuntimeError(f"Adding playlist items failed with HTTP {status}: {text[:500]}")


def sync_playlist(api: JellyfinApi, name: str, folder_path: str, playlist_ids: dict[str, str]) -> None:
    item_ids = load_folder_video_ids(folder_path)
    if name in playlist_ids:
        playlist_id = playlist_ids[name]
        clear_playlist(api, playlist_id)
        action = "updated"
    else:
        result = api.json_request(
            "POST",
            "/Playlists",
            body={
                "Name": name,
                "Ids": [],
                "UserId": api.session.user_id,
                "MediaType": "Video",
                "IsPublic": False,
            },
        )
        playlist_id = result["Id"]
        action = "created"

    if item_ids:
        add_playlist_items(api, playlist_id, item_ids)

    print(f"{action}: {name}: {len(item_ids)} videos from {folder_path}")


def main() -> int:
    session = get_session()
    api = JellyfinApi(session)
    playlists = existing_playlists(api)
    for name, folder_path in FOLDER_PLAYLISTS.items():
        sync_playlist(api, name, folder_path, playlists)
        time.sleep(0.5)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as exc:
        print(f"ERROR: {exc}", file=sys.stderr)
        raise SystemExit(1)

import { beforeEach, describe, expect, it, vi } from "vitest";
import { POST } from "../actions/route";
import { clearSpiritFlixAdminPreviewStore, getSmokeRoot, handleSpiritFlixAdminAction } from "@/lib/spiritflix/admin/actions";

vi.mock("@/lib/spiritflix/admin/actions", async (importOriginal) => {
  const actual = await importOriginal<typeof import("@/lib/spiritflix/admin/actions")>();
  return {
    ...actual,
    handleSpiritFlixAdminAction: vi.fn(actual.handleSpiritFlixAdminAction),
  };
});

describe("SpiritFlix admin actions route", () => {
  beforeEach(() => {
    clearSpiritFlixAdminPreviewStore();
    vi.mocked(handleSpiritFlixAdminAction).mockClear();
  });

  it("rejects invalid JSON", async () => {
    const response = await POST(
      new Request("http://localhost/api/spiritflix/admin/actions", {
        method: "POST",
        body: "not-json",
      }) as never,
    );
    expect(response.status).toBe(400);
  });

  it("rejects missing action", async () => {
    const response = await POST(
      new Request("http://localhost/api/spiritflix/admin/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ mode: "preview" }),
      }) as never,
    );
    expect(response.status).toBe(400);
  });

  it("POST preview does not require confirm token", async () => {
    const response = await POST(
      new Request("http://localhost/api/spiritflix/admin/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "createFolder",
          mode: "preview",
          parentPath: getSmokeRoot(),
          name: "route-preview-folder",
        }),
      }) as never,
    );
    const payload = await response.json();
    expect(handleSpiritFlixAdminAction).toHaveBeenCalled();
    expect(payload.previewId).toBeTruthy();
  });

  it("POST execute requires confirmation token", async () => {
    const response = await POST(
      new Request("http://localhost/api/spiritflix/admin/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "createFolder",
          mode: "execute",
          confirmToken: "missing",
          parentPath: getSmokeRoot(),
          name: "route-exec-folder",
        }),
      }) as never,
    );
    const payload = await response.json();
    expect(payload.allowed).toBe(false);
  });

  it("rejects unsafe paths through the action engine", async () => {
    const response = await POST(
      new Request("http://localhost/api/spiritflix/admin/actions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          action: "softDelete",
          mode: "preview",
          sourcePath: "/mnt/spirit-8tb/media",
        }),
      }) as never,
    );
    const payload = await response.json();
    expect(payload.allowed).toBe(false);
    expect(response.status).toBe(400);
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { GET } from "../fs/route";

let tempRoot = "";
let originalRoots: string | undefined;

describe("SpiritFlix admin filesystem API", () => {
  beforeEach(async () => {
    originalRoots = process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-admin-fs-"));
    process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = tempRoot;
    await fs.mkdir(path.join(tempRoot, "Movies"));
    await fs.writeFile(path.join(tempRoot, "Movies", "clip.mp4"), "video");
  });

  afterEach(async () => {
    if (originalRoots === undefined) {
      delete process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    } else {
      process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = originalRoots;
    }
    await fs.rm(tempRoot, { force: true, recursive: true });
  });

  it("returns read-only normalized filesystem records", async () => {
    const response = await GET(new Request(`http://localhost/api/spiritflix/admin/fs?path=${encodeURIComponent(tempRoot)}`) as never);
    const body = await response.json();

    expect(response.status).toBe(200);
    expect(body.schema).toBe("spiritflix-admin-fs/v1");
    expect(body.items[0]).toEqual(expect.objectContaining({ name: "Movies", type: "folder", parentPath: expect.any(String) }));
  });

  it("rejects path traversal", async () => {
    const response = await GET(
      new Request(`http://localhost/api/spiritflix/admin/fs?path=${encodeURIComponent(`${tempRoot}${path.sep}..${path.sep}outside`)}`) as never,
    );
    const body = await response.json();

    expect(response.status).toBe(400);
    expect(body.error).toMatch(/traversal/i);
  });

  it("rejects paths outside the allowed root", async () => {
    const outside = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-admin-outside-"));
    const response = await GET(new Request(`http://localhost/api/spiritflix/admin/fs?path=${encodeURIComponent(outside)}`) as never);
    const body = await response.json();

    expect(response.status).toBe(400);
    expect(body.error).toMatch(/outside/i);
    await fs.rm(outside, { force: true, recursive: true });
  });
});

