import { getOrGenerateAdminVideoThumbnail } from "@/lib/spiritflix/admin/thumbnail";

let tempRoot = "";
let originalRoots: string | undefined;

function thumbnailRequest(targetPath: string) {
  return new Request(`http://localhost/api/spiritflix/admin/thumbnail?path=${encodeURIComponent(targetPath)}`) as never;
}

describe("SpiritFlix admin thumbnail API", () => {
  beforeEach(async () => {
    originalRoots = process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-admin-thumb-"));
    process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = tempRoot;
    vi.mocked(getOrGenerateAdminVideoThumbnail).mockReset();
  });

  afterEach(async () => {
    if (originalRoots === undefined) {
      delete process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    } else {
      process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = originalRoots;
    }
    await fs.rm(tempRoot, { force: true, recursive: true });
  });

  it("rejects path traversal", async () => {
    const response = await GET(thumbnailRequest(`${tempRoot}${path.sep}..${path.sep}outside/video.mp4`));
    const body = await response.json();
    expect(response.status).toBe(400);
    expect(body.error).toMatch(/traversal/i);
  });

  it("rejects paths outside the allowed root", async () => {
    const outside = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-admin-outside-"));
    const response = await GET(thumbnailRequest(`${outside}/clip.mp4`));
    const body = await response.json();
    expect(response.status).toBe(400);
    expect(body.error).toMatch(/outside/i);
    await fs.rm(outside, { force: true, recursive: true });
  });

  it("rejects non-video files", async () => {
    const textPath = path.join(tempRoot, "notes.txt");
    await fs.writeFile(textPath, "hello");
    const response = await GET(thumbnailRequest(textPath));
    const body = await response.json();
    expect(response.status).toBe(404);
    expect(body.error).toMatch(/unavailable/i);
  });

  it("returns cached image when cache exists", async () => {
    const cacheFile = path.join(tempRoot, "cached.jpg");
    await fs.writeFile(cacheFile, Buffer.from([0xff, 0xd8, 0xff, 0xd9]));
    vi.mocked(getOrGenerateAdminVideoThumbnail).mockResolvedValue({
      cachePath: cacheFile,
      cacheKey: "cached",
    });

    const response = await GET(thumbnailRequest(path.join(tempRoot, "clip.mp4")));
    expect(response.status).toBe(200);
    expect(response.headers.get("Content-Type")).toBe("image/jpeg");
    const bytes = Buffer.from(await response.arrayBuffer());
    expect(bytes.length).toBeGreaterThan(0);
  });

  it("attempts generation only for valid video paths", async () => {
    const videoPath = path.join(tempRoot, "generate.mp4");
    await fs.writeFile(videoPath, "fake-video");
    const cacheFile = path.join(tempRoot, "generated.jpg");
    await fs.writeFile(cacheFile, Buffer.from([0xff, 0xd8, 0xff, 0xd9]));
    vi.mocked(getOrGenerateAdminVideoThumbnail).mockResolvedValue({
      cachePath: cacheFile,
      cacheKey: "abc",
    });

    const response = await GET(thumbnailRequest(videoPath));
    expect(getOrGenerateAdminVideoThumbnail).toHaveBeenCalledWith(videoPath);
    expect(response.status).toBe(200);
  });
});

import { NextRequest, NextResponse } from "next/server";
import { handleSpiritFlixAdminAction, normalizeSpiritFlixAdminActionRequest } from "@/lib/spiritflix/admin/actions";
import type { SpiritFlixAdminActionRequest } from "@/lib/spiritflix/admin/types";

export const runtime = "nodejs";

export async function POST(request: NextRequest) {
  let payload: SpiritFlixAdminActionRequest;

  try {
    payload = normalizeSpiritFlixAdminActionRequest((await request.json()) as SpiritFlixAdminActionRequest);
  } catch {
    return NextResponse.json({ error: "Invalid SpiritFlix admin action request." }, { status: 400 });
  }

  if (!payload.action || !(payload.mode ?? payload.phase)) {
    return NextResponse.json({ error: "SpiritFlix admin actions require action and mode." }, { status: 400 });
  }

  try {
    const response = await handleSpiritFlixAdminAction(payload);
    return NextResponse.json(response, {
      status: response.allowed ? 200 : 400,
      headers: { "Cache-Control": "no-store" },
    });
  } catch (error) {
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "SpiritFlix admin action failed." },
      { status: 500, headers: { "Cache-Control": "no-store" } },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { isSpiritFlixAdminPathError } from "@/lib/spiritflix/admin/paths";
import { listSpiritFlixAdminDirectory } from "@/lib/spiritflix/admin/fs";
import type { SpiritFlixAdminSortBy, SpiritFlixAdminSortOrder } from "@/lib/spiritflix/admin/types";

export const runtime = "nodejs";

function numberParam(value: string | null): number | undefined {
  if (!value) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

export async function GET(request: NextRequest) {
  const url = new URL(request.url);

  try {
    const payload = await listSpiritFlixAdminDirectory({
      path: url.searchParams.get("path") ?? undefined,
      searchTerm: url.searchParams.get("searchTerm") ?? undefined,
      sortBy: (url.searchParams.get("sortBy") as SpiritFlixAdminSortBy | null) ?? "title",
      sortOrder: (url.searchParams.get("sortOrder") as SpiritFlixAdminSortOrder | null) ?? "asc",
      limit: numberParam(url.searchParams.get("limit")),
      startIndex: numberParam(url.searchParams.get("startIndex")),
    });

    return NextResponse.json(payload, {
      headers: {
        "Cache-Control": "no-store",
      },
    });
  } catch (error) {
    const status = isSpiritFlixAdminPathError(error) ? 400 : 500;
    return NextResponse.json(
      { error: error instanceof Error ? error.message : "SpiritFlix admin filesystem listing failed." },
      { status },
    );
  }
}

import { NextRequest, NextResponse } from "next/server";
import { getServerJellyfinCredentials, jellyfinImagePath } from "@/lib/spiritflix/admin/jellyfin-server";

export const runtime = "nodejs";

const allowedTypes = new Set(["Primary", "Thumb", "Backdrop"]);

export async function GET(request: NextRequest) {
  const credentials = getServerJellyfinCredentials();
  if (!credentials) {
    return NextResponse.json({ error: "SpiritFlix admin image proxy is not configured." }, { status: 503 });
  }

  const itemId = request.nextUrl.searchParams.get("itemId") ?? "";
  const imageType = request.nextUrl.searchParams.get("type") ?? "Primary";
  const tag = request.nextUrl.searchParams.get("tag") ?? undefined;
  const width = Number(request.nextUrl.searchParams.get("width") ?? "360");

  if (!itemId || !allowedTypes.has(imageType)) {
    return NextResponse.json({ error: "Invalid SpiritFlix admin image request." }, { status: 400 });
  }

  const path = jellyfinImagePath(itemId, imageType as "Primary" | "Thumb" | "Backdrop", tag, Number.isFinite(width) ? width : 360);
  const response = await fetch(`${credentials.serverUrl}${path}`, {
    headers: {
      "X-Emby-Token": credentials.accessToken,
    },
    cache: "no-store",
  });

  if (!response.ok || !response.body) {
    return NextResponse.json({ error: "Image unavailable." }, { status: response.status });
  }

  return new NextResponse(response.body, {
    status: response.status,
    headers: {
      "Content-Type": response.headers.get("Content-Type") ?? "image/jpeg",
      "Cache-Control": "private, max-age=300",
    },
  });
}

