import fs from "node:fs/promises";
import path from "node:path";
import { NextRequest, NextResponse } from "next/server";
import { SPIRITFLIX_MEDIA_ROOT } from "@/lib/spiritflix/admin/constants";
import { getSpiritFlixAdminAllowedRoots, isSpiritFlixAdminPathError, resolveSpiritFlixAdminPath } from "@/lib/spiritflix/admin/paths";
import {
  assertSmartVideoPathCandidate,
  buildSmartRenamePreviewDraft,
  getSmartAnalysisPath,
  isSpiritFlixSmartVideoExtension,
  projectApprovedSmartMetadata,
  readSmartAnalysis,
  type SpiritFlixSmartAnalysis,
  writeApprovedSmartMetadataSidecar,
} from "@/lib/spiritflix/admin/smart";
import { markSpiritFlixSmartAnalysisReviewed, runSpiritFlixSmartReviewPipeline, saveSpiritFlixSmartAnalysisReview } from "@/lib/spiritflix/admin/smart/review";
import { assertSpiritFlixSmartReviewPayload } from "@/lib/spiritflix/admin/smart/review-metadata";

const FORBIDDEN_EXECUTE_ACTIONS = new Set([
  "applyRename",
  "applyMove",
  "executeRename",
  "executeMove",
]);

export const runtime = "nodejs";

function isSubPath(parent: string, child: string): boolean {
  const relative = path.relative(parent, child);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

function resolveSmartMediaRoot(targetPath: string): string {
  const allowedRoots = getSpiritFlixAdminAllowedRoots();
  const match = [...allowedRoots].sort((left, right) => right.length - left.length).find((root) => isSubPath(root, targetPath));
  if (!match) return SPIRITFLIX_MEDIA_ROOT;

  let current = path.resolve(match);
  while (true) {
    if (path.basename(current) === "media") return current;
    const parent = path.dirname(current);
    if (parent === current) break;
    current = parent;
  }

  return match;
}

async function loadVideoAnalysis(videoPath: string, mediaRoot: string): Promise<{
  analysis: SpiritFlixSmartAnalysis | null;
  sidecarPath: string;
}> {
  const stat = await fs.stat(videoPath);
  if (!stat.isFile()) {
    throw new Error("Smart analysis is only available for video files.");
  }

  const extension = path.extname(videoPath).toLowerCase();
  if (!isSpiritFlixSmartVideoExtension(extension)) {
    throw new Error("Smart analysis is only available for supported video files.");
  }

  const validatedPath = assertSmartVideoPathCandidate(videoPath, { mediaRoot });
  const pathInput = {
    videoPath: validatedPath,
    fileSizeBytes: stat.size,
    mtimeMs: stat.mtimeMs,
  };
  const analysis = await readSmartAnalysis(pathInput, { mediaRoot });
  const sidecarPath = getSmartAnalysisPath(pathInput, { mediaRoot });
  return { analysis, sidecarPath };
}

function jsonError(error: unknown, fallbackStatus = 500) {
  if (isSpiritFlixAdminPathError(error)) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Invalid path." }, { status: 400 });
  }
  const message = error instanceof Error ? error.message : "Smart analysis request failed.";
  const status = /only available|folder|video files|unknown field|known tag|review|overlap|must be|not in suggestedTags|too large/i.test(message)
    ? 400
    : fallbackStatus;
  return NextResponse.json({ error: message }, { status });
}

export async function GET(request: NextRequest) {
  const videoPath = new URL(request.url).searchParams.get("path")?.trim() ?? "";
  if (!videoPath) {
    return NextResponse.json({ error: "Missing video path." }, { status: 400 });
  }

  try {
    const { realPath } = await resolveSpiritFlixAdminPath(videoPath);
    const mediaRoot = resolveSmartMediaRoot(realPath);
    const payload = await loadVideoAnalysis(realPath, mediaRoot);
    return NextResponse.json(payload, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return jsonError(error);
  }
}

export async function POST(request: NextRequest) {
  let body: { path?: string; action?: string; review?: unknown };
  try {
    body = (await request.json()) as { path?: string; action?: string; review?: unknown };
  } catch {
    return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const videoPath = body.path?.trim() ?? "";
  if (!videoPath) {
    return NextResponse.json({ error: "Missing video path." }, { status: 400 });
  }

  const action = body.action?.trim() || "analyze";

  try {
    const { realPath } = await resolveSpiritFlixAdminPath(videoPath);
    const mediaRoot = resolveSmartMediaRoot(realPath);
    const stat = await fs.stat(realPath);

    if (!stat.isFile()) {
      return NextResponse.json({ error: "Smart analysis only supports a single video file path." }, { status: 400 });
    }

    const extension = path.extname(realPath).toLowerCase();
    if (!isSpiritFlixSmartVideoExtension(extension)) {
      return NextResponse.json({ error: "Smart analysis only supports supported video files." }, { status: 400 });
    }

    assertSmartVideoPathCandidate(realPath, { mediaRoot });

    // S6: reject all execute actions outright
    if (FORBIDDEN_EXECUTE_ACTIONS.has(action)) {
      return NextResponse.json(
        { error: `${action} is not available in smart tagging. File mutations require Level 2 preview â†’ confirm.` },
        { status: 400 },
      );
    }

    let analysis: SpiritFlixSmartAnalysis;
    if (action === "markReviewed") {
      analysis = await markSpiritFlixSmartAnalysisReviewed(realPath, { mediaRoot });
    } else if (action === "saveReview") {
      const review = assertSpiritFlixSmartReviewPayload(
        body.review ?? { approvedTagIds: [], rejectedTagIds: [] },
      );
      analysis = await saveSpiritFlixSmartAnalysisReview(realPath, review, { mediaRoot });
    } else if (action === "analyze") {
      analysis = await runSpiritFlixSmartReviewPipeline(realPath, { mediaRoot });
    } else if (action === "exportMetadata" || action === "confirmMetadata") {
      // S9: confirm approved metadata to admin metadata sidecar only
      const pathInput = { videoPath: realPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs };
      const loaded = await readSmartAnalysis(pathInput, { mediaRoot });
      if (!loaded) {
        return NextResponse.json({ error: "No smart analysis found for this video. Run analyze first." }, { status: 400 });
      }
      if (!loaded.reviewedMetadata || loaded.reviewedMetadata.reviewStatus === "unreviewed") {
        return NextResponse.json({ error: "Analysis must be reviewed before exporting metadata." }, { status: 400 });
      }
      const result = await writeApprovedSmartMetadataSidecar(loaded, { mediaRoot });
      const projection = projectApprovedSmartMetadata(loaded);
      return NextResponse.json({
        metadataPath: result.path,
        metadata: projection,
        confirmed: true,
      }, { headers: { "Cache-Control": "no-store" } });
    } else if (action === "prepareRenamePreview") {
      // S6: build rename preview draft â€” no execute, no Level 2 call
      const pathInput = { videoPath: realPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs };
      const loaded = await readSmartAnalysis(pathInput, { mediaRoot });
      if (!loaded) {
        return NextResponse.json({ error: "No smart analysis found for this video. Run analyze first." }, { status: 400 });
      }
      if (!loaded.reviewedMetadata || loaded.reviewedMetadata.reviewStatus === "unreviewed") {
        return NextResponse.json({ error: "Analysis must be reviewed before preparing rename preview." }, { status: 400 });
      }
      const projection = projectApprovedSmartMetadata(loaded);
      const filenameSuggestion = projection.filenameSuggestion;
      if (!filenameSuggestion) {
        return NextResponse.json({ error: "No filename suggestion available from reviewed metadata." }, { status: 400 });
      }
      const draft = buildSmartRenamePreviewDraft({
        sourcePath: realPath,
        filenameSuggestion,
      });
      return NextResponse.json({
        renamePreview: draft,
      }, { headers: { "Cache-Control": "no-store" } });
    } else {
      return NextResponse.json({ error: "Unsupported smart analysis action." }, { status: 400 });
    }

    const sidecarPath = getSmartAnalysisPath(
      { videoPath: realPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs },
      { mediaRoot },
    );

    return NextResponse.json({ analysis, sidecarPath }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return jsonError(error);
  }
}

import { NextRequest, NextResponse } from "next/server";
import { isSpiritFlixAdminPathError } from "@/lib/spiritflix/admin/paths";
import {
  buildSpiritFlixSmartRenamePlan,
  previewSpiritFlixSmartBatch,
  reviewSpiritFlixSmartBatch,
  runSpiritFlixSmartBatch,
  type SpiritFlixSmartBatchReviewMode,
} from "@/lib/spiritflix/admin/smart";

export const runtime = "nodejs";

function numberParam(value: unknown): number | undefined {
  if (typeof value === "number" && Number.isFinite(value)) return value;
  if (typeof value !== "string" || !value.trim()) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : undefined;
}

function boolParam(value: unknown): boolean {
  return value === true || value === "true";
}

function jsonError(error: unknown, fallbackStatus = 500) {
  if (isSpiritFlixAdminPathError(error)) {
    return NextResponse.json({ error: error instanceof Error ? error.message : "Invalid path." }, { status: 400 });
  }
  const message = error instanceof Error ? error.message : "Smart batch analysis failed.";
  const status = /requires a folder|path|outside|traversal|not allowed|selection|unsupported/i.test(message) ? 400 : fallbackStatus;
  return NextResponse.json({ error: message.slice(0, 500) }, { status });
}

export async function GET(request: NextRequest) {
  const url = new URL(request.url);
  try {
    const payload = await previewSpiritFlixSmartBatch({
      path: url.searchParams.get("path") ?? undefined,
      recursive: boolParam(url.searchParams.get("recursive")),
      maxItems: numberParam(url.searchParams.get("maxItems")),
    });
    return NextResponse.json(payload, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return jsonError(error);
  }
}

export async function POST(request: NextRequest) {
  let body: {
    path?: string;
    paths?: string[];
    action?: string;
    reviewMode?: string;
    recursive?: boolean;
    maxItems?: number;
    force?: boolean;
  };
  try {
    body = (await request.json()) as typeof body;
  } catch {
    return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const action = body.action?.trim() || "run";
  if (action !== "preview" && action !== "run" && action !== "review" && action !== "renamePlan") {
    return NextResponse.json({ error: "Unsupported smart batch action." }, { status: 400 });
  }

  try {
    const options = {
      path: body.path,
      paths: Array.isArray(body.paths) ? body.paths : undefined,
      recursive: Boolean(body.recursive),
      maxItems: numberParam(body.maxItems),
      force: Boolean(body.force),
    };
    const payload = action === "preview"
      ? await previewSpiritFlixSmartBatch(options)
      : action === "renamePlan"
        ? await buildSpiritFlixSmartRenamePlan(options)
        : action === "review"
          ? await reviewSpiritFlixSmartBatch({
              ...options,
              reviewMode: assertReviewMode(body.reviewMode),
            })
          : await runSpiritFlixSmartBatch(options);
    return NextResponse.json(payload, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    return jsonError(error);
  }
}

function assertReviewMode(value: unknown): SpiritFlixSmartBatchReviewMode {
  if (value === "approve_all_tags" || value === "reject_all_tags" || value === "mark_reviewed") {
    return value;
  }
  throw new Error("Unsupported smart batch review mode.");
}

import fs from "node:fs/promises";
import { NextRequest, NextResponse } from "next/server";
import { isSpiritFlixAdminPathError } from "@/lib/spiritflix/admin/paths";
import { getOrGenerateAdminVideoThumbnail } from "@/lib/spiritflix/admin/thumbnail";

export const runtime = "nodejs";

export async function GET(request: NextRequest) {
  const videoPath = new URL(request.url).searchParams.get("path")?.trim() ?? "";
  if (!videoPath) {
    return NextResponse.json({ error: "Missing video path." }, { status: 400 });
  }

  try {
    const result = await getOrGenerateAdminVideoThumbnail(videoPath);
    if (!result) {
      return NextResponse.json({ error: "Thumbnail unavailable." }, { status: 404 });
    }

    const image = await fs.readFile(result.cachePath);
    return new NextResponse(image, {
      status: 200,
      headers: {
        "Content-Type": "image/jpeg",
        "Cache-Control": "private, max-age=86400",
        "X-SpiritFlix-Thumbnail-Key": result.cacheKey,
      },
    });
  } catch (error) {
    if (isSpiritFlixAdminPathError(error)) {
      return NextResponse.json({ error: error instanceof Error ? error.message : "Invalid path." }, { status: 400 });
    }
    return NextResponse.json({ error: "Thumbnail generation failed." }, { status: 500 });
  }
}

import { readdir, readFile } from "node:fs/promises";
import path from "node:path";
import { NextRequest, NextResponse } from "next/server";
import type {
  FaceOrganizerMetadataResponse,
  FaceOrganizerPerformer,
  FaceOrganizerStatus,
  FaceOrganizerVideoMatch,
} from "@/lib/spiritflix-types";

interface FaceMetadataRequestItem {
  id?: string;
  name?: string;
  path?: string;
}

interface FaceMetadataRequest {
  items?: FaceMetadataRequestItem[];
}

interface SidecarPerformer {
  id?: string;
  name?: string;
  confidence?: number;
  similarity?: number;
  status?: string;
  verification_needed?: boolean;
}

interface FaceMatchDecision {
  decision?: string;
  performer_name?: string;
  performer_id?: string;
  visual_confirmed?: boolean;
}

interface FaceSidecar {
  video_path?: string;
  generated_at?: string;
  verification_needed?: boolean;
  performers?: SidecarPerformer[];
  faces_detected?: number;
  face_match_decisions?: FaceMatchDecision[];
}

const MEDIA_ROOTS = ["/mnt/spirit-8tb/media/yes", "/mnt/spirit-8tb/media/other"];
const KNOWN_PERFORMERS_INDEX = "/home/source/SpiritOS/scripts/media/known_performers/index.json";
const FACE_ENROLLED_GROUPS = "/home/source/SpiritOS/scripts/media/face_enrolled_performers.json";
const MODEL_INDEX = "/home/source/SpiritOS/scripts/media/model_index.json";
const HIGH_CONFIDENCE = 0.8;
const POSSIBLE_CONFIDENCE = 0.55;

function normalizeNameKey(value?: string): string {
  return (value ?? "").toLowerCase().replace(/[^a-z0-9]/g, "");
}

function normalizePathKey(value?: string): string {
  return (value ?? "")
    .replaceAll("\\", "/")
    .replace(/^\/DATA\//, "/mnt/spirit-8tb/media/")
    .replace(/^\/media\//, "/mnt/spirit-8tb/media/")
    .toLowerCase();
}

function basenameKey(value?: string): string {
  return path.basename(normalizePathKey(value)).toLowerCase();
}

function stemPathKey(value?: string): string {
  const normalized = normalizePathKey(value);
  const parsed = path.posix.parse(normalized);
  return path.posix.join(parsed.dir, parsed.name).toLowerCase();
}

function basenameStemKey(value?: string): string {
  return path.posix.parse(basenameKey(value)).name.toLowerCase();
}

function performerKeys(name?: string, id?: string): Set<string> {
  return new Set([name, id].map(normalizeNameKey).filter(Boolean));
}

function latestDecisionForPerformer(sidecar: FaceSidecar | undefined, performer: FaceOrganizerPerformer | undefined): FaceMatchDecision | undefined {
  if (!sidecar || !performer) return undefined;
  const targetKeys = performerKeys(performer.name, performer.id);
  for (const decision of [...(sidecar.face_match_decisions ?? [])].reverse()) {
    const keys = performerKeys(decision.performer_name, decision.performer_id);
    if ([...targetKeys].some((key) => keys.has(key))) return decision;
  }
  return undefined;
}

function toStatus(
  performers: FaceOrganizerPerformer[],
  verificationNeeded: boolean,
  sidecarFound: boolean,
  acceptedByUser: boolean,
): FaceOrganizerStatus {
  if (!sidecarFound) return "unscanned";
  const bestConfidence = Math.max(0, ...performers.map((performer) => performer.confidence ?? 0));
  const best = performers[0];
  if (acceptedByUser && best?.name && best.name !== "unknown performer") return "confirmed";
  if (best?.name && best.name !== "unknown performer" && bestConfidence >= HIGH_CONFIDENCE && !verificationNeeded) return "confirmed";
  if (bestConfidence >= POSSIBLE_CONFIDENCE) return "needs_review";
  return "unknown";
}

async function readKnownPerformers(): Promise<FaceOrganizerPerformer[]> {
  try {
    const parsed = JSON.parse(await readFile(KNOWN_PERFORMERS_INDEX, "utf8")) as {
      performers?: Array<{ id?: string; name?: string; aliases?: string[]; added_at?: string }>;
    };
    return (parsed.performers ?? [])
      .filter((performer) => performer.name)
      .map((performer) => ({
        id: performer.id,
        name: performer.name ?? "Unknown",
        aliases: performer.aliases ?? [],
        status: "verified",
        verificationNeeded: false,
        source: "known_performers",
      }));
  } catch {
    return [];
  }
}

async function readEnrolledSources(): Promise<NonNullable<FaceOrganizerMetadataResponse["enrolledSources"]>> {
  const enrolledSources: NonNullable<FaceOrganizerMetadataResponse["enrolledSources"]> = {};
  try {
    const parsed = JSON.parse(await readFile(FACE_ENROLLED_GROUPS, "utf8")) as {
      groups?: Array<{
        name?: string;
        slug?: string;
        candidate_videos?: number;
        enrolled_samples?: unknown[];
        recommendation_source_videos?: string[];
        recommendations_refreshed_at?: string;
      }>;
    };
    (parsed.groups ?? []).forEach((group) => {
      if (!group.name) return;
      const source = {
        name: group.name,
        slug: group.slug,
        candidateVideos: Math.max(0, group.candidate_videos ?? 0),
        enrolledScreens: Array.isArray(group.enrolled_samples) ? group.enrolled_samples.length : undefined,
        recommendationSourceVideos: group.recommendation_source_videos ?? [],
        refreshedAt: group.recommendations_refreshed_at,
        source: "enrolled" as const,
      };
      enrolledSources[normalizeNameKey(group.name)] = source;
      if (group.slug) enrolledSources[normalizeNameKey(group.slug)] = source;
    });
  } catch {
    // The enrolled page JSON is generated by the review server; SpiritFlix can still use the model index if it is absent.
  }

  try {
    const parsed = JSON.parse(await readFile(MODEL_INDEX, "utf8")) as {
      models?: Array<{ name?: string; slug?: string; aliases?: string[]; video_count?: number }>;
    };
    (parsed.models ?? []).forEach((model) => {
      if (!model.name) return;
      const keySet = new Set([model.name, model.slug, ...(model.aliases ?? [])].filter(Boolean).map((item) => normalizeNameKey(item)));
      const candidateVideos = Math.max(0, model.video_count ?? 0);
      const source = {
        name: model.name,
        slug: model.slug,
        candidateVideos,
        source: "model_index" as const,
      };
      keySet.forEach((key) => {
        if (!key) return;
        const current = enrolledSources[key];
        if (!current || candidateVideos > current.candidateVideos) {
          enrolledSources[key] = source;
        }
      });
    });
  } catch {
    // Keep face metadata usable even if the organizer model index has not been generated.
  }

  return enrolledSources;
}

async function findSidecars(root: string): Promise<string[]> {
  const entries = await readdir(root, { withFileTypes: true }).catch(() => []);
  const files = await Promise.all(
    entries.map(async (entry) => {
      const fullPath = path.join(root, entry.name);
      if (entry.isDirectory()) {
        if (entry.name === ".face-review") return [];
        return findSidecars(fullPath);
      }
      return entry.isFile() && entry.name.endsWith(".face-meta.json") ? [fullPath] : [];
    }),
  );
  return files.flat();
}

async function loadSidecarIndex(): Promise<Map<string, { path: string; data: FaceSidecar }>> {
  const sidecarPaths = (await Promise.all(MEDIA_ROOTS.map(findSidecars))).flat();
  const index = new Map<string, { path: string; data: FaceSidecar }>();

  await Promise.all(
    sidecarPaths.map(async (sidecarPath) => {
      try {
        const data = JSON.parse(await readFile(sidecarPath, "utf8")) as FaceSidecar;
        const videoPath = data.video_path
          ? normalizePathKey(data.video_path)
          : normalizePathKey(sidecarPath.replace(/\.face-meta\.json$/, ""));
        const bySidecarPath = normalizePathKey(sidecarPath.replace(/\.face-meta\.json$/, ""));
        const entry = { path: sidecarPath, data };
        index.set(videoPath, entry);
        index.set(bySidecarPath, entry);
        index.set(stemPathKey(videoPath), entry);
        index.set(stemPathKey(bySidecarPath), entry);
        index.set(basenameKey(videoPath), entry);
        index.set(basenameStemKey(videoPath), entry);
        index.set(basenameStemKey(bySidecarPath), entry);
      } catch {
        // Ignore malformed sidecars; the organizer can regenerate them.
      }
    }),
  );

  return index;
}

function toVideoMatch(item: FaceMetadataRequestItem, sidecar: { path: string; data: FaceSidecar } | undefined): FaceOrganizerVideoMatch {
  const performers = (sidecar?.data.performers ?? [])
    .map((performer): FaceOrganizerPerformer => ({
      id: performer.id,
      name: performer.name ?? "unknown performer",
      confidence: performer.confidence,
      similarity: performer.similarity,
      status: performer.status,
      verificationNeeded: performer.verification_needed,
      source: "sidecar",
    }))
    .sort((left, right) => (right.confidence ?? 0) - (left.confidence ?? 0));

  const verificationNeeded = sidecar?.data.verification_needed ?? performers.some((performer) => performer.verificationNeeded) ?? false;
  const primaryPerformer = performers[0];
  const latestDecision = latestDecisionForPerformer(sidecar?.data, primaryPerformer);
  const acceptedByUser = latestDecision?.decision === "accepted" && latestDecision.visual_confirmed === true;
  const status = toStatus(performers, verificationNeeded, Boolean(sidecar), acceptedByUser);
  const confidence = primaryPerformer?.confidence;
  const label =
    status === "confirmed" && primaryPerformer
      ? `Identified: ${primaryPerformer.name} (${Math.round((confidence ?? 0) * 100)}%)`
      : status === "needs_review" && primaryPerformer
        ? `Needs review: ${primaryPerformer.name} (${Math.round((confidence ?? 0) * 100)}%)`
        : status === "unknown"
          ? "Unknown performer"
          : "Unscanned";

  return {
    itemId: item.id ?? "",
    itemPath: item.path,
    sidecarPath: sidecar?.path,
    videoPath: sidecar?.data.video_path,
    primaryPerformer,
    performers,
    status,
    label,
    confidence,
    verificationNeeded,
    facesDetected: sidecar?.data.faces_detected,
    generatedAt: sidecar?.data.generated_at,
  };
}

export async function POST(request: NextRequest) {
  let payload: FaceMetadataRequest;
  try {
    payload = (await request.json()) as FaceMetadataRequest;
  } catch {
    return NextResponse.json({ error: "Invalid face metadata request." }, { status: 400 });
  }

  const items = (payload.items ?? []).filter((item) => item.id);
  const [knownPerformers, enrolledSources, sidecarIndex] = await Promise.all([
    readKnownPerformers(),
    readEnrolledSources(),
    loadSidecarIndex(),
  ]);
  const videos: FaceOrganizerMetadataResponse["videos"] = {};

  items.forEach((item) => {
    const normalizedPath = normalizePathKey(item.path);
    const match =
      sidecarIndex.get(normalizedPath) ||
      sidecarIndex.get(stemPathKey(item.path)) ||
      sidecarIndex.get(basenameKey(item.path)) ||
      sidecarIndex.get(basenameStemKey(item.path)) ||
      sidecarIndex.get(basenameKey(item.name)) ||
      sidecarIndex.get(basenameStemKey(item.name));
    videos[item.id ?? ""] = toVideoMatch(item, match);
  });

  const response: FaceOrganizerMetadataResponse = {
    knownPerformers,
    enrolledSources,
    videos,
    scannedCount: Object.values(videos).filter((video) => video.status !== "unscanned").length,
    generatedAt: new Date().toISOString(),
  };

  return NextResponse.json(response, {
    headers: {
      "Cache-Control": "no-store",
    },
  });
}

import { readFile, stat } from "node:fs/promises";
import path from "node:path";
import { NextRequest, NextResponse } from "next/server";

export const runtime = "nodejs";

const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp", ".gif"]);
const GALLERY_DIR_NAME = "model_gallery";

function galleryRootCandidates(): string[] {
  return [
    process.env.SPIRITFLIX_GALLERY_ROOT,
    "/home/source/SpiritOS/scripts/media/model_gallery",
    path.join(process.cwd(), "scripts", "media", GALLERY_DIR_NAME),
  ].filter((value): value is string => Boolean(value));
}

async function exists(target: string): Promise<boolean> {
  try {
    await stat(target);
    return true;
  } catch {
    return false;
  }
}

async function findGalleryRoot(): Promise<string> {
  for (const candidate of galleryRootCandidates()) {
    if (await exists(candidate)) return candidate;
  }
  return galleryRootCandidates()[0] ?? path.join(process.cwd(), "scripts", "media", GALLERY_DIR_NAME);
}

function contentTypeFor(fileName: string): string {
  const ext = path.extname(fileName).toLowerCase();
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".png") return "image/png";
  if (ext === ".webp") return "image/webp";
  if (ext === ".gif") return "image/gif";
  return "application/octet-stream";
}

function isSafeModelSlug(value: string): boolean {
  return /^[a-z0-9][a-z0-9-]*$/.test(value);
}

export async function GET(request: NextRequest) {
  const model = request.nextUrl.searchParams.get("model") ?? "";
  const file = request.nextUrl.searchParams.get("file") ?? "";
  if (!isSafeModelSlug(model) || !file || file !== path.basename(file) || !IMAGE_EXTENSIONS.has(path.extname(file).toLowerCase())) {
    return NextResponse.json({ error: "Invalid gallery image path." }, { status: 400 });
  }

  const galleryRoot = await findGalleryRoot();
  const modelRoot = path.resolve(galleryRoot, model);
  const target = path.resolve(modelRoot, file);
  if (target !== modelRoot && !target.startsWith(`${modelRoot}${path.sep}`)) {
    return NextResponse.json({ error: "Invalid gallery image path." }, { status: 400 });
  }

  try {
    const payload = await readFile(target);
    return new NextResponse(payload, {
      headers: {
        "Cache-Control": "no-store",
        "Content-Type": contentTypeFor(file),
      },
    });
  } catch {
    return NextResponse.json({ error: "Gallery image not found." }, { status: 404 });
  }
}

import { readdir, readFile, stat } from "node:fs/promises";
import path from "node:path";
import { NextResponse } from "next/server";
import type { SpiritFlixGalleryItem, SpiritFlixGalleryResponse } from "@/lib/spiritflix-types";

export const runtime = "nodejs";

const IMAGE_EXTENSIONS = new Set([".jpg", ".jpeg", ".png", ".webp", ".gif"]);
const GALLERY_DIR_NAME = "model_gallery";
const GALLERY_SIDECAR_SUFFIX = ".gallery.json";

interface EnrolledGroup {
  name?: string;
  slug?: string;
  model_slug?: string;
}

interface EnrolledPayload {
  groups?: EnrolledGroup[];
}

interface GallerySidecar {
  model_name?: string;
  model_key?: string;
  model_slug?: string;
  collection?: string;
  uploaded_at?: string;
  content_type?: string;
  size_bytes?: number;
}

function normalizeNameKey(value = ""): string {
  return value.toLowerCase().replace(/[^a-z0-9]/g, "");
}

function slugToName(slug: string): string {
  return slug
    .split("-")
    .filter(Boolean)
    .map((part) => part.slice(0, 1).toUpperCase() + part.slice(1))
    .join(" ") || "Gallery";
}

function galleryRootCandidates(): string[] {
  return [
    process.env.SPIRITFLIX_GALLERY_ROOT,
    "/home/source/SpiritOS/scripts/media/model_gallery",
    path.join(process.cwd(), "scripts", "media", GALLERY_DIR_NAME),
  ].filter((value): value is string => Boolean(value));
}

async function exists(target: string): Promise<boolean> {
  try {
    await stat(target);
    return true;
  } catch {
    return false;
  }
}

async function findGalleryRoot(): Promise<string> {
  for (const candidate of galleryRootCandidates()) {
    if (await exists(candidate)) return candidate;
  }
  return galleryRootCandidates()[0] ?? path.join(process.cwd(), "scripts", "media", GALLERY_DIR_NAME);
}

async function readJson<T>(target: string, fallback: T): Promise<T> {
  try {
    return JSON.parse(await readFile(target, "utf8")) as T;
  } catch {
    return fallback;
  }
}

async function readModelNames(galleryRoot: string): Promise<Map<string, string>> {
  const mediaDir = path.dirname(galleryRoot);
  const enrolled = await readJson<EnrolledPayload>(path.join(mediaDir, "face_enrolled_performers.json"), { groups: [] });
  const names = new Map<string, string>();
  for (const group of enrolled.groups ?? []) {
    const name = group.name?.trim();
    const slug = (group.model_slug ?? group.slug)?.trim();
    if (name && slug) names.set(slug, name);
  }
  return names;
}

async function readGallerySidecar(imagePath: string): Promise<GallerySidecar> {
  return readJson<GallerySidecar>(`${imagePath}${GALLERY_SIDECAR_SUFFIX}`, {});
}

function contentTypeFor(fileName: string, sidecar: GallerySidecar): string {
  if (sidecar.content_type?.startsWith("image/")) return sidecar.content_type;
  const ext = path.extname(fileName).toLowerCase();
  if (ext === ".jpg" || ext === ".jpeg") return "image/jpeg";
  if (ext === ".png") return "image/png";
  if (ext === ".webp") return "image/webp";
  if (ext === ".gif") return "image/gif";
  return "application/octet-stream";
}

async function scanGallery(): Promise<SpiritFlixGalleryResponse> {
  const galleryRoot = await findGalleryRoot();
  const modelNames = await readModelNames(galleryRoot);
  const entries = await readdir(galleryRoot, { withFileTypes: true }).catch(() => []);
  const items: SpiritFlixGalleryItem[] = [];

  for (const entry of entries) {
    if (!entry.isDirectory()) continue;
    const modelSlug = entry.name;
    const modelDir = path.join(galleryRoot, modelSlug);
    const files = await readdir(modelDir, { withFileTypes: true }).catch(() => []);
    for (const file of files) {
      if (!file.isFile()) continue;
      if (!IMAGE_EXTENSIONS.has(path.extname(file.name).toLowerCase())) continue;
      if (file.name.endsWith(GALLERY_SIDECAR_SUFFIX)) continue;
      const imagePath = path.join(modelDir, file.name);
      const [fileStat, sidecar] = await Promise.all([stat(imagePath), readGallerySidecar(imagePath)]);
      const modelName = sidecar.model_name ?? modelNames.get(modelSlug) ?? slugToName(modelSlug);
      const src = `/api/spiritflix/gallery/image?model=${encodeURIComponent(modelSlug)}&file=${encodeURIComponent(file.name)}`;
      items.push({
        id: `${modelSlug}/${file.name}`,
        modelName,
        modelKey: sidecar.model_key ?? normalizeNameKey(modelName),
        modelSlug,
        fileName: file.name,
        src,
        thumbnailSrc: src,
        collection: sidecar.collection ?? "",
        uploadedAt: sidecar.uploaded_at ?? fileStat.mtime.toISOString(),
        sizeBytes: sidecar.size_bytes ?? fileStat.size,
        contentType: contentTypeFor(file.name, sidecar),
      });
    }
  }

  items.sort((left, right) => (right.uploadedAt ?? "").localeCompare(left.uploadedAt ?? ""));
  const groups = Array.from(
    items.reduce((map, item) => {
      const current = map.get(item.modelSlug) ?? {
        name: item.modelName,
        modelKey: item.modelKey,
        modelSlug: item.modelSlug,
        itemCount: 0,
      };
      current.itemCount += 1;
      map.set(item.modelSlug, current);
      return map;
    }, new Map<string, SpiritFlixGalleryResponse["groups"][number]>()),
  ).map(([, group]) => group);

  return {
    schema: "spiritflix-model-gallery/v1",
    generatedAt: new Date().toISOString(),
    items,
    groups: groups.sort((left, right) => left.name.localeCompare(right.name)),
    summary: {
      galleryItems: items.length,
      modelsWithGallery: groups.length,
    },
  };
}

export async function GET() {
  const payload = await scanGallery();
  return NextResponse.json(payload, {
    headers: {
      "Cache-Control": "no-store",
    },
  });
}

import { NextRequest, NextResponse } from "next/server";
import { normalizeJellyfinServerUrl } from "@/lib/spiritflix-jellyfin-client";

const allowedHosts = new Set([
  "10.0.0.186:8096",
  "spirit.tailb69ea6.ts.net:8096",
  "100.111.32.31:8096",
  "127.0.0.1:8096",
  "localhost:8096",
]);

function isAllowedServer(serverUrl: string): boolean {
  try {
    const parsed = new URL(serverUrl);
    return (parsed.protocol === "http:" || parsed.protocol === "https:") && allowedHosts.has(parsed.host);
  } catch {
    return false;
  }
}

function isAllowedPath(path: string): boolean {
  return path.startsWith("/") && !path.startsWith("//") && !path.includes("://");
}

function proxyPath(serverUrl: string, token: string, path: string): string {
  const params = new URLSearchParams({
    serverUrl,
    token,
    path,
  });
  return `/api/spiritflix/hls?${params.toString()}`;
}

function rewritePlaylist(body: string, serverUrl: string, token: string, basePath: string): string {
  const base = new URL(basePath, "http://spiritflix.local");
  return body
    .split("\n")
    .map((line) => {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith("#")) return line;
      const resolved = new URL(trimmed, base);
      return proxyPath(serverUrl, token, `${resolved.pathname}${resolved.search}`);
    })
    .join("\n");
}

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const serverUrl = normalizeJellyfinServerUrl(searchParams.get("serverUrl") ?? "");
  const token = searchParams.get("token") ?? "";
  const path = searchParams.get("path") ?? "";

  if (!isAllowedServer(serverUrl) || !token || !isAllowedPath(path)) {
    return NextResponse.json({ error: "Invalid HLS request." }, { status: 400 });
  }

  const upstream = new URL(path, serverUrl);
  if (!upstream.searchParams.has("api_key")) upstream.searchParams.set("api_key", token);

  const headers: HeadersInit = {};
  const range = request.headers.get("Range");
  if (range) headers.Range = range;

  const response = await fetch(upstream, { headers });
  if (!response.body) {
    return NextResponse.json({ error: "HLS stream unavailable." }, { status: response.status });
  }

  const contentType = response.headers.get("Content-Type") ?? "";
  if (contentType.includes("mpegurl") || upstream.pathname.endsWith(".m3u8")) {
    const rewritten = rewritePlaylist(await response.text(), serverUrl, token, `${upstream.pathname}${upstream.search}`);
    return new NextResponse(rewritten, {
      status: response.status,
      headers: {
        "Content-Type": contentType || "application/vnd.apple.mpegurl",
        "Cache-Control": "private, max-age=10",
      },
    });
  }

  const passthrough = new Headers();
  [
    "Content-Type",
    "Content-Length",
    "Content-Range",
    "Accept-Ranges",
    "Cache-Control",
  ].forEach((header) => {
    const value = response.headers.get(header);
    if (value) passthrough.set(header, value);
  });

  return new NextResponse(response.body, {
    status: response.status,
    headers: passthrough,
  });
}

import { NextRequest, NextResponse } from "next/server";
import { normalizeJellyfinServerUrl } from "@/lib/spiritflix-jellyfin-client";

const allowedHosts = new Set([
  "spirit.tailb69ea6.ts.net:8096",
  "100.111.32.31:8096",
  "127.0.0.1:8096",
  "localhost:8096",
]);

interface ProxyBody {
  serverUrl?: string;
  path?: string;
  method?: string;
  body?: unknown;
  authorization?: string;
}

function isAllowedServer(serverUrl: string): boolean {
  try {
    const parsed = new URL(serverUrl);
    return (parsed.protocol === "http:" || parsed.protocol === "https:") && allowedHosts.has(parsed.host);
  } catch {
    return false;
  }
}

export async function POST(request: NextRequest) {
  let payload: ProxyBody;
  try {
    payload = (await request.json()) as ProxyBody;
  } catch {
    return NextResponse.json({ error: "Invalid proxy request." }, { status: 400 });
  }

  const serverUrl = normalizeJellyfinServerUrl(payload.serverUrl ?? "");
  const path = payload.path ?? "";
  const method = (payload.method ?? "GET").toUpperCase();

  if (!isAllowedServer(serverUrl)) {
    return NextResponse.json({ error: "That Jellyfin server is not allowed for SpiritFlix." }, { status: 400 });
  }

  if (!path.startsWith("/") || path.startsWith("//") || path.includes("://")) {
    return NextResponse.json({ error: "Invalid Jellyfin API path." }, { status: 400 });
  }

  if (!["DELETE", "GET", "POST"].includes(method)) {
    return NextResponse.json({ error: "Unsupported Jellyfin API method." }, { status: 405 });
  }

  const response = await fetch(`${serverUrl}${path}`, {
    method,
    headers: {
      Accept: "application/json",
      "Content-Type": "application/json",
      ...(payload.authorization ? { "X-Emby-Authorization": payload.authorization } : {}),
    },
    body: method === "POST" ? JSON.stringify(payload.body ?? {}) : undefined,
  });

  if (response.status === 204) {
    return new NextResponse(null, {
      status: 204,
      headers: {
        "Content-Type": response.headers.get("Content-Type") ?? "application/json",
      },
    });
  }

  const text = await response.text();
  return new NextResponse(text, {
    status: response.status,
    headers: {
      "Content-Type": response.headers.get("Content-Type") ?? "application/json",
    },
  });
}

import { NextRequest, NextResponse } from "next/server";
import { normalizeJellyfinServerUrl } from "@/lib/spiritflix-jellyfin-client";

const allowedHosts = new Set([
  "10.0.0.186:8096",
  "spirit.tailb69ea6.ts.net:8096",
  "100.111.32.31:8096",
  "127.0.0.1:8096",
  "localhost:8096",
]);

function isAllowedServer(serverUrl: string): boolean {
  try {
    const parsed = new URL(serverUrl);
    return (parsed.protocol === "http:" || parsed.protocol === "https:") && allowedHosts.has(parsed.host);
  } catch {
    return false;
  }
}

export async function POST(request: NextRequest) {
  const payload = (await request.json()) as {
    serverUrl?: string;
    path?: string;
    authorization?: string;
  };
  const serverUrl = normalizeJellyfinServerUrl(payload.serverUrl ?? "");
  const path = payload.path ?? "";

  if (!isAllowedServer(serverUrl) || !path.startsWith("/") || path.startsWith("//") || path.includes("://")) {
    return NextResponse.json({ error: "Invalid image request." }, { status: 400 });
  }

  const response = await fetch(`${serverUrl}${path}`, {
    headers: {
      ...(payload.authorization ? { "X-Emby-Authorization": payload.authorization } : {}),
    },
  });

  if (!response.ok || !response.body) {
    return NextResponse.json({ error: "Image unavailable." }, { status: response.status });
  }

  return new NextResponse(response.body, {
    status: response.status,
    headers: {
      "Content-Type": response.headers.get("Content-Type") ?? "image/jpeg",
      "Cache-Control": "private, max-age=300",
    },
  });
}

import { NextRequest, NextResponse } from "next/server";
import { normalizeJellyfinServerUrl } from "@/lib/spiritflix-jellyfin-client";

const allowedHosts = new Set([
  "10.0.0.186:8096",
  "spirit.tailb69ea6.ts.net:8096",
  "100.111.32.31:8096",
  "127.0.0.1:8096",
  "localhost:8096",
]);

function isAllowedServer(serverUrl: string): boolean {
  try {
    const parsed = new URL(serverUrl);
    return (parsed.protocol === "http:" || parsed.protocol === "https:") && allowedHosts.has(parsed.host);
  } catch {
    return false;
  }
}

export async function GET(request: NextRequest) {
  const searchParams = request.nextUrl.searchParams;
  const serverUrl = normalizeJellyfinServerUrl(searchParams.get("serverUrl") ?? "");
  const itemId = searchParams.get("itemId") ?? "";
  const token = searchParams.get("token") ?? "";

  if (!isAllowedServer(serverUrl) || !/^[a-fA-F0-9-]+$/.test(itemId) || !token) {
    return NextResponse.json({ error: "Invalid stream request." }, { status: 400 });
  }

  const upstream = new URL(`${serverUrl}/Videos/${itemId}/Stream`);
  upstream.searchParams.set("Static", "true");
  upstream.searchParams.set("api_key", token);
  upstream.searchParams.set("PlaySessionId", `spiritflix-${itemId}`);

  const headers: HeadersInit = {};
  const range = request.headers.get("Range");
  if (range) headers.Range = range;

  const response = await fetch(upstream, { headers });
  if (!response.body) {
    return NextResponse.json({ error: "Stream unavailable." }, { status: response.status });
  }

  const passthrough = new Headers();
  [
    "Content-Type",
    "Content-Length",
    "Content-Range",
    "Accept-Ranges",
    "Cache-Control",
  ].forEach((header) => {
    const value = response.headers.get(header);
    if (value) passthrough.set(header, value);
  });

  return new NextResponse(response.body, {
    status: response.status,
    headers: passthrough,
  });
}

