import type { JellyfinItem } from "@/lib/spiritflix-types";

const item: JellyfinItem = {
  Id: "video-1",
  Name: "Fold Tap Test",
  Type: "Video",
  RunTimeTicks: 1200000000,
  UserData: {
    IsFavorite: false,
