      { id: "folder:anime", name: "anime", type: "folder", path: `${SPIRITFLIX_MEDIA_ROOT}/anime`, parentPath: SPIRITFLIX_MEDIA_ROOT, dateModified: "2026-06-15T12:00:00.000Z" },
