        sizeBytes: 1024,
        dateModified: "2026-06-14T12:00:00.000Z",
        playable: true,
      },
    ],
  };
}

function mockAdminFetch() {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (input: RequestInfo | URL, init?: RequestInit) => {
      const url = String(input);
      if (url.startsWith("/api/spiritflix/admin/jellyfin-index")) {
        return Response.json({ items: [], source: "unconfigured" });
      }
      if (url.startsWith("/api/spiritflix/admin/thumbnail")) {
        return new Response(new Blob([new Uint8Array([0xff, 0xd8, 0xff, 0xd9])]), { status: 200, headers: { "Content-Type": "image/jpeg" } });
      }
      if (url.startsWith("/api/spiritflix/admin/fs")) {
        return Response.json(yesFolderPayload());
      }
      if (url.startsWith("/api/spiritflix/admin/smart/analysis")) {
        return Response.json({ analysis: null, sidecarPath: null });
      }
      if (url.startsWith("/api/spiritflix/admin/smart/batch")) {
        const body = init?.body ? JSON.parse(String(init.body)) as { action?: string } : {};
        if (body.action === "renamePlan") {
          return Response.json({
            schema: "spiritflix-smart-rename-plan/v1",
            generatedAt: "2026-06-18T12:00:00.000Z",
            rootPath: `${SPIRITFLIX_MEDIA_ROOT}/yes`,
            recursive: false,
            maxItems: 50,
            applyEnabled: false,
            applyGate: "Real rename/move apply is disabled until Britton explicitly approves a future apply task.",
            counts: {
              candidates: 1,
              ready: 1,
              blocked: 0,
              needs_review: 0,
              skipped: 0,
              collisions: 0,
              target_conflicts: 0,
            },
            items: [
              {
                sourcePath: "/mnt/spirit-8tb/media/yes/Beta Clip.mp4",
                currentName: "Beta Clip.mp4",
                suggestedName: "Beta Clip HD.mp4",
                targetPath: "/mnt/spirit-8tb/media/yes/Beta Clip HD.mp4",
                status: "ready",
                reviewStatus: "reviewed",
                approvedTags: ["HD"],
                rejectedTagIds: [],
                warnings: [],
                readyForLevel2Preview: true,
              },
            ],
          });
        }
        return Response.json({
          schema: "spiritflix-smart-batch/v1",
          generatedAt: "2026-06-18T12:00:00.000Z",
          mode: "preview",
          rootPath: `${SPIRITFLIX_MEDIA_ROOT}/yes`,
          recursive: false,
          maxItems: 12,
          counts: {
            candidates: 2,
            analyzed: 0,
            skipped: 0,
            already_current: 0,
            failed: 0,
            needs_review: 0,
            rename_preview_available: 0,
          },
          visualContentTaggingEnabled: false,
          visualContentTaggingMessage: "Analyze folder samples frames and asks the local visual model for review-required content tags. No tags or names are applied until confirm.",
          items: [
            {
              path: "/mnt/spirit-8tb/media/yes/Beta Clip.mp4",
              name: "Beta Clip.mp4",
              parentPath: "/mnt/spirit-8tb/media/yes",
              extension: ".mp4",
              status: "candidate",
              sidecarCurrent: false,
              needsReview: false,
              suggestedTagCount: 0,
              renamePreviewAvailable: false,
              reviewStatus: "unreviewed",
              analysisStatus: "needs_review",
              tags: [{ id: "watermark", label: "Watermark", group: "watermark", confidence: 0.68, reviewRequired: true, reviewState: "pending" }],
              qualityBadges: [{ id: "hd", label: "HD", group: "quality", confidence: 0.92, reviewRequired: false, reviewState: "pending" }],
              modelName: "Unknown Model",
              modelSource: "unknown",
              nameReason: "Readable title preserved; extension is kept only for target-path preview.",
              visualTaggingAvailable: false,
              approvedTagCount: 0,
              rejectedTagCount: 0,
              pendingTagCount: 1,
              renamePreviewStatus: "provisional",
              proposedFilename: "Beta Clip HD",
              proposedTargetPath: "/mnt/spirit-8tb/media/yes/Beta Clip HD.mp4",
              renameBlocker: "Review or approve tags/metadata to unlock rename preview.",
              renameWarnings: ["Provisional preview, not eligible for apply until reviewed."],
              sidecarRef: "analysis/abc123def456.json",
            },
          ],
        });
      }
      return Response.json({ items: [] });
    }),
  );
}

describe("SpiritFlix admin Level 2R interactions", () => {
