"use client";

import { useCallback, useState } from "react";
import { Heart, Star } from "lucide-react";
import type { JellyfinClient } from "@/lib/spiritflix-jellyfin-client";
import { formatBytes, formatItemDateLabel } from "@/lib/spiritflix/admin/format";
import type { SpiritFlixAdminItem } from "@/lib/spiritflix/admin/types";
import { SpiritFlixAdminContextMenu } from "./SpiritFlixAdminContextMenu";
import { SpiritFlixAdminItemMenuButton } from "./SpiritFlixAdminItemMenuButton";
import { buildItemMenuItems, type SpiritFlixAdminMenuActionId } from "./item-menu";
import type { SpiritFlixAdminViewMode } from "./SpiritFlixAdminToolbar";
import { SpiritFlixAdminThumbnail } from "./SpiritFlixAdminThumbnail";

interface SpiritFlixAdminTableProps {
  items: SpiritFlixAdminItem[];
  jellyfinClient?: JellyfinClient;
  loading: boolean;
  selectedItem: SpiritFlixAdminItem | null;
  serverImageProxy?: boolean;
  viewMode: SpiritFlixAdminViewMode;
  onBrowsePath: (path: string) => void;
  onSelectItem: (item: SpiritFlixAdminItem | null) => void;
  onMenuAction: (actionId: SpiritFlixAdminMenuActionId, item: SpiritFlixAdminItem | null) => void;
}

function cardMeta(item: SpiritFlixAdminItem): string {
  const date = formatItemDateLabel(item);
  const parts: string[] = [];

  if (item.type === "folder") {
    if (date.text) parts.push(`${date.label} ${date.text}`.trim());
    return parts.join(" Â· ");
  }

  if (date.text) parts.push(`${date.label} ${date.text}`.trim());
  const size = formatBytes(item.sizeBytes);
  if (size) parts.push(size);

  return parts.join(" Â· ");
}

export function SpiritFlixAdminTable({
  items,
  jellyfinClient,
  loading,
  selectedItem,
  serverImageProxy,
  viewMode,
  onBrowsePath,
  onSelectItem,
  onMenuAction,
}: SpiritFlixAdminTableProps) {
  const [openMenuItemId, setOpenMenuItemId] = useState<string | null>(null);
  const [menuPosition, setMenuPosition] = useState<{ x: number; y: number } | null>(null);
  const [contextItem, setContextItem] = useState<SpiritFlixAdminItem | null>(null);

  const closeMenu = useCallback(() => {
    setOpenMenuItemId(null);
    setMenuPosition(null);
    setContextItem(null);
  }, []);

  const openContextMenu = useCallback((event: React.MouseEvent, item: SpiritFlixAdminItem) => {
    event.preventDefault();
    event.stopPropagation();
    onSelectItem(item);
    setContextItem(item);
    setOpenMenuItemId(null);
    setMenuPosition({ x: event.clientX, y: event.clientY });
  }, [onSelectItem]);

  const handleCardClick = useCallback(
    (item: SpiritFlixAdminItem) => {
      onSelectItem(item);
    },
    [onSelectItem],
  );

  const handleCardDoubleClick = useCallback(
    (item: SpiritFlixAdminItem) => {
      if (item.type === "folder" && item.path) {
        onBrowsePath(item.path);
        return;
      }
      if (item.jellyfinItemId || item.jellyfinId) {
        window.location.assign(`/spiritflix?item=${encodeURIComponent(item.jellyfinItemId ?? item.jellyfinId ?? "")}`);
      }
    },
    [onBrowsePath],
  );

  if (loading) {
    return <div className="spiritflix-admin-empty">Loading files...</div>;
  }

  if (!items.length) {
    return <div className="spiritflix-admin-empty">No files or folders here.</div>;
  }

  const contextMenuItems = contextItem ? buildItemMenuItems(contextItem, "") : [];

  return (
    <div className={`spiritflix-admin-items is-${viewMode}`}>
      <table className="spiritflix-admin-table" aria-hidden={viewMode === "grid"}>
        <thead>
          <tr>
            <th>Name</th>
            <th>Library</th>
            <th>Type</th>
            <th>Size</th>
            <th>Date</th>
            <th>State</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {items.map((item) => {
            const date = formatItemDateLabel(item);
            const menuItems = buildItemMenuItems(item, "");
            const menuOpen = openMenuItemId === item.id && viewMode === "list";
            return (
              <tr
                className={selectedItem?.id === item.id ? "is-selected" : ""}
                data-testid="admin-item-row"
                key={item.id}
                onClick={() => handleCardClick(item)}
                onContextMenu={(event) => openContextMenu(event, item)}
                onDoubleClick={() => handleCardDoubleClick(item)}
              >
                <td>
                  <div className="spiritflix-admin-name-button">
                    <SpiritFlixAdminThumbnail compact client={jellyfinClient} item={item} serverImageProxy={serverImageProxy} />
                    <span>{item.name}</span>
                  </div>
                </td>
                <td>{item.libraryName ?? ""}</td>
                <td>{item.itemType ?? item.type}</td>
                <td>{formatBytes(item.sizeBytes)}</td>
                <td>{date.text ? `${date.label} ${date.text}`.trim() : ""}</td>
                <td>
                  <span className="spiritflix-admin-state-icons">
                    {item.watched ? <Star size={15} aria-label="Watched" /> : null}
                    {item.favorite ? <Heart size={15} aria-label="Favorite" /> : null}
                  </span>
                </td>
                <td>
                  <SpiritFlixAdminItemMenuButton
                    itemLabel={item.name}
                    items={menuItems}
                    open={menuOpen}
                    position={menuOpen ? menuPosition : null}
                    onClose={closeMenu}
                    onOpen={(position) => {
                      onSelectItem(item);
                      setContextItem(null);
                      setOpenMenuItemId(item.id);
                      setMenuPosition(position);
                    }}
                    onSelect={(actionId) => onMenuAction(actionId, item)}
                  />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>

      <div
        className="spiritflix-admin-card-list"
        aria-hidden={viewMode === "list"}
        onContextMenu={(event) => {
          if ((event.target as HTMLElement).closest("[data-testid='admin-item-card']")) return;
          event.preventDefault();
        }}
      >
        {items.map((item) => {
          const menuItems = buildItemMenuItems(item, "");
          const menuOpen = openMenuItemId === item.id && viewMode === "grid";
          return (
            <div
              className={`spiritflix-admin-card${selectedItem?.id === item.id ? " is-selected" : ""}`}
              data-testid="admin-item-card"
              data-image-status={item.imageStatus ?? "missing"}
              data-jellyfin-match={item.jellyfinMatchedBy ?? "none"}
              key={item.id}
              role="button"
              tabIndex={0}
              title={item.path}
              onClick={() => handleCardClick(item)}
              onContextMenu={(event) => openContextMenu(event, item)}
              onDoubleClick={() => handleCardDoubleClick(item)}
              onKeyDown={(event) => {
                if (event.key === "Enter") handleCardDoubleClick(item);
                if (event.key === " ") {
                  event.preventDefault();
                  handleCardClick(item);
                }
              }}
            >
              <SpiritFlixAdminThumbnail client={jellyfinClient} item={item} serverImageProxy={serverImageProxy} />
              <span className="spiritflix-admin-card-title">{item.name}</span>
              <span className="spiritflix-admin-card-meta">{cardMeta(item)}</span>
              <SpiritFlixAdminItemMenuButton
                itemLabel={item.name}
                items={menuItems}
                open={menuOpen}
                position={menuOpen ? menuPosition : null}
                onClose={closeMenu}
                onOpen={(position) => {
                  onSelectItem(item);
                  setContextItem(null);
                  setOpenMenuItemId(item.id);
                  setMenuPosition(position);
                }}
                onSelect={(actionId) => onMenuAction(actionId, item)}
              />
            </div>
          );
        })}
      </div>

      {contextItem && menuPosition && !openMenuItemId ? (
        <SpiritFlixAdminContextMenu
          items={contextMenuItems}
          position={menuPosition}
          onClose={closeMenu}
          onSelect={(actionId) => onMenuAction(actionId, contextItem)}
        />
      ) : null}
    </div>
  );
}

"use client";

import Image from "next/image";
import { useEffect, useMemo, useState } from "react";
import { FileJson, FileVideo, Folder, Play } from "lucide-react";
import type { JellyfinClient } from "@/lib/spiritflix-jellyfin-client";
import type { SpiritFlixAdminItem } from "@/lib/spiritflix/admin/types";
import { SpiritFlixImage } from "../SpiritFlixImage";

export type SpiritFlixAdminThumbnailSource = "jellyfin" | "local" | "fallback";

interface SpiritFlixAdminThumbnailProps {
  client?: JellyfinClient;
  item: SpiritFlixAdminItem;
  compact?: boolean;
  serverImageProxy?: boolean;
  onSourceChange?: (source: SpiritFlixAdminThumbnailSource) => void;
}

type ThumbnailStage = "jellyfin-client" | "jellyfin-server" | "local" | "fallback";

function fallbackIcon(item: SpiritFlixAdminItem) {
  if (item.type === "folder") return <Folder size={28} aria-hidden="true" />;
  if (item.extension?.includes("json")) return <FileJson size={24} aria-hidden="true" />;
  if (item.playable) return <Play size={26} aria-hidden="true" />;
  return <FileVideo size={24} aria-hidden="true" />;
}

function imageTagForItem(item: SpiritFlixAdminItem): string | undefined {
  if (!item.jellyfinItem || !item.imageType) return undefined;
  if (item.imageType === "Backdrop") return item.jellyfinItem.BackdropImageTags?.[0];
  return item.jellyfinItem.ImageTags?.[item.imageType];
}

function stageToSource(stage: ThumbnailStage): SpiritFlixAdminThumbnailSource {
  if (stage === "jellyfin-client" || stage === "jellyfin-server") return "jellyfin";
  if (stage === "local") return "local";
  return "fallback";
}

function AdminServerImage({
  alt,
  compact,
  item,
  onFailed,
}: {
  alt: string;
  compact: boolean;
  item: SpiritFlixAdminItem;
  onFailed: () => void;
}) {
  const [failed, setFailed] = useState(false);
  const width = compact ? 96 : 360;
  const itemId = item.jellyfinItemId ?? item.jellyfinId;
  const tag = imageTagForItem(item);

  useEffect(() => {
    if (failed) onFailed();
  }, [failed, onFailed]);

  if (!itemId || !item.imageType || failed) {
    return <span className="spiritflix-admin-thumbnail__fallback">{fallbackIcon(item)}</span>;
  }

  const query = new URLSearchParams({
    itemId,
    type: item.imageType,
    width: String(width),
    ...(tag ? { tag } : {}),
  });

  return (
    <Image
      src={`/api/spiritflix/admin/image?${query.toString()}`}
      alt={alt}
      loading="lazy"
      width={width}
      height={Math.round(width * 1.5)}
      unoptimized
      onError={() => setFailed(true)}
    />
  );
}

function LocalVideoThumbnail({
  alt,
  compact,
  item,
  onFailed,
}: {
  alt: string;
  compact: boolean;
  item: SpiritFlixAdminItem;
  onFailed: () => void;
}) {
  const [failed, setFailed] = useState(false);
  const width = compact ? 96 : 360;

  useEffect(() => {
    if (failed) onFailed();
  }, [failed, onFailed]);

  if (!item.path || failed) {
    return <span className="spiritflix-admin-thumbnail__fallback">{fallbackIcon(item)}</span>;
  }

  const query = new URLSearchParams({ path: item.path });

  return (
    <Image
      src={`/api/spiritflix/admin/thumbnail?${query.toString()}`}
      alt={alt}
      loading="lazy"
      width={width}
      height={Math.round(width * 0.56)}
      unoptimized
      data-thumbnail-source="local"
      onError={() => setFailed(true)}
    />
  );
}

export function SpiritFlixAdminThumbnail({ client, item, compact = false, serverImageProxy = false, onSourceChange }: SpiritFlixAdminThumbnailProps) {
  const canShowJellyfinImage =
    Boolean(item.jellyfinItem) &&
    Boolean(item.imageType) &&
    item.imageStatus === "available" &&
    item.type !== "folder";

  const canUseClientImage = canShowJellyfinImage && Boolean(client);
  const canUseServerImage = canShowJellyfinImage && serverImageProxy && Boolean(item.jellyfinItemId ?? item.jellyfinId);
  const canUseLocalThumbnail = item.playable && Boolean(item.path) && item.type !== "folder";

  const initialStage = useMemo<ThumbnailStage>(() => {
    if (canUseClientImage) return "jellyfin-client";
    if (canUseServerImage) return "jellyfin-server";
    if (canUseLocalThumbnail) return "local";
    return "fallback";
  }, [canUseClientImage, canUseLocalThumbnail, canUseServerImage, item.id]);

  const [stage, setStage] = useState<ThumbnailStage>(initialStage);

  useEffect(() => {
    setStage(initialStage);
  }, [initialStage]);

  const source = stageToSource(stage);

  useEffect(() => {
    onSourceChange?.(source);
  }, [onSourceChange, source]);

  const advanceFromJellyfin = () => {
    setStage(canUseLocalThumbnail ? "local" : "fallback");
  };

  const showPlayBadge = item.playable && source !== "fallback";

  let body: React.ReactNode;
  if (stage === "jellyfin-client" && client && item.jellyfinItem && item.imageType) {
    body = (
      <SpiritFlixImage
        client={client}
        item={item.jellyfinItem}
        type={item.imageType}
        width={compact ? 96 : 360}
        alt={item.name}
        fallback={
          canUseLocalThumbnail ? (
            <LocalVideoThumbnail alt={item.name} compact={compact} item={item} onFailed={() => setStage("fallback")} />
          ) : (
            <span className="spiritflix-admin-thumbnail__fallback">{fallbackIcon(item)}</span>
          )
        }
      />
    );
  } else if (stage === "jellyfin-server") {
    body = <AdminServerImage alt={item.name} compact={compact} item={item} onFailed={advanceFromJellyfin} />;
  } else if (stage === "local") {
    body = <LocalVideoThumbnail alt={item.name} compact={compact} item={item} onFailed={() => setStage("fallback")} />;
  } else {
    body = <span className="spiritflix-admin-thumbnail__fallback">{fallbackIcon(item)}</span>;
  }

  return (
    <span
      className={`spiritflix-admin-thumbnail${compact ? " is-compact" : ""}${source !== "fallback" ? " has-image" : ""}`}
      data-image-status={item.imageStatus ?? "missing"}
      data-match={item.jellyfinMatchedBy ?? "none"}
      data-thumbnail-source={source}
    >
      {body}
      {showPlayBadge ? (
        <span className="spiritflix-admin-thumbnail__play" aria-hidden="true">
          <Play size={compact ? 13 : 17} />
        </span>
      ) : null}
    </span>
  );
}

"use client";

import { ArrowDownAZ, ArrowUpAZ, FileJson, Grid2X2, List, RefreshCw, Search, Sparkles, Upload } from "lucide-react";
import { SPIRITFLIX_ADMIN_LEVEL2_GATE_MESSAGE, SPIRITFLIX_ADMIN_LEVEL2_GATED } from "@/lib/spiritflix/admin/constants";
import type { SpiritFlixAdminSortBy, SpiritFlixAdminSortOrder } from "@/lib/spiritflix/admin/types";

export type SpiritFlixAdminViewMode = "grid" | "list";

interface SpiritFlixAdminToolbarProps {
  includeMetadataFiles: boolean;
  loading: boolean;
  searchTerm: string;
  sortBy: SpiritFlixAdminSortBy;
  sortOrder: SpiritFlixAdminSortOrder;
  viewMode: SpiritFlixAdminViewMode;
  onIncludeMetadataFilesChange: (value: boolean) => void;
  onBatchSmartAnalyze: () => void;
  onManage: () => void;
  onRefresh: () => void;
  onSearchTermChange: (value: string) => void;
  onSortByChange: (value: SpiritFlixAdminSortBy) => void;
  onSortOrderChange: (value: SpiritFlixAdminSortOrder) => void;
  onViewModeChange: (value: SpiritFlixAdminViewMode) => void;
}

const sortOptions: Array<{ label: string; value: SpiritFlixAdminSortBy }> = [
  { label: "Name A-Z", value: "title" },
  { label: "Date added", value: "dateAdded" },
  { label: "Date modified", value: "dateModified" },
  { label: "Size", value: "size" },
  { label: "Runtime", value: "runtime" },
  { label: "Folder/path", value: "path" },
];

export function SpiritFlixAdminToolbar({
  includeMetadataFiles,
  loading,
  searchTerm,
  sortBy,
  sortOrder,
  viewMode,
  onIncludeMetadataFilesChange,
  onBatchSmartAnalyze,
  onManage,
  onRefresh,
  onSearchTermChange,
  onSortByChange,
  onSortOrderChange,
  onViewModeChange,
}: SpiritFlixAdminToolbarProps) {
  return (
    <header className="spiritflix-admin-toolbar">
      <p className="spiritflix-admin-toolbar__title">Files</p>
      <label className="spiritflix-admin-search">
        <Search size={18} aria-hidden="true" />
        <input
          aria-label="Search admin media"
          value={searchTerm}
          onChange={(event) => onSearchTermChange(event.target.value)}
