        />
      </label>
      <label className="spiritflix-admin-select">
        <span>Sort</span>
        <select aria-label="Sort admin media" value={sortBy} onChange={(event) => onSortByChange(event.target.value as SpiritFlixAdminSortBy)}>
          {sortOptions.map((option) => (
            <option key={option.value} value={option.value}>
              {option.label}
            </option>
          ))}
        </select>
      </label>
      <button
        className="spiritflix-admin-icon-button"
        type="button"
        aria-label={sortOrder === "asc" ? "Sort descending" : "Sort ascending"}
        onClick={() => onSortOrderChange(sortOrder === "asc" ? "desc" : "asc")}
      >
        {sortOrder === "asc" ? <ArrowDownAZ size={18} aria-hidden="true" /> : <ArrowUpAZ size={18} aria-hidden="true" />}
      </button>
      <div className="spiritflix-admin-view-toggle" role="group" aria-label="Admin view mode">
        <button className={viewMode === "grid" ? "is-active" : ""} type="button" aria-label="Grid view" onClick={() => onViewModeChange("grid")}>
          <Grid2X2 size={18} aria-hidden="true" />
        </button>
        <button className={viewMode === "list" ? "is-active" : ""} type="button" aria-label="List view" onClick={() => onViewModeChange("list")}>
          <List size={18} aria-hidden="true" />
        </button>
      </div>
      <label className="spiritflix-admin-check">
        <input type="checkbox" checked={includeMetadataFiles} onChange={(event) => onIncludeMetadataFilesChange(event.target.checked)} />
        <FileJson size={17} aria-hidden="true" />
        Show metadata
      </label>
      <button
        className="spiritflix-admin-manage-action"
        type="button"
        aria-label="Batch smart analyze"
        onClick={onBatchSmartAnalyze}
      >
        <Sparkles size={17} aria-hidden="true" />
        Batch smart
      </button>
      <button
        className="spiritflix-admin-manage-action"
        type="button"
        disabled={SPIRITFLIX_ADMIN_LEVEL2_GATED}
        title={SPIRITFLIX_ADMIN_LEVEL2_GATED ? SPIRITFLIX_ADMIN_LEVEL2_GATE_MESSAGE : "Preview and confirm guarded file actions"}
        aria-label="Manage"
        onClick={onManage}
      >
        <Upload size={17} aria-hidden="true" />
        Manage
      </button>
      <button className="spiritflix-admin-icon-button" type="button" aria-label="Refresh admin listing" onClick={onRefresh}>
        <RefreshCw className={loading ? "is-spinning" : ""} size={18} aria-hidden="true" />
      </button>
    </header>
  );
}

"use client";

import { useCallback, useState } from "react";
import { createPortal } from "react-dom";
import { CheckCircle2, Download, FolderSearch, RotateCw, ShieldAlert, X } from "lucide-react";
import type {
  SpiritFlixSmartBatchItem,
  SpiritFlixSmartBatchPreview,
  SpiritFlixSmartBatchReviewMode,
  SpiritFlixSmartRenamePlan,
} from "@/lib/spiritflix/admin/smart";

interface SpiritFlixSmartBatchPanelProps {
  currentPath: string;
  open: boolean;
  onClose: () => void;
}

interface BatchResponse extends SpiritFlixSmartBatchPreview {
  error?: string;
}

interface RenamePlanResponse extends SpiritFlixSmartRenamePlan {
  error?: string;
}

function statusLabel(status: string): string {
  if (status === "already_current") return "current";
  return status.replace(/_/g, " ");
}

function formatConfidence(value: number): string {
  return `${Math.round(value * 100)}%`;
}

function renameStatusLabel(item: SpiritFlixSmartBatchItem): string {
  if (item.renamePreviewStatus === "ready") return "Rename preview ready";
  if (item.renamePreviewStatus === "provisional") return "Provisional preview";
  if (item.renamePreviewStatus === "needs_review") return "Needs review first";
  if (item.renamePreviewStatus === "missing_suggestion") return "No approved filename";
  if (item.renamePreviewStatus === "blocked") return "Rename preview blocked";
  return "Rename preview unavailable";
}

function operatorStatus(item: SpiritFlixSmartBatchItem): string {
  if (item.status === "failed") return "failed";
  if (item.reviewStatus === "reviewed") return "reviewed";
  if (item.needsReview || item.pendingTagCount > 0 || item.renamePreviewStatus === "needs_review") return "needs review";
  if (item.status === "analyzed" || item.status === "already_current" || item.sidecarCurrent) return "analyzed";
  return "candidate";
}

function tagEmptyMessage(result: SpiritFlixSmartBatchPreview, item: SpiritFlixSmartBatchItem): string {
  if (result.mode === "preview" && item.status === "candidate") return "No tags yet - run Analyze folder";
  if (!item.sidecarCurrent && !item.analysisStatus) return "No tags yet - run Analyze folder";
  if (!item.visualTaggingAvailable) return "No content tags yet";
  return "No content tags found";
}

function recommendedNameMessage(item: SpiritFlixSmartBatchItem): { title: string; detail?: string; blocked?: boolean } {
  if (item.proposedFilename && item.renamePreviewStatus === "ready") {
    return { title: item.proposedFilename, detail: "Ready recommended name" };
  }
  if (item.proposedFilename) {
    return { title: item.proposedFilename, detail: "Provisional recommended name, not apply-ready" };
  }
  if (!item.sidecarCurrent && !item.analysisStatus) return { title: "Run Analyze folder first" };
  if (item.reviewStatus === "unreviewed" || item.renamePreviewStatus === "needs_review") {
    return { title: "Review/approve tags to unlock final rename preview" };
  }
  if (item.renameBlocker) return { title: item.renameBlocker, blocked: true };
  return { title: "No recommended name available" };
}

function renamePlanButtonLabel(result: SpiritFlixSmartBatchPreview | null): string {
  if (!result) return "Rename plan";
  const hasAnalyzed = result.counts.analyzed > 0 || result.counts.already_current > 0;
  if (!hasAnalyzed) return "Analyze folder first";
  if (result.counts.needs_review > 0) return "Review/approve items to create final rename plan";
  return "View rename plan";
}

function renamePlanHint(result: SpiritFlixSmartBatchPreview | null): string {
  if (!result) return "Run Preview folder or Analyze folder to inspect names.";
  const hasAnalyzed = result.counts.analyzed > 0 || result.counts.already_current > 0;
  const hasProvisional = result.items.some((item) => item.renamePreviewStatus === "provisional" && item.proposedFilename);
  if (!hasAnalyzed) return "Analyze folder first.";
  if (result.counts.needs_review > 0) return "Review/approve items to create final rename plan.";
  if (hasProvisional) return "Provisional names are visible, but not apply-ready.";
  return "Rename plan remains preview-only; real apply is disabled.";
}

export function SpiritFlixSmartBatchPanel({ currentPath, open, onClose }: SpiritFlixSmartBatchPanelProps) {
  const [result, setResult] = useState<SpiritFlixSmartBatchPreview | null>(null);
  const [renamePlan, setRenamePlan] = useState<SpiritFlixSmartRenamePlan | null>(null);
  const [running, setRunning] = useState(false);
  const [error, setError] = useState("");

  const callBatch = useCallback(async (action: "preview" | "run") => {
    setRunning(true);
    setError("");
    try {
      const response = await fetch("/api/spiritflix/admin/smart/batch", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: currentPath, action, maxItems: 12 }),
      });
      const payload = (await response.json()) as BatchResponse;
      if (!response.ok) throw new Error(payload.error ?? "Smart batch request failed.");
      setResult(payload);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Smart batch request failed.");
    } finally {
      setRunning(false);
    }
  }, [currentPath]);

  const callReview = useCallback(async (reviewMode: SpiritFlixSmartBatchReviewMode, paths?: string[]) => {
    setRunning(true);
    setError("");
    try {
      const response = await fetch("/api/spiritflix/admin/smart/batch", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: currentPath, paths, action: "review", reviewMode, maxItems: 50 }),
      });
      const payload = (await response.json()) as BatchResponse;
      if (!response.ok) throw new Error(payload.error ?? "Smart batch review failed.");
      setResult(payload);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Smart batch review failed.");
    } finally {
      setRunning(false);
    }
  }, [currentPath]);

  const refreshItem = useCallback(async (path: string) => {
    setRunning(true);
    setError("");
    try {
      const response = await fetch("/api/spiritflix/admin/smart/batch", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: currentPath, paths: [path], action: "run", force: true, maxItems: 1 }),
      });
      const payload = (await response.json()) as BatchResponse;
      if (!response.ok) throw new Error(payload.error ?? "Smart item refresh failed.");
      setResult(payload);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Smart item refresh failed.");
    } finally {
      setRunning(false);
    }
  }, [currentPath]);

  const callRenamePlan = useCallback(async () => {
    setRunning(true);
    setError("");
    try {
      const response = await fetch("/api/spiritflix/admin/smart/batch", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: currentPath, action: "renamePlan", maxItems: 50 }),
      });
      const payload = (await response.json()) as RenamePlanResponse;
      if (!response.ok) throw new Error(payload.error ?? "Smart rename plan failed.");
      setRenamePlan(payload);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Smart rename plan failed.");
    } finally {
      setRunning(false);
    }
  }, [currentPath]);

  if (!open || typeof document === "undefined") return null;

  return createPortal(
    <div className="spiritflix-smart-batch" role="presentation">
      <button className="spiritflix-smart-review__backdrop" type="button" aria-label="Close smart batch panel" onClick={onClose} />
      <aside className="spiritflix-smart-batch__panel" aria-label="Smart batch analysis" role="dialog" aria-modal="true">
        <header className="spiritflix-smart-review__header">
          <div>
            <p className="spiritflix-smart-review__eyebrow">
              <FolderSearch size={15} aria-hidden="true" />
              Batch smart
            </p>
            <h2>Folder analysis</h2>
          </div>
          <button className="spiritflix-smart-review__close" type="button" aria-label="Close" onClick={onClose}>
            <X size={18} aria-hidden="true" />
          </button>
        </header>

        <p className="spiritflix-smart-review__path">{currentPath}</p>
        <p className="spiritflix-smart-review__boundary">
          S8.1 writes analysis/review sidecars and exports rename plans only. Real rename/move apply is disabled until Britton explicitly approves a future apply task.
        </p>
        {error ? <p className="spiritflix-smart-review__error">{error}</p> : null}

        <section className="spiritflix-smart-review__section">
          <h3>Batch controls</h3>
          <div className="spiritflix-smart-review__action-buttons">
            <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callBatch("preview")}>
              {running ? "Working..." : "Preview folder"}
            </button>
            <button className="spiritflix-smart-review__primary" type="button" disabled={running} onClick={() => void callBatch("run")}>
              {running ? "Working..." : "Analyze folder"}
            </button>
            <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callReview("approve_all_tags")}>
              <CheckCircle2 size={15} aria-hidden="true" />
              Approve tags
            </button>
            <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callReview("reject_all_tags")}>
              <ShieldAlert size={15} aria-hidden="true" />
              Reject tags
            </button>
            <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callReview("mark_reviewed")}>
              Mark reviewed
            </button>
            <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callRenamePlan()}>
              <Download size={15} aria-hidden="true" />
              {renamePlanButtonLabel(result)}
            </button>
          </div>
          <p className="spiritflix-smart-batch__hint">{renamePlanHint(result)}</p>
        </section>

        {result ? (
          <>
            <section className="spiritflix-smart-review__section">
              <h3>Summary</h3>
              <dl className="spiritflix-smart-review__grid">
                <div>
                  <dt>Candidates</dt>
                  <dd>{result.counts.candidates}</dd>
                </div>
                <div>
                  <dt>Analyzed</dt>
                  <dd>{result.counts.analyzed}</dd>
                </div>
                <div>
                  <dt>Needs review</dt>
                  <dd>{result.counts.needs_review}</dd>
                </div>
                <div>
                  <dt>Ready names</dt>
                  <dd>{result.counts.rename_preview_available}</dd>
                </div>
                <div>
                  <dt>Failed</dt>
                  <dd>{result.counts.failed}</dd>
                </div>
              </dl>
              <p className="spiritflix-smart-review__boundary">
                Preview folder only lists candidates. Analyze folder reads metadata and creates smart tags. Recommended names become final after review/approval.
              </p>
              <p className="spiritflix-smart-batch__hint">{result.visualContentTaggingMessage}</p>
            </section>

            <section className="spiritflix-smart-review__section">
              <h3>Videos</h3>
              <div className="spiritflix-smart-batch__items">
                {result.items.map((item) => (
                  <article className="spiritflix-smart-batch__item" key={item.path}>
                    <div className="spiritflix-smart-batch__item-header">
                      <div className="spiritflix-smart-batch__title-block">
                      <p className="spiritflix-smart-batch__name">{item.name}</p>
                        <p className="spiritflix-smart-batch__meta">{item.parentPath}</p>
                      </div>
                      <span className={`spiritflix-smart-batch__status is-${operatorStatus(item).replace(/\s+/g, "-")}`}>
                        {operatorStatus(item)}
                      </span>
                    </div>

                    <section className="spiritflix-smart-batch__operator-section">
                      <h4>Model/performer</h4>
                      <p className="spiritflix-smart-batch__recommended-name">{item.modelName}</p>
                      <p className="spiritflix-smart-batch__meta">
                        {item.modelSource === "face_rec" ? "Read-only face-rec evidence" : item.modelSource === "path" ? "Model folder fallback" : "Unknown model fallback"}
                      </p>
                    </section>

                    <section className="spiritflix-smart-batch__operator-section">
                      <h4>Smart tags</h4>
                      {item.tags.length ? (
                        <div className="spiritflix-smart-review__tags">
                          {item.tags.map((tag) => (
                            <span
                              className={`spiritflix-smart-tag-pill is-group-${tag.group}${tag.reviewRequired ? " is-review-required" : ""}`}
                              key={tag.id}
                              title={`${tag.group} - ${formatConfidence(tag.confidence)} confidence${tag.reviewRequired ? " - review required" : ""}`}
                            >
                              <span className="spiritflix-smart-tag-pill__label">{tag.label}</span>
                              <span className="spiritflix-smart-tag-pill__meta">{formatConfidence(tag.confidence)}</span>
                              <span className="spiritflix-smart-tag-pill__flag">{tag.reviewState}</span>
                            </span>
                          ))}
                        </div>
                      ) : (
                        <p className="spiritflix-smart-batch__empty">{tagEmptyMessage(result, item)}</p>
                      )}
                    </section>

                    {item.qualityBadges.length ? (
                      <section className="spiritflix-smart-batch__operator-section">
                        <h4>Quality/technical</h4>
                        <div className="spiritflix-smart-review__tags is-technical">
                          {item.qualityBadges.map((tag) => (
                            <span
                              className={`spiritflix-smart-tag-pill is-group-${tag.group}`}
                              key={tag.id}
                              title={`${tag.group} - ${formatConfidence(tag.confidence)} confidence`}
                            >
                              <span className="spiritflix-smart-tag-pill__label">{tag.label}</span>
                              <span className="spiritflix-smart-tag-pill__meta">{formatConfidence(tag.confidence)}</span>
                            </span>
                          ))}
                        </div>
                      </section>
                    ) : null}

                    <section className="spiritflix-smart-batch__operator-section">
                      <h4>Recommended name</h4>
                      {(() => {
                        const message = recommendedNameMessage(item);
                        return (
                          <>
                            <p className={message.blocked ? "spiritflix-smart-batch__blocker" : "spiritflix-smart-batch__recommended-name"}>{message.title}</p>
                            {message.detail ? <p className="spiritflix-smart-batch__meta">{message.detail}</p> : null}
                          </>
                        );
                      })()}
                      {item.nameReason ? <p className="spiritflix-smart-batch__meta">Why this name: {item.nameReason}</p> : null}
                    </section>

                    <div className="spiritflix-smart-batch__actions">
                      <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void refreshItem(item.path)}>
                        <RotateCw size={15} aria-hidden="true" />
                        Analyze/refresh item
                      </button>
                      <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callReview("approve_all_tags", [item.path])}>
                        Approve tags
                      </button>
                      <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callReview("reject_all_tags", [item.path])}>
                        Reject tags
                      </button>
                      <button className="spiritflix-smart-review__secondary" type="button" disabled={running} onClick={() => void callReview("mark_reviewed", [item.path])}>
                        Mark reviewed
                      </button>
                    </div>

                    <details className="spiritflix-smart-batch__advanced">
                      <summary>Advanced details</summary>
                      <dl className="spiritflix-smart-review__grid">
                        <div>
                          <dt>Batch status</dt>
                          <dd>{statusLabel(item.status)}</dd>
                        </div>
                        <div>
                          <dt>Analysis status</dt>
                          <dd>{item.analysisStatus ?? "not analyzed"}</dd>
                        </div>
                        <div>
                          <dt>Review status</dt>
                          <dd>{item.reviewStatus ?? "unreviewed"}</dd>
                        </div>
                        <div>
                          <dt>Tag counts</dt>
                          <dd>{item.approvedTagCount} approved, {item.rejectedTagCount} rejected, {item.pendingTagCount} pending content tags</dd>
                        </div>
                        <div>
                          <dt>Technical badges</dt>
                          <dd>{item.qualityBadges.map((tag) => tag.label).join(", ") || "none"}</dd>
                        </div>
                        <div>
                          <dt>Visual tagging</dt>
                          <dd>{item.visualTaggingAvailable ? "local evidence tags available" : "not enabled"}</dd>
                        </div>
                        <div>
                          <dt>Rename status</dt>
                          <dd>{renameStatusLabel(item)}</dd>
                        </div>
                        <div>
                          <dt>Sidecar</dt>
                          <dd>{item.sidecarRef ?? "none"}</dd>
                        </div>
                        <div>
                          <dt>Target path</dt>
                          <dd className="is-mono">{item.proposedTargetPath ?? "not available"}</dd>
                        </div>
                      </dl>
                      {item.renameBlocker ? <p className="spiritflix-smart-batch__reason">{item.renameBlocker}</p> : null}
                      {item.renameWarnings.length ? <p className="spiritflix-smart-batch__reason">{item.renameWarnings.join(" ")}</p> : null}
                      {item.reason ? <p className="spiritflix-smart-batch__reason">{item.reason}</p> : null}
                    </details>
                  </article>
                ))}
              </div>
            </section>
          </>
        ) : null}

        {renamePlan ? (
          <section className="spiritflix-smart-review__section">
            <h3>Rename plan</h3>
            <p className="spiritflix-smart-review__boundary">{renamePlan.applyGate}</p>
            <dl className="spiritflix-smart-review__grid">
              <div>
                <dt>Ready</dt>
                <dd>{renamePlan.counts.ready}</dd>
              </div>
              <div>
                <dt>Blocked</dt>
                <dd>{renamePlan.counts.blocked}</dd>
              </div>
              <div>
                <dt>Needs review</dt>
                <dd>{renamePlan.counts.needs_review}</dd>
              </div>
              <div>
                <dt>Collisions</dt>
                <dd>{renamePlan.counts.collisions}</dd>
              </div>
              <div>
                <dt>Target conflicts</dt>
                <dd>{renamePlan.counts.target_conflicts}</dd>
              </div>
              <div>
                <dt>Apply enabled</dt>
                <dd>{renamePlan.applyEnabled ? "Yes" : "No"}</dd>
              </div>
            </dl>
            <div className="spiritflix-smart-batch__items">
              {renamePlan.items.map((item) => (
                <article className="spiritflix-smart-batch__item" key={item.sourcePath}>
                  <div>
                    <p className="spiritflix-smart-batch__name">{item.currentName}</p>
                    <p className="spiritflix-smart-batch__meta">
                      {item.suggestedName ?? "no proposal"} - {item.readyForLevel2Preview ? "ready recommended name" : "not apply-ready"}
                    </p>
                  </div>
                  <span className={item.readyForLevel2Preview ? "is-ready" : ""}>
                    {item.readyForLevel2Preview ? "ready" : "blocked"}
                  </span>
                  {item.warnings.length ? (
                    <p className="spiritflix-smart-batch__reason">{item.warnings.join(" ")}</p>
                  ) : null}
                </article>
              ))}
            </div>
          </section>
        ) : null}

        <footer className="spiritflix-smart-review__footer">
          <button className="spiritflix-smart-review__secondary" type="button" onClick={onClose}>
            Close
          </button>
        </footer>
      </aside>
    </div>,
    document.body,
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { createPortal } from "react-dom";
import { Sparkles, X } from "lucide-react";
import type { SpiritFlixSmartAnalysis, SpiritFlixSmartReviewInput } from "@/lib/spiritflix/admin/smart/types";
import { buildEmptyReviewDraft, countReviewTagStates, tagReviewState } from "@/lib/spiritflix/admin/smart/review-metadata";
import type { SpiritFlixAdminItem } from "@/lib/spiritflix/admin/types";
import { SpiritFlixSmartTagPill } from "./SpiritFlixSmartTagPill";

interface SpiritFlixSmartReviewPanelProps {
  item: SpiritFlixAdminItem;
  open: boolean;
  onClose: () => void;
}

interface SmartAnalysisResponse {
  analysis: SpiritFlixSmartAnalysis | null;
  sidecarPath?: string;
}

interface ExportMetadataResponse {
  metadataPath?: string;
  metadata?: {
    sourcePath: string;
    displayTitle?: string;
    filenameSuggestion?: string;
    category?: string;
    collections: string[];
    approvedTags: Array<{ id: string; label: string; group: string; confidence: number }>;
    rejectedTagIds: string[];
    reviewStatus: string;
    reviewedAt?: string;
    notes?: string;
  };
  error?: string;
}

interface PrepareRenameResponse {
  renamePreview?: {
    sourcePath: string;
    suggestedName: string;
    targetPath: string;
    warnings: string[];
    readyForLevel2Preview: boolean;
  };
  error?: string;
}

function formatConfidence(value: number): string {
  return `${Math.round(value * 100)}%`;
}

function formatReviewStatus(status: string | undefined): string {
  switch (status) {
    case "partially_reviewed":
      return "Partially reviewed";
    case "reviewed":
      return "Reviewed";
    case "rejected":
      return "Rejected";
    default:
      return "Unreviewed";
  }
}

function collectionsToInput(value: string): string[] {
  return value
    .split(",")
    .map((entry) => entry.trim())
    .filter(Boolean);
}

export function SpiritFlixSmartReviewPanel({ item, open, onClose }: SpiritFlixSmartReviewPanelProps) {
  const [analysis, setAnalysis] = useState<SpiritFlixSmartAnalysis | null>(null);
  const [sidecarPath, setSidecarPath] = useState<string | null>(null);
  const [draft, setDraft] = useState<SpiritFlixSmartReviewInput>({
    approvedTagIds: [],
    rejectedTagIds: [],
    editedDisplayTitle: "",
    editedFilenameSuggestion: "",
    editedCategory: "",
    editedCollections: [],
    notes: "",
  });
  const [collectionsInput, setCollectionsInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [analyzing, setAnalyzing] = useState(false);
  const [marking, setMarking] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  // S6 state
  const [exporting, setExporting] = useState(false);
  const [preparingRename, setPreparingRename] = useState(false);
  const [exportResult, setExportResult] = useState<ExportMetadataResponse["metadata"] | null>(null);
  const [renamePreview, setRenamePreview] = useState<PrepareRenameResponse["renamePreview"] | null>(null);

  const syncDraftFromAnalysis = useCallback((next: SpiritFlixSmartAnalysis | null) => {
    const nextDraft = buildEmptyReviewDraft(next);
    setDraft(nextDraft);
    setCollectionsInput((nextDraft.editedCollections ?? []).join(", "));
  }, []);

  const loadAnalysis = useCallback(async () => {
    if (!item.path) return;
    setLoading(true);
    setError("");
    try {
      const response = await fetch(`/api/spiritflix/admin/smart/analysis?path=${encodeURIComponent(item.path)}`, {
        method: "GET",
        cache: "no-store",
        headers: { Accept: "application/json" },
      });
      const payload = (await response.json()) as SmartAnalysisResponse & { error?: string };
      if (!response.ok) throw new Error(payload.error ?? "Failed to load smart analysis.");
      setAnalysis(payload.analysis);
      setSidecarPath(payload.sidecarPath ?? null);
      syncDraftFromAnalysis(payload.analysis);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Failed to load smart analysis.");
      setAnalysis(null);
      setSidecarPath(null);
      syncDraftFromAnalysis(null);
    } finally {
      setLoading(false);
    }
  }, [item.path, syncDraftFromAnalysis]);

  useEffect(() => {
    if (!open) return;
    void loadAnalysis();
  }, [open, loadAnalysis]);

  useEffect(() => {
    if (!open) return;
    function onKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [open, onClose]);

  const runAnalyze = useCallback(async () => {
    if (!item.path) return;
    setAnalyzing(true);
    setError("");
    try {
      const response = await fetch("/api/spiritflix/admin/smart/analysis", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: item.path, action: "analyze" }),
      });
      const payload = (await response.json()) as SmartAnalysisResponse & { error?: string };
      if (!response.ok) throw new Error(payload.error ?? "Smart analysis failed.");
      setAnalysis(payload.analysis);
      setSidecarPath(payload.sidecarPath ?? null);
      syncDraftFromAnalysis(payload.analysis);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Smart analysis failed.");
    } finally {
      setAnalyzing(false);
    }
  }, [item.path, syncDraftFromAnalysis]);

  const runMarkReviewed = useCallback(async () => {
    if (!item.path || !analysis) return;
    setMarking(true);
    setError("");
    try {
      const response = await fetch("/api/spiritflix/admin/smart/analysis", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: item.path, action: "markReviewed" }),
      });
      const payload = (await response.json()) as SmartAnalysisResponse & { error?: string };
      if (!response.ok) throw new Error(payload.error ?? "Failed to mark reviewed.");
      setAnalysis(payload.analysis);
      setSidecarPath(payload.sidecarPath ?? null);
      syncDraftFromAnalysis(payload.analysis);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Failed to mark reviewed.");
    } finally {
      setMarking(false);
    }
  }, [analysis, item.path, syncDraftFromAnalysis]);

  const runSaveReview = useCallback(async () => {
    if (!item.path || !analysis) return;
    setSaving(true);
    setError("");
    try {
      const payloadReview: SpiritFlixSmartReviewInput = {
        ...draft,
        editedCollections: collectionsToInput(collectionsInput),
        editedDisplayTitle: draft.editedDisplayTitle?.trim() || undefined,
        editedFilenameSuggestion: draft.editedFilenameSuggestion?.trim() || undefined,
        editedCategory: draft.editedCategory?.trim() || undefined,
        notes: draft.notes?.trim() || undefined,
      };
      const response = await fetch("/api/spiritflix/admin/smart/analysis", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: item.path, action: "saveReview", review: payloadReview }),
      });
      const payload = (await response.json()) as SmartAnalysisResponse & { error?: string };
      if (!response.ok) throw new Error(payload.error ?? "Failed to save review.");
      setAnalysis(payload.analysis);
      setSidecarPath(payload.sidecarPath ?? null);
      syncDraftFromAnalysis(payload.analysis);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Failed to save review.");
    } finally {
      setSaving(false);
    }
  }, [analysis, collectionsInput, draft, item.path, syncDraftFromAnalysis]);

  // S9: confirm approved metadata to admin metadata sidecar
  const runExportMetadata = useCallback(async () => {
    if (!item.path || !analysis) return;
    setExporting(true);
    setError("");
    setExportResult(null);
    try {
      const response = await fetch("/api/spiritflix/admin/smart/analysis", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: item.path, action: "confirmMetadata" }),
      });
      const payload = (await response.json()) as ExportMetadataResponse;
      if (!response.ok) throw new Error(payload.error ?? "Failed to confirm metadata.");
      setExportResult(payload.metadata ?? null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Failed to confirm metadata.");
    } finally {
      setExporting(false);
    }
  }, [analysis, item.path]);

  // S6: prepare rename preview
  const runPrepareRenamePreview = useCallback(async () => {
    if (!item.path || !analysis) return;
    setPreparingRename(true);
    setError("");
    setRenamePreview(null);
    try {
      const response = await fetch("/api/spiritflix/admin/smart/analysis", {
        method: "POST",
        headers: { Accept: "application/json", "Content-Type": "application/json" },
        body: JSON.stringify({ path: item.path, action: "prepareRenamePreview" }),
      });
      const payload = (await response.json()) as PrepareRenameResponse;
      if (!response.ok) throw new Error(payload.error ?? "Failed to prepare rename preview.");
      setRenamePreview(payload.renamePreview ?? null);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : "Failed to prepare rename preview.");
    } finally {
      setPreparingRename(false);
    }
  }, [analysis, item.path]);

  const tagCounts = useMemo(() => (analysis ? countReviewTagStates(analysis, draft) : { approved: 0, rejected: 0, pending: 0 }), [analysis, draft]);

  const setTagDecision = useCallback((tagId: string, decision: "approved" | "rejected" | "pending") => {
    setDraft((current) => {
      const approvedTagIds = current.approvedTagIds.filter((id) => id !== tagId);
      const rejectedTagIds = current.rejectedTagIds.filter((id) => id !== tagId);
      if (decision === "approved") approvedTagIds.push(tagId);
      if (decision === "rejected") rejectedTagIds.push(tagId);
      return { ...current, approvedTagIds, rejectedTagIds };
    });
  }, []);

  if (!open || typeof document === "undefined") return null;

  const reviewStatus = analysis?.reviewedMetadata?.reviewStatus ?? "unreviewed";
  const sampleCount = analysis?.samples.length ?? 0;
  const evidenceTimestamps = analysis?.samples.map((sample) => sample.timestampLabel).join(", ") ?? "";
  const hasReviewedMetadata = analysis?.reviewedMetadata != null && analysis.reviewedMetadata.reviewStatus !== "unreviewed";

  return createPortal(
    <div className="spiritflix-smart-review" role="presentation">
      <button className="spiritflix-smart-review__backdrop" type="button" aria-label="Close smart review panel" onClick={onClose} />
      <aside className="spiritflix-smart-review__panel" aria-label="Smart tag review" role="dialog" aria-modal="true">
        <header className="spiritflix-smart-review__header">
          <div>
            <p className="spiritflix-smart-review__eyebrow">
              <Sparkles size={15} aria-hidden="true" />
              Smart tags
            </p>
            <h2>{item.name}</h2>
          </div>
          <button className="spiritflix-smart-review__close" type="button" aria-label="Close" onClick={onClose}>
            <X size={18} aria-hidden="true" />
          </button>
        </header>

        <p className="spiritflix-smart-review__path">{item.path}</p>
        <p className="spiritflix-smart-review__boundary">
          S9 analyzes sampled frames, lets you review/edit tags and names, then confirms only metadata sidecars. It does not rename or move files.
        </p>

        {loading ? <p className="spiritflix-smart-review__status">Loading smart analysisâ€¦</p> : null}
        {error ? <p className="spiritflix-smart-review__error">{error}</p> : null}

        {!loading && !analysis ? (
          <section className="spiritflix-smart-review__section">
            <h3>No smart analysis yet</h3>
            <p>Run a one-video scan to collect metadata, sample frames, local visual tags, and name suggestions. Nothing is renamed or moved.</p>
          </section>
        ) : null}

        {analysis ? (
          <>
            <section className="spiritflix-smart-review__section">
              <h3>Status</h3>
              <dl className="spiritflix-smart-review__grid">
                <div>
                  <dt>Analysis status</dt>
                  <dd>{analysis.status}</dd>
                </div>
                <div>
                  <dt>Review status</dt>
                  <dd>{formatReviewStatus(reviewStatus)}</dd>
                </div>
                <div>
                  <dt>Confidence</dt>
                  <dd>{formatConfidence(analysis.confidence)}</dd>
                </div>
                <div>
                  <dt>Tag counts</dt>
                  <dd>
                    {tagCounts.approved} approved Â· {tagCounts.rejected} rejected Â· {tagCounts.pending} pending
                  </dd>
                </div>
                <div>
                  <dt>Safety</dt>
                  <dd>{analysis.safety.requiresHumanReview ? "Human review required" : "Review optional"}</dd>
                </div>
              </dl>
            </section>

            <section className="spiritflix-smart-review__section">
              <h3>Review metadata</h3>
              <label className="spiritflix-smart-review__field">
                <span>Display title</span>
                <input
                  type="text"
                  value={draft.editedDisplayTitle ?? ""}
                  onChange={(event) => setDraft((current) => ({ ...current, editedDisplayTitle: event.target.value }))}
                />
              </label>
              <label className="spiritflix-smart-review__field">
                <span>Filename suggestion only</span>
                <input
                  type="text"
                  value={draft.editedFilenameSuggestion ?? ""}
                  onChange={(event) => setDraft((current) => ({ ...current, editedFilenameSuggestion: event.target.value }))}
                />
                <small>This does not rename the file yet.</small>
              </label>
              <label className="spiritflix-smart-review__field">
                <span>Category</span>
                <input
                  type="text"
                  value={draft.editedCategory ?? ""}
                  onChange={(event) => setDraft((current) => ({ ...current, editedCategory: event.target.value }))}
                />
              </label>
              <label className="spiritflix-smart-review__field">
                <span>Collections (comma-separated)</span>
                <input type="text" value={collectionsInput} onChange={(event) => setCollectionsInput(event.target.value)} />
              </label>
              <label className="spiritflix-smart-review__field">
                <span>Review notes</span>
                <textarea value={draft.notes ?? ""} onChange={(event) => setDraft((current) => ({ ...current, notes: event.target.value }))} rows={3} />
              </label>
            </section>

            <section className="spiritflix-smart-review__section">
              <h3>Original suggestions</h3>
              <dl className="spiritflix-smart-review__grid">
                <div>
                  <dt>Display title</dt>
                  <dd>{analysis.suggestedDisplayTitle ?? "â€”"}</dd>
                </div>
                <div>
                  <dt>Suggested filename</dt>
                  <dd>{analysis.suggestedFilename ?? "â€”"}</dd>
                </div>
                <div>
                  <dt>Category</dt>
                  <dd>{analysis.suggestedCategory ?? "â€”"}</dd>
                </div>
                <div>
                  <dt>Collections</dt>
                  <dd>{analysis.suggestedCollections?.join(", ") || "â€”"}</dd>
                </div>
              </dl>
            </section>

            <section className="spiritflix-smart-review__section">
              <h3>Tags</h3>
              {analysis.suggestedTags.length ? (
                <div className="spiritflix-smart-review__tags">
                  {analysis.suggestedTags.map((tag) => (
                    <SpiritFlixSmartTagPill
                      key={tag.id}
                      tag={tag}
                      reviewState={tagReviewState(tag.id, draft)}
                      onApprove={() => setTagDecision(tag.id, "approved")}
                      onReject={() => setTagDecision(tag.id, "rejected")}
                      onReset={() => setTagDecision(tag.id, "pending")}
                    />
                  ))}
                </div>
              ) : (
                <p>No suggested tags.</p>
              )}
            </section>

            <section className="spiritflix-smart-review__section">
              <h3>Evidence</h3>
              <dl className="spiritflix-smart-review__grid">
                <div>
                  <dt>Samples</dt>
                  <dd>{sampleCount}</dd>
                </div>
                <div>
                  <dt>Timestamps</dt>
                  <dd>{evidenceTimestamps || "â€”"}</dd>
                </div>
                <div>
                  <dt>Sidecar</dt>
                  <dd className="is-mono">{sidecarPath ? sidecarPath.split("/").slice(-2).join("/") : "â€”"}</dd>
                </div>
              </dl>
            </section>

            {analysis.notes ? (
              <section className="spiritflix-smart-review__section">
                <h3>Scanner notes</h3>
                <p className="spiritflix-smart-review__notes">{analysis.notes}</p>
              </section>
            ) : null}

            {/* â”€â”€ S6: Approved metadata section â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            {hasReviewedMetadata ? (
              <>
                <section className="spiritflix-smart-review__section spiritflix-smart-review__section--approved">
                  <h3>Approved metadata</h3>
                  <dl className="spiritflix-smart-review__grid">
                    <div>
                      <dt>Display title</dt>
                      <dd>{analysis.reviewedMetadata!.editedDisplayTitle ?? analysis.suggestedDisplayTitle ?? "â€”"}</dd>
                    </div>
                    <div>
                      <dt>Filename suggestion</dt>
                      <dd className="is-mono">{analysis.reviewedMetadata!.editedFilenameSuggestion ?? analysis.suggestedFilename ?? "â€”"}</dd>
                    </div>
                    <div>
                      <dt>Category</dt>
                      <dd>{analysis.reviewedMetadata!.editedCategory ?? analysis.suggestedCategory ?? "â€”"}</dd>
                    </div>
                    <div>
                      <dt>Collections</dt>
                      <dd>{(analysis.reviewedMetadata!.editedCollections ?? analysis.suggestedCollections)?.join(", ") || "â€”"}</dd>
                    </div>
                    <div>
                      <dt>Approved tags</dt>
                      <dd>
                        {analysis.reviewedMetadata!.approvedTagIds.length
                          ? analysis.reviewedMetadata!.approvedTagIds.join(", ")
                          : "â€”"}
                      </dd>
                    </div>
                    <div>
                      <dt>Rejected tags</dt>
                      <dd>
                        {analysis.reviewedMetadata!.rejectedTagIds.length
                          ? analysis.reviewedMetadata!.rejectedTagIds.join(", ")
                          : "â€”"}
                      </dd>
                    </div>
                  </dl>
                </section>

                <section className="spiritflix-smart-review__section spiritflix-smart-review__section--actions">
                  <h3>Confirm approved metadata</h3>
                  <p className="spiritflix-smart-review__boundary">Confirm writes approved tags and display-name overrides to SpiritFlix metadata sidecars only.</p>
                  <div className="spiritflix-smart-review__action-buttons">
                    <button
                      className="spiritflix-smart-review__primary"
                      type="button"
                      disabled={exporting}
                      onClick={() => void runExportMetadata()}
                    >
                      {exporting ? "Confirmingâ€¦" : "Confirm approved tags and name"}
                    </button>
                    <button
                      className="spiritflix-smart-review__secondary"
                      type="button"
                      disabled={preparingRename}
                      onClick={() => void runPrepareRenamePreview()}
                    >
                      {preparingRename ? "Preparingâ€¦" : "Prepare rename preview"}
                    </button>
                  </div>
                </section>

                {/* Export result */}
                {exportResult ? (
                  <section className="spiritflix-smart-review__section spiritflix-smart-review__section--export-result">
                    <h3>Metadata confirmed</h3>
                    <dl className="spiritflix-smart-review__grid">
                      <div>
                        <dt>Title</dt>
                        <dd>{exportResult.displayTitle ?? "â€”"}</dd>
                      </div>
                      <div>
                        <dt>Category</dt>
                        <dd>{exportResult.category ?? "â€”"}</dd>
                      </div>
                      <div>
                        <dt>Tags</dt>
                        <dd>{exportResult.approvedTags.map((t) => t.label).join(", ") || "â€”"}</dd>
                      </div>
                      <div>
                        <dt>Path</dt>
                        <dd className="is-mono">{exportResult.sourcePath.split("/").slice(-2).join("/")}</dd>
                      </div>
                    </dl>
                  </section>
                ) : null}

                {/* Rename preview */}
                {renamePreview ? (
                  <section className="spiritflix-smart-review__section spiritflix-smart-review__section--rename-preview">
                    <h3>Rename preview</h3>
                    <dl className="spiritflix-smart-review__grid">
                      <div>
                        <dt>Current filename</dt>
                        <dd className="is-mono">{item.name}</dd>
                      </div>
                      <div>
                        <dt>Suggested filename</dt>
                        <dd className="is-mono">{renamePreview.suggestedName}</dd>
                      </div>
                      <div>
                        <dt>Target path</dt>
                        <dd className="is-mono">{renamePreview.targetPath.split("/").slice(-3).join("/")}</dd>
                      </div>
                      <div>
                        <dt>Warnings</dt>
                        <dd>
                          {renamePreview.warnings.length
                            ? renamePreview.warnings.map((w) => (
                                <p key={w} className="spiritflix-smart-review__warning">{w}</p>
                              ))
                            : "None"}
                        </dd>
                      </div>
                      <div>
                        <dt>Ready for Level 2</dt>
                        <dd>{renamePreview.readyForLevel2Preview ? "Yes" : "No"}</dd>
                      </div>
                    </dl>
                    <p className="spiritflix-smart-review__boundary">Execute rename comes in S7.</p>
                  </section>
                ) : null}
              </>
            ) : null}
          </>
        ) : null}

        <footer className="spiritflix-smart-review__footer">
          <button className="spiritflix-smart-review__primary" type="button" disabled={analyzing} onClick={() => void runAnalyze()}>
            {analyzing ? "Analyzingâ€¦" : analysis ? "Refresh suggestions" : "Analyze this video"}
          </button>
          {analysis ? (
            <>
              <button className="spiritflix-smart-review__primary" type="button" disabled={saving} onClick={() => void runSaveReview()}>
                {saving ? "Savingâ€¦" : "Save review"}
              </button>
              <button className="spiritflix-smart-review__secondary" type="button" disabled={marking} onClick={() => void runMarkReviewed()}>
                {marking ? "Savingâ€¦" : "Mark reviewed"}
              </button>
            </>
          ) : null}
          <button className="spiritflix-smart-review__secondary" type="button" onClick={onClose}>
            Close
          </button>
        </footer>
      </aside>
    </div>,
    document.body,
  );
}

"use client";

import type { SpiritFlixSmartTag } from "@/lib/spiritflix/admin/smart/types";

export type SpiritFlixSmartTagReviewState = "approved" | "rejected" | "pending";

interface SpiritFlixSmartTagPillProps {
  tag: SpiritFlixSmartTag;
  reviewState?: SpiritFlixSmartTagReviewState;
  onApprove?: () => void;
  onReject?: () => void;
  onReset?: () => void;
}

export function SpiritFlixSmartTagPill({ tag, reviewState = "pending", onApprove, onReject, onReset }: SpiritFlixSmartTagPillProps) {
  const confidencePct = Math.round(tag.confidence * 100);
  const interactive = Boolean(onApprove || onReject || onReset);

  return (
    <div
      className={`spiritflix-smart-tag-pill-wrap is-${reviewState}${interactive ? " is-interactive" : ""}`}
      data-review-state={reviewState}
    >
      <span
        className={`spiritflix-smart-tag-pill is-group-${tag.group}${tag.reviewRequired ? " is-review-required" : ""}`}
        title={`${tag.group} Â· ${confidencePct}% confidence${tag.reviewRequired ? " Â· review required" : ""}`}
      >
        <span className="spiritflix-smart-tag-pill__label">{tag.label}</span>
        <span className="spiritflix-smart-tag-pill__meta">{confidencePct}%</span>
        {tag.reviewRequired ? <span className="spiritflix-smart-tag-pill__flag">review</span> : null}
      </span>
      {interactive ? (
        <div className="spiritflix-smart-tag-pill__actions">
          <button type="button" aria-label={`Approve ${tag.label}`} onClick={onApprove}>
            Approve
          </button>
          <button type="button" aria-label={`Reject ${tag.label}`} onClick={onReject}>
            Reject
          </button>
          <button type="button" aria-label={`Reset ${tag.label}`} onClick={onReset}>
            Reset
          </button>
        </div>
      ) : null}
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

export function useAdminScrollRestore(dependencyKey: string) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const savedScrollTop = useRef(0);
  const shouldRestore = useRef(false);

  const saveScroll = useCallback(() => {
    if (scrollRef.current) {
      savedScrollTop.current = scrollRef.current.scrollTop;
    }
  }, []);

  const requestRestore = useCallback(() => {
    shouldRestore.current = true;
  }, []);

  const restoreScroll = useCallback(() => {
    if (!shouldRestore.current || !scrollRef.current) return;
    scrollRef.current.scrollTop = savedScrollTop.current;
    shouldRestore.current = false;
  }, []);

  useEffect(() => {
    if (!shouldRestore.current) return;
    requestAnimationFrame(() => {
      restoreScroll();
    });
  }, [dependencyKey, restoreScroll]);

  return { scrollRef, saveScroll, requestRestore, restoreScroll };
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import {
  clearStoredSession,
  getStoredSession,
  JellyfinClient,
  isPlayableItem,
  normalizeJellyfinServerUrl,
  SPIRITFLIX_DEFAULT_SERVER,
  storeSession,
} from "@/lib/spiritflix-jellyfin-client";
import type {
  JellyfinItem,
  SpiritFlixHomeData,
  SpiritFlixServerInfo,
  SpiritFlixSession,
} from "@/lib/spiritflix-types";
import { hasResumeProgress } from "@/lib/spiritflix-resume";
import { SpiritFlixHome } from "./SpiritFlixHome";
import { SpiritFlixLogin } from "./SpiritFlixLogin";
import { SpiritFlixDetailsModal } from "./SpiritFlixDetailsModal";
import { SpiritFlixPlayer } from "./SpiritFlixPlayer";

export interface SpiritFlixPlaybackQueue {
  items: JellyfinItem[];
  originalItems?: JellyfinItem[];
  currentIndex: number;
  sourceTitle: string;
  startPositionTicks?: number;
  isShuffled?: boolean;
}

export interface SpiritFlixPlaybackProgress {
  itemId: string;
  item?: JellyfinItem;
  positionTicks: number;
  isEnded?: boolean;
}

const emptyHome: SpiritFlixHomeData = {
  libraries: [],
  playlists: [],
  selectedLibraryId: null,
  featuredItems: [],
  libraryItems: [],
  continueWatching: [],
  watchHistory: [],
  latestAdded: [],
  favorites: [],
};

const OTHER_LIBRARY_NAME = "Other";
const PLAYLIST_LIBRARY_NAME = "Playlists";
const HIDDEN_LIBRARY_NAMES = new Set(["music"]);

function isMediaLibrary(library: { Name: string; CollectionType?: string }): boolean {
  const name = library.Name.toLowerCase();
  const collectionType = library.CollectionType?.toLowerCase();
  return (
    !HIDDEN_LIBRARY_NAMES.has(name) &&
    name !== PLAYLIST_LIBRARY_NAME.toLowerCase() &&
    collectionType !== "playlists" &&
    collectionType !== "music"
  );
}

function uniqueItems(items: JellyfinItem[]): JellyfinItem[] {
  const seen = new Set<string>();
  return items.filter((item) => {
    if (seen.has(item.Id)) return false;
    seen.add(item.Id);
    return true;
  });
}

function shuffleItems(items: JellyfinItem[]): JellyfinItem[] {
  return items
    .map((item) => ({ item, sort: Math.random() }))
    .sort((left, right) => left.sort - right.sort)
    .map(({ item }) => item);
}

function shuffleQueueAfterCurrent(items: JellyfinItem[], currentItemId: string): JellyfinItem[] {
  const currentItem = items.find((item) => item.Id === currentItemId);
  const remainingItems = items.filter((item) => item.Id !== currentItemId);
  return currentItem ? [currentItem, ...shuffleItems(remainingItems)] : shuffleItems(items);
}

function getLastPlayedMs(item: JellyfinItem): number {
  if (!item.UserData?.LastPlayedDate) return 0;
  const value = new Date(item.UserData.LastPlayedDate).getTime();
  return Number.isFinite(value) ? value : 0;
}

function sortByLastPlayed(items: JellyfinItem[]): JellyfinItem[] {
  return [...items].sort((left, right) => getLastPlayedMs(right) - getLastPlayedMs(left));
}

function hasWatchActivity(item: JellyfinItem): boolean {
  return Boolean(
    item.UserData?.LastPlayedDate ||
      item.UserData?.Played ||
      (item.UserData?.PlaybackPositionTicks && item.UserData.PlaybackPositionTicks > 0) ||
      (item.UserData?.PlayCount && item.UserData.PlayCount > 0),
  );
}

function isKenshinItem(item: JellyfinItem): boolean {
  return [item.Name, item.SeriesName, item.Path].some((value) => value?.toLowerCase().includes("kenshin"));
}

function byEpisodeOrder(left: JellyfinItem, right: JellyfinItem): number {
  return (
    (left.ParentIndexNumber ?? 0) - (right.ParentIndexNumber ?? 0) ||
    (left.IndexNumber ?? 0) - (right.IndexNumber ?? 0) ||
    left.Name.localeCompare(right.Name)
  );
}

function applyPlaybackProgress(item: JellyfinItem, progress: SpiritFlixPlaybackProgress): JellyfinItem {
  if (item.Id !== progress.itemId) return item;
  const runtimeTicks = item.RunTimeTicks ?? 0;
  const clampedTicks = progress.isEnded ? 0 : Math.max(0, progress.positionTicks);
  const playedPercentage = progress.isEnded
    ? 100
    : runtimeTicks > 0
      ? Math.max(0, Math.min(100, (clampedTicks / runtimeTicks) * 100))
      : item.UserData?.PlayedPercentage;

  return {
    ...item,
    UserData: {
      ...item.UserData,
      PlaybackPositionTicks: clampedTicks,
      Played: progress.isEnded ? true : false,
      PlayedPercentage: playedPercentage,
      LastPlayedDate: new Date().toISOString(),
    },
  };
}

function upsertPlaybackItem(items: JellyfinItem[], item: JellyfinItem): JellyfinItem[] {
  const nextItems = items.filter((candidate) => candidate.Id !== item.Id);
  if (item.UserData?.Played || !(item.UserData?.PlaybackPositionTicks && item.UserData.PlaybackPositionTicks > 0)) {
    return nextItems;
  }
  return [item, ...nextItems];
}

function upsertWatchHistoryItem(items: JellyfinItem[], item: JellyfinItem): JellyfinItem[] {
  const nextItems = items.filter((candidate) => candidate.Id !== item.Id);
  if (!hasWatchActivity(item)) return nextItems;
  return sortByLastPlayed([item, ...nextItems]);
}

function applyFavoriteState(item: JellyfinItem, itemId: string, isFavorite: boolean): JellyfinItem {
  if (item.Id !== itemId) return item;
  return {
    ...item,
    UserData: {
      ...item.UserData,
      IsFavorite: isFavorite,
    },
  };
}

function upsertFavoriteItem(items: JellyfinItem[], item: JellyfinItem): JellyfinItem[] {
  const nextItems = items.filter((candidate) => candidate.Id !== item.Id);
  if (!item.UserData?.IsFavorite) return nextItems;
  return [item, ...nextItems].sort((left, right) => left.Name.localeCompare(right.Name));
}

export function inferPlaybackQueueForItem(
  item: JellyfinItem,
  homeData: SpiritFlixHomeData,
): { items: JellyfinItem[]; sourceTitle: string } | null {
  const sources: Array<{ items: JellyfinItem[]; sourceTitle: string }> = [
    { items: homeData.continueWatching, sourceTitle: "Continue Watching" },
    { items: homeData.latestAdded, sourceTitle: "Latest Added" },
    { items: homeData.featuredItems, sourceTitle: "Featured Anime" },
    { items: homeData.favorites, sourceTitle: "Favorites" },
    { items: homeData.watchHistory, sourceTitle: "Watch History" },
    { items: homeData.libraryItems, sourceTitle: "Library" },
  ];

  return sources.find((source) => source.items.some((sourceItem) => sourceItem.Id === item.Id)) ?? null;
}

interface SpiritFlixBrowseRoute {
  libraryId: string | null;
  modelName: string | null;
}

function getSpiritFlixBrowseRoute(): SpiritFlixBrowseRoute {
  if (typeof window === "undefined") {
    return { libraryId: null, modelName: null };
  }
  const query = new URLSearchParams(window.location.search);
  return {
    libraryId: query.get("library"),
    modelName: query.get("model"),
  };
}

export function buildSpiritFlixBrowsePath({ libraryId, modelName }: SpiritFlixBrowseRoute): string {
  const query = new URLSearchParams();
  if (libraryId) query.set("library", libraryId);
  if (libraryId && modelName) query.set("model", modelName);
  const queryText = query.toString();
  return queryText ? `/spiritflix?${queryText}` : "/spiritflix";
}

function setSpiritFlixBrowseRoute(
  { libraryId, modelName }: SpiritFlixBrowseRoute,
  mode: "push" | "replace" = "push",
) {
  if (typeof window === "undefined") return;
  const nextPath = buildSpiritFlixBrowsePath({ libraryId, modelName });
  if (`${window.location.pathname}${window.location.search}` === nextPath) return;
  if (mode === "replace") {
    window.history.replaceState(window.history.state, "", nextPath);
    return;
  }
  window.history.pushState(window.history.state, "", nextPath);
}

export function SpiritFlixApp() {
  const [session, setSession] = useState<SpiritFlixSession | null>(null);
  const [isRestoringSession, setIsRestoringSession] = useState(true);
  const [serverUrl, setServerUrl] = useState(SPIRITFLIX_DEFAULT_SERVER);
  const [serverInfo, setServerInfo] = useState<SpiritFlixServerInfo | null>(null);
  const [serverError, setServerError] = useState("");
  const [homeData, setHomeData] = useState<SpiritFlixHomeData>(emptyHome);
  const [selectedItem, setSelectedItem] = useState<JellyfinItem | null>(null);
  const [playingItem, setPlayingItem] = useState<JellyfinItem | null>(null);
  const [playingQueue, setPlayingQueue] = useState<SpiritFlixPlaybackQueue | null>(null);
  const [searchTerm, setSearchTerm] = useState("");
  const [loadingHome, setLoadingHome] = useState(false);
  const [homeError, setHomeError] = useState("");
  const loadedSessionKeyRef = useRef<string | null>(null);
  const initialBrowseRouteRef = useRef<SpiritFlixBrowseRoute | null>(null);

  const client = useMemo(
    () => new JellyfinClient(session?.serverUrl ?? serverUrl, session?.accessToken, session?.userId),
    [serverUrl, session],
  );

  const checkServer = useCallback(
    async (target = serverUrl) => {
      setServerError("");
      try {
        const info = await new JellyfinClient(target).checkPublicInfo();
        setServerInfo(info);
        setServerUrl(normalizeJellyfinServerUrl(target));
      } catch {
        setServerInfo(null);
        setServerError("SpiritFlix cannot reach that Jellyfin server from this browser right now.");
      }
    },
    [serverUrl],
  );

  const loadHome = useCallback(
    async (libraryId?: string | null, term = searchTerm, options: { silent?: boolean } = {}) => {
      if (!session) return;
      if (!options.silent) setLoadingHome(true);
      setHomeError("");
      try {
        const libraries = (await client.getLibraries()).filter(isMediaLibrary);
        const otherLibrary = libraries.find((library) => library.Name.toLowerCase() === OTHER_LIBRARY_NAME.toLowerCase());
        const requestedLibraryId = libraryId === undefined ? homeData.selectedLibraryId : libraryId;
        const selectedLibraryId = requestedLibraryId && libraries.some((library) => library.Id === requestedLibraryId)
          ? requestedLibraryId
          : requestedLibraryId === null
            ? null
            : otherLibrary?.Id ?? libraries[0]?.Id ?? null;
        const animeLibrary = libraries.find((library) => library.Name.toLowerCase() === "anime");
        const [libraryItems, featuredItems, continueWatching, watchHistory, latestAdded, favorites] = await Promise.all([
          selectedLibraryId ? client.getLibraryItems(selectedLibraryId, term) : Promise.resolve([]),
          !selectedLibraryId && animeLibrary
            ? client
                .getLibraryItems(animeLibrary.Id)
                .then((items) => items.filter((item) => isPlayableItem(item) && isKenshinItem(item)).sort(byEpisodeOrder))
            : Promise.resolve([]),
          selectedLibraryId ? client.getLibraryResumeItems(selectedLibraryId) : client.getContinueWatching(),
          client.getWatchHistory(selectedLibraryId ?? undefined),
          selectedLibraryId ? client.getLibraryItems(selectedLibraryId, "", 18) : client.getLatestAdded(),
          selectedLibraryId ? client.getLibraryFavoriteItems(selectedLibraryId) : client.getFavorites(),
        ]);
        const libraryItemsUnique = uniqueItems(libraryItems);
        const watchHistoryItems = sortByLastPlayed(uniqueItems(watchHistory.filter(hasWatchActivity)));
        const continueWatchingItems = sortByLastPlayed(
          uniqueItems([
            ...continueWatching,
            ...watchHistoryItems.filter(hasResumeProgress),
            ...libraryItemsUnique.filter(hasResumeProgress),
          ]),
        );
        setHomeData({
          libraries,
          playlists: [],
          selectedLibraryId,
          featuredItems: uniqueItems(featuredItems),
          libraryItems: libraryItemsUnique,
          continueWatching: continueWatchingItems,
          watchHistory: watchHistoryItems,
          latestAdded: uniqueItems(latestAdded),
          favorites: uniqueItems(favorites),
        });
      } catch {
        setHomeError("Could not load your Jellyfin library. Log out and back in if the token expired.");
      } finally {
        if (!options.silent) setLoadingHome(false);
      }
    },
    [client, homeData.selectedLibraryId, searchTerm, session],
  );

  useEffect(() => {
    const timer = window.setTimeout(() => {
      initialBrowseRouteRef.current = getSpiritFlixBrowseRoute();
      if (window.location.pathname.startsWith("/spiritflix/watch/")) {
        setSpiritFlixBrowseRoute(initialBrowseRouteRef.current, "replace");
      }
      const stored = getStoredSession();
      if (stored) {
        setSession(stored);
        setServerUrl(stored.serverUrl);
      }
      setIsRestoringSession(false);
    }, 0);
    return () => window.clearTimeout(timer);
  }, []);

  useEffect(() => {
    if (isRestoringSession) return undefined;
    const timer = window.setTimeout(() => {
      void checkServer(serverUrl);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [checkServer, isRestoringSession, serverUrl]);

  useEffect(() => {
    if (!session) {
      loadedSessionKeyRef.current = null;
      return undefined;
    }
    const sessionKey = `${session.serverUrl}:${session.userId}:${session.accessToken}`;
    if (loadedSessionKeyRef.current === sessionKey) return undefined;
    loadedSessionKeyRef.current = sessionKey;
    const timer = window.setTimeout(() => {
      void loadHome(initialBrowseRouteRef.current?.libraryId ?? null);
    }, 0);
    return () => window.clearTimeout(timer);
  }, [loadHome, session]);

  useEffect(() => {
    if (!session) return undefined;
    const refreshPlaybackState = () => {
      void loadHome(homeData.selectedLibraryId, searchTerm, { silent: true });
    };
    const handleVisibilityChange = () => {
      if (document.visibilityState === "visible") refreshPlaybackState();
    };
    const timer = window.setInterval(refreshPlaybackState, 30000);
    window.addEventListener("focus", refreshPlaybackState);
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      window.clearInterval(timer);
      window.removeEventListener("focus", refreshPlaybackState);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [homeData.selectedLibraryId, loadHome, searchTerm, session]);

  const handleLogin = async (username: string, password: string, targetServerUrl: string) => {
    const authClient = new JellyfinClient(targetServerUrl);
    const nextSession = await authClient.login(username, password);
    storeSession(nextSession);
    setSession(nextSession);
    setServerUrl(nextSession.serverUrl);
    await checkServer(nextSession.serverUrl);
  };

  const handleLogout = () => {
    setSpiritFlixBrowseRoute({ libraryId: null, modelName: null }, "replace");
    clearStoredSession();
    loadedSessionKeyRef.current = null;
    setSession(null);
    setHomeData(emptyHome);
    setSelectedItem(null);
    setPlayingItem(null);
    setPlayingQueue(null);
  };

  const buildQueue = (
    item: JellyfinItem,
    items: JellyfinItem[] = [item],
    sourceTitle = "Direct play",
    startPositionTicks?: number,
  ) => {
    const playableItems = uniqueItems(items.filter(isPlayableItem));
    const queueItems = playableItems.some((queueItem) => queueItem.Id === item.Id) ? playableItems : [item, ...playableItems];
    return {
      items: queueItems,
      originalItems: queueItems,
      currentIndex: Math.max(0, queueItems.findIndex((queueItem) => queueItem.Id === item.Id)),
      sourceTitle,
      startPositionTicks,
      isShuffled: false,
    };
  };

  const handlePlay = (item: JellyfinItem, queueItems?: JellyfinItem[], sourceTitle?: string, startPositionTicks?: number) => {
    if (isPlayableItem(item)) {
      setPlayingItem(item);
      setPlayingQueue(buildQueue(item, queueItems, sourceTitle, startPositionTicks));
    }
  };

  const handleQueueSelect = (item: JellyfinItem) => {
    setPlayingItem(item);
    setPlayingQueue((current) => {
      if (!current) return buildQueue(item);
      const currentIndex = current.items.findIndex((queueItem) => queueItem.Id === item.Id);
      return {
        ...current,
        currentIndex: currentIndex >= 0 ? currentIndex : current.currentIndex,
      };
    });
  };

  const handleShuffleQueue = useCallback((currentItemId: string) => {
    setPlayingQueue((current) => {
      if (!current || current.items.length < 2) return current;
      const originalItems = current.originalItems?.length ? current.originalItems : current.items;
      const items = current.isShuffled ? originalItems : shuffleQueueAfterCurrent(originalItems, currentItemId);
      return {
        ...current,
        originalItems,
        items,
        currentIndex: Math.max(0, items.findIndex((queueItem) => queueItem.Id === currentItemId)),
        isShuffled: !current.isShuffled,
      };
    });
  }, []);

  const handlePlaybackProgress = useCallback(
    (progress: SpiritFlixPlaybackProgress) => {
      setSelectedItem((current) => (current?.Id === progress.itemId ? applyPlaybackProgress(current, progress) : current));

      setHomeData((current) => {
        let updatedItem: JellyfinItem | null = progress.item ? applyPlaybackProgress(progress.item, progress) : null;
        const nextLibraryItems = current.libraryItems.map((item) => {
          const nextItem = applyPlaybackProgress(item, progress);
          if (nextItem.Id === progress.itemId) updatedItem = nextItem;
          return nextItem;
        });
        const nextFeaturedItems = current.featuredItems.map((item) => applyPlaybackProgress(item, progress));
        const nextLatestAdded = current.latestAdded.map((item) => applyPlaybackProgress(item, progress));
        const nextFavorites = current.favorites.map((item) => applyPlaybackProgress(item, progress));
        const nextWatchHistory = current.watchHistory.map((item) => {
          const nextItem = applyPlaybackProgress(item, progress);
          if (nextItem.Id === progress.itemId) updatedItem = nextItem;
          return nextItem;
        });
        const nextContinueWatching = current.continueWatching.map((item) => {
          const nextItem = applyPlaybackProgress(item, progress);
          if (nextItem.Id === progress.itemId) updatedItem = nextItem;
          return nextItem;
        });
        const sourceItem = updatedItem ?? [...current.libraryItems, ...current.continueWatching, ...current.featuredItems, ...current.latestAdded, ...current.favorites].find(
          (item): item is JellyfinItem => Boolean(item && item.Id === progress.itemId),
        );
        const nextSourceItem = sourceItem ? applyPlaybackProgress(sourceItem, progress) : null;
        return {
          ...current,
          libraryItems: nextLibraryItems,
          featuredItems: nextFeaturedItems,
          latestAdded: nextLatestAdded,
          favorites: nextFavorites,
          watchHistory: nextSourceItem
            ? upsertWatchHistoryItem(nextWatchHistory, nextSourceItem)
            : nextWatchHistory,
          continueWatching: nextSourceItem
            ? upsertPlaybackItem(nextContinueWatching, nextSourceItem)
            : nextContinueWatching.filter((item) => item.Id !== progress.itemId),
        };
      });
    },
    [],
  );

  const handleToggleFavorite = useCallback(
    (item: JellyfinItem, isFavorite: boolean) => {
      const nextItem = applyFavoriteState(item, item.Id, isFavorite);
      setSelectedItem((current) => (current?.Id === item.Id ? applyFavoriteState(current, item.Id, isFavorite) : current));
      setPlayingItem((current) => (current?.Id === item.Id ? applyFavoriteState(current, item.Id, isFavorite) : current));
      setPlayingQueue((current) =>
        current
          ? {
              ...current,
              items: current.items.map((queueItem) => applyFavoriteState(queueItem, item.Id, isFavorite)),
            }
          : current,
      );
      setHomeData((current) => ({
        ...current,
        libraryItems: current.libraryItems.map((libraryItem) => applyFavoriteState(libraryItem, item.Id, isFavorite)),
        featuredItems: current.featuredItems.map((featuredItem) => applyFavoriteState(featuredItem, item.Id, isFavorite)),
        continueWatching: current.continueWatching.map((resumeItem) => applyFavoriteState(resumeItem, item.Id, isFavorite)),
        watchHistory: current.watchHistory.map((historyItem) => applyFavoriteState(historyItem, item.Id, isFavorite)),
        latestAdded: current.latestAdded.map((latestItem) => applyFavoriteState(latestItem, item.Id, isFavorite)),
        favorites: upsertFavoriteItem(
          current.favorites.map((favoriteItem) => applyFavoriteState(favoriteItem, item.Id, isFavorite)),
          nextItem,
        ),
      }));

      void client.setFavorite(item.Id, isFavorite).catch(() => {
        void loadHome(homeData.selectedLibraryId);
      });
    },
    [client, homeData.selectedLibraryId, loadHome],
  );

  const handleOpenDetails = (item: JellyfinItem) => {
    setSelectedItem(item);
  };

  const handleDetailsPlay = (item: JellyfinItem) => {
    const inferredQueue = inferPlaybackQueueForItem(item, homeData);
    setSelectedItem(null);
    handlePlay(
      item,
      inferredQueue?.items,
      inferredQueue?.sourceTitle,
      item.UserData?.PlaybackPositionTicks,
    );
  };

  const handleSearch = (term: string) => {
    setSearchTerm(term);
    void loadHome(homeData.selectedLibraryId, term);
  };

  const handleSelectHome = () => {
    initialBrowseRouteRef.current = { libraryId: null, modelName: null };
    setSpiritFlixBrowseRoute({ libraryId: null, modelName: null });
    void loadHome(null);
  };

  const handleSelectLibrary = (libraryId: string) => {
    initialBrowseRouteRef.current = { libraryId, modelName: null };
    setSpiritFlixBrowseRoute({ libraryId, modelName: null });
    void loadHome(libraryId);
  };

  const handleSelectModel = (modelName: string | null) => {
    const libraryId = homeData.selectedLibraryId;
    if (!libraryId) return;
    initialBrowseRouteRef.current = { libraryId, modelName };
    setSpiritFlixBrowseRoute({ libraryId, modelName });
  };

  return (
    <main className="spiritflix-shell">
      {isRestoringSession ? (
        <section className="spiritflix-restore">
          <div className="spiritflix-brand">
            <span className="spiritflix-brand__sigil">SF</span>
            <span>SpiritFlix</span>
          </div>
        </section>
      ) : !session ? (
        <SpiritFlixLogin
          serverUrl={serverUrl}
          serverInfo={serverInfo}
          serverError={serverError}
          onServerUrlChange={setServerUrl}
          onRetry={() => checkServer(serverUrl)}
          onLogin={handleLogin}
        />
      ) : (
        <SpiritFlixHome
          client={client}
          data={homeData}
          loading={loadingHome}
          error={homeError}
          session={session}
          searchTerm={searchTerm}
          serverInfo={serverInfo}
          onLogout={handleLogout}
          onRefresh={() => loadHome(homeData.selectedLibraryId)}
          onSearch={handleSearch}
          onSelectHome={handleSelectHome}
          onSelectLibrary={handleSelectLibrary}
          initialModelName={initialBrowseRouteRef.current?.modelName ?? null}
          onSelectModel={handleSelectModel}
          onOpenDetails={handleOpenDetails}
          onPlay={handlePlay}
        />
      )}

      {selectedItem ? (
        <SpiritFlixDetailsModal
          client={client}
          item={selectedItem}
          onClose={() => setSelectedItem(null)}
          onPlay={handleDetailsPlay}
        />
      ) : null}

      {playingItem ? (
        <SpiritFlixPlayer
          client={client}
          item={playingItem}
          queue={playingQueue}
          startPositionTicks={playingQueue?.startPositionTicks}
          onPlaybackProgress={handlePlaybackProgress}
          onToggleFavorite={handleToggleFavorite}
          onSelectItem={handleQueueSelect}
          onShuffleQueue={handleShuffleQueue}
          onClose={() => {
            setPlayingItem(null);
            setPlayingQueue(null);
            void loadHome(homeData.selectedLibraryId);
          }}
        />
      ) : null}
    </main>
  );
}

"use client";

import { Info, Play } from "lucide-react";
import { isPlayableItem, type JellyfinClient } from "@/lib/spiritflix-jellyfin-client";
import { getResumeProgressPercent, getResumeSlotLabel, hasResumeProgress } from "@/lib/spiritflix-resume";
import type { FaceOrganizerVideoMatch, JellyfinItem } from "@/lib/spiritflix-types";
import { SpiritFlixImage } from "./SpiritFlixImage";

interface SpiritFlixCardProps {
  client: JellyfinClient;
  item: JellyfinItem;
  variant?: "poster" | "landscape";
  showResume?: boolean;
  faceMatch?: FaceOrganizerVideoMatch;
  modelName?: string;
  playOnPrimaryTap?: boolean;
  onOpenDetails: (item: JellyfinItem) => void;
  onPlay: (item: JellyfinItem, startPositionTicks?: number) => void;
}

export function SpiritFlixCard({
  client,
  item,
  variant = "poster",
  showResume = true,
  faceMatch,
  modelName,
  playOnPrimaryTap = false,
  onOpenDetails,
  onPlay,
}: SpiritFlixCardProps) {
  const progress = getResumeProgressPercent(item);
  const hasProgress = showResume && hasResumeProgress(item);
  const canPlay = isPlayableItem(item);
  const imageType = variant === "landscape" ? "Thumb" : "Primary";
  const resumeTicks = item.UserData?.PlaybackPositionTicks;

  return (
    <article className={`spiritflix-card spiritflix-card--${variant}`}>
      <button
        className="spiritflix-card__poster"
        type="button"
        onClick={() => {
          if (playOnPrimaryTap && canPlay) {
            onPlay(item, hasProgress ? resumeTicks : undefined);
          } else {
            onOpenDetails(item);
          }
        }}
      >
        <SpiritFlixImage
          client={client}
          item={item}
          type={imageType}
          width={variant === "landscape" ? 520 : 420}
          alt={item.Name}
        />
        <span className="spiritflix-card__veil" />
        {progress > 0 ? (
          <span className="spiritflix-card__progress">
            <span style={{ width: `${Math.min(100, progress)}%` }} />
          </span>
        ) : null}
        {faceMatch ? (
          <span className={`spiritflix-face-badge spiritflix-card__face-badge is-${faceMatch.status}`}>
            {faceMatch.status === "confirmed"
              ? `Identified: ${faceMatch.primaryPerformer?.name ?? modelName ?? "Performer"} (${Math.round((faceMatch.confidence ?? 0) * 100)}%)`
              : faceMatch.label}
          </span>
        ) : null}
        {hasProgress ? <span className="spiritflix-card__resume-badge">Resume</span> : null}
      </button>
      <div className="spiritflix-card__meta">
        <h3>{item.Name}</h3>
        <p>{modelName ?? (hasProgress ? getResumeSlotLabel(item) : [item.ProductionYear, item.Type].filter(Boolean).join(" / "))}</p>
      </div>
      <div className="spiritflix-card__actions">
        {canPlay ? (
          <button
            type="button"
            onClick={() => onPlay(item, hasProgress ? resumeTicks : undefined)}
            aria-label={`${hasProgress ? "Resume" : "Play"} ${item.Name}`}
          >
            <Play size={17} aria-hidden="true" />
          </button>
        ) : null}
        <button type="button" onClick={() => onOpenDetails(item)} aria-label={`Open details for ${item.Name}`}>
          <Info size={17} aria-hidden="true" />
        </button>
      </div>
    </article>
  );
}

"use client";

import { Calendar, Clock, Heart, Play, RotateCcw, X } from "lucide-react";
