interface GalleryLightboxProps {
  items: SpiritFlixGalleryItem[];
  initialIndex: number;
  onClose: () => void;
}

function GalleryLightbox({ items, initialIndex, onClose }: GalleryLightboxProps) {
  const [activeIndex, setActiveIndex] = useState(initialIndex);
  const [isPlaying, setIsPlaying] = useState(items.length > 1);
  const [intervalSeconds, setIntervalSeconds] = useState(() => {
    if (typeof window === "undefined") return 5;
    const stored = window.localStorage.getItem(GALLERY_INTERVAL_KEY);
    const value = stored ? Number(stored) : 5;
    return Number.isFinite(value) ? Math.min(30, Math.max(2, value)) : 5;
  });
  const rootRef = useRef<HTMLDivElement | null>(null);
  const activeItem = items[activeIndex] ?? items[0];

  const goToOffset = useCallback(
    (offset: number) => {
      setActiveIndex((current) => {
        if (!items.length) return 0;
        return (current + offset + items.length) % items.length;
      });
    },
    [items.length],
  );

  useEffect(() => {
    setActiveIndex(Math.min(Math.max(initialIndex, 0), Math.max(0, items.length - 1)));
    setIsPlaying(items.length > 1);
  }, [initialIndex, items.length]);

  useEffect(() => {
    window.localStorage.setItem(GALLERY_INTERVAL_KEY, String(intervalSeconds));
  }, [intervalSeconds]);

  useEffect(() => {
    if (!isPlaying || items.length <= 1) return undefined;
    const timer = window.setInterval(() => goToOffset(1), intervalSeconds * 1000);
    return () => window.clearInterval(timer);
  }, [goToOffset, intervalSeconds, isPlaying, items.length]);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") onClose();
      if (event.key === "ArrowLeft") goToOffset(-1);
      if (event.key === "ArrowRight") goToOffset(1);
      if (event.key === " ") {
        event.preventDefault();
        setIsPlaying((current) => !current);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [goToOffset, onClose]);

  const toggleFullscreen = async () => {
    if (document.fullscreenElement) {
      await document.exitFullscreen().catch(() => undefined);
      return;
    }
    await rootRef.current?.requestFullscreen().catch(() => undefined);
  };

  if (!activeItem) return null;

  return (
    <div className="spiritflix-gallery-viewer" ref={rootRef} role="dialog" aria-modal="true">
      <div className="spiritflix-gallery-viewer__stage">
        <img src={activeItem.src} alt={`${activeItem.modelName} gallery picture`} />
      </div>
      <div className="spiritflix-gallery-viewer__top">
        <button type="button" onClick={onClose} aria-label="Close gallery">
          <X size={22} aria-hidden="true" />
        </button>
        <div className="spiritflix-gallery-viewer__title">
          <strong>{activeItem.modelName}</strong>
          <span>
            {activeIndex + 1} / {items.length}
            {activeItem.collection ? ` / ${activeItem.collection}` : ""}
          </span>
        </div>
        <button type="button" onClick={toggleFullscreen} aria-label="Fullscreen gallery">
          <Maximize2 size={21} aria-hidden="true" />
        </button>
      </div>
      <div className="spiritflix-gallery-viewer__controls">
        <button type="button" onClick={() => goToOffset(-1)} disabled={items.length <= 1} aria-label="Previous picture">
          <ChevronLeft size={24} aria-hidden="true" />
        </button>
        <button type="button" onClick={() => setIsPlaying((current) => !current)} disabled={items.length <= 1} aria-label={isPlaying ? "Pause gallery" : "Play gallery"}>
          {isPlaying ? <Pause size={22} aria-hidden="true" /> : <Play size={22} fill="currentColor" aria-hidden="true" />}
        </button>
        <label className="spiritflix-gallery-viewer__timer">
          <Timer size={18} aria-hidden="true" />
          <input
            type="number"
            min={2}
            max={30}
            step={1}
            value={intervalSeconds}
            onChange={(event) => {
              const value = Number(event.target.value);
              if (Number.isFinite(value)) setIntervalSeconds(Math.min(30, Math.max(2, value)));
            }}
            aria-label="Gallery seconds per picture"
          />
        </label>
        <button type="button" onClick={() => goToOffset(1)} disabled={items.length <= 1} aria-label="Next picture">
          <ChevronRight size={24} aria-hidden="true" />
        </button>
      </div>
    </div>
  );
}

export function SpiritFlixHome({
  client,
  data,
  loading,
  error,
  session,
  searchTerm,
  serverInfo,
  onLogout,
  onRefresh,
  onSearch,
  onSelectHome,
  onSelectLibrary,
  initialModelName = null,
  onSelectModel,
  onOpenDetails,
  onPlay,
}: SpiritFlixHomeProps) {
  const [viewMode, setViewMode] = useState<LibraryViewMode>("grid");
  const [sortMode, setSortMode] = useState<LibrarySortMode>("model");
  const [sortDirection, setSortDirection] = useState<LibrarySortDirection>("desc");
  const [filtersOpen, setFiltersOpen] = useState(false);
  const [selectedModel, setSelectedModel] = useState<string | null>(initialModelName);
  const [faceMetadata, setFaceMetadata] = useState<FaceOrganizerMetadataResponse | null>(null);
  const [faceMetadataError, setFaceMetadataError] = useState("");
  const [galleryData, setGalleryData] = useState<SpiritFlixGalleryResponse | null>(null);
  const [galleryError, setGalleryError] = useState("");
  const [galleryLightbox, setGalleryLightbox] = useState<{ items: SpiritFlixGalleryItem[]; index: number } | null>(null);
  const [playPrimaryTapOnMobile, setPlayPrimaryTapOnMobile] = useState(false);
  const longPressTimerRef = useRef<number | null>(null);
  const didLongPressShuffleRef = useRef(false);
  const resumeTrackRef = useRef<HTMLDivElement | null>(null);
  const modelStripRef = useRef<HTMLDivElement | null>(null);
  const isHomeView = data.selectedLibraryId === null;
  const hero = isHomeView
    ? data.featuredItems[0] ?? data.continueWatching[0] ?? data.latestAdded[0] ?? data.libraryItems[0] ?? null
    : data.libraryItems[0] ?? data.latestAdded[0] ?? data.continueWatching[0] ?? null;
  const selectedLibrary = data.libraries.find((library) => library.Id === data.selectedLibraryId);
  const libraryTitle = isHomeView ? "Home" : displayLibraryName(selectedLibrary?.Name);
  const modelGroups = useMemo(() => buildModelGroups(data.libraryItems, faceMetadata), [data.libraryItems, faceMetadata]);
  const selectedModelGroup = selectedModel ? modelGroups.find((model) => model.name === selectedModel) : null;
  const playableLibraryItems = useMemo(() => data.libraryItems.filter(isPlayableItem), [data.libraryItems]);
  const galleryItems = useMemo(() => galleryData?.items ?? [], [galleryData]);
  const selectedModelGalleryItems = useMemo(
    () => (selectedModelGroup ? galleryItems.filter((item) => galleryItemMatchesModel(item, selectedModelGroup.name)) : []),
    [galleryItems, selectedModelGroup],
  );
  const visibleGalleryItems = selectedModelGroup ? selectedModelGalleryItems : galleryItems;
  const visibleLibraryItems = useMemo(() => {
    const sourceItems = selectedModelGroup?.items ?? playableLibraryItems;
    const direction = sortDirection === "asc" ? 1 : -1;

    return [...sourceItems].sort((left, right) => {
      if (sortMode === "title") {
        return direction * left.Name.localeCompare(right.Name);
      }

      if (sortMode === "dateAdded") {
        return direction * (getDateCreatedMs(left) - getDateCreatedMs(right)) || left.Name.localeCompare(right.Name);
      }

      if (sortMode === "duration") {
        return compareOptionalNumber(getDurationTicks(left), getDurationTicks(right), sortDirection) || left.Name.localeCompare(right.Name);
      }

      const modelCompare = getDisplayModelName(left, faceMetadata).localeCompare(getDisplayModelName(right, faceMetadata));
      if (modelCompare) return direction * modelCompare;
      const leftMatch = getFaceMatch(left, faceMetadata);
      const rightMatch = getFaceMatch(right, faceMetadata);
      return getStatusRank(leftMatch?.status) - getStatusRank(rightMatch?.status) || left.Name.localeCompare(right.Name);
    });
  }, [faceMetadata, playableLibraryItems, selectedModelGroup, sortDirection, sortMode]);
  const continueWatchingItems = useMemo(() => {
    const sourceItems = selectedModelGroup?.items ?? playableLibraryItems;
    const allowedIds = selectedModelGroup ? new Set(sourceItems.map((item) => item.Id)) : null;
    const seen = new Set<string>();
    return [...data.continueWatching, ...data.watchHistory, ...sourceItems]
      .filter((item) => {
        if (allowedIds && !allowedIds.has(item.Id)) return false;
        if (seen.has(item.Id)) return false;
        seen.add(item.Id);
        return true;
      })
      .filter(hasResumeProgress)
      .sort((left, right) => {
        const leftDate = left.UserData?.LastPlayedDate ? new Date(left.UserData.LastPlayedDate).getTime() : 0;
        const rightDate = right.UserData?.LastPlayedDate ? new Date(right.UserData.LastPlayedDate).getTime() : 0;
        return rightDate - leftDate;
      })
      .slice(0, 14);
  }, [data.continueWatching, data.watchHistory, playableLibraryItems, selectedModelGroup]);
  const favoriteItems = useMemo(() => {
    const sourceItems = selectedModelGroup?.items ?? playableLibraryItems;
    const allowedIds = selectedModelGroup ? new Set(sourceItems.map((item) => item.Id)) : null;
    const seen = new Set<string>();
    return data.favorites
      .filter((item) => isPlayableItem(item) && item.UserData?.IsFavorite)
      .filter((item) => {
        if (allowedIds && !allowedIds.has(item.Id)) return false;
        if (seen.has(item.Id)) return false;
        seen.add(item.Id);
        return true;
      })
      .sort((left, right) => left.Name.localeCompare(right.Name));
  }, [data.favorites, playableLibraryItems, selectedModelGroup]);
  const historyItems = useMemo(() => {
    const sourceItems = selectedModelGroup?.items ?? playableLibraryItems;
    const allowedIds = selectedModelGroup ? new Set(sourceItems.map((item) => item.Id)) : null;
    const seen = new Set<string>();
    return [...data.continueWatching, ...data.watchHistory, ...sourceItems]
      .filter((item) => {
        if (allowedIds && !allowedIds.has(item.Id)) return false;
        if (seen.has(item.Id)) return false;
        seen.add(item.Id);
        return Boolean(
          item.UserData?.LastPlayedDate ||
            item.UserData?.Played ||
            (item.UserData?.PlaybackPositionTicks && item.UserData.PlaybackPositionTicks > 0) ||
            (item.UserData?.PlayCount && item.UserData.PlayCount > 0),
        );
      })
      .sort((left, right) => getLastPlayedMs(right) - getLastPlayedMs(left) || left.Name.localeCompare(right.Name))
      .slice(0, 80);
  }, [data.continueWatching, data.watchHistory, playableLibraryItems, selectedModelGroup]);
  const libraryStats = [
    { label: "Videos", value: playableLibraryItems.length },
    { label: "Models", value: modelGroups.length },
    { label: "Selected", value: selectedModelGroup?.count ?? playableLibraryItems.length },
    { label: "Pics", value: visibleGalleryItems.length },
    { label: "Identified", value: playableLibraryItems.filter((item) => hasIdentifiedFace(getFaceMatch(item, faceMetadata))).length },
    { label: "Review", value: playableLibraryItems.filter((item) => getFaceMatch(item, faceMetadata)?.status === "needs_review").length },
    { label: "Unscanned", value: playableLibraryItems.filter((item) => getFaceMatch(item, faceMetadata)?.status === "unscanned").length },
    { label: "New", value: getNewThisWeekCount(playableLibraryItems) },
  ];
  const heroMeta = hero
    ? [hero.ProductionYear, hero.Type, hero.Genres?.slice(0, 2).join(" / ")].filter(Boolean).join(" / ")
    : "";
  const heroQueue =
    hero && data.featuredItems.some((item) => item.Id === hero.Id)
      ? data.featuredItems
      : hero && data.continueWatching.some((item) => item.Id === hero.Id)
        ? data.continueWatching
        : hero && data.latestAdded.some((item) => item.Id === hero.Id)
          ? data.latestAdded
          : data.libraryItems;
  const heroSource =
    hero && data.featuredItems.some((item) => item.Id === hero.Id)
      ? "Featured Anime"
      : hero && data.continueWatching.some((item) => item.Id === hero.Id)
        ? "Continue Watching"
      : hero && data.latestAdded.some((item) => item.Id === hero.Id)
        ? "Latest Added"
        : libraryTitle;
  const canPlayHero = hero ? isPlayableItem(hero) : false;

  const loadGallery = useCallback(async () => {
    try {
      const nextGallery = await client.getGallery();
      setGalleryData(nextGallery);
      setGalleryError("");
    } catch {
      setGalleryData(null);
      setGalleryError("Gallery is unavailable; uploaded pictures will appear after the organizer gallery index is reachable.");
    }
  }, [client]);

  const handleRefresh = () => {
    onRefresh();
    void loadGallery();
  };

  useEffect(() => {
    const stored = window.localStorage.getItem(LIBRARY_VIEW_MODE_KEY);
    if (stored === "grid" || stored === "list" || stored === "history" || stored === "gallery") setViewMode(stored);
    const storedSort = window.localStorage.getItem(LIBRARY_SORT_MODE_KEY);
    if (storedSort === "model" || storedSort === "title" || storedSort === "dateAdded" || storedSort === "duration") setSortMode(storedSort);
    const storedDirection = window.localStorage.getItem(LIBRARY_SORT_DIRECTION_KEY);
    if (storedDirection === "asc" || storedDirection === "desc") setSortDirection(storedDirection);
  }, []);

  useEffect(() => {
    void loadGallery();
  }, [loadGallery]);

  useEffect(() => {
    const queries = [
      window.matchMedia("(max-width: 980px)"),
      window.matchMedia("(pointer: coarse)"),
    ];
    const updateMode = () => setPlayPrimaryTapOnMobile(queries.some((query) => query.matches));

    updateMode();
    queries.forEach((query) => query.addEventListener("change", updateMode));
    return () => queries.forEach((query) => query.removeEventListener("change", updateMode));
  }, []);

  useEffect(() => {
    window.localStorage.setItem(LIBRARY_VIEW_MODE_KEY, viewMode);
  }, [viewMode]);

  useEffect(() => {
    window.localStorage.setItem(LIBRARY_SORT_MODE_KEY, sortMode);
  }, [sortMode]);

  useEffect(() => {
    window.localStorage.setItem(LIBRARY_SORT_DIRECTION_KEY, sortDirection);
  }, [sortDirection]);

  useEffect(() => {
    setSelectedModel(initialModelName);
  }, [data.selectedLibraryId, initialModelName]);

  useEffect(() => {
    if (!selectedModel || !modelGroups.length) return;
    if (modelGroups.some((model) => model.name === selectedModel)) return;
    setSelectedModel(null);
    onSelectModel(null);
  }, [modelGroups, onSelectModel, selectedModel]);

  const selectModel = (modelName: string | null) => {
    setSelectedModel(modelName);
    onSelectModel(modelName);
  };

  useEffect(() => {
    if (isHomeView || !playableLibraryItems.length) {
      setFaceMetadata(null);
      setFaceMetadataError("");
      return undefined;
    }

    let isCancelled = false;
    const cacheKey = `${FACE_METADATA_CACHE_KEY}:${data.selectedLibraryId}:${playableLibraryItems.map((item) => item.Id).join(",")}`;
    const cached = window.localStorage.getItem(cacheKey);
    if (cached) {
      try {
        setFaceMetadata(JSON.parse(cached) as FaceOrganizerMetadataResponse);
      } catch {
        window.localStorage.removeItem(cacheKey);
      }
    }

    void client
      .getFaceOrganizerMetadata(playableLibraryItems)
      .then((metadata) => {
        if (isCancelled) return;
        setFaceMetadata(metadata);
        setFaceMetadataError("");
        window.localStorage.setItem(cacheKey, JSON.stringify(metadata));
      })
      .catch(() => {
        if (!isCancelled) setFaceMetadataError("Face Organizer metadata is unavailable; using Jellyfin model hints.");
      });

    return () => {
      isCancelled = true;
    };
  }, [client, data.selectedLibraryId, isHomeView, playableLibraryItems]);

  const playShuffle = (scope: "library" | "model") => {
    const sourceItems = scope === "model" && selectedModelGroup ? selectedModelGroup.items : playableLibraryItems;
    const shuffled = shuffleItems(sourceItems);
    const firstItem = shuffled[0];
    if (firstItem) {
      onPlay(firstItem, shuffled, scope === "model" && selectedModelGroup ? `${selectedModelGroup.name} Shuffle` : `${libraryTitle} Shuffle`);
    }
  };

  const clearLongPressTimer = () => {
    if (longPressTimerRef.current) {
      window.clearTimeout(longPressTimerRef.current);
      longPressTimerRef.current = null;
    }
  };

  const startShuffleLongPress = () => {
    didLongPressShuffleRef.current = false;
    if (!selectedModelGroup) return;
    clearLongPressTimer();
    longPressTimerRef.current = window.setTimeout(() => {
      longPressTimerRef.current = null;
      didLongPressShuffleRef.current = true;
      playShuffle("model");
    }, 520);
  };

  const handleShuffleClick = () => {
    if (didLongPressShuffleRef.current) {
      didLongPressShuffleRef.current = false;
      return;
    }
    playShuffle("library");
  };

  const scrollRow = (ref: { current: HTMLDivElement | null }, direction: "left" | "right") => {
    const node = ref.current;
    if (!node) return;
    const distance = Math.max(260, node.clientWidth * 0.82);
    node.scrollBy({ left: direction === "left" ? -distance : distance, behavior: "smooth" });
  };

  return (
    <section className="spiritflix-home">
      <header className="spiritflix-topbar">
        <div className="spiritflix-brand spiritflix-brand--compact">
          <span className="spiritflix-brand__sigil">SF</span>
          <span>SpiritFlix</span>
        </div>
        <nav className="spiritflix-topbar__links" aria-label="SpiritFlix sections">
          <button type="button" className={isHomeView ? "is-active" : undefined} onClick={onSelectHome}>
            Home
          </button>
          {data.libraries.map((library) => (
            <button
              key={library.Id}
              type="button"
              className={library.Id === data.selectedLibraryId ? "is-active" : undefined}
              aria-current={library.Id === data.selectedLibraryId ? "page" : undefined}
              onClick={() => onSelectLibrary(library.Id)}
            >
              {displayLibraryName(library.Name)}
            </button>
          ))}
        </nav>
        <div className="spiritflix-search">
          <Search size={17} aria-hidden="true" />
          <input
            value={searchTerm}
            onChange={(event) => onSearch(event.target.value)}
            placeholder="Search your Jellyfin library"
          />
        </div>
        <div className="spiritflix-topbar__controls">
          <button className="spiritflix-source-pill" type="button" onClick={handleRefresh} title="Refresh Jellyfin source">
            <Server size={15} aria-hidden="true" />
            <span>{serverInfo?.ServerName ?? "Jellyfin"}</span>
          </button>
          <button className="spiritflix-icon-button" type="button" onClick={handleRefresh} aria-label="Refresh library">
            <RefreshCw size={18} aria-hidden="true" />
          </button>
          <button className="spiritflix-icon-button" type="button" onClick={onLogout} aria-label="Switch source or sign out">
            <Settings size={18} aria-hidden="true" />
          </button>
          <button className="spiritflix-logout" type="button" onClick={onLogout}>
            <LogOut size={17} aria-hidden="true" />
            <span>{session.username}</span>
          </button>
        </div>
      </header>

      <section className={`spiritflix-hero ${hero ? "" : "spiritflix-hero--empty"}`}>
        {hero ? (
          <>
            <SpiritFlixImage client={client} item={hero} type="Primary" width={700} className="spiritflix-hero__ambient" />
            <SpiritFlixImage client={client} item={hero} type="Backdrop" width={1600} className="spiritflix-hero__image" />
          </>
        ) : null}
        <div className="spiritflix-hero__shade" />
        <div className="spiritflix-hero__content">
          <span className="spiritflix-kicker">
            <Sparkles size={14} aria-hidden="true" />
            {serverInfo?.ServerName ? `${serverInfo.ServerName} / ${libraryTitle}` : libraryTitle}
          </span>
          <h1>{hero?.Name ?? "Your cinema is waiting"}</h1>
          {heroMeta ? <div className="spiritflix-hero__meta">{heroMeta}</div> : null}
          <p>{hero?.Overview || "Choose a library and stream from your real Jellyfin server."}</p>
          <div className="spiritflix-hero__actions">
            {hero ? (
              <>
                {canPlayHero ? (
                  <button
                    className="spiritflix-primary-button"
                    type="button"
                    onClick={() => onPlay(hero, heroQueue, heroSource, hasResumeProgress(hero) ? getResumePositionTicks(hero) : undefined)}
                  >
                    {hasResumeProgress(hero) ? (
                      <RotateCcw size={19} aria-hidden="true" />
                    ) : (
                      <Play size={19} fill="currentColor" aria-hidden="true" />
                    )}
                    {hasResumeProgress(hero) ? `Resume from ${getResumeSlotLabel(hero).split(" / ")[0]}` : "Play"}
                  </button>
                ) : null}
                <button className="spiritflix-secondary-button" type="button" onClick={() => onOpenDetails(hero)}>
                  Details
                </button>
              </>
            ) : null}
          </div>
        </div>
      </section>

      {error ? <p className="spiritflix-error spiritflix-error--home">{error}</p> : null}
      {loading ? <div className="spiritflix-loading">Loading Jellyfin rows...</div> : null}

      <div className="spiritflix-rows">
        {!isHomeView ? (
          <section className="spiritflix-library-v2" aria-label={`${libraryTitle} model library`}>
            <div className="spiritflix-library-v2__header">
              <div>
                <span className="spiritflix-kicker">
                  <Sparkles size={14} aria-hidden="true" />
                  {libraryTitle}
                </span>
                <h2>{viewMode === "gallery" ? (selectedModelGroup ? `${selectedModelGroup.name} Pics` : "Gallery") : selectedModelGroup?.name ?? "All Models"}</h2>
              </div>
              <div className="spiritflix-view-toggle" aria-label="Library view">
                <button
                  type="button"
                  className={viewMode === "grid" ? "is-active" : undefined}
                  aria-pressed={viewMode === "grid"}
                  onClick={() => setViewMode("grid")}
                >
                  <Grid2X2 size={18} aria-hidden="true" />
                  <span>Grid</span>
                </button>
                <button
                  type="button"
                  className={viewMode === "list" ? "is-active" : undefined}
                  aria-pressed={viewMode === "list"}
                  onClick={() => setViewMode("list")}
                >
                  <List size={19} aria-hidden="true" />
                  <span>List</span>
                </button>
                <button
                  type="button"
                  className={viewMode === "history" ? "is-active" : undefined}
                  aria-pressed={viewMode === "history"}
                  onClick={() => setViewMode("history")}
                >
                  <Clock3 size={18} aria-hidden="true" />
                  <span>History</span>
                </button>
                <button
                  type="button"
                  className={viewMode === "gallery" ? "is-active" : undefined}
                  aria-pressed={viewMode === "gallery"}
                  onClick={() => setViewMode("gallery")}
                >
                  <Images size={18} aria-hidden="true" />
                  <span>Gallery</span>
                </button>
              </div>
            </div>

            {selectedModelGroup && selectedModelGalleryItems.length ? (
              <div className="spiritflix-model-tabs" aria-label={`${selectedModelGroup.name} media tabs`}>
                <button
                  type="button"
                  className={viewMode !== "gallery" ? "is-active" : undefined}
                  aria-pressed={viewMode !== "gallery"}
                  onClick={() => setViewMode("grid")}
                >
                  Videos
                </button>
                <button
                  type="button"
                  className={viewMode === "gallery" ? "is-active" : undefined}
                  aria-pressed={viewMode === "gallery"}
                  onClick={() => setViewMode("gallery")}
                >
                  Pics
                </button>
              </div>
            ) : null}

            <div className="spiritflix-library-modebar">
              <button
                type="button"
                className="spiritflix-filter-trigger"
                aria-expanded={filtersOpen}
                onClick={() => setFiltersOpen((current) => !current)}
              >
                <SlidersHorizontal size={18} aria-hidden="true" />
                <span>{getSortModeLabel(sortMode)} / {getSortDirectionLabel(sortDirection)}</span>
              </button>
            </div>

            <AnimatePresence>
              {filtersOpen ? (
                <motion.div
                  className="spiritflix-filter-popout"
                  initial={{ opacity: 0, y: -8, scale: 0.98 }}
                  animate={{ opacity: 1, y: 0, scale: 1 }}
                  exit={{ opacity: 0, y: -8, scale: 0.98 }}
                  transition={{ duration: 0.16 }}
                >
                  <div className="spiritflix-filter-popout__section">
                    <span>Sort</span>
                    <div className="spiritflix-filter-options">
                      {[
                        ["model", "Model"],
                        ["dateAdded", "Last added"],
                        ["duration", "Duration"],
                        ["title", "Title"],
                      ].map(([value, label]) => (
                        <button
                          key={value}
                          type="button"
                          className={sortMode === value ? "is-active" : undefined}
                          aria-pressed={sortMode === value}
                          onClick={() => setSortMode(value as LibrarySortMode)}
                        >
                          {label}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="spiritflix-filter-popout__section">
                    <span>Order</span>
                    <div className="spiritflix-filter-options spiritflix-filter-options--two">
                      <button
                        type="button"
                        className={sortDirection === "desc" ? "is-active" : undefined}
                        aria-pressed={sortDirection === "desc"}
                        onClick={() => setSortDirection("desc")}
                      >
                        Descending
                      </button>
                      <button
                        type="button"
                        className={sortDirection === "asc" ? "is-active" : undefined}
                        aria-pressed={sortDirection === "asc"}
                        onClick={() => setSortDirection("asc")}
                      >
                        Ascending
                      </button>
                    </div>
                  </div>
                </motion.div>
              ) : null}
            </AnimatePresence>

            <div className="spiritflix-library-stats" aria-label="Library stats">
              {libraryStats.map((stat) => (
                <div key={stat.label} className="spiritflix-library-stat">
                  <strong>{stat.value}</strong>
                  <span>{stat.label}</span>
                </div>
              ))}
            </div>
            {faceMetadataError ? <p className="spiritflix-face-note">{faceMetadataError}</p> : null}
            {galleryError ? <p className="spiritflix-face-note">{galleryError}</p> : null}

            {viewMode !== "gallery" && continueWatchingItems.length ? (
              <section className="spiritflix-resume-section" aria-label="Continue Watching">
                <div className="spiritflix-resume-section__header">
                  <div>
                    <h3>Continue Watching</h3>
                    <span>Private Jellyfin lane / {selectedModelGroup?.name ?? libraryTitle}</span>
                  </div>
                  <div className="spiritflix-row-controls" aria-label="Scroll Continue Watching">
                    <button type="button" onClick={() => scrollRow(resumeTrackRef, "left")} aria-label="Scroll Continue Watching left">
                      <ChevronLeft size={22} aria-hidden="true" />
                    </button>
                    <button type="button" onClick={() => scrollRow(resumeTrackRef, "right")} aria-label="Scroll Continue Watching right">
                      <ChevronRight size={22} aria-hidden="true" />
                    </button>
                  </div>
                </div>
                <div className="spiritflix-resume-track" ref={resumeTrackRef}>
                  {continueWatchingItems.map((item) => {
                    const progress = getResumeProgressPercent(item);
                    const resumeTicks = getResumePositionTicks(item);
                    const timeLeft = getTimeLeftLabel(item);
                    return (
                      <motion.button
                        key={item.Id}
                        type="button"
                        className="spiritflix-resume-card"
                        onClick={() => onPlay(item, visibleLibraryItems, "Continue Watching", resumeTicks)}
                        whileTap={{ scale: 0.985 }}
                        aria-label={`Resume ${item.Name} at ${getResumeSlotLabel(item)}`}
                      >
                        <span className="spiritflix-resume-card__thumb">
                          <SpiritFlixImage client={client} item={item} type="Thumb" width={420} alt="" />
                        </span>
                          <span className="spiritflix-resume-card__copy">
                          <strong>{getDisplayModelName(item, faceMetadata)}</strong>
                          <small>{item.Name}</small>
                          <span>{getResumeSlotLabel(item)}</span>
                          {timeLeft ? <em>{timeLeft}</em> : null}
                        </span>
                        <span className="spiritflix-resume-card__progress" aria-hidden="true">
                          <span style={{ width: `${progress}%` }} />
                        </span>
                      </motion.button>
                    );
                  })}
                </div>
              </section>
            ) : null}

            {viewMode !== "gallery" ? (
              <SpiritFlixRail
                title="Favorites"
                variant="poster"
                client={client}
                items={favoriteItems}
                playOnPrimaryTap={playPrimaryTapOnMobile}
                onOpenDetails={onOpenDetails}
                onPlay={onPlay}
                emptyText={`No favorites in ${selectedModelGroup?.name ?? libraryTitle} yet.`}
              />
            ) : null}

            <section className="spiritflix-model-section" aria-label="Model filters">
              <div className="spiritflix-model-section__header">
                <span>Models</span>
                <div className="spiritflix-row-controls" aria-label="Scroll Models">
                  <button type="button" onClick={() => scrollRow(modelStripRef, "left")} aria-label="Scroll Models left">
                    <ChevronLeft size={22} aria-hidden="true" />
                  </button>
                  <button type="button" onClick={() => scrollRow(modelStripRef, "right")} aria-label="Scroll Models right">
                    <ChevronRight size={22} aria-hidden="true" />
                  </button>
                </div>
              </div>
              <div className="spiritflix-model-strip" ref={modelStripRef} aria-label="Models">
                <button
                  type="button"
                  className={`spiritflix-model-pill ${selectedModel === null ? "is-active" : ""}`}
                  onClick={() => selectModel(null)}
                >
                  All Models
                </button>
                {modelGroups.map((model) => {
                  const galleryCount = galleryItems.filter((item) => galleryItemMatchesModel(item, model.name)).length;
                  return (
                    <motion.button
                      layout
                      key={model.name}
                      type="button"
                      className={`spiritflix-model-card ${selectedModel === model.name ? "is-active" : ""}`}
                      onClick={() => selectModel(model.name)}
                      whileTap={{ scale: 0.98 }}
                    >
                      <SpiritFlixImage client={client} item={model.representative} type="Primary" width={260} alt="" />
                      <span>
                        <strong>{model.name}</strong>
                        <small>{model.indexedCount} videos{galleryCount ? ` / ${galleryCount} pics` : ""}</small>
                      </span>
                    </motion.button>
                  );
                })}
              </div>
            </section>

            <AnimatePresence mode="wait">
              {viewMode === "gallery" ? (
                <motion.div
                  key="gallery"
                  className="spiritflix-gallery-grid"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.18 }}
                >
                  {visibleGalleryItems.map((item, index) => (
                    <GalleryCard
                      key={item.id}
                      item={item}
                      onOpen={() => setGalleryLightbox({ items: visibleGalleryItems, index })}
                    />
                  ))}
                </motion.div>
              ) : viewMode === "grid" ? (
                <motion.div
                  key="grid"
                  className="spiritflix-library-grid"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.18 }}
                >
                  {visibleLibraryItems.map((item) => (
                    <LibraryFeedCard
                      key={item.Id}
                      client={client}
                      item={item}
                      playOnPrimaryTap={playPrimaryTapOnMobile}
                      onOpenDetails={onOpenDetails}
                      onPlay={(selectedItem, startPositionTicks) =>
                        onPlay(selectedItem, visibleLibraryItems, selectedModelGroup?.name ?? libraryTitle, startPositionTicks)
                      }
                    />
                  ))}
                </motion.div>
              ) : viewMode === "list" ? (
                <motion.div
                  key="list"
                  className="spiritflix-library-list"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.18 }}
                >
                  {visibleLibraryItems.map((item) => (
                    <button
                      key={item.Id}
                      type="button"
                      className="spiritflix-library-row"
                      onClick={() => {
                        if (playPrimaryTapOnMobile && isPlayableItem(item)) {
                          onPlay(
                            item,
                            visibleLibraryItems,
                            selectedModelGroup?.name ?? libraryTitle,
                            hasResumeProgress(item) ? getResumePositionTicks(item) : undefined,
                          );
                        } else {
                          onOpenDetails(item);
                        }
                      }}
                    >
                      <span className="spiritflix-library-row__thumb">
                        <SpiritFlixImage client={client} item={item} type="Thumb" width={260} alt="" />
                      </span>
                      <span className="spiritflix-library-row__copy">
                        <strong>{item.Name}</strong>
                        <small>{getDisplayModelName(item, faceMetadata)}</small>
                        <em className={`spiritflix-face-badge is-${getFaceMatch(item, faceMetadata)?.status ?? "unscanned"}`}>
                          {getFaceMatch(item, faceMetadata)?.label ?? "Unscanned"}
                        </em>
                        <span>{hasResumeProgress(item) ? getResumeSlotLabel(item) : `${formatRuntime(getDurationTicks(item))} / ${item.UserData?.PlayCount ?? 0} plays`}</span>
                        {hasResumeProgress(item) ? <em>Resume from {getResumeSlotLabel(item).split(" / ")[0]}</em> : null}
                      </span>
                      {isPlayableItem(item) ? (
                        <span
                          className="spiritflix-library-row__play"
                          onClick={(event) => {
                            event.stopPropagation();
                            onPlay(
                              item,
                              visibleLibraryItems,
                              selectedModelGroup?.name ?? libraryTitle,
                              hasResumeProgress(item) ? getResumePositionTicks(item) : undefined,
                            );
                          }}
                        >
                          <Play size={18} fill="currentColor" aria-hidden="true" />
                        </span>
                      ) : null}
                    </button>
                  ))}
                </motion.div>
              ) : (
                <motion.div
                  key="history"
                  className="spiritflix-library-list spiritflix-library-list--history"
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -8 }}
                  transition={{ duration: 0.18 }}
                >
                  {historyItems.map((item) => (
                    <button
                      key={item.Id}
                      type="button"
                      className="spiritflix-library-row spiritflix-library-row--history"
                      onClick={() => {
                        if (isPlayableItem(item)) {
                          onPlay(
                            item,
                            historyItems,
                            "Watch History",
                            hasResumeProgress(item) ? getResumePositionTicks(item) : undefined,
                          );
                        } else {
                          onOpenDetails(item);
                        }
                      }}
                    >
                      <span className="spiritflix-library-row__thumb">
                        <SpiritFlixImage client={client} item={item} type="Thumb" width={260} alt="" />
                      </span>
                      <span className="spiritflix-library-row__copy">
                        <strong>{item.Name}</strong>
                        <small>{getDisplayModelName(item, faceMetadata)}</small>
                        <em>{getLastPlayedLabel(item)}</em>
                        <span>
                          {hasResumeProgress(item)
                            ? `${getResumeSlotLabel(item)} / ${getTimeLeftLabel(item)}`
                            : `${formatRuntime(getDurationTicks(item))} / ${item.UserData?.PlayCount ?? 0} plays`}
                        </span>
                      </span>
                      {isPlayableItem(item) ? (
                        <span
                          className="spiritflix-library-row__play"
                          onClick={(event) => {
                            event.stopPropagation();
                            onPlay(
                              item,
                              historyItems,
                              "Watch History",
                              hasResumeProgress(item) ? getResumePositionTicks(item) : undefined,
                            );
                          }}
                        >
                          <Play size={18} fill="currentColor" aria-hidden="true" />
                        </span>
                      ) : null}
                    </button>
                  ))}
                </motion.div>
              )}
            </AnimatePresence>

            {viewMode === "gallery" && !visibleGalleryItems.length ? (
              <p className="spiritflix-empty">No gallery pictures found for {selectedModelGroup?.name ?? "any model"} yet.</p>
            ) : viewMode === "history" && !historyItems.length ? (
              <p className="spiritflix-empty">No private watch history has synced for {selectedModelGroup?.name ?? libraryTitle} yet.</p>
            ) : viewMode !== "history" && !visibleLibraryItems.length ? (
              <p className="spiritflix-empty">{libraryTitle} has no indexed videos yet.</p>
            ) : null}

            {viewMode !== "gallery" ? (
              <motion.button
                type="button"
                className="spiritflix-shuffle-fab"
                onClick={handleShuffleClick}
                onPointerDown={startShuffleLongPress}
                onPointerUp={clearLongPressTimer}
                onPointerCancel={clearLongPressTimer}
                onContextMenu={(event) => {
                  event.preventDefault();
                  if (selectedModelGroup) playShuffle("model");
                }}
                disabled={!playableLibraryItems.length}
                whileTap={{ scale: 0.97 }}
                aria-label={
                  selectedModelGroup
                    ? `Shuffle ${libraryTitle}; long press to shuffle ${selectedModelGroup.name}`
                    : `Shuffle ${libraryTitle}`
                }
              >
                <Shuffle size={21} aria-hidden="true" />
                <span>
                  <strong>Shuffle Gooner Mix</strong>
                  <small>{selectedModelGroup ? `Hold: ${selectedModelGroup.name}` : "Whole library"}</small>
                </span>
              </motion.button>
            ) : null}
          </section>
        ) : null}
        {isHomeView ? (
          <>
            <SpiritFlixRail
              title="Continue Watching"
              variant="landscape"
              client={client}
              items={data.continueWatching}
              playOnPrimaryTap={playPrimaryTapOnMobile}
              onOpenDetails={onOpenDetails}
              onPlay={onPlay}
              emptyText="Nothing in progress yet."
            />
            <SpiritFlixRail
              title="Latest Added"
              variant="poster"
              client={client}
              items={data.latestAdded}
              playOnPrimaryTap={playPrimaryTapOnMobile}
              onOpenDetails={onOpenDetails}
              onPlay={onPlay}
              emptyText="No recent videos found."
            />
            <SpiritFlixRail
              title="Favorites"
              variant="poster"
              client={client}
              items={data.favorites}
              playOnPrimaryTap={playPrimaryTapOnMobile}
              onOpenDetails={onOpenDetails}
              onPlay={onPlay}
              emptyText="No favorite videos yet."
            />
          </>
        ) : null}
      </div>
      {galleryLightbox ? (
        <GalleryLightbox
          items={galleryLightbox.items}
          initialIndex={galleryLightbox.index}
          onClose={() => setGalleryLightbox(null)}
        />
      ) : null}
    </section>
  );
}

"use client";

import Image from "next/image";
import { useEffect, useState } from "react";
import type { ReactNode } from "react";
import type { JellyfinClient } from "@/lib/spiritflix-jellyfin-client";
import type { JellyfinItem } from "@/lib/spiritflix-types";

interface SpiritFlixImageProps {
  client: JellyfinClient;
  item: JellyfinItem;
  type?: "Primary" | "Backdrop" | "Thumb";
  width?: number;
  alt?: string;
  className?: string;
  fallback?: ReactNode;
  onLoad?: () => void;
}

function imageFallbackOrder(type: "Primary" | "Backdrop" | "Thumb"): Array<"Primary" | "Backdrop" | "Thumb"> {
  if (type === "Thumb") return ["Thumb", "Primary", "Backdrop"];
  if (type === "Backdrop") return ["Backdrop", "Thumb", "Primary"];
  return ["Primary", "Thumb", "Backdrop"];
}

export function SpiritFlixImage({
  client,
  item,
  type = "Primary",
  width = 500,
  alt = "",
  className,
  fallback,
  onLoad,
}: SpiritFlixImageProps) {
  const [src, setSrc] = useState("");
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    let alive = true;
    let objectUrl = "";

    async function loadImage() {
      setFailed(false);
      setSrc("");

      for (const imageType of imageFallbackOrder(type)) {
        try {
          const nextSrc = await client.getImageObjectUrl(item, imageType, width);
          if (alive) {
            objectUrl = nextSrc;
            setSrc(nextSrc);
            return;
          }
          URL.revokeObjectURL(nextSrc);
          return;
        } catch {
          // Try the next Jellyfin image type before falling back to the letter tile.
        }
      }

      if (alive) setFailed(true);
    }

    void loadImage();

    return () => {
      alive = false;
      if (objectUrl) URL.revokeObjectURL(objectUrl);
    };
  }, [client, item, type, width]);

  if (failed || !src) {
    if (fallback) return fallback;
    return (
      <span className={`spiritflix-image-fallback ${className ?? ""}`} aria-label={alt || item.Name}>
        <span>{item.Name.slice(0, 1).toUpperCase()}</span>
      </span>
    );
  }

  return (
    <Image
      src={src}
      alt={alt}
      className={className}
      loading="lazy"
      width={width}
      height={Math.round(width * 1.5)}
      unoptimized
      onLoad={onLoad}
    />
  );
}

"use client";

import { FormEvent, useState } from "react";
import { Eye, EyeOff, LogIn, RefreshCw, Server, ShieldCheck } from "lucide-react";
import { SPIRITFLIX_FALLBACK_SERVER } from "@/lib/spiritflix-jellyfin-client";
import type { SpiritFlixServerInfo } from "@/lib/spiritflix-types";

interface SpiritFlixLoginProps {
  serverUrl: string;
  serverInfo: SpiritFlixServerInfo | null;
  serverError: string;
  onServerUrlChange: (serverUrl: string) => void;
  onRetry: () => void;
  onLogin: (username: string, password: string, serverUrl: string) => Promise<void>;
}

export function SpiritFlixLogin({
  serverUrl,
  serverInfo,
  serverError,
  onServerUrlChange,
  onRetry,
  onLogin,
}: SpiritFlixLoginProps) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loginError, setLoginError] = useState("");
  const [isLoggingIn, setIsLoggingIn] = useState(false);

  const handleSubmit = async (event: FormEvent) => {
    event.preventDefault();
    setLoginError("");
    setIsLoggingIn(true);
    try {
      await onLogin(username, password, serverUrl);
      setPassword("");
    } catch (error) {
      setLoginError(error instanceof Error ? error.message : "Jellyfin could not complete authentication.");
    } finally {
      setIsLoggingIn(false);
    }
  };

  return (
    <section className="spiritflix-login">
      <div className="spiritflix-login__backdrop" />
      <div className="spiritflix-login__panel">
        <div className="spiritflix-brand">
          <span className="spiritflix-brand__sigil">SF</span>
          <span>SpiritFlix</span>
        </div>

        <h1>SpiritFlix</h1>
        <p className="spiritflix-login__copy">
          Sign in with the dedicated private Jellyfin user for this library.
        </p>

        <div className={`spiritflix-health ${serverInfo ? "is-ok" : "is-warn"}`}>
          <Server aria-hidden="true" size={18} />
          <span>
            {serverInfo
              ? `Connected to ${serverInfo.ServerName ?? "Jellyfin"} ${serverInfo.Version ?? ""}`.trim()
              : serverError || "Checking Jellyfin reachability..."}
          </span>
          <button type="button" onClick={onRetry} aria-label="Retry server health check">
            <RefreshCw size={16} aria-hidden="true" />
          </button>
        </div>

        <form className="spiritflix-login__form" onSubmit={handleSubmit}>
          <label>
            Jellyfin server
            <input value={serverUrl} onChange={(event) => onServerUrlChange(event.target.value)} />
          </label>
          <button
            type="button"
            className="spiritflix-link-button"
            onClick={() => onServerUrlChange(SPIRITFLIX_FALLBACK_SERVER)}
          >
            Use fallback private URL
          </button>
          <label>
            Username
            <input
              autoComplete="username"
              value={username}
              onChange={(event) => setUsername(event.target.value)}
              required
            />
          </label>
          <label>
            Password
            <span className="spiritflix-password-field">
              <input
                type={showPassword ? "text" : "password"}
                autoComplete="current-password"
                value={password}
                onChange={(event) => setPassword(event.target.value)}
                required
              />
              <button
                type="button"
                onClick={() => setShowPassword((current) => !current)}
                aria-label={showPassword ? "Hide password" : "Show password"}
              >
                {showPassword ? <EyeOff size={18} aria-hidden="true" /> : <Eye size={18} aria-hidden="true" />}
              </button>
            </span>
          </label>

          {loginError ? <p className="spiritflix-error">{loginError}</p> : null}

          <button className="spiritflix-primary-button" type="submit" disabled={isLoggingIn}>
            <LogIn size={19} aria-hidden="true" />
            {isLoggingIn ? "Signing in..." : "Sign in"}
          </button>
        </form>

        <div className="spiritflix-login__privacy">
          <ShieldCheck size={17} aria-hidden="true" />
          <span>Resume history stays in this user&apos;s Jellyfin lane; do not use your main Jellyfin user here.</span>
        </div>
      </div>
    </section>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState, type CSSProperties } from "react";
import {
  ChevronsDown,
  Heart,
  ListMusic,
  Maximize,
  Minimize,
  Pause,
  PictureInPicture2,
  Play,
  RefreshCw,
  Repeat,
  Repeat1,
  Shuffle,
  SkipBack,
  SkipForward,
  Volume2,
  VolumeX,
  X,
} from "lucide-react";
import { ticksToSeconds, type JellyfinClient } from "@/lib/spiritflix-jellyfin-client";
import type { JellyfinItem } from "@/lib/spiritflix-types";
import type { SpiritFlixPlaybackProgress, SpiritFlixPlaybackQueue } from "./SpiritFlixApp";

interface SpiritFlixPlayerProps {
  client: JellyfinClient;
  item: JellyfinItem;
  queue: SpiritFlixPlaybackQueue | null;
  startPositionTicks?: number;
  onPlaybackProgress: (progress: SpiritFlixPlaybackProgress) => void;
  onToggleFavorite: (item: JellyfinItem, isFavorite: boolean) => void;
  onSelectItem: (item: JellyfinItem) => void;
  onShuffleQueue: (currentItemId: string) => void;
  onClose: () => void;
}

type FitMode = "fit" | "fill";
type RepeatMode = "off" | "queue" | "one";

const FIT_STORAGE_KEY = "spiritflix_player_fit_mode";
const REPEAT_STORAGE_KEY = "spiritflix_player_repeat_mode";
const VOLUME_STORAGE_KEY = "spiritflix_player_volume";
const MUTED_STORAGE_KEY = "spiritflix_player_muted";
const TAP_MAX_MOVEMENT = 26;
const TAP_MAX_MS = 420;
const DOUBLE_TAP_MAX_MS = 480;
const DOUBLE_TAP_MAX_DISTANCE = 96;
const DOUBLE_TAP_EDGE_ZONE = 0.3;
const CENTER_TAP_MIN = 0.38;
const CENTER_TAP_MAX = 0.62;
const TOUCH_SEEK_ACTIVATION_PX = 34;
const TOUCH_SEEK_HOLD_MS = 90;
const TOUCH_SEEK_VERTICAL_RATIO = 1.35;
const TOUCH_SEEK_MAX_SECONDS = 90;
const TOUCH_SEEK_PX_PER_SECOND = 7.5;
const PINCH_TOGGLE_THRESHOLD = 0.08;
const PINCH_GESTURE_SUPPRESS_MS = 450;
const HLS_MANIFEST_TIMEOUT_MS = 8000;
const PLAYBACK_FEEDBACK_MS = 1150;

interface HlsController {
  loadSource: (source: string) => void;
  attachMedia: (media: HTMLMediaElement) => void;
  on: (event: string, listener: (event: string, data?: { fatal?: boolean; details?: string }) => void) => void;
  destroy: () => void;
}

type MiniPlayerDocument = Document;

type MiniPlayerVideo = HTMLVideoElement & {
  webkitPresentationMode?: "inline" | "picture-in-picture" | "fullscreen";
  webkitSetPresentationMode?: (mode: "inline" | "picture-in-picture") => void;
  webkitSupportsPresentationMode?: (mode: "picture-in-picture") => boolean;
};
const TOUCH_MOUSE_REVEAL_SUPPRESS_MS = 1200;
const UI_TIME_UPDATE_MS = 500;
const PLAYBACK_REPORT_MS = 15000;
const DEFAULT_AUDIBLE_VOLUME = 0.8;
const PORTRAIT_VIDEO_ASPECT_CUTOFF = 0.9;
const PORTRAIT_SAFE_FILL_SCALE = 1.12;
const WIDE_SAFE_FILL_SCALE = 1.24;
const MODERATE_SAFE_FILL_SCALE = 1.34;

type PlaybackFeedbackInput =
  | { kind: "play" | "pause" }
  | { kind: "seek-back" | "seek-forward"; seconds: number };

type PlaybackFeedback =
  | { id: number; kind: "play" | "pause" }
  | { id: number; kind: "seek-back" | "seek-forward"; seconds: number };

type SeekTapZone = "left-seek" | "right-seek";
type PlayerTapZone = SeekTapZone | "center" | "surface";

function secondsToTicks(seconds: number): number {
  return Math.max(0, Math.round(seconds * 10000000));
}

function formatTime(seconds: number): string {
  if (!Number.isFinite(seconds)) return "0:00";
  const whole = Math.max(0, Math.floor(seconds));
  const hours = Math.floor(whole / 3600);
  const minutes = Math.floor((whole % 3600) / 60);
  const rest = whole % 60;
  return hours
    ? `${hours}:${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}`
    : `${minutes}:${String(rest).padStart(2, "0")}`;
}

function renderPlaybackFeedback(feedback: PlaybackFeedback) {
  switch (feedback.kind) {
    case "pause":
      return <Pause size={58} aria-hidden="true" />;
    case "play":
      return <Play size={58} fill="currentColor" aria-hidden="true" />;
    case "seek-back":
      return (
        <>
          <SkipBack size={36} aria-hidden="true" />
          <strong>{feedback.seconds}s</strong>
        </>
      );
    case "seek-forward":
      return (
        <>
          <strong>{feedback.seconds}s</strong>
          <SkipForward size={36} aria-hidden="true" />
        </>
      );
  }
}

function getStoredFitMode(): FitMode {
  if (typeof window === "undefined") return "fit";
  const stored = window.localStorage.getItem(FIT_STORAGE_KEY);
  return stored === "fill" || stored === "fit" ? stored : "fit";
}

function isRepeatMode(value: string | null): value is RepeatMode {
  return value === "off" || value === "queue" || value === "one";
}

function getStoredRepeatMode(): RepeatMode {
  if (typeof window === "undefined") return "off";
  const stored = window.localStorage.getItem(REPEAT_STORAGE_KEY);
  return isRepeatMode(stored) ? stored : "off";
}

function getStoredVolume(): number {
  if (typeof window === "undefined") return 1;
  const stored = Number(window.localStorage.getItem(VOLUME_STORAGE_KEY));
  return Number.isFinite(stored) ? Math.max(0, Math.min(1, stored)) : 1;
}

function getStoredMuted(): boolean {
  if (typeof window === "undefined") return false;
  return window.localStorage.getItem(MUTED_STORAGE_KEY) === "true";
}

export function getSmartFillScale(shellAspectRatio: number, videoAspectRatio: number): number {
  if (
    !Number.isFinite(shellAspectRatio) ||
    !Number.isFinite(videoAspectRatio) ||
    shellAspectRatio <= 0 ||
    videoAspectRatio <= 0
  ) {
    return 1;
  }

  const coverScale =
    shellAspectRatio > videoAspectRatio
      ? shellAspectRatio / videoAspectRatio
      : videoAspectRatio / shellAspectRatio;

  if (coverScale <= 1.04) return 1;

  const safeScale =
    videoAspectRatio < PORTRAIT_VIDEO_ASPECT_CUTOFF
      ? PORTRAIT_SAFE_FILL_SCALE
      : coverScale >= 1.45
        ? WIDE_SAFE_FILL_SCALE
        : MODERATE_SAFE_FILL_SCALE;

  return Math.max(1, Math.min(coverScale, safeScale));
}

function isInteractiveTarget(target: EventTarget | null): boolean {
  return target instanceof Element && Boolean(target.closest("button, input, a, [role='button']"));
}

function getTouchAt(
  touches: { length: number; item?: (index: number) => { clientX: number; clientY: number } | null; [index: number]: { clientX: number; clientY: number } | undefined },
  index: number,
): { clientX: number; clientY: number } | null {
  return touches.item?.(index) ?? touches[index] ?? null;
}

function getPlayerTapZone(x: number, shellWidth: number): PlayerTapZone {
  const width = Math.max(1, shellWidth);
  const ratio = x / width;
  if (ratio <= DOUBLE_TAP_EDGE_ZONE) return "left-seek";
  if (ratio >= 1 - DOUBLE_TAP_EDGE_ZONE) return "right-seek";
  if (ratio >= CENTER_TAP_MIN && ratio <= CENTER_TAP_MAX) return "center";
  return "surface";
}

function supportsMiniPlayer(video: MiniPlayerVideo | null): boolean {
  if (typeof document === "undefined" || !video) return false;
  const pictureDocument = document as MiniPlayerDocument;
  return Boolean(
    (pictureDocument.pictureInPictureEnabled && typeof video.requestPictureInPicture === "function") ||
      video.webkitSupportsPresentationMode?.("picture-in-picture"),
  );
}

export function SpiritFlixPlayer({
  client,
  item,
  queue,
  startPositionTicks,
  onPlaybackProgress,
  onToggleFavorite,
  onSelectItem,
  onShuffleQueue,
  onClose,
}: SpiritFlixPlayerProps) {
  const videoRef = useRef<HTMLVideoElement | null>(null);
  const shellRef = useRef<HTMLElement | null>(null);
  const lastReportedTicksRef = useRef(0);
  const lastUiProgressAtRef = useRef(0);
  const lastUiTimeAtRef = useRef(0);
  const lastPlaybackReportAtRef = useRef(0);
  const firstNonZeroReportRef = useRef(false);
  const endedRef = useRef(false);
  const hideTimer = useRef<number | null>(null);
  const feedbackTimer = useRef<number | null>(null);
  const tapRevealTimer = useRef<number | null>(null);
  const feedbackIdRef = useRef(0);
  const usingHlsRef = useRef(false);
  const waitingSinceRef = useRef<number | null>(null);
  const itemRef = useRef(item);
  const pointerStartRef = useRef<{ x: number; y: number; time: number; currentTime: number } | null>(null);
  const lastTapRef = useRef<{ time: number; x: number; y: number; zone: SeekTapZone } | null>(null);
  const lastPointerTapAtRef = useRef(0);
  const touchTapStartRef = useRef<{ x: number; y: number; time: number; currentTime: number; isSeeking: boolean } | null>(null);
  const pinchStartRef = useRef<{ startDistance: number; currentDistance: number } | null>(null);
  const suppressPointerUntilRef = useRef(0);
  const suppressTouchUntilRef = useRef(0);
  const lastTouchInteractionAtRef = useRef(0);
  const volumeRef = useRef(getStoredVolume());
  const mutedRef = useRef(getStoredMuted());
  const repeatModeRef = useRef<RepeatMode>(getStoredRepeatMode());

  const [isPlaying, setIsPlaying] = useState(false);
  const [isMuted, setIsMuted] = useState(() => getStoredMuted());
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [showControls, setShowControls] = useState(true);
  const [controlsHiddenByUser, setControlsHiddenByUser] = useState(false);
  const [currentTime, setCurrentTime] = useState(0);
  const [duration, setDuration] = useState(0);
  const [volume, setVolume] = useState(() => getStoredVolume());
  const [isVolumeOpen, setIsVolumeOpen] = useState(false);
  const [fitMode, setFitMode] = useState<FitMode>(() => getStoredFitMode());
  const [videoAspectRatio, setVideoAspectRatio] = useState(16 / 9);
  const [shellSize, setShellSize] = useState({ width: 0, height: 0 });
  const [streamError, setStreamError] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [usingHls, setUsingHls] = useState(false);
  const [retryCount, setRetryCount] = useState(0);
  const [endedAtQueueEnd, setEndedAtQueueEnd] = useState(false);
  const [repeatMode, setRepeatMode] = useState<RepeatMode>(() => getStoredRepeatMode());
  const [miniPlayerSupported, setMiniPlayerSupported] = useState(false);
  const [isMiniPlayer, setIsMiniPlayer] = useState(false);
  const [isQueueOpen, setIsQueueOpen] = useState(false);
  const [playbackFeedback, setPlaybackFeedback] = useState<PlaybackFeedback | null>(null);

  const queueItems = queue?.items ?? [item];
  const queueIndex = queueItems.findIndex((queueItem) => queueItem.Id === item.Id);
  const currentIndex = queueIndex >= 0 ? queueIndex : queue?.currentIndex ?? 0;
  const previousItem = currentIndex > 0 ? queueItems[currentIndex - 1] : null;
  const nextItem = currentIndex < queueItems.length - 1 ? queueItems[currentIndex + 1] : null;
  const upNextTitle = nextItem?.Name ?? null;
  const isFavorite = Boolean(item.UserData?.IsFavorite);
  const repeatLabel =
    repeatMode === "one" ? "Repeat current video" : repeatMode === "queue" ? "Repeat queue" : "Repeat off";
  const isShuffled = Boolean(queue?.isShuffled);
  const shuffleLabel = isShuffled
    ? `Shuffle on for ${queue?.sourceTitle ?? "current queue"}`
    : `Shuffle off for ${queue?.sourceTitle ?? "current queue"}`;
  const miniPlayerLabel = miniPlayerSupported ? (isMiniPlayer ? "Exit mini player" : "Mini player") : "Mini player unavailable";

  useEffect(() => {
    itemRef.current = item;
  }, [item]);

  const emitPlaybackProgress = useCallback(
    (positionTicks: number, isEnded = false) => {
      onPlaybackProgress({
        itemId: item.Id,
        item: itemRef.current,
        positionTicks,
        isEnded,
      });
    },
    [item.Id, onPlaybackProgress],
  );

  const flushPlaybackProgress = useCallback(
    (
      event: "Progress" | "Stopped" = "Progress",
      options: { isPaused?: boolean; keepalive?: boolean; updateUi?: boolean } = {},
    ) => {
      const video = videoRef.current;
      const positionSeconds = video?.currentTime || ticksToSeconds(lastReportedTicksRef.current);
      const positionTicks = secondsToTicks(positionSeconds);
      if (positionTicks <= 0) return;

      lastReportedTicksRef.current = positionTicks;
      lastPlaybackReportAtRef.current = performance.now();
      if (options.updateUi) {
        setCurrentTime(positionSeconds);
        emitPlaybackProgress(positionTicks, false);
      }
      void client.reportPlayback(
        item.Id,
        event,
        positionTicks,
        options.isPaused ?? video?.paused ?? false,
        { keepalive: options.keepalive },
      );
    },
    [client, emitPlaybackProgress, item.Id],
  );

  const revealControls = useCallback(
    (keepVisible = false) => {
      setControlsHiddenByUser(false);
      setShowControls(true);
      if (hideTimer.current) window.clearTimeout(hideTimer.current);
      if (!keepVisible && isPlaying) {
        hideTimer.current = window.setTimeout(() => setShowControls(false), 2600);
      }
    },
    [isPlaying],
  );

  const clearTapRevealTimer = useCallback(() => {
    if (!tapRevealTimer.current) return;
    window.clearTimeout(tapRevealTimer.current);
    tapRevealTimer.current = null;
  }, []);

  const scheduleTapReveal = useCallback(() => {
    clearTapRevealTimer();
    tapRevealTimer.current = window.setTimeout(() => {
      tapRevealTimer.current = null;
      revealControls();
    }, DOUBLE_TAP_MAX_MS);
  }, [clearTapRevealTimer, revealControls]);

  const hideControls = useCallback(() => {
    if (hideTimer.current) window.clearTimeout(hideTimer.current);
    const activeElement = document.activeElement;
    if (activeElement instanceof HTMLElement && shellRef.current?.contains(activeElement)) {
      activeElement.blur();
    }
    setControlsHiddenByUser(true);
    setShowControls(false);
  }, []);

  const flashPlaybackFeedback = useCallback((feedback: PlaybackFeedbackInput) => {
    feedbackIdRef.current += 1;
    setPlaybackFeedback({ id: feedbackIdRef.current, ...feedback } as PlaybackFeedback);
    if (feedbackTimer.current) window.clearTimeout(feedbackTimer.current);
    feedbackTimer.current = window.setTimeout(() => setPlaybackFeedback(null), PLAYBACK_FEEDBACK_MS);
  }, []);

  const flashTapFeedback = useCallback(
    (kind: "play" | "pause") => {
      flashPlaybackFeedback({ kind });
    },
    [flashPlaybackFeedback],
  );

  const flashSeekFeedback = useCallback(
    (seconds: number) => {
      const roundedSeconds = Math.max(1, Math.abs(Math.round(seconds)));
      flashPlaybackFeedback({
        kind: seconds < 0 ? "seek-back" : "seek-forward",
        seconds: roundedSeconds,
      });
    },
    [flashPlaybackFeedback],
  );

  const seekTo = useCallback((seconds: number) => {
    const video = videoRef.current;
    if (!video) return;
    video.currentTime = Math.max(0, Math.min(video.duration || Number.MAX_SAFE_INTEGER, seconds));
    setCurrentTime(video.currentTime);
  }, []);

  const seekBy = useCallback(
    (seconds: number, options: { feedback?: boolean } = {}) => {
      const video = videoRef.current;
      if (!video) return;
      seekTo(video.currentTime + seconds);
      if (options.feedback !== false) flashSeekFeedback(seconds);
      revealControls();
    },
    [flashSeekFeedback, revealControls, seekTo],
  );

  const seekFromTouchDelta = useCallback(
    (startTime: number, dx: number) => {
      const secondsDelta = Math.max(
        -TOUCH_SEEK_MAX_SECONDS,
        Math.min(TOUCH_SEEK_MAX_SECONDS, dx / TOUCH_SEEK_PX_PER_SECOND),
      );
      seekTo(startTime + secondsDelta);
      flashSeekFeedback(secondsDelta || (dx < 0 ? -1 : 1));
    },
    [flashSeekFeedback, seekTo],
  );

  const togglePlay = useCallback(() => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) {
      flashTapFeedback("play");
      void video.play().then(() => {
        if (hideTimer.current) window.clearTimeout(hideTimer.current);
        hideTimer.current = window.setTimeout(() => setShowControls(false), 2600);
      }).catch(() => setShowControls(true));
    } else {
      flashTapFeedback("pause");
      video.pause();
    }
    revealControls();
  }, [flashTapFeedback, revealControls]);

  const setFit = useCallback((mode: FitMode) => {
    setFitMode(mode);
    window.localStorage.setItem(FIT_STORAGE_KEY, mode);
  }, []);

  const toggleFullscreen = useCallback(() => {
    const shell = shellRef.current;
    const video = videoRef.current as (HTMLVideoElement & { webkitEnterFullscreen?: () => void }) | null;
    if (document.fullscreenElement) {
      void document.exitFullscreen();
      return;
    }
    if (shell?.requestFullscreen) {
      void shell.requestFullscreen();
      return;
    }
    video?.webkitEnterFullscreen?.();
  }, []);

  const toggleMiniPlayer = useCallback(() => {
    const video = videoRef.current as MiniPlayerVideo | null;
    if (!video) return;
    const pictureDocument = document as MiniPlayerDocument;

    const toggle = async () => {
      if (pictureDocument.pictureInPictureElement) {
        await pictureDocument.exitPictureInPicture?.();
        setIsMiniPlayer(false);
        revealControls(true);
        return;
      }

      if (video.webkitPresentationMode === "picture-in-picture") {
        video.webkitSetPresentationMode?.("inline");
        setIsMiniPlayer(false);
        revealControls(true);
        return;
      }

      if (pictureDocument.pictureInPictureEnabled && video.requestPictureInPicture) {
        await video.requestPictureInPicture();
        setIsMiniPlayer(true);
        revealControls(true);
        return;
      }

      if (video.webkitSupportsPresentationMode?.("picture-in-picture")) {
        video.webkitSetPresentationMode?.("picture-in-picture");
        setIsMiniPlayer(true);
        revealControls(true);
      }
    };

    void toggle().catch(() => {
      setMiniPlayerSupported(false);
      setIsMiniPlayer(false);
      revealControls(true);
    });
  }, [revealControls]);

  const selectQueueItem = useCallback(
    (target: JellyfinItem | null) => {
      if (!target) return;
      setEndedAtQueueEnd(false);
      onSelectItem(target);
    },
    [onSelectItem],
  );

  const cycleRepeatMode = () => {
    setRepeatMode((current) => {
      const next = current === "off" ? "queue" : current === "queue" ? "one" : "off";
      repeatModeRef.current = next;
      window.localStorage.setItem(REPEAT_STORAGE_KEY, next);
      if (videoRef.current) videoRef.current.loop = next === "one";
      return next;
    });
    revealControls(true);
  };

  const shuffleCurrentQueue = () => {
    onShuffleQueue(item.Id);
    revealControls(true);
  };

  const toggleQueueDrawer = () => {
    setIsQueueOpen((open) => !open);
    revealControls(true);
  };

  const selectNextItem = () => {
    if (nextItem) {
      selectQueueItem(nextItem);
      return;
    }
    if (repeatModeRef.current === "queue" && queueItems.length > 0) {
      selectQueueItem(queueItems[0] ?? item);
    }
  };

  const updateVolume = useCallback((nextVolume: number) => {
    const video = videoRef.current;
    const clamped = Math.max(0, Math.min(1, nextVolume));
    setVolume(clamped);
    volumeRef.current = clamped;
    window.localStorage.setItem(VOLUME_STORAGE_KEY, String(clamped));
    if (video) {
      video.volume = clamped;
      video.muted = clamped === 0;
      mutedRef.current = video.muted;
      window.localStorage.setItem(MUTED_STORAGE_KEY, String(video.muted));
      setIsMuted(video.muted);
    }
  }, []);

  const updateMuted = useCallback((nextMuted: boolean) => {
    const video = videoRef.current;
    mutedRef.current = nextMuted;
    window.localStorage.setItem(MUTED_STORAGE_KEY, String(nextMuted));
    setIsMuted(nextMuted);
    if (video) video.muted = nextMuted;
  }, []);

  const toggleMuted = useCallback(() => {
    const video = videoRef.current;
    const currentlySilent = (video?.muted ?? mutedRef.current) || volumeRef.current <= 0;
    if (currentlySilent) {
      const audibleVolume = volumeRef.current > 0 ? volumeRef.current : DEFAULT_AUDIBLE_VOLUME;
      setVolume(audibleVolume);
      volumeRef.current = audibleVolume;
      window.localStorage.setItem(VOLUME_STORAGE_KEY, String(audibleVolume));
      if (video) {
        video.volume = audibleVolume;
        video.muted = false;
      }
      mutedRef.current = false;
      window.localStorage.setItem(MUTED_STORAGE_KEY, "false");
      setIsMuted(false);
      setIsVolumeOpen(true);
      revealControls(true);
      void video?.play().catch(() => undefined);
      return;
    }

    updateMuted(true);
    setIsVolumeOpen(true);
    revealControls(true);
  }, [revealControls, updateMuted]);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return undefined;
    const directUrl = client.getStreamUrl(item.Id);
    const hlsUrl = client.getHlsUrl(item.Id);
    const preferHls = typeof window !== "undefined" && window.location.protocol === "https:";
    let hlsInstance: HlsController | null = null;
    let cancelled = false;

    const resetVideo = () => {
      setStreamError("");
      setUsingHls(false);
      setIsLoading(true);
      setEndedAtQueueEnd(false);
      endedRef.current = false;
      lastUiProgressAtRef.current = 0;
      lastUiTimeAtRef.current = 0;
      lastPlaybackReportAtRef.current = performance.now();
      firstNonZeroReportRef.current = false;
      usingHlsRef.current = false;
      waitingSinceRef.current = null;
      video.pause();
      video.removeAttribute("src");
      video.load();
      video.volume = volumeRef.current;
      video.muted = mutedRef.current;
      video.loop = repeatModeRef.current === "one";
    };

    const startHls = async (): Promise<boolean> => {
      if (cancelled || usingHlsRef.current) return usingHlsRef.current;
      try {
        const { default: Hls } = await import("hls.js");
        if (Hls.isSupported()) {
          const instance = new Hls();
          const controller = instance as unknown as HlsController;
          const manifestReady = new Promise<void>((resolve, reject) => {
            const timeoutId = window.setTimeout(() => reject(new Error("HLS manifest timed out.")), HLS_MANIFEST_TIMEOUT_MS);
            controller.on(Hls.Events.MANIFEST_PARSED, () => {
              window.clearTimeout(timeoutId);
              resolve();
            });
            controller.on(Hls.Events.ERROR, (_event, data) => {
              if (!data?.fatal) return;
              window.clearTimeout(timeoutId);
              reject(new Error(data.details ?? "HLS playback failed."));
            });
          });
          controller.loadSource(hlsUrl);
          controller.attachMedia(video);
          hlsInstance = controller;
          await manifestReady;
        } else if (video.canPlayType("application/vnd.apple.mpegurl")) {
          video.src = hlsUrl;
          video.load();
        } else {
          setStreamError("This browser could not play the Jellyfin stream.");
          setIsLoading(false);
          return false;
        }
        usingHlsRef.current = true;
        setUsingHls(true);
        setStreamError("");
        return true;
      } catch (error) {
        hlsInstance?.destroy();
        hlsInstance = null;
        setStreamError(error instanceof Error ? error.message : "Direct playback failed and HLS fallback could not start.");
        setIsLoading(false);
        return false;
      }
    };

    const startPlayback = async () => {
      try {
        await video.play();
      } catch (error) {
        if (preferHls && !video.muted) {
          video.muted = true;
          mutedRef.current = true;
          setIsMuted(true);
          window.localStorage.setItem(MUTED_STORAGE_KEY, "true");
          await video.play().catch(() => undefined);
        }
        setShowControls(true);
        if (error instanceof DOMException && error.name !== "NotAllowedError") {
          setStreamError(error.message);
        }
      }
    };

    const setup = async () => {
      resetVideo();
      if (preferHls) {
        const hlsReady = await startHls();
        if (!hlsReady) {
          video.src = directUrl;
          video.load();
          setStreamError("");
          setUsingHls(false);
          usingHlsRef.current = false;
        }
      } else {
        video.src = directUrl;
        video.load();
      }
      const resumeAt = ticksToSeconds(startPositionTicks ?? item.UserData?.PlaybackPositionTicks);
      if (resumeAt) video.currentTime = resumeAt;
      const startTicks = resumeAt ? secondsToTicks(resumeAt) : 0;
      lastReportedTicksRef.current = startTicks;
      await client.reportPlayback(item.Id, "Start", startTicks, false);
      emitPlaybackProgress(startTicks, false);
      await startPlayback();
    };

    setup().catch(() => {
      setIsLoading(false);
      setStreamError("Could not prepare this Jellyfin stream.");
    });

    const handleDirectError = async () => {
      if (cancelled || usingHlsRef.current) return;
      const hlsReady = await startHls();
      if (hlsReady) await startPlayback();
    };

    video.addEventListener("error", handleDirectError);
    return () => {
      cancelled = true;
      video.removeEventListener("error", handleDirectError);
      const stopTicks = secondsToTicks(video.currentTime || ticksToSeconds(lastReportedTicksRef.current));
      void client.reportPlayback(item.Id, "Stopped", stopTicks, video.paused, { keepalive: true });
      emitPlaybackProgress(endedRef.current ? secondsToTicks(video.duration || ticksToSeconds(item.RunTimeTicks)) : stopTicks, endedRef.current);
      hlsInstance?.destroy();
    };
  }, [client, emitPlaybackProgress, item.Id, item.RunTimeTicks, item.UserData?.PlaybackPositionTicks, retryCount, startPositionTicks]);

  useEffect(() => {
    const flushForMobileSuspend = () => {
      if (endedRef.current) return;
      flushPlaybackProgress("Progress", { isPaused: true, keepalive: true });
    };
    const handleVisibilityChange = () => {
      if (document.visibilityState === "hidden") flushForMobileSuspend();
    };

    window.addEventListener("pagehide", flushForMobileSuspend);
    window.addEventListener("beforeunload", flushForMobileSuspend);
    document.addEventListener("visibilitychange", handleVisibilityChange);
    return () => {
      window.removeEventListener("pagehide", flushForMobileSuspend);
      window.removeEventListener("beforeunload", flushForMobileSuspend);
      document.removeEventListener("visibilitychange", handleVisibilityChange);
    };
  }, [flushPlaybackProgress]);

  useEffect(() => {
    repeatModeRef.current = repeatMode;
    window.localStorage.setItem(REPEAT_STORAGE_KEY, repeatMode);
    if (videoRef.current) videoRef.current.loop = repeatMode === "one";
  }, [repeatMode]);

  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(Boolean(document.fullscreenElement));
      revealControls();
    };
    document.addEventListener("fullscreenchange", handleFullscreenChange);
    return () => document.removeEventListener("fullscreenchange", handleFullscreenChange);
  }, [revealControls]);

  useEffect(() => {
    const video = videoRef.current as MiniPlayerVideo | null;
    const pictureDocument = document as MiniPlayerDocument;

    const updateMiniPlayerState = () => {
      setMiniPlayerSupported(supportsMiniPlayer(video));
      setIsMiniPlayer(
        Boolean(pictureDocument.pictureInPictureElement && pictureDocument.pictureInPictureElement === video) ||
          video?.webkitPresentationMode === "picture-in-picture",
      );
    };

    updateMiniPlayerState();
    video?.addEventListener("enterpictureinpicture", updateMiniPlayerState);
    video?.addEventListener("leavepictureinpicture", updateMiniPlayerState);
    video?.addEventListener("webkitpresentationmodechanged", updateMiniPlayerState);
    return () => {
      video?.removeEventListener("enterpictureinpicture", updateMiniPlayerState);
      video?.removeEventListener("leavepictureinpicture", updateMiniPlayerState);
      video?.removeEventListener("webkitpresentationmodechanged", updateMiniPlayerState);
    };
  }, [item.Id, retryCount]);

  useEffect(() => {
    const shell = shellRef.current;
    if (!shell) return undefined;

    const updateShellSize = () => {
      setShellSize({
        width: shell.clientWidth || window.innerWidth,
        height: shell.clientHeight || window.innerHeight,
      });
    };

    updateShellSize();
    const observer = new ResizeObserver(updateShellSize);
    observer.observe(shell);
    window.addEventListener("orientationchange", updateShellSize);
    window.addEventListener("resize", updateShellSize);

    return () => {
      observer.disconnect();
      window.removeEventListener("orientationchange", updateShellSize);
      window.removeEventListener("resize", updateShellSize);
    };
  }, []);

  useEffect(() => {
    return () => {
      if (hideTimer.current) window.clearTimeout(hideTimer.current);
      if (feedbackTimer.current) window.clearTimeout(feedbackTimer.current);
      if (tapRevealTimer.current) window.clearTimeout(tapRevealTimer.current);
    };
  }, []);

  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.target instanceof HTMLInputElement) return;
      const key = event.key.toLowerCase();
      if (key === " " || key === "k") {
        event.preventDefault();
        togglePlay();
      } else if (key === "arrowleft") {
        event.preventDefault();
        seekBy(-10);
      } else if (key === "arrowright") {
        event.preventDefault();
        seekBy(10);
      } else if (key === "arrowup") {
        event.preventDefault();
        updateVolume(volume + 0.08);
      } else if (key === "arrowdown") {
        event.preventDefault();
        updateVolume(volume - 0.08);
      } else if (key === "m") {
        event.preventDefault();
        const video = videoRef.current;
        if (video) {
          updateMuted(!video.muted);
        }
      } else if (key === "f") {
        event.preventDefault();
        toggleFullscreen();
      } else if (key === "escape") {
        event.preventDefault();
        if (document.fullscreenElement) {
          void document.exitFullscreen();
        } else {
          onClose();
        }
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [onClose, seekBy, toggleFullscreen, togglePlay, updateMuted, updateVolume, volume]);

  const handlePointerDown = (event: React.PointerEvent<HTMLElement>) => {
    if (event.pointerType === "touch") {
      lastTouchInteractionAtRef.current = Date.now();
      return;
    }
    if (Date.now() < suppressPointerUntilRef.current || pinchStartRef.current) return;
    if (isInteractiveTarget(event.target)) return;
    event.currentTarget.setPointerCapture?.(event.pointerId);
    pointerStartRef.current = {
      x: event.clientX,
      y: event.clientY,
      time: Date.now(),
      currentTime: videoRef.current?.currentTime ?? 0,
    };
  };

  const handlePlayerTap = useCallback(
    (x: number, y: number) => {
      const shellWidth = shellRef.current?.clientWidth ?? window.innerWidth;
      const zone = getPlayerTapZone(x, shellWidth);
      const activeElement = document.activeElement;
      const controlsHaveFocus =
        activeElement instanceof HTMLElement &&
        Boolean(activeElement.closest(".spiritflix-player__top, .spiritflix-player__controls"));
      const controlsAreVisible = !controlsHiddenByUser && (showControls || !isPlaying || controlsHaveFocus);

      const lastTap = lastTapRef.current;
      if (
        (zone === "left-seek" || zone === "right-seek") &&
        lastTap &&
        lastTap.zone === zone &&
        Date.now() - lastTap.time < DOUBLE_TAP_MAX_MS &&
        Math.abs(x - lastTap.x) < DOUBLE_TAP_MAX_DISTANCE &&
        Math.abs(y - lastTap.y) < DOUBLE_TAP_MAX_DISTANCE
      ) {
        lastTapRef.current = null;
        clearTapRevealTimer();
        seekBy(zone === "left-seek" ? -10 : 10);
        return;
      }

      if (zone === "center") {
        lastTapRef.current = null;
        clearTapRevealTimer();
        setControlsHiddenByUser(false);
        revealControls();
        togglePlay();
      } else if (controlsAreVisible) {
        clearTapRevealTimer();
        if (zone === "left-seek" || zone === "right-seek") {
          lastTapRef.current = { time: Date.now(), x, y, zone };
        } else {
          lastTapRef.current = null;
        }
        hideControls();
      } else if (zone === "left-seek" || zone === "right-seek") {
        lastTapRef.current = { time: Date.now(), x, y, zone };
        scheduleTapReveal();
      } else {
        lastTapRef.current = null;
        clearTapRevealTimer();
        revealControls();
      }
    },
    [
      clearTapRevealTimer,
      controlsHiddenByUser,
      hideControls,
      isPlaying,
      revealControls,
      scheduleTapReveal,
      seekBy,
      showControls,
      togglePlay,
    ],
  );

  const handlePointerUp = (event: React.PointerEvent<HTMLElement>) => {
    if (event.pointerType === "touch") {
      lastTouchInteractionAtRef.current = Date.now();
      pointerStartRef.current = null;
      return;
    }
    if (Date.now() < suppressPointerUntilRef.current || pinchStartRef.current) {
      pointerStartRef.current = null;
      return;
    }
    if (isInteractiveTarget(event.target)) return;
    event.currentTarget.releasePointerCapture?.(event.pointerId);
    const start = pointerStartRef.current;
    pointerStartRef.current = null;
    if (!start) {
      revealControls();
      return;
    }

    const dx = event.clientX - start.x;
    const dy = event.clientY - start.y;
    const elapsed = Date.now() - start.time;
    const absX = Math.abs(dx);
    const absY = Math.abs(dy);
    const isTap = absX <= TAP_MAX_MOVEMENT && absY <= TAP_MAX_MOVEMENT && elapsed <= TAP_MAX_MS;

    if (absY > 120 && absY > absX * 1.2 && dy > 0) {
      onClose();
      return;
    }

    if (absX > 70 && absX > absY * 1.35) {
      const seconds = Math.max(-45, Math.min(45, Math.round(dx / 8)));
      seekBy(seconds);
      return;
    }

    if (isTap) {
      lastPointerTapAtRef.current = Date.now();
      handlePlayerTap(event.clientX, event.clientY);
      return;
    }

    revealControls();
  };

  const touchDistance = (touches: { length: number; item(index: number): { clientX: number; clientY: number } | null }) => {
    if (touches.length < 2) return 0;
    const first = getTouchAt(touches, 0);
    const second = getTouchAt(touches, 1);
    if (!first || !second) return 0;
    return Math.hypot(second.clientX - first.clientX, second.clientY - first.clientY);
  };

  const playerStyle = useMemo(
    () => {
      const shellAspectRatio =
        shellSize.width > 0 && shellSize.height > 0 ? shellSize.width / shellSize.height : videoAspectRatio;
      const neededFillScale = getSmartFillScale(shellAspectRatio, videoAspectRatio);

      return {
        "--spiritflix-fill-scale": neededFillScale.toFixed(3),
        "--spiritflix-video-aspect": videoAspectRatio.toFixed(6),
      } as CSSProperties;
    },
    [shellSize.height, shellSize.width, videoAspectRatio],
  );

  return (
    <section
      className={`spiritflix-player is-fit-${fitMode} ${
        !controlsHiddenByUser && (showControls || !isPlaying) ? "is-awake" : "is-idle"
      } ${controlsHiddenByUser ? "is-controls-hidden" : ""}`}
      ref={shellRef}
      style={playerStyle}
      aria-label={`${item.Name} player`}
      onPointerDown={handlePointerDown}
      onPointerUp={handlePointerUp}
      onPointerCancel={() => {
        pointerStartRef.current = null;
      }}
      onPointerMove={(event) => {
        if (
          event.pointerType === "mouse" &&
          Date.now() - lastTouchInteractionAtRef.current > TOUCH_MOUSE_REVEAL_SUPPRESS_MS
        ) {
          revealControls();
        }
      }}
      onMouseMove={() => {
        if (Date.now() - lastTouchInteractionAtRef.current > TOUCH_MOUSE_REVEAL_SUPPRESS_MS) {
          revealControls();
        }
      }}
      onTouchStart={(event) => {
        lastTouchInteractionAtRef.current = Date.now();
        if (event.touches.length === 2) {
          event.preventDefault();
          const distance = touchDistance(event.touches);
          pinchStartRef.current = { startDistance: distance, currentDistance: distance };
          pointerStartRef.current = null;
          touchTapStartRef.current = null;
          lastTapRef.current = null;
        } else if (event.touches.length === 1 && !isInteractiveTarget(event.target)) {
          const touch = getTouchAt(event.touches, 0);
          if (touch) {
            touchTapStartRef.current = {
              x: touch.clientX,
              y: touch.clientY,
              time: Date.now(),
              currentTime: videoRef.current?.currentTime ?? 0,
              isSeeking: false,
            };
          }
        }
      }}
      onTouchMove={(event) => {
        const pinch = pinchStartRef.current;
        if (pinch && event.touches.length === 2) {
          const nextDistance = touchDistance(event.touches);
          if (!nextDistance) return;
          event.preventDefault();
          pinchStartRef.current = { ...pinch, currentDistance: nextDistance };
          return;
        }

        const start = touchTapStartRef.current;
        const touch = getTouchAt(event.touches, 0);
        if (!start || !touch || event.touches.length !== 1 || Date.now() < suppressTouchUntilRef.current) return;

        const dx = touch.clientX - start.x;
        const dy = touch.clientY - start.y;
        const absX = Math.abs(dx);
        const absY = Math.abs(dy);
        const hasHeldLongEnough = Date.now() - start.time >= TOUCH_SEEK_HOLD_MS;
        const isHorizontalSeek =
          start.isSeeking ||
          (hasHeldLongEnough && absX >= TOUCH_SEEK_ACTIVATION_PX && absX > absY * TOUCH_SEEK_VERTICAL_RATIO);
        if (!isHorizontalSeek) return;

        event.preventDefault();
        touchTapStartRef.current = { ...start, isSeeking: true };
        lastTapRef.current = null;
        seekFromTouchDelta(start.currentTime, dx);
        revealControls(true);
      }}
      onTouchEnd={(event) => {
        lastTouchInteractionAtRef.current = Date.now();
        const pinch = pinchStartRef.current;
        if (pinch && event.touches.length < 2) {
          const distanceRatio = pinch.currentDistance / pinch.startDistance;
          if (distanceRatio >= 1 + PINCH_TOGGLE_THRESHOLD && fitMode !== "fill") {
            setFit("fill");
            revealControls();
          } else if (distanceRatio <= 1 - PINCH_TOGGLE_THRESHOLD && fitMode !== "fit") {
            setFit("fit");
            revealControls();
          }
          suppressPointerUntilRef.current = Date.now() + PINCH_GESTURE_SUPPRESS_MS;
          suppressTouchUntilRef.current = Date.now() + PINCH_GESTURE_SUPPRESS_MS;
          touchTapStartRef.current = null;
        } else {
          const start = touchTapStartRef.current;
          const touch = getTouchAt(event.changedTouches, 0);
          touchTapStartRef.current = null;
          if (start?.isSeeking) {
            suppressPointerUntilRef.current = Date.now() + PINCH_GESTURE_SUPPRESS_MS;
            suppressTouchUntilRef.current = Date.now() + PINCH_GESTURE_SUPPRESS_MS;
            revealControls();
            return;
          }
          if (
            start &&
            touch &&
            Date.now() >= suppressTouchUntilRef.current &&
            Date.now() - lastPointerTapAtRef.current > PINCH_GESTURE_SUPPRESS_MS
          ) {
            const dx = touch.clientX - start.x;
            const dy = touch.clientY - start.y;
            const elapsed = Date.now() - start.time;
            if (Math.abs(dx) <= TAP_MAX_MOVEMENT && Math.abs(dy) <= TAP_MAX_MOVEMENT && elapsed <= TAP_MAX_MS) {
              suppressPointerUntilRef.current = Date.now() + PINCH_GESTURE_SUPPRESS_MS;
              handlePlayerTap(touch.clientX, touch.clientY);
            }
          }
        }
        pinchStartRef.current = null;
      }}
    >
      <div className="spiritflix-player__stage">
        <video
          key={`${item.Id}-${retryCount}`}
          ref={videoRef}
          playsInline
          controls={false}
          loop={repeatMode === "one"}
          controlsList="nodownload noplaybackrate noremoteplayback"
          preload="metadata"
          onWaiting={() => {
            setIsLoading(true);
            if (!waitingSinceRef.current) {
              waitingSinceRef.current = performance.now();
            }
          }}
          onCanPlay={() => {
            setStreamError("");
            setIsLoading(false);
            if (waitingSinceRef.current) {
              waitingSinceRef.current = null;
            }
          }}
          onPlaying={() => {
            setIsPlaying(true);
            setIsLoading(false);
            if (waitingSinceRef.current) {
              waitingSinceRef.current = null;
            }
          }}
          onPlay={() => setIsPlaying(true)}
          onPause={() => {
            setIsPlaying(false);
            flushPlaybackProgress("Progress", { isPaused: true, updateUi: true });
          }}
          onTimeUpdate={(event) => {
            const video = event.currentTarget;
            const positionTicks = secondsToTicks(video.currentTime);
            const now = Date.now();
            if (now - lastUiTimeAtRef.current >= UI_TIME_UPDATE_MS) {
              lastUiTimeAtRef.current = now;
              setCurrentTime(video.currentTime);
            }
            if (now - lastUiProgressAtRef.current >= PLAYBACK_REPORT_MS) {
              lastUiProgressAtRef.current = now;
              emitPlaybackProgress(positionTicks, false);
            }
            if (!firstNonZeroReportRef.current && video.currentTime >= 3) {
              firstNonZeroReportRef.current = true;
              lastReportedTicksRef.current = positionTicks;
              lastPlaybackReportAtRef.current = performance.now();
              void client.reportPlayback(item.Id, "Progress", positionTicks, false);
            }
            if (performance.now() - lastPlaybackReportAtRef.current >= PLAYBACK_REPORT_MS) {
              lastPlaybackReportAtRef.current = performance.now();
              lastReportedTicksRef.current = positionTicks;
              void client.reportPlayback(item.Id, "Progress", positionTicks, false);
            }
          }}
          onLoadedMetadata={(event) => {
            const video = event.currentTarget;
            setDuration(Number.isFinite(video.duration) ? video.duration : ticksToSeconds(item.RunTimeTicks));
            if (video.videoWidth > 0 && video.videoHeight > 0) {
              setVideoAspectRatio(video.videoWidth / video.videoHeight);
            }
          }}
          onEnded={() => {
            setIsPlaying(false);
            endedRef.current = true;
            void client.reportPlayback(item.Id, "Stopped", secondsToTicks(videoRef.current?.duration || duration), false, { keepalive: true });
            emitPlaybackProgress(secondsToTicks(videoRef.current?.duration || duration), true);
            const currentRepeatMode = repeatModeRef.current;
            if (currentRepeatMode === "one") {
              const video = videoRef.current;
              if (video) {
                video.currentTime = 0;
                void video.play();
              }
            } else if (nextItem) {
              selectQueueItem(nextItem);
            } else if (currentRepeatMode === "queue" && queueItems.length > 0) {
              selectQueueItem(queueItems[0] ?? item);
            } else {
              setEndedAtQueueEnd(true);
              revealControls(true);
            }
          }}
        />
      </div>

      {isLoading && !streamError && !isPlaying ? (
        <div className="spiritflix-player__loading" aria-live="polite">
          <span />
        </div>
      ) : null}

      {playbackFeedback ? (
        <div
          className={`spiritflix-player__tap-feedback is-${playbackFeedback.kind}`}
          aria-hidden="true"
          key={playbackFeedback.id}
        >
          {renderPlaybackFeedback(playbackFeedback)}
        </div>
      ) : null}

      <div className="spiritflix-player__top">
        <button type="button" onClick={onClose} aria-label="Close player" title="Close">
          <X size={22} aria-hidden="true" />
        </button>
        <div className="spiritflix-player__title">
          <strong>{item.Name}</strong>
          <span>{queue?.sourceTitle ?? (usingHls ? "HLS fallback" : "Direct stream")}</span>
        </div>
        <button className="spiritflix-player__collapse" type="button" onClick={onClose} aria-label="Exit player" title="Exit player">
          <ChevronsDown size={22} aria-hidden="true" />
        </button>
      </div>

      {streamError ? (
        <div className="spiritflix-player__error" role="alert">
          <strong>Stream unavailable</strong>
          <p>{streamError}</p>
          <div>
            <button type="button" onClick={() => setRetryCount((count) => count + 1)}>
              <RefreshCw size={18} aria-hidden="true" />
              Retry
            </button>
            <button type="button" onClick={onClose}>Back</button>
          </div>
        </div>
      ) : null}

      {endedAtQueueEnd ? (
        <div className="spiritflix-player__ended">
          <strong>End of queue</strong>
          <div>
            <button type="button" onClick={() => seekTo(0)}>
              <RefreshCw size={18} aria-hidden="true" />
              Replay
            </button>
            <button type="button" onClick={onClose}>Close</button>
          </div>
        </div>
      ) : null}

      <div className="spiritflix-player__controls">
        <div className="spiritflix-player__scrub-row">
          <span className="spiritflix-player__time">{formatTime(currentTime)}</span>
          <input
            className="spiritflix-player__scrub"
            aria-label="Seek"
            type="range"
            min={0}
            max={duration || ticksToSeconds(item.RunTimeTicks) || 0}
            step={0.1}
            value={Math.min(currentTime, duration || currentTime)}
            onPointerDown={() => revealControls(true)}
            onChange={(event) => seekTo(Number(event.target.value))}
          />
          <span className="spiritflix-player__time">{formatTime(duration || ticksToSeconds(item.RunTimeTicks))}</span>
        </div>

        <div className="spiritflix-player__button-row">
          <div className="spiritflix-player__transport">
            <button type="button" onClick={() => selectQueueItem(previousItem)} disabled={!previousItem} aria-label="Previous video" title="Previous">
              <SkipBack size={20} aria-hidden="true" />
            </button>
            <button className="spiritflix-player__play" type="button" onClick={togglePlay} aria-label={isPlaying ? "Pause" : "Play"} title={isPlaying ? "Pause" : "Play"}>
              {isPlaying ? <Pause size={30} aria-hidden="true" /> : <Play size={30} fill="currentColor" aria-hidden="true" />}
            </button>
            <button type="button" onClick={selectNextItem} disabled={!nextItem && repeatMode !== "queue"} aria-label="Next video" title="Next">
              <SkipForward size={20} aria-hidden="true" />
            </button>
            <button
              className={repeatMode !== "off" ? "is-active" : undefined}
              type="button"
              onClick={cycleRepeatMode}
              aria-label={repeatLabel}
              aria-pressed={repeatMode !== "off"}
              title={repeatLabel}
            >
              {repeatMode === "one" ? <Repeat1 size={20} aria-hidden="true" /> : <Repeat size={20} aria-hidden="true" />}
            </button>
            <button
              className={isShuffled ? "is-active" : undefined}
              type="button"
              onClick={shuffleCurrentQueue}
              disabled={queueItems.length < 2}
              aria-label={shuffleLabel}
              aria-pressed={isShuffled}
              title={shuffleLabel}
            >
              <Shuffle size={20} aria-hidden="true" />
            </button>
            <button
              className={isFavorite ? "is-active" : undefined}
              type="button"
              onClick={() => {
                onToggleFavorite(item, !isFavorite);
                revealControls(true);
              }}
              aria-label={isFavorite ? "Remove favorite" : "Add favorite"}
              aria-pressed={isFavorite}
              title={isFavorite ? "Remove favorite" : "Add favorite"}
            >
              <Heart size={20} fill={isFavorite ? "currentColor" : "none"} aria-hidden="true" />
            </button>
          </div>

          <div className="spiritflix-player__tools">
            <div className={`spiritflix-player__volume ${isVolumeOpen ? "is-expanded" : ""}`}>
              <button
                type="button"
                onClick={toggleMuted}
                aria-label={isMuted ? "Unmute" : "Mute"}
                aria-controls="spiritflix-player-volume"
                aria-expanded={isVolumeOpen}
                title={isMuted ? "Unmute" : "Mute"}
              >
                {isMuted ? <VolumeX size={20} aria-hidden="true" /> : <Volume2 size={20} aria-hidden="true" />}
              </button>
              <input
                id="spiritflix-player-volume"
                aria-label="Volume"
                type="range"
                min={0}
                max={1}
                step={0.01}
                value={isMuted ? 0 : volume}
                onPointerDown={() => {
                  setIsVolumeOpen(true);
                  revealControls(true);
                }}
                onFocus={() => {
                  setIsVolumeOpen(true);
                  revealControls(true);
                }}
                onChange={(event) => updateVolume(Number(event.target.value))}
              />
            </div>

            <button
              className={isMiniPlayer ? "is-active" : undefined}
              type="button"
              onClick={toggleMiniPlayer}
              disabled={!miniPlayerSupported}
              aria-label={miniPlayerLabel}
              aria-pressed={isMiniPlayer}
              title={miniPlayerLabel}
            >
              <PictureInPicture2 size={20} aria-hidden="true" />
            </button>
            <button
              className={isQueueOpen ? "is-active" : undefined}
              type="button"
              onClick={toggleQueueDrawer}
              disabled={queueItems.length < 2}
              aria-label={isQueueOpen ? "Close queue" : "Open queue"}
              aria-expanded={isQueueOpen}
              aria-controls="spiritflix-player-queue"
              title={isQueueOpen ? "Close queue" : "Open queue"}
            >
              <ListMusic size={20} aria-hidden="true" />
            </button>
            <button type="button" onClick={toggleFullscreen} aria-label={isFullscreen ? "Exit fullscreen" : "Fullscreen"} title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}>
              {isFullscreen ? <Minimize size={20} aria-hidden="true" /> : <Maximize size={20} aria-hidden="true" />}
            </button>
          </div>
        </div>

        {upNextTitle ? (
          <div className="spiritflix-player__up-next">
            <span>Up next</span>
            <strong>{upNextTitle}</strong>
          </div>
        ) : null}
      </div>

      {isQueueOpen ? (
        <aside className="spiritflix-player__queue" id="spiritflix-player-queue" aria-label="Playback queue">
          <div className="spiritflix-player__queue-header">
            <div>
              <span>{queue?.sourceTitle ?? "Queue"}</span>
              <strong>{queueItems.length} videos</strong>
            </div>
            <button type="button" onClick={() => setIsQueueOpen(false)} aria-label="Close queue" title="Close queue">
              <X size={18} aria-hidden="true" />
            </button>
          </div>
          <div className="spiritflix-player__queue-list">
            {queueItems.map((queueItem, index) => {
              const isCurrent = queueItem.Id === item.Id;
              return (
                <button
                  className={isCurrent ? "is-current" : undefined}
                  type="button"
                  key={`${queueItem.Id}-${index}`}
                  onClick={() => {
                    if (!isCurrent) selectQueueItem(queueItem);
                    setIsQueueOpen(false);
                  }}
                  aria-current={isCurrent ? "true" : undefined}
                >
                  <span>{String(index + 1).padStart(2, "0")}</span>
                  <strong>{queueItem.Name}</strong>
                </button>
              );
            })}
          </div>
        </aside>
      ) : null}
    </section>
  );
}

"use client";

import { useRef } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import type { JellyfinClient } from "@/lib/spiritflix-jellyfin-client";
import type { JellyfinItem } from "@/lib/spiritflix-types";
import { SpiritFlixCard } from "./SpiritFlixCard";

interface SpiritFlixRailProps {
  title: string;
  variant?: "poster" | "landscape";
  client: JellyfinClient;
  items: JellyfinItem[];
  emptyText: string;
  playOnPrimaryTap?: boolean;
  onOpenDetails: (item: JellyfinItem) => void;
  onPlay: (item: JellyfinItem, queueItems?: JellyfinItem[], sourceTitle?: string, startPositionTicks?: number) => void;
}

export function SpiritFlixRail({
  title,
  variant = "poster",
  client,
  items,
  emptyText,
  playOnPrimaryTap = false,
  onOpenDetails,
  onPlay,
}: SpiritFlixRailProps) {
  const trackRef = useRef<HTMLDivElement | null>(null);

  const scroll = (direction: "left" | "right") => {
    const track = trackRef.current;
    if (!track) return;
    track.scrollBy({ left: direction === "left" ? -520 : 520, behavior: "smooth" });
  };

  return (
    <section className={`spiritflix-rail spiritflix-rail--${variant}`}>
      <div className="spiritflix-rail__header">
        <h2>{title}</h2>
        {items.length ? (
          <div className="spiritflix-rail__controls" aria-hidden="true">
            <button type="button" onClick={() => scroll("left")} tabIndex={-1}>
              <ChevronLeft size={17} />
            </button>
            <button type="button" onClick={() => scroll("right")} tabIndex={-1}>
              <ChevronRight size={17} />
            </button>
          </div>
        ) : null}
      </div>
      {items.length ? (
        <div className="spiritflix-rail__track" ref={trackRef}>
          {items.map((item) => (
            <SpiritFlixCard
              key={item.Id}
              variant={variant}
              client={client}
              item={item}
              playOnPrimaryTap={playOnPrimaryTap}
              onOpenDetails={onOpenDetails}
              onPlay={(selectedItem, startPositionTicks) => onPlay(selectedItem, items, title, startPositionTicks)}
            />
          ))}
        </div>
      ) : (
        <p className="spiritflix-empty">{emptyText}</p>
      )}
    </section>
  );
}

import fs from "node:fs/promises";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import {
  buildPathItemKey,
  clearSpiritFlixAdminPreviewStore,
  getSmokeRoot,
  handleSpiritFlixAdminAction,
  moveSpiritFlixAdminPath,
  validateOrderItemKey,
} from "../actions";
import { SPIRITFLIX_MEDIA_ROOT } from "../constants";
import { getReceiptsDirectory } from "../receipts";

const smokeRoot = getSmokeRoot();

async function countReceiptLines(): Promise<number> {
  const receiptsDir = getReceiptsDirectory();
  const stamp = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  const file = path.join(receiptsDir, `${stamp}.jsonl`);
  try {
    const raw = await fs.readFile(file, "utf8");
    return raw.split("\n").filter(Boolean).length;
  } catch {
    return 0;
  }
}

describe("SpiritFlix admin actions", () => {
  let receiptBaseline = 0;

  beforeEach(async () => {
    clearSpiritFlixAdminPreviewStore();
    await fs.mkdir(smokeRoot, { recursive: true });
    receiptBaseline = await countReceiptLines();
  });

  afterEach(async () => {
    clearSpiritFlixAdminPreviewStore();
    await fs.rm(smokeRoot, { force: true, recursive: true });
  });

  it("validates custom order item keys", () => {
    expect(validateOrderItemKey("jellyfin:abc123")).toBe(true);
    expect(validateOrderItemKey(buildPathItemKey("/mnt/spirit-8tb/media/other/test.mkv"))).toBe(true);
    expect(validateOrderItemKey("bad-key")).toBe(false);
  });

  it("previews createFolder without writing receipts", async () => {
    const preview = await handleSpiritFlixAdminAction({
      action: "createFolder",
      mode: "preview",
      parentPath: smokeRoot,
      name: "preview-only-folder",
    });

    expect(preview.allowed).toBe(true);
    expect(preview.previewId).toBeTruthy();
    expect(await countReceiptLines()).toBe(receiptBaseline);
    await expect(fs.stat(path.join(smokeRoot, "preview-only-folder"))).rejects.toThrow();
  });

  it("previews and executes create folder inside the smoke root", async () => {
    const preview = await handleSpiritFlixAdminAction({
      action: "createFolder",
      mode: "preview",
      parentPath: smokeRoot,
      name: "cursor-smoke-folder",
    });

    expect(preview.allowed).toBe(true);

    const executed = await handleSpiritFlixAdminAction({
      action: "createFolder",
      mode: "execute",
      confirmToken: preview.previewId,
      parentPath: smokeRoot,
      name: "cursor-smoke-folder",
    });

    expect(executed.allowed).toBe(true);
    expect(executed.receipt?.status).toBe("executed");
    const created = await fs.stat(path.join(smokeRoot, "cursor-smoke-folder"));
    expect(created.isDirectory()).toBe(true);
    expect(await countReceiptLines()).toBeGreaterThan(receiptBaseline);
  });

  it("previews and executes rename preserving video extension", async () => {
    const sourcePath = path.join(smokeRoot, "clip.mkv");
    await fs.writeFile(sourcePath, "smoke");

    const preview = await handleSpiritFlixAdminAction({
      action: "rename",
      mode: "preview",
      sourcePath,
      name: "cursor-smoke-renamed",
    });

    expect(preview.allowed).toBe(true);
    expect(preview.preview?.targetPath).toContain("cursor-smoke-renamed.mkv");

    const executed = await handleSpiritFlixAdminAction({
      action: "rename",
      mode: "execute",
      confirmToken: preview.previewId,
      sourcePath,
      name: "cursor-smoke-renamed",
    });

    expect(executed.allowed).toBe(true);
    await expect(fs.stat(path.join(smokeRoot, "cursor-smoke-renamed.mkv"))).resolves.toBeTruthy();
  });

  it("previews and executes move within smoke root", async () => {
    const nested = path.join(smokeRoot, "move-src");
    const dest = path.join(smokeRoot, "move-dest");
    await fs.mkdir(nested, { recursive: true });
    await fs.mkdir(dest, { recursive: true });
    const filePath = path.join(nested, "disposable.txt");
    await fs.writeFile(filePath, "move me");

    const preview = await handleSpiritFlixAdminAction({
      action: "move",
      mode: "preview",
      sourcePath: filePath,
      targetPath: dest,
    });
    expect(preview.allowed).toBe(true);

    const executed = await handleSpiritFlixAdminAction({
      action: "move",
      mode: "execute",
      confirmToken: preview.previewId,
      sourcePath: filePath,
      targetPath: dest,
    });
    expect(executed.allowed).toBe(true);
    await expect(fs.stat(path.join(dest, "disposable.txt"))).resolves.toBeTruthy();
  });

  it("softDelete moves into .trash and restore rejects overwrite", async () => {
    const filePath = path.join(smokeRoot, "trash-me.txt");
    await fs.writeFile(filePath, "trash");

    const deletePreview = await handleSpiritFlixAdminAction({
      action: "softDelete",
      mode: "preview",
      sourcePath: filePath,
    });
    expect(deletePreview.allowed).toBe(true);
    expect(deletePreview.preview?.targetPath).toContain(`${path.sep}.trash${path.sep}`);

    const deleted = await handleSpiritFlixAdminAction({
      action: "softDelete",
      mode: "execute",
      confirmToken: deletePreview.previewId,
      sourcePath: filePath,
    });
    expect(deleted.allowed).toBe(true);
    const trashPath = deleted.preview?.targetPath as string;
    await expect(fs.stat(filePath)).rejects.toThrow();

    const restorePreview = await handleSpiritFlixAdminAction({
      action: "restore",
      mode: "preview",
      sourcePath: trashPath,
    });
    expect(restorePreview.allowed).toBe(true);
    const restoreTarget = restorePreview.preview?.targetPath as string;

    await fs.writeFile(restoreTarget, "blocker");
    const blockedRestore = await handleSpiritFlixAdminAction({
      action: "restore",
      mode: "preview",
      sourcePath: trashPath,
    });
    expect(blockedRestore.allowed).toBe(false);

    await fs.rm(restoreTarget);
    const restored = await handleSpiritFlixAdminAction({
      action: "restore",
      mode: "execute",
      confirmToken: restorePreview.previewId,
      sourcePath: trashPath,
    });
    expect(restored.allowed).toBe(true);
    await expect(fs.stat(restoreTarget)).resolves.toBeTruthy();
  });

  it("moveSpiritFlixAdminPath copies then deletes when rename hits EXDEV", async () => {
    const sourcePath = path.join(smokeRoot, "exdev-source.txt");
    const targetPath = path.join(smokeRoot, "nested", "exdev-target.txt");
    await fs.mkdir(path.dirname(targetPath), { recursive: true });
    await fs.writeFile(sourcePath, "cross-device");

    const exdev = Object.assign(new Error("EXDEV: cross-device link not permitted"), { code: "EXDEV" }) as NodeJS.ErrnoException;
    const renameSpy = vi.spyOn(fs, "rename").mockRejectedValueOnce(exdev);

    await moveSpiritFlixAdminPath(sourcePath, targetPath);

    expect(renameSpy).toHaveBeenCalled();
    await expect(fs.readFile(targetPath, "utf8")).resolves.toBe("cross-device");
    await expect(fs.stat(sourcePath)).rejects.toThrow();
    renameSpy.mockRestore();
    await fs.rm(targetPath);
    await fs.rm(path.dirname(targetPath), { recursive: true, force: true });
  });

  it("writeMetadata rejects unknown fields and writes only under metadata root", async () => {
    const sourcePath = path.join(smokeRoot, "meta-target.txt");
    await fs.writeFile(sourcePath, "meta");

    const blocked = await handleSpiritFlixAdminAction({
      action: "writeMetadata",
      mode: "preview",
      sourcePath,
      metadata: { displayTitle: "ok", evilField: "nope" } as never,
    });
    expect(blocked.allowed).toBe(false);

    const preview = await handleSpiritFlixAdminAction({
      action: "writeMetadata",
      mode: "preview",
      sourcePath,
      metadata: { displayTitle: "Smoke title", notes: "disposable" },
    });
    expect(preview.allowed).toBe(true);
    expect(preview.preview?.targetPath).toContain(`${path.sep}.spiritflix-admin${path.sep}metadata${path.sep}`);

    const executed = await handleSpiritFlixAdminAction({
      action: "writeMetadata",
      mode: "execute",
      confirmToken: preview.previewId,
      sourcePath,
      metadata: { displayTitle: "Smoke title", notes: "disposable" },
    });
    expect(executed.allowed).toBe(true);
    expect(executed.preview?.targetPath).not.toContain(smokeRoot);
  });

  it("saveOrder validates stable keys and writes order.json", async () => {
    const key = buildPathItemKey(path.join(smokeRoot, "order-item.txt"));
    const blocked = await handleSpiritFlixAdminAction({
      action: "saveOrder",
      mode: "preview",
      order: { version: 1, updatedAt: new Date().toISOString(), groups: [{ id: "g1", name: "G", itemKeys: ["bad"] }] },
    });
    expect(blocked.allowed).toBe(false);

    const preview = await handleSpiritFlixAdminAction({
      action: "saveOrder",
      mode: "preview",
      order: { version: 1, updatedAt: new Date().toISOString(), groups: [{ id: "g1", name: "Smoke", itemKeys: [key] }] },
    });
    expect(preview.allowed).toBe(true);

    const executed = await handleSpiritFlixAdminAction({
      action: "saveOrder",
      mode: "execute",
      confirmToken: preview.previewId,
      order: { version: 1, updatedAt: new Date().toISOString(), groups: [{ id: "g1", name: "Smoke", itemKeys: [key] }] },
    });
    expect(executed.allowed).toBe(true);
    expect(executed.preview?.targetPath).toContain("order.json");
  });

  it("rejects path traversal and outside roots", async () => {
    const traversal = await handleSpiritFlixAdminAction({
      action: "rename",
      mode: "preview",
      sourcePath: `${smokeRoot}/../outside`,
      name: "blocked",
    });
    expect(traversal.allowed).toBe(false);

    const outside = await handleSpiritFlixAdminAction({
      action: "rename",
      mode: "preview",
      sourcePath: "/etc/passwd",
      name: "blocked",
    });
    expect(outside.allowed).toBe(false);
  });

  it("rejects protected media root destructive actions", async () => {
    const blocked = await handleSpiritFlixAdminAction({
      action: "softDelete",
      mode: "preview",
      sourcePath: SPIRITFLIX_MEDIA_ROOT,
    });
    expect(blocked.allowed).toBe(false);
    expect(blocked.message).toMatch(/protected/i);

    const blockedLibrary = await handleSpiritFlixAdminAction({
      action: "rename",
      mode: "preview",
      sourcePath: `${SPIRITFLIX_MEDIA_ROOT}/yes`,
      name: "renamed-yes",
    });
    expect(blockedLibrary.allowed).toBe(false);
  });

  it("requires preview token before execute", async () => {
    const executed = await handleSpiritFlixAdminAction({
      action: "createFolder",
      mode: "execute",
      confirmToken: "missing-token",
      parentPath: smokeRoot,
      name: "no-preview",
    });
    expect(executed.allowed).toBe(false);
  });

  it("gates Jellyfin rescan when credentials are unavailable", async () => {
    const originalKey = process.env.JELLYFIN_API_KEY;
    delete process.env.JELLYFIN_API_KEY;
    const preview = await handleSpiritFlixAdminAction({
      action: "requestJellyfinRescan",
      mode: "preview",
      rescanPath: smokeRoot,
    });
    if (originalKey) process.env.JELLYFIN_API_KEY = originalKey;
    expect(preview.allowed).toBe(false);
    expect(preview.message).toMatch(/not active yet/i);
  });
});

