import fs from "node:fs/promises";
import path from "node:path";
import { createHash, randomUUID } from "node:crypto";
import { SPIRITFLIX_MEDIA_ROOT } from "./constants";
import { getServerJellyfinCredentials } from "./jellyfin-server";
import {
  assertWritableSpiritFlixAdminPath,
  isSpiritFlixAdminTrashPath,
  resolveSpiritFlixAdminPath,
  validateSpiritFlixAdminPathCandidate,
} from "./paths";
import { createReceiptId, writeSpiritFlixAdminReceipt } from "./receipts";
import type {
  SpiritFlixAdminActionName,
  SpiritFlixAdminActionRequest,
  SpiritFlixAdminActionResponse,
  SpiritFlixAdminActionRiskLevel,
  SpiritFlixAdminMetadataSidecar,
  SpiritFlixAdminOrderFile,
  SpiritFlixAdminReceipt,
} from "./types";

const METADATA_ROOT = path.join(SPIRITFLIX_MEDIA_ROOT, ".spiritflix-admin", "metadata");
const ORDER_FILE = path.join(SPIRITFLIX_MEDIA_ROOT, ".spiritflix-admin", "order.json");
const TRASH_ROOT = path.join(SPIRITFLIX_MEDIA_ROOT, ".trash");
const SMOKE_ROOT = path.join(SPIRITFLIX_MEDIA_ROOT, "other", ".spiritflix-admin-smoke");

const VIDEO_EXTENSIONS = new Set([".avi", ".m4v", ".mkv", ".mov", ".mp4", ".mpeg", ".mpg", ".webm", ".wmv"]);
const ALLOWED_METADATA_FIELDS = new Set([
  "displayTitle",
  "customTags",
  "collection",
  "notes",
  "manualSortGroup",
  "manualSortIndex",
  "hiddenFromViewer",
  "favoriteOverride",
]);
const MAX_METADATA_BYTES = 16_384;
const MAX_ORDER_BYTES = 65_536;

const previewStore = new Map<
  string,
  { action: SpiritFlixAdminActionName; payload: SpiritFlixAdminActionRequest; receipt: SpiritFlixAdminReceipt }
>();

export function normalizeSpiritFlixAdminActionRequest(request: SpiritFlixAdminActionRequest): SpiritFlixAdminActionRequest {
  const phase = request.mode ?? request.phase ?? "preview";
  const previewId = request.confirmToken ?? request.previewId;
  const folderName = request.folderName ?? (request.action === "createFolder" ? request.name : undefined);
  const newName = request.newName ?? (request.action === "rename" ? request.name : undefined);
  const targetPath =
    request.targetPath ??
    (request.action === "createFolder" ? request.parentPath : undefined) ??
    (request.action === "move" ? request.parentPath : undefined);

  return {
    ...request,
    phase,
    previewId,
    folderName,
    newName,
    targetPath,
  };
}

function sanitizeName(value: string): string {
  const cleaned = value.trim().replace(/[\\/:*?"<>|]/g, "_").replace(/\.\.+/g, ".");
  if (!cleaned || cleaned === "." || cleaned === ".." || cleaned.includes("/") || cleaned.includes("\\")) {
    throw new Error("Name is not allowed.");
  }
  return cleaned;
}

function stableItemKey(value: string): string {
  const normalized = value.replace(/\\/g, "/").toLowerCase();
  return `path:${createHash("sha256").update(normalized).digest("hex")}`;
}

function riskForAction(action: SpiritFlixAdminActionName): SpiritFlixAdminActionRiskLevel {
  switch (action) {
    case "softDelete":
    case "move":
      return "medium";
    case "requestJellyfinRescan":
      return "high";
    case "rename":
    case "restore":
      return "medium";
    default:
      return "low";
  }
}

async function assertAllowedPath(candidate: string): Promise<string> {
  const resolved = await resolveSpiritFlixAdminPath(candidate);
  return resolved.realPath;
}

async function assertParentExists(parentPath: string): Promise<string> {
  const realParent = await assertAllowedPath(parentPath);
  const stats = await fs.stat(realParent);
  if (!stats.isDirectory()) throw new Error("Parent path must be a folder.");
  return realParent;
}

function buildPlannedReceipt(
  action: string,
  affectedPaths: string[],
  extra: Partial<SpiritFlixAdminReceipt> = {},
): SpiritFlixAdminReceipt {
  return {
    id: createReceiptId(),
    timestamp: new Date().toISOString(),
    actor: "spiritflix-admin",
    action,
    status: "planned",
    affectedPaths,
    reversible: extra.reversible ?? true,
    ...extra,
  };
}

function response(
  action: SpiritFlixAdminActionName,
  phase: "preview" | "execute",
  previewId: string,
  allowed: boolean,
  message: string,
  extra: Partial<SpiritFlixAdminActionResponse> = {},
): SpiritFlixAdminActionResponse {
  return {
    schema: "spiritflix-admin-action/v1",
    action,
    phase,
    previewId,
    allowed,
    message,
    riskLevel: extra.riskLevel ?? riskForAction(action),
    ...extra,
  };
}

function resolveRenameTarget(sourcePath: string, rawName: string): string {
  const sanitized = sanitizeName(rawName);
  const extension = path.extname(sourcePath);
  if (VIDEO_EXTENSIONS.has(extension.toLowerCase()) && !path.extname(sanitized)) {
    return `${sanitized}${extension}`;
  }
  return sanitized;
}

function validateMetadata(payload: unknown): SpiritFlixAdminMetadataSidecar {
  if (!payload || typeof payload !== "object" || Array.isArray(payload)) {
    throw new Error("Metadata payload is required.");
  }
  const record = payload as Record<string, unknown>;
  for (const key of Object.keys(record)) {
    if (!ALLOWED_METADATA_FIELDS.has(key)) {
      throw new Error(`Unknown metadata field: ${key}`);
    }
  }
  const serialized = JSON.stringify(record);
  if (serialized.length > MAX_METADATA_BYTES) {
    throw new Error("Metadata payload is too large.");
  }
  return record as SpiritFlixAdminMetadataSidecar;
}

async function atomicWriteFile(filePath: string, content: string): Promise<void> {
  const tempPath = `${filePath}.tmp-${process.pid}-${Date.now()}`;
  await fs.writeFile(tempPath, content, "utf8");
  await moveSpiritFlixAdminPath(tempPath, filePath);
}

/** Rename when possible; copy+delete across mount points (yes/ vs .trash on sda1). */
export async function moveSpiritFlixAdminPath(sourcePath: string, targetPath: string): Promise<void> {
  try {
    await fs.rename(sourcePath, targetPath);
    return;
  } catch (error) {
    const err = error as NodeJS.ErrnoException;
    if (err.code !== "EXDEV") throw error;
  }

  await fs.mkdir(path.dirname(targetPath), { recursive: true });
  const stats = await fs.stat(sourcePath);
  if (stats.isDirectory()) {
    await fs.cp(sourcePath, targetPath, { recursive: true, errorOnExist: true });
    await fs.rm(sourcePath, { recursive: true, force: true });
    return;
  }

  await fs.copyFile(sourcePath, targetPath);
  await fs.unlink(sourcePath);
}

async function crossDeviceMoveWarning(sourcePath: string, targetPath: string): Promise<string | null> {
  try {
    const [sourceStat, targetParentStat] = await Promise.all([
      fs.stat(sourcePath),
      fs.stat(path.dirname(targetPath)),
    ]);
    if (sourceStat.dev !== targetParentStat.dev) {
      return "Source and trash are on different volumes; delete copies the file then removes the original.";
    }
  } catch {
    return null;
  }
  return null;
}

async function uniqueTrashPath(targetPath: string): Promise<string> {
  let candidate = targetPath;
  let counter = 1;
  while (true) {
    try {
      await fs.access(candidate);
      const directory = path.dirname(candidate);
      const base = path.basename(candidate);
      candidate = path.join(directory, `${base}.__trash-${counter}`);
      counter += 1;
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return candidate;
      throw error;
    }
  }
}

function restoreTargetFromTrash(trashPath: string): string {
  if (!isSpiritFlixAdminTrashPath(trashPath)) {
    throw new Error("Restore source must be inside the trash folder.");
  }
  const relative = trashPath.split(`${path.sep}.trash${path.sep}`)[1]?.split(path.sep).slice(1).join(path.sep);
  if (!relative) throw new Error("Could not determine restore target.");
  return path.join(SPIRITFLIX_MEDIA_ROOT, relative);
}

export async function handleSpiritFlixAdminAction(rawRequest: SpiritFlixAdminActionRequest): Promise<SpiritFlixAdminActionResponse> {
  const request = normalizeSpiritFlixAdminActionRequest(rawRequest);
  const phase = request.phase ?? "preview";
  const previewId = request.previewId ?? createReceiptId();

  if (phase === "execute") {
    const cached = previewStore.get(previewId);
    if (!cached || cached.action !== request.action) {
      return response(request.action, "execute", previewId, false, "Preview confirmation is required before executing this action.");
    }
    previewStore.delete(previewId);
    return executeAction(cached.action, normalizeSpiritFlixAdminActionRequest(cached.payload), previewId, cached.receipt);
  }

  try {
    return await previewAction(request.action, request, previewId);
  } catch (error) {
    const reason = error instanceof Error ? error.message : "Action blocked.";
    return response(request.action, "preview", previewId, false, reason);
  }
}

async function previewAction(
  action: SpiritFlixAdminActionName,
  request: SpiritFlixAdminActionRequest,
  previewId: string,
): Promise<SpiritFlixAdminActionResponse> {
  switch (action) {
    case "createFolder":
      return previewCreateFolder(request, previewId);
    case "rename":
      return previewRename(request, previewId);
    case "move":
      return previewMove(request, previewId);
    case "softDelete":
      return previewSoftDelete(request, previewId);
    case "restore":
      return previewRestore(request, previewId);
    case "writeMetadata":
      return previewWriteMetadata(request, previewId);
    case "saveOrder":
      return previewSaveOrder(request, previewId);
    case "requestJellyfinRescan":
      return previewRescan(request, previewId);
    default:
      return response(action, "preview", previewId, false, "Unknown action.");
  }
}

async function previewCreateFolder(request: SpiritFlixAdminActionRequest, previewId: string) {
  const parentPath = await assertParentExists(request.targetPath ?? SPIRITFLIX_MEDIA_ROOT);
  const folderName = sanitizeName(request.folderName ?? "");
  const targetPath = path.join(parentPath, folderName);
  await fs.access(targetPath).then(() => {
    throw new Error("Folder already exists.");
  }).catch((error: NodeJS.ErrnoException) => {
    if (error.code !== "ENOENT") throw error;
  });

  const receipt = buildPlannedReceipt("createFolder", [targetPath], {
    targetPath,
    sourcePath: parentPath,
    rollbackHint: "Delete the created folder if empty.",
    previewId,
  });
  previewStore.set(previewId, { action: "createFolder", payload: request, receipt });
  return response("createFolder", "preview", previewId, true, `Create folder ${folderName}`, {
    receipt,
    preview: {
      targetPath,
      sourcePath: parentPath,
      affectedPaths: [targetPath],
      warnings: [],
      reversible: true,
    },
  });
}

async function previewRename(request: SpiritFlixAdminActionRequest, previewId: string) {
  const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
  assertWritableSpiritFlixAdminPath(sourcePath, "rename");
  const parentPath = path.dirname(sourcePath);
  const newName = resolveRenameTarget(sourcePath, request.newName ?? "");
  const targetPath = path.join(parentPath, newName);
  if (targetPath === sourcePath) throw new Error("New name matches the current name.");
  await fs.access(targetPath).then(() => {
    throw new Error("Target already exists.");
  }).catch((error: NodeJS.ErrnoException) => {
    if (error.code !== "ENOENT") throw error;
  });

  const receipt = buildPlannedReceipt("rename", [sourcePath, targetPath], {
    sourcePath,
    targetPath,
    rollbackHint: "Rename back to the original filename.",
    previewId,
  });
  previewStore.set(previewId, { action: "rename", payload: request, receipt });
  return response("rename", "preview", previewId, true, `Rename to ${newName}`, {
    receipt,
    preview: {
      sourcePath,
      targetPath,
      affectedPaths: [sourcePath, targetPath],
      warnings: [],
      reversible: true,
    },
  });
}

async function previewMove(request: SpiritFlixAdminActionRequest, previewId: string) {
  const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
  assertWritableSpiritFlixAdminPath(sourcePath, "move");
  const targetParent = await assertParentExists(request.targetPath ?? request.parentPath ?? "");
  const targetPath = path.join(targetParent, path.basename(sourcePath));

  if (targetPath === sourcePath) throw new Error("Item is already at the target location.");
  await fs.access(targetPath).then(() => {
    throw new Error("Target already exists.");
  }).catch((error: NodeJS.ErrnoException) => {
    if (error.code !== "ENOENT") throw error;
  });

  const warnings: string[] = [];
  const sourceStats = await fs.stat(sourcePath);
  if (sourceStats.isDirectory()) warnings.push("Moving folders can take time. Review the affected path before confirming.");

  const receipt = buildPlannedReceipt("move", [sourcePath, targetPath], {
    sourcePath,
    targetPath,
    rollbackHint: "Move the item back to the source folder.",
    previewId,
  });
  previewStore.set(previewId, { action: "move", payload: request, receipt });
  return response("move", "preview", previewId, true, `Move to ${targetParent}`, {
    receipt,
    preview: {
      sourcePath,
      targetPath,
      affectedPaths: [sourcePath, targetPath],
      warnings,
      reversible: true,
    },
  });
}

async function previewSoftDelete(request: SpiritFlixAdminActionRequest, previewId: string) {
  const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
  assertWritableSpiritFlixAdminPath(sourcePath, "soft delete");
  const relative = path.relative(SPIRITFLIX_MEDIA_ROOT, sourcePath);
  const trashDay = new Date().toISOString().slice(0, 10).replace(/-/g, "");
  const targetPath = await uniqueTrashPath(path.join(TRASH_ROOT, trashDay, relative));
  const crossDeviceWarning = await crossDeviceMoveWarning(sourcePath, targetPath);
  const warnings = [
    "Soft delete moves to SpiritFlix trash, not permanent delete.",
    "No hard delete is performed.",
    ...(crossDeviceWarning ? [crossDeviceWarning] : []),
  ];
  const receipt = buildPlannedReceipt("softDelete", [sourcePath, targetPath], {
    sourcePath,
    targetPath,
    rollbackHint: "Restore from trash to the original path.",
    previewId,
  });
  previewStore.set(previewId, { action: "softDelete", payload: request, receipt });
  return response("softDelete", "preview", previewId, true, "Move item to soft trash", {
    receipt,
    preview: {
      sourcePath,
      targetPath,
      affectedPaths: [sourcePath, targetPath],
      warnings,
      reversible: true,
    },
  });
}

async function previewRestore(request: SpiritFlixAdminActionRequest, previewId: string) {
  const trashPath = await assertAllowedPath(request.sourcePath ?? "");
  const targetPath = request.targetPath
    ? await validateSpiritFlixAdminPathCandidate(request.targetPath)
    : await validateSpiritFlixAdminPathCandidate(restoreTargetFromTrash(trashPath));
  await fs.access(targetPath).then(() => {
    throw new Error("Restore target already exists.");
  }).catch((error: NodeJS.ErrnoException) => {
    if (error.code !== "ENOENT") throw error;
  });

  const receipt = buildPlannedReceipt("restore", [trashPath, targetPath], {
    sourcePath: trashPath,
    targetPath,
    rollbackHint: "Soft-delete again if needed.",
    previewId,
  });
  previewStore.set(previewId, { action: "restore", payload: request, receipt });
  return response("restore", "preview", previewId, true, "Restore item from trash", {
    receipt,
    preview: {
      sourcePath: trashPath,
      targetPath,
      affectedPaths: [trashPath, targetPath],
      warnings: [],
      reversible: true,
    },
  });
}

async function previewWriteMetadata(request: SpiritFlixAdminActionRequest, previewId: string) {
  const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
  validateMetadata(request.metadata ?? {});
  const hash = createHash("sha256").update(sourcePath.replace(/\\/g, "/").toLowerCase()).digest("hex");
  const targetPath = path.join(METADATA_ROOT, `${hash}.json`);
  const receipt = buildPlannedReceipt("writeMetadata", [targetPath], {
    sourcePath,
    targetPath,
    rollbackHint: "Edit or delete the metadata sidecar.",
    previewId,
  });
  previewStore.set(previewId, { action: "writeMetadata", payload: request, receipt });
  return response("writeMetadata", "preview", previewId, true, "Write SpiritFlix metadata sidecar", {
    receipt,
    preview: {
      sourcePath,
      targetPath,
      affectedPaths: [targetPath],
      warnings: ["Does not edit Jellyfin database rows.", "Metadata is stored under .spiritflix-admin/metadata only."],
      reversible: true,
    },
  });
}

async function previewSaveOrder(request: SpiritFlixAdminActionRequest, previewId: string) {
  const order = request.order;
  if (!order || order.version !== 1 || !Array.isArray(order.groups)) throw new Error("Invalid custom order payload.");
  const serialized = JSON.stringify(order);
  if (serialized.length > MAX_ORDER_BYTES) throw new Error("Custom order payload is too large.");
  for (const group of order.groups) {
    for (const key of group.itemKeys) {
      if (!validateOrderItemKey(key)) {
        throw new Error(`Invalid order item key: ${key}`);
      }
    }
  }
  const receipt = buildPlannedReceipt("saveOrder", [ORDER_FILE], {
    targetPath: ORDER_FILE,
    rollbackHint: "Restore the previous order.json backup.",
    previewId,
  });
  previewStore.set(previewId, { action: "saveOrder", payload: request, receipt });
  return response("saveOrder", "preview", previewId, true, "Save custom shelf order", {
    receipt,
    preview: { targetPath: ORDER_FILE, affectedPaths: [ORDER_FILE], warnings: [], reversible: true },
  });
}

async function previewRescan(request: SpiritFlixAdminActionRequest, previewId: string) {
  const targetPath = await assertAllowedPath(request.rescanPath ?? SPIRITFLIX_MEDIA_ROOT);
  const credentials = getServerJellyfinCredentials();
  if (!credentials) {
    return response(
      "requestJellyfinRescan",
      "preview",
      previewId,
      false,
      "Rescan action is not active yet because safe Jellyfin admin auth is unavailable.",
      {
        riskLevel: "high",
        preview: {
          targetPath,
          affectedPaths: [targetPath],
          warnings: ["Preview only â€” rescan execution is gated until server credentials are configured."],
          reversible: false,
        },
      },
    );
  }

  const receipt = buildPlannedReceipt("requestJellyfinRescan", [targetPath], {
    targetPath,
    reversible: false,
    rollbackHint: "Rescan is not reversible.",
    previewId,
  });
  previewStore.set(previewId, { action: "requestJellyfinRescan", payload: request, receipt });
  return response("requestJellyfinRescan", "preview", previewId, true, `Request Jellyfin rescan for ${targetPath}`, {
    receipt,
    preview: {
      targetPath,
      affectedPaths: [targetPath],
      warnings: ["Does not restart Jellyfin."],
      reversible: false,
    },
  });
}

async function executeAction(
  action: SpiritFlixAdminActionName,
  request: SpiritFlixAdminActionRequest,
  previewId: string,
  planned: SpiritFlixAdminReceipt,
): Promise<SpiritFlixAdminActionResponse> {
  try {
    switch (action) {
      case "createFolder": {
        const parentPath = await assertParentExists(request.targetPath ?? SPIRITFLIX_MEDIA_ROOT);
        const folderName = sanitizeName(request.folderName ?? "");
        const targetPath = path.join(parentPath, folderName);
        await fs.mkdir(targetPath, { recursive: false });
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          targetPath,
          affectedPaths: [targetPath],
          previewId,
        });
        return response(action, "execute", previewId, true, "Folder created.", {
          receipt,
          preview: { targetPath, affectedPaths: [targetPath], warnings: [] },
        });
      }
      case "rename": {
        const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
        assertWritableSpiritFlixAdminPath(sourcePath, "rename");
        const targetPath = path.join(path.dirname(sourcePath), resolveRenameTarget(sourcePath, request.newName ?? ""));
        await moveSpiritFlixAdminPath(sourcePath, targetPath);
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          sourcePath,
          targetPath,
          affectedPaths: [sourcePath, targetPath],
          previewId,
        });
        return response(action, "execute", previewId, true, "Rename complete.", {
          receipt,
          preview: { sourcePath, targetPath, affectedPaths: [sourcePath, targetPath], warnings: [] },
        });
      }
      case "move": {
        const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
        assertWritableSpiritFlixAdminPath(sourcePath, "move");
        const targetParent = await assertParentExists(request.targetPath ?? request.parentPath ?? "");
        const targetPath = path.join(targetParent, path.basename(sourcePath));
        await moveSpiritFlixAdminPath(sourcePath, targetPath);
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          sourcePath,
          targetPath,
          affectedPaths: [sourcePath, targetPath],
          previewId,
        });
        return response(action, "execute", previewId, true, "Move complete.", {
          receipt,
          preview: { sourcePath, targetPath, affectedPaths: [sourcePath, targetPath], warnings: [] },
        });
      }
      case "softDelete": {
        const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
        assertWritableSpiritFlixAdminPath(sourcePath, "soft delete");
        const relative = path.relative(SPIRITFLIX_MEDIA_ROOT, sourcePath);
        const trashDay = new Date().toISOString().slice(0, 10).replace(/-/g, "");
        const targetPath = await uniqueTrashPath(path.join(TRASH_ROOT, trashDay, relative));
        await fs.mkdir(path.dirname(targetPath), { recursive: true });
        await moveSpiritFlixAdminPath(sourcePath, targetPath);
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          sourcePath,
          targetPath,
          affectedPaths: [sourcePath, targetPath],
          previewId,
        });
        return response(action, "execute", previewId, true, "Moved to trash.", {
          receipt,
          preview: { sourcePath, targetPath, affectedPaths: [sourcePath, targetPath], warnings: [] },
        });
      }
      case "restore": {
        const trashPath = await assertAllowedPath(request.sourcePath ?? "");
        const targetPath = request.targetPath
          ? await validateSpiritFlixAdminPathCandidate(request.targetPath)
          : await validateSpiritFlixAdminPathCandidate(restoreTargetFromTrash(trashPath));
        await fs.access(targetPath).then(() => {
          throw new Error("Restore target already exists.");
        }).catch((error: NodeJS.ErrnoException) => {
          if (error.code !== "ENOENT") throw error;
        });
        await fs.mkdir(path.dirname(targetPath), { recursive: true });
        await moveSpiritFlixAdminPath(trashPath, targetPath);
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          sourcePath: trashPath,
          targetPath,
          affectedPaths: [trashPath, targetPath],
          previewId,
        });
        return response(action, "execute", previewId, true, "Restore complete.", {
          receipt,
          preview: { sourcePath: trashPath, targetPath, affectedPaths: [trashPath, targetPath], warnings: [] },
        });
      }
      case "writeMetadata": {
        const sourcePath = await assertAllowedPath(request.sourcePath ?? "");
        const metadata = validateMetadata(request.metadata ?? {});
        const hash = createHash("sha256").update(sourcePath.replace(/\\/g, "/").toLowerCase()).digest("hex");
        const targetPath = path.join(METADATA_ROOT, `${hash}.json`);
        await fs.mkdir(METADATA_ROOT, { recursive: true });
        await atomicWriteFile(targetPath, JSON.stringify({ sourcePath, ...metadata }, null, 2));
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          sourcePath,
          targetPath,
          affectedPaths: [targetPath],
          previewId,
        });
        return response(action, "execute", previewId, true, "Metadata saved.", {
          receipt,
          preview: { sourcePath, targetPath, affectedPaths: [targetPath], warnings: [] },
        });
      }
      case "saveOrder": {
        await fs.mkdir(path.dirname(ORDER_FILE), { recursive: true });
        const order: SpiritFlixAdminOrderFile = {
          ...(request.order as SpiritFlixAdminOrderFile),
          version: 1,
          updatedAt: new Date().toISOString(),
        };
        await atomicWriteFile(ORDER_FILE, JSON.stringify(order, null, 2));
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          targetPath: ORDER_FILE,
          affectedPaths: [ORDER_FILE],
          previewId,
        });
        return response(action, "execute", previewId, true, "Custom order saved.", {
          receipt,
          preview: { targetPath: ORDER_FILE, affectedPaths: [ORDER_FILE], warnings: [] },
        });
      }
      case "requestJellyfinRescan": {
        const credentials = getServerJellyfinCredentials();
        if (!credentials) {
          throw new Error("Rescan action is not active yet because safe Jellyfin admin auth is unavailable.");
        }
        const targetPath = await assertAllowedPath(request.rescanPath ?? SPIRITFLIX_MEDIA_ROOT);
        await fetch(`${credentials.serverUrl}/Library/Refresh`, {
          method: "POST",
          headers: { "X-Emby-Token": credentials.accessToken },
        });
        const receipt = await writeSpiritFlixAdminReceipt({
          ...planned,
          status: "executed",
          targetPath,
          affectedPaths: [targetPath],
          reversible: false,
          previewId,
        });
        return response(action, "execute", previewId, true, "Jellyfin rescan requested.", {
          receipt,
          preview: { targetPath, affectedPaths: [targetPath], warnings: [] },
        });
      }
      default:
        return response(action, "execute", previewId, false, "Unknown action.");
    }
  } catch (error) {
    const receipt = await writeSpiritFlixAdminReceipt({
      ...planned,
      id: randomUUID(),
      status: "failed",
      reason: error instanceof Error ? error.message : "Action failed.",
      affectedPaths: planned.affectedPaths,
      previewId,
    });
    return response(action, "execute", previewId, false, receipt.reason ?? "Action failed.", { receipt });
  }
}

export function getSmokeRoot(): string {
  return SMOKE_ROOT;
}

export function validateOrderItemKey(key: string): boolean {
  return /^jellyfin:[^:]+$/.test(key) || /^path:[a-f0-9]{64}$/.test(key);
}

export function buildPathItemKey(filePath: string): string {
  return stableItemKey(filePath);
}

export function clearSpiritFlixAdminPreviewStore(): void {
  previewStore.clear();
}

export const SPIRITFLIX_DATA_ROOT = "/mnt/spirit-8tb";
export const SPIRITFLIX_MEDIA_ROOT = "/mnt/spirit-8tb/media";
export const SPIRITFLIX_MEDIA_INBOX = "/mnt/spirit-8tb/media-inbox";
export const SPIRITFLIX_ADMIN_THUMBNAIL_CACHE_ROOT = "/mnt/spirit-8tb/media/.spiritflix-admin/thumbnails";

/** Level 1R4 passed â€” Level 2 guarded CRUD is active. */
export const SPIRITFLIX_ADMIN_LEVEL2_GATED = false;
export const SPIRITFLIX_ADMIN_LEVEL2_GATE_MESSAGE = "Level 2 management is gated until file view passes.";

export interface SpiritFlixAdminNavEntry {
  path: string;
  label: string;
}

/** Sidebar quick-nav: media root first, then library folders. */
export const SPIRITFLIX_ADMIN_NAV: SpiritFlixAdminNavEntry[] = [
  { path: SPIRITFLIX_MEDIA_ROOT, label: "media" },
  { path: `${SPIRITFLIX_MEDIA_ROOT}/yes`, label: "yes" },
  { path: `${SPIRITFLIX_MEDIA_ROOT}/anime`, label: "anime" },
  { path: `${SPIRITFLIX_MEDIA_ROOT}/movies`, label: "movies" },
  { path: `${SPIRITFLIX_MEDIA_ROOT}/tv`, label: "tv" },
  { path: `${SPIRITFLIX_MEDIA_ROOT}/music`, label: "music" },
  { path: `${SPIRITFLIX_MEDIA_ROOT}/other`, label: "other" },
  { path: SPIRITFLIX_MEDIA_INBOX, label: "media-inbox" },
];

export function activeAdminNavPath(currentPath: string, entries: SpiritFlixAdminNavEntry[] = SPIRITFLIX_ADMIN_NAV): string {
  const normalized = currentPath.replace(/\\/g, "/").replace(/\/+$/, "");
  const sorted = [...entries].sort((left, right) => right.path.length - left.path.length);
  return sorted.find((entry) => normalized === entry.path || normalized.startsWith(`${entry.path}/`))?.path ?? "";
}

import type { SpiritFlixAdminItem } from "./types";

function formatDate(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "" : date.toLocaleDateString(undefined, { month: "short", day: "numeric", year: "numeric" });
}

export function formatItemDateLabel(item: SpiritFlixAdminItem): { label: string; text: string } {
  if (item.dateAdded && (item.jellyfinId || item.jellyfinItemId)) {
    return { label: "Added", text: formatDate(item.dateAdded) };
  }

  if (item.dateCreated && item.dateModified && item.dateCreated !== item.dateModified) {
    return { label: "Created", text: formatDate(item.dateCreated) };
  }

  if (item.dateModified) {
    return { label: "Modified", text: formatDate(item.dateModified) };
  }

  if (item.dateAdded) {
    return { label: "Added", text: formatDate(item.dateAdded) };
  }

  if (item.dateCreated) {
    return { label: "Created", text: formatDate(item.dateCreated) };
  }

  return { label: "", text: "" };
}

export function formatBytes(value?: number): string {
  if (!value) return "";
  const units = ["B", "KB", "MB", "GB", "TB"];
  let size = value;
  let unit = 0;
  while (size >= 1024 && unit < units.length - 1) {
    size /= 1024;
    unit += 1;
  }
  return `${size.toFixed(size >= 10 || unit === 0 ? 0 : 1)} ${units[unit]}`;
}

export function isMetadataSidecar(name: string): boolean {
  if (name.startsWith(".")) return true;
  const lower = name.toLowerCase();
  return lower.endsWith(".media-ingest.json") || lower.endsWith(".face-meta.json") || lower.endsWith(".json");
}

import fs from "node:fs/promises";
import path from "node:path";
import type { SpiritFlixAdminFsResponse, SpiritFlixAdminItem, SpiritFlixAdminSortBy, SpiritFlixAdminSortOrder } from "./types";
import { resolveSpiritFlixAdminPath } from "./paths";

const MEDIA_EXTENSIONS = new Set([".avi", ".m4v", ".mkv", ".mov", ".mp4", ".mpeg", ".mpg", ".webm", ".wmv"]);

function compareValue(left: string | number | boolean | undefined, right: string | number | boolean | undefined): number {
  if (typeof left === "number" || typeof right === "number") return (left ?? 0) < (right ?? 0) ? -1 : (left ?? 0) > (right ?? 0) ? 1 : 0;
  if (typeof left === "boolean" || typeof right === "boolean") return Number(left ?? false) - Number(right ?? false);
  return String(left ?? "").localeCompare(String(right ?? ""), undefined, { numeric: true, sensitivity: "base" });
}

function itemSortValue(item: SpiritFlixAdminItem, sortBy: SpiritFlixAdminSortBy): string | number | boolean | undefined {
  if (sortBy === "dateModified") return item.dateModified;
  if (sortBy === "dateAdded") return item.dateAdded ?? item.dateCreated;
  if (sortBy === "runtime") return item.runtimeTicks;
  if (sortBy === "size") return item.sizeBytes;
  if (sortBy === "path") return item.path;
  if (sortBy === "library") return item.libraryName;
  if (sortBy === "watched") return item.watched;
  if (sortBy === "favorite") return item.favorite;
  return item.name;
}

function sortItems(items: SpiritFlixAdminItem[], sortBy: SpiritFlixAdminSortBy, sortOrder: SpiritFlixAdminSortOrder): SpiritFlixAdminItem[] {
  const direction = sortOrder === "desc" ? -1 : 1;
  return [...items].sort((left, right) => {
    if (left.type !== right.type) return left.type === "folder" ? -1 : 1;
    return compareValue(itemSortValue(left, sortBy), itemSortValue(right, sortBy)) * direction || left.name.localeCompare(right.name);
  });
}

function breadcrumbs(root: string, currentPath: string): Array<{ name: string; path: string }> {
  const parts = path.relative(root, currentPath).split(path.sep).filter(Boolean);
  const rootName = path.basename(root) || root;
  return [
    { name: rootName, path: root },
    ...parts.map((name, index) => ({
      name,
      path: path.join(root, ...parts.slice(0, index + 1)),
    })),
  ];
}

export async function listSpiritFlixAdminDirectory(options: {
  path?: string;
  searchTerm?: string;
  sortBy?: SpiritFlixAdminSortBy;
  sortOrder?: SpiritFlixAdminSortOrder;
  limit?: number;
  startIndex?: number;
}): Promise<SpiritFlixAdminFsResponse> {
  const resolved = await resolveSpiritFlixAdminPath(options.path);
  const stats = await fs.stat(resolved.realPath);

  if (!stats.isDirectory()) {
    throw new Error("SpiritFlix admin filesystem listing requires a folder path.");
  }

  const entries = await fs.readdir(resolved.realPath, { withFileTypes: true });
  const search = options.searchTerm?.trim().toLowerCase() ?? "";
  const items: SpiritFlixAdminItem[] = [];

  for (const entry of entries) {
    if (!entry.isDirectory() && !entry.isFile()) continue;
    if (entry.name.startsWith(".")) continue;
    if (search && !entry.name.toLowerCase().includes(search)) continue;

    const itemPath = path.join(resolved.realPath, entry.name);
    const itemStat = await fs.stat(itemPath);
    const extension = entry.isFile() ? path.extname(entry.name).toLowerCase() : undefined;

    items.push({
      id: `${entry.isDirectory() ? "folder" : "file"}:${itemPath}`,
      name: entry.name,
      type: entry.isDirectory() ? "folder" : "file",
      path: itemPath,
      parentPath: resolved.realPath,
      extension,
      sizeBytes: entry.isFile() ? itemStat.size : undefined,
      dateCreated: itemStat.birthtime.toISOString(),
      dateModified: itemStat.mtime.toISOString(),
      playable: Boolean(extension && MEDIA_EXTENSIONS.has(extension)),
    });
  }

  const sorted = sortItems(items, options.sortBy ?? "title", options.sortOrder ?? "asc");
  const startIndex = Math.max(0, options.startIndex ?? 0);
  const limit = Math.max(1, Math.min(500, options.limit ?? 200));
  const page = sorted.slice(startIndex, startIndex + limit);
  const parentPath = resolved.realPath === resolved.allowedRoot ? undefined : path.dirname(resolved.realPath);

  return {
    schema: "spiritflix-admin-fs/v1",
    generatedAt: new Date().toISOString(),
    root: resolved.allowedRoot,
    currentPath: resolved.realPath,
    parentPath,
    breadcrumbs: breadcrumbs(resolved.allowedRoot, resolved.realPath),
    items: page,
    totalRecordCount: sorted.length,
  };
}

import { normalizeJellyfinServerUrl } from "@/lib/spiritflix-jellyfin-client";
import type { JellyfinItem, JellyfinLibrary } from "@/lib/spiritflix-types";
import type {
  JellyfinAdminItemsResponse,
  SpiritFlixAdminItem,
  SpiritFlixAdminLibraryRequest,
  SpiritFlixAdminLibraryResponse,
  SpiritFlixAdminSortBy,
  SpiritFlixAdminSortOrder,
} from "./types";

const CLIENT_NAME = "SpiritFlix Admin";
const CLIENT_VERSION = "0.1.0";
const DEVICE_NAME = "SpiritFlix Admin API";
const DEVICE_ID = "spiritflix-admin-api";
const DEFAULT_INCLUDE_ITEM_TYPES = "Movie,Series,Season,Episode,Video,Folder";
const ITEM_FIELDS =
  "Path,SeriesName,DateCreated,DateLastMediaAdded,DateLastSaved,IndexNumber,ParentIndexNumber,Overview,ProductionYear,RunTimeTicks,Genres,People,UserData,PrimaryImageAspectRatio,MediaSources,ChildCount";

const allowedHosts = new Set([
  "spirit.tailb69ea6.ts.net:8096",
  "100.111.32.31:8096",
  "127.0.0.1:8096",
  "localhost:8096",
]);

const sortMap: Record<SpiritFlixAdminSortBy, string> = {
  dateAdded: "DateCreated",
  dateModified: "DateLastSaved",
  title: "SortName",
  runtime: "Runtime",
  size: "Size",
  path: "Path",
  library: "SortName",
  watched: "PlayCount",
  favorite: "SortName",
};

function isAllowedServer(serverUrl: string): boolean {
  try {
    const parsed = new URL(serverUrl);
    return (parsed.protocol === "http:" || parsed.protocol === "https:") && allowedHosts.has(parsed.host);
  } catch {
    return false;
  }
}

function authHeader(token: string): string {
  return [
    `MediaBrowser Client="${CLIENT_NAME}"`,
    `Device="${DEVICE_NAME}"`,
    `DeviceId="${DEVICE_ID}"`,
    `Version="${CLIENT_VERSION}"`,
    `Token="${token}"`,
  ].join(", ");
}

function queryString(params: Record<string, string | number | boolean | undefined>): string {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined && value !== "") query.set(key, String(value));
  });
  return query.toString();
}

async function jellyfinRequest<T>(serverUrl: string, token: string, path: string): Promise<T> {
  const response = await fetch(`${serverUrl}${path}`, {
    method: "GET",
    headers: {
      Accept: "application/json",
      "X-Emby-Authorization": authHeader(token),
    },
    cache: "no-store",
  });

  if (!response.ok) {
    throw new Error(`Jellyfin admin request failed with status ${response.status}.`);
  }

  return (await response.json()) as T;
}

function parentPathFor(item: JellyfinItem): string | undefined {
  const sourcePath = item.Path ?? item.MediaSources?.find((source) => source.Path)?.Path;
  if (!sourcePath) return undefined;
  const slash = Math.max(sourcePath.lastIndexOf("/"), sourcePath.lastIndexOf("\\"));
  return slash > 0 ? sourcePath.slice(0, slash) : undefined;
}

function extensionFor(item: JellyfinItem): string | undefined {
  const sourcePath = item.Path ?? item.MediaSources?.find((source) => source.Path)?.Path;
  const match = sourcePath?.match(/(\.[a-z0-9]+)$/i);
  return match?.[1]?.toLowerCase();
}

export function normalizeJellyfinAdminItem(item: JellyfinItem, libraries: JellyfinLibrary[]): SpiritFlixAdminItem {
  const library = libraries.find((candidate) => candidate.Id === item.Id) ?? libraries.find((candidate) => item.Path?.toLowerCase().includes(candidate.Name.toLowerCase()));
  const mediaSource = item.MediaSources?.find((source) => source.Path || source.Size || source.RunTimeTicks);
  const path = mediaSource?.Path ?? item.Path;
  const people = item.People?.filter((person) => ["actor", "actress", "artist", "performer"].includes(person.Type?.toLowerCase() ?? ""));

  return {
    id: `jellyfin:${item.Id}`,
    name: item.Name,
    type: "jellyfin-item",
    libraryName: library?.Name,
    jellyfinId: item.Id,
    jellyfinItemId: item.Id,
    jellyfinItem: item,
    path,
    parentPath: parentPathFor(item),
    jellyfinPath: item.Path,
    mediaType: item.MediaType,
    itemType: item.Type,
    extension: extensionFor(item),
    sizeBytes: mediaSource?.Size,
    dateCreated: item.DateCreated,
    dateModified: undefined,
    dateAdded: item.DateCreated,
    runtimeTicks: item.RunTimeTicks ?? mediaSource?.RunTimeTicks,
    watched: Boolean(item.UserData?.Played),
    favorite: Boolean(item.UserData?.IsFavorite),
    hasImage: Boolean(item.ImageTags?.Primary || item.ImageTags?.Thumb || item.BackdropImageTags?.length),
    imageType: item.ImageTags?.Primary ? "Primary" : item.ImageTags?.Thumb ? "Thumb" : item.BackdropImageTags?.length ? "Backdrop" : undefined,
    imageStatus: item.ImageTags?.Primary || item.ImageTags?.Thumb || item.BackdropImageTags?.length ? "available" : "missing",
    jellyfinMatchedBy: "exact-path",
    jellyfinMatchCandidateCount: 1,
    playable: item.MediaType === "Video" || ["Movie", "Episode", "Video"].includes(item.Type),
    resumePositionTicks: item.UserData?.PlaybackPositionTicks,
    modelNames: people?.map((person) => person.Name).filter(Boolean),
  };
}

export async function listJellyfinAdminItems(request: SpiritFlixAdminLibraryRequest): Promise<SpiritFlixAdminLibraryResponse> {
  const serverUrl = normalizeJellyfinServerUrl(request.serverUrl ?? "");
  const accessToken = request.accessToken ?? "";
  const userId = request.userId ?? "";

  if (!serverUrl || !accessToken || !userId) {
    throw new Error("SpiritFlix admin library requires a Jellyfin session.");
  }

  if (!isAllowedServer(serverUrl)) {
    throw new Error("That Jellyfin server is not allowed for SpiritFlix admin.");
  }

  const sortBy = request.sortBy ?? "dateAdded";
  const sortOrder = request.sortOrder ?? "desc";
  const limit = Math.max(1, Math.min(500, request.limit ?? 100));
  const startIndex = Math.max(0, request.startIndex ?? 0);
  const includeItemTypes = request.includeItemTypes || DEFAULT_INCLUDE_ITEM_TYPES;
  const libraries = (await jellyfinRequest<JellyfinAdminItemsResponse & { Items?: JellyfinLibrary[] }>(serverUrl, accessToken, `/Users/${userId}/Views`)).Items ?? [];
  const selectedLibraryId = request.libraryId ?? "";
  const parentId = request.parentId || selectedLibraryId;
  const query = queryString({
    ParentId: parentId,
    Recursive: request.recursive ?? true,
    IncludeItemTypes: includeItemTypes,
    Fields: ITEM_FIELDS,
    ImageTypeLimit: 1,
    EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
    SortBy: sortMap[sortBy] ?? "DateCreated",
    SortOrder: sortOrder === "asc" ? "Ascending" : "Descending",
    SearchTerm: request.searchTerm,
    Limit: limit,
    StartIndex: startIndex,
  });
  const items = await jellyfinRequest<JellyfinAdminItemsResponse>(serverUrl, accessToken, `/Users/${userId}/Items?${query}`);

  return {
    schema: "spiritflix-admin-library/v1",
    generatedAt: new Date().toISOString(),
    libraries,
    items: (items.Items ?? []).map((item) => normalizeJellyfinAdminItem(item, libraries)),
    totalRecordCount: items.TotalRecordCount ?? items.Items?.length ?? 0,
    query: {
      searchTerm: request.searchTerm ?? "",
      libraryId: selectedLibraryId,
      parentId,
      recursive: request.recursive ?? true,
      sortBy,
      sortOrder,
      limit,
      startIndex,
      includeItemTypes,
    },
  };
}

import type { JellyfinItem } from "@/lib/spiritflix-types";
import type { SpiritFlixAdminImageStatus, SpiritFlixAdminImageType, SpiritFlixAdminMatchMethod } from "./types";
import { adminPathsEquivalent, expandSpiritFlixPathAliases, normalizeAdminPath } from "./path-aliases";

export interface SpiritFlixAdminJellyfinMatch {
  item?: JellyfinItem;
  itemId?: string;
  imageType?: SpiritFlixAdminImageType;
  imageStatus: SpiritFlixAdminImageStatus;
  matchedBy: SpiritFlixAdminMatchMethod;
  candidateCount: number;
}

function basename(value?: string): string {
  const normalized = normalizeAdminPath(value);
  return normalized ? (normalized.split("/").filter(Boolean).at(-1) ?? "") : "";
}

function dirname(value?: string): string {
  const normalized = normalizeAdminPath(value);
  const parts = normalized.split("/").filter(Boolean);
  if (parts.length <= 1) return "";
  return `${normalized.startsWith("/") ? "/" : ""}${parts.slice(0, -1).join("/")}`;
}

function itemPaths(item: JellyfinItem): string[] {
  const paths = [item.Path, ...(item.MediaSources ?? []).map((source) => source.Path)].filter(Boolean) as string[];
  return [...new Set(paths.map(normalizeAdminPath).filter(Boolean))];
}

function itemNames(item: JellyfinItem): string[] {
  return [...new Set([item.Name, ...itemPaths(item).map((itemPath) => basename(itemPath))].map((name) => name?.toLowerCase()).filter(Boolean) as string[])];
}

function foldersEquivalent(left?: string, right?: string): boolean {
  const leftAliases = expandSpiritFlixPathAliases(left);
  const rightAliases = expandSpiritFlixPathAliases(right);
  return leftAliases.some((alias) => rightAliases.includes(alias));
}

export function preferredAdminImageType(item?: JellyfinItem): SpiritFlixAdminImageType | undefined {
  if (!item) return undefined;
  if (item.ImageTags?.Primary) return "Primary";
  if (item.ImageTags?.Thumb) return "Thumb";
  if (item.BackdropImageTags?.length) return "Backdrop";
  return undefined;
}

function matchResult(item: JellyfinItem, matchedBy: SpiritFlixAdminMatchMethod, candidateCount: number): SpiritFlixAdminJellyfinMatch {
  const imageType = preferredAdminImageType(item);
  return {
    item,
    itemId: item.Id,
    imageType,
    imageStatus: imageType ? "available" : "missing",
    matchedBy,
    candidateCount,
  };
}

function uniqueById(items: JellyfinItem[]): JellyfinItem[] {
  const byId = new Map<string, JellyfinItem>();
  for (const item of items) {
    byId.set(item.Id, item);
  }
  return [...byId.values()];
}

export function matchJellyfinItemForAdminFile(filePath: string | undefined, jellyfinItems: JellyfinItem[]): SpiritFlixAdminJellyfinMatch {
  const normalizedFilePath = normalizeAdminPath(filePath);
  if (!normalizedFilePath) {
    return { imageStatus: "missing", matchedBy: "none", candidateCount: 0 };
  }

  const fileName = basename(normalizedFilePath);
  const fileFolder = dirname(normalizedFilePath);

  const exactMatches = uniqueById(
    jellyfinItems.filter((item) => itemPaths(item).some((itemPath) => adminPathsEquivalent(itemPath, normalizedFilePath))),
  );
  if (exactMatches.length === 1) return matchResult(exactMatches[0], "exact-path", exactMatches.length);
  if (exactMatches.length > 1) return { imageStatus: "ambiguous", matchedBy: "ambiguous", candidateCount: exactMatches.length };

  const sameFolderMatches = uniqueById(
    jellyfinItems.filter((item) =>
      itemPaths(item).some((itemPath) => basename(itemPath) === fileName && foldersEquivalent(dirname(itemPath), fileFolder)),
    ),
  );
  if (sameFolderMatches.length === 1) return matchResult(sameFolderMatches[0], "same-folder-basename", sameFolderMatches.length);
  if (sameFolderMatches.length > 1) return { imageStatus: "ambiguous", matchedBy: "ambiguous", candidateCount: sameFolderMatches.length };

  const filenameMatches = uniqueById(
    jellyfinItems.filter((item) => {
      const paths = itemPaths(item);
      const hasPathInCurrentFolder = paths.some(
        (itemPath) => foldersEquivalent(dirname(itemPath), fileFolder) && basename(itemPath) === fileName,
      );
      if (hasPathInCurrentFolder) return true;
      if (paths.length > 0) return false;
      return itemNames(item).includes(fileName);
    }),
  );
  if (filenameMatches.length === 1) return matchResult(filenameMatches[0], "filename", filenameMatches.length);
  if (filenameMatches.length > 1) return { imageStatus: "ambiguous", matchedBy: "ambiguous", candidateCount: filenameMatches.length };

  return { imageStatus: "missing", matchedBy: "none", candidateCount: 0 };
}

import { normalizeJellyfinServerUrl } from "@/lib/spiritflix-jellyfin-client";
import type { JellyfinItem } from "@/lib/spiritflix-types";

const DEFAULT_SERVER = "http://127.0.0.1:8096";

const allowedHosts = new Set([
  "spirit.tailb69ea6.ts.net:8096",
  "100.111.32.31:8096",
  "127.0.0.1:8096",
  "localhost:8096",
]);

export interface SpiritFlixServerJellyfinCredentials {
  serverUrl: string;
  accessToken: string;
  userId: string;
}

function isAllowedServer(serverUrl: string): boolean {
  try {
    const parsed = new URL(serverUrl);
    return (parsed.protocol === "http:" || parsed.protocol === "https:") && allowedHosts.has(parsed.host);
  } catch {
    return false;
  }
}

export function getServerJellyfinCredentials(): SpiritFlixServerJellyfinCredentials | null {
  const accessToken = process.env.JELLYFIN_API_KEY?.trim();
  const serverUrl = normalizeJellyfinServerUrl(process.env.JELLYFIN_URL?.trim() || DEFAULT_SERVER);
  const userId = process.env.JELLYFIN_USER_ID?.trim();

  if (!accessToken || !isAllowedServer(serverUrl)) return null;

  return { serverUrl, accessToken, userId: userId || "" };
}

async function jellyfinRequest<T>(credentials: SpiritFlixServerJellyfinCredentials, path: string): Promise<T> {
  const response = await fetch(`${credentials.serverUrl}${path}`, {
    method: "GET",
    headers: {
      Accept: "application/json",
      "X-Emby-Token": credentials.accessToken,
    },
    cache: "no-store",
  });

  if (!response.ok) {
    throw new Error(`Jellyfin server request failed with status ${response.status}.`);
  }

  return (await response.json()) as T;
}

export async function resolveServerJellyfinUserId(credentials: SpiritFlixServerJellyfinCredentials): Promise<string> {
  if (credentials.userId) return credentials.userId;
  const users = await jellyfinRequest<Array<{ Id: string }>>(credentials, "/Users");
  const userId = users[0]?.Id;
  if (!userId) throw new Error("No Jellyfin users available for SpiritFlix admin.");
  return userId;
}

export async function listServerJellyfinVideoItems(credentials: SpiritFlixServerJellyfinCredentials, userId: string): Promise<JellyfinItem[]> {
  const query = new URLSearchParams({
    Recursive: "true",
    IncludeItemTypes: "Movie,Episode,Video",
    Fields: "Path,MediaSources,ImageTags,BackdropImageTags,DateCreated",
    ImageTypeLimit: "1",
    EnableImageTypes: "Primary,Backdrop,Thumb",
    Limit: "500",
  });

  const payload = await jellyfinRequest<{ Items?: JellyfinItem[] }>(credentials, `/Users/${userId}/Items?${query}`);
  return payload.Items ?? [];
}

export function jellyfinImagePath(
  itemId: string,
  imageType: "Primary" | "Thumb" | "Backdrop",
  tag: string | undefined,
  width = 360,
): string {
  const query = new URLSearchParams({
    maxWidth: String(width),
    quality: "88",
    ...(tag ? { tag } : {}),
  });
  return `/Items/${itemId}/Images/${imageType}?${query}`;
}

const HOST_MEDIA_PREFIX = "/mnt/spirit-8tb/media";
const CONTAINER_MEDIA_PREFIX = "/media";
const HOST_INBOX_PREFIX = "/mnt/spirit-8tb/media-inbox";
const CONTAINER_INBOX_PREFIX = "/media-inbox";

export function normalizeAdminPath(value?: string): string {
  return (value ?? "")
    .trim()
    .replace(/\\/g, "/")
    .replace(/\/+/g, "/")
    .replace(/\/$/, "")
    .toLowerCase();
}

/** Host/container alias expansion for Jellyfin path matching. */
export function expandSpiritFlixPathAliases(value?: string): string[] {
  const normalized = normalizeAdminPath(value);
  if (!normalized) return [];

  const aliases = new Set<string>([normalized]);

  if (normalized === HOST_MEDIA_PREFIX || normalized.startsWith(`${HOST_MEDIA_PREFIX}/`)) {
    aliases.add(CONTAINER_MEDIA_PREFIX + normalized.slice(HOST_MEDIA_PREFIX.length));
  } else if (normalized === CONTAINER_MEDIA_PREFIX || normalized.startsWith(`${CONTAINER_MEDIA_PREFIX}/`)) {
    aliases.add(HOST_MEDIA_PREFIX + normalized.slice(CONTAINER_MEDIA_PREFIX.length));
  }

  if (normalized === HOST_INBOX_PREFIX || normalized.startsWith(`${HOST_INBOX_PREFIX}/`)) {
    aliases.add(CONTAINER_INBOX_PREFIX + normalized.slice(HOST_INBOX_PREFIX.length));
  } else if (normalized === CONTAINER_INBOX_PREFIX || normalized.startsWith(`${CONTAINER_INBOX_PREFIX}/`)) {
    aliases.add(HOST_INBOX_PREFIX + normalized.slice(CONTAINER_INBOX_PREFIX.length));
  }

  return [...aliases];
}

export function adminPathsEquivalent(left?: string, right?: string): boolean {
  const leftAliases = expandSpiritFlixPathAliases(left);
  const rightAliases = expandSpiritFlixPathAliases(right);
  return leftAliases.some((alias) => rightAliases.includes(alias));
}

import { SPIRITFLIX_MEDIA_ROOT } from "./constants";

/** Top-level library folders and media root â€” never rename/move/soft-delete these. */
export const SPIRITFLIX_ADMIN_PROTECTED_PATHS = [
  SPIRITFLIX_MEDIA_ROOT,
  `${SPIRITFLIX_MEDIA_ROOT}/yes`,
  `${SPIRITFLIX_MEDIA_ROOT}/anime`,
  `${SPIRITFLIX_MEDIA_ROOT}/movies`,
  `${SPIRITFLIX_MEDIA_ROOT}/tv`,
  `${SPIRITFLIX_MEDIA_ROOT}/music`,
  `${SPIRITFLIX_MEDIA_ROOT}/other`,
];

export function normalizeSpiritFlixAdminPath(candidate: string): string {
  return candidate.replace(/\\/g, "/").replace(/\/+$/, "");
}

export function isProtectedSpiritFlixAdminPath(candidate: string): boolean {
  const normalized = normalizeSpiritFlixAdminPath(candidate);
  return SPIRITFLIX_ADMIN_PROTECTED_PATHS.some((protectedPath) => normalizeSpiritFlixAdminPath(protectedPath) === normalized);
}

export function isSpiritFlixAdminTrashPath(candidate: string): boolean {
  return normalizeSpiritFlixAdminPath(candidate).includes("/.trash/");
}

export function assertWritableSpiritFlixAdminPath(candidate: string, operation: string): void {
  if (isProtectedSpiritFlixAdminPath(candidate)) {
    throw new Error(`Cannot ${operation} protected library path.`);
  }

  const normalized = normalizeSpiritFlixAdminPath(candidate);
  const jellyfinSystemPatterns = [/jellyfin/i, /library\.db$/i, /system\.xml$/i, /\.sqlite$/i];
  if (jellyfinSystemPatterns.some((pattern) => pattern.test(normalized))) {
    throw new Error(`Cannot ${operation} Jellyfin system path.`);
  }
}

import fs from "node:fs/promises";
import path from "node:path";
import {
  assertWritableSpiritFlixAdminPath,
  isProtectedSpiritFlixAdminPath,
  isSpiritFlixAdminTrashPath,
  normalizeSpiritFlixAdminPath,
  SPIRITFLIX_ADMIN_PROTECTED_PATHS,
} from "./path-rules";

export {
  assertWritableSpiritFlixAdminPath,
  isProtectedSpiritFlixAdminPath,
  isSpiritFlixAdminTrashPath,
  normalizeSpiritFlixAdminPath,
  SPIRITFLIX_ADMIN_PROTECTED_PATHS,
};

const DEFAULT_ALLOWED_ROOTS = [
  "/mnt/spirit-8tb/media",
  "/mnt/spirit-8tb/media/anime",
  "/mnt/spirit-8tb/media/movies",
  "/mnt/spirit-8tb/media/tv",
  "/mnt/spirit-8tb/media/music",
  "/mnt/spirit-8tb/media/other",
  "/mnt/spirit-8tb/media/yes",
  "/mnt/spirit-8tb/media-inbox",
];

const BLOCKED_SEGMENTS = new Set([".env", ".git", ".ssh", "config", "secrets"]);
const ALLOWLISTED_HIDDEN_ROOTS = new Set<string>([
  ".spiritflix-admin-smoke",
  ".spiritflix-admin-receipts",
  ".spiritflix-admin",
  ".trash",
]);

function configuredRoots(): string[] {
  const raw = process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
  if (!raw) return DEFAULT_ALLOWED_ROOTS;
  return raw
    .split(path.delimiter)
    .map((entry) => entry.trim())
    .filter(Boolean);
}

function hasTraversalSegment(target: string): boolean {
  return target.split(/[\\/]+/).some((segment) => segment === "..");
}

function isSubPath(parent: string, child: string): boolean {
  const relative = path.relative(parent, child);
  return relative === "" || (!relative.startsWith("..") && !path.isAbsolute(relative));
}

function hasBlockedSegment(target: string, allowedRoot: string): boolean {
  const relative = path.relative(allowedRoot, target);
  if (!relative) return false;
  return relative.split(path.sep).some((segment) => {
    const lower = segment.toLowerCase();
    if (BLOCKED_SEGMENTS.has(lower)) return true;
    return lower.startsWith(".") && !ALLOWLISTED_HIDDEN_ROOTS.has(lower);
  });
}

export function getSpiritFlixAdminAllowedRoots(): string[] {
  return configuredRoots().map((root) => path.resolve(root));
}

export async function resolveSpiritFlixAdminPath(candidate = ""): Promise<{ allowedRoot: string; targetPath: string; realPath: string }> {
  if (hasTraversalSegment(candidate)) {
    throw new Error("Path traversal is not allowed.");
  }

  const allowedRoots = getSpiritFlixAdminAllowedRoots();
  const targetPath = path.resolve(candidate || allowedRoots[0] || "/");
  const allowedRoot = allowedRoots.find((root) => isSubPath(root, targetPath));

  if (!allowedRoot) {
    throw new Error("Path is outside the SpiritFlix admin allowlist.");
  }

  if (hasBlockedSegment(targetPath, allowedRoot)) {
    throw new Error("Hidden or system paths are not available in the SpiritFlix admin explorer.");
  }

  const [realPath, realRoot] = await Promise.all([fs.realpath(targetPath), fs.realpath(allowedRoot)]);

  if (!isSubPath(realRoot, realPath)) {
    throw new Error("Symlink escape is not allowed.");
  }

  return { allowedRoot: realRoot, targetPath, realPath };
}

/** Validate a path under allowlist even when the target file does not exist yet (restore/move targets). */
export async function validateSpiritFlixAdminPathCandidate(candidate = ""): Promise<string> {
  if (hasTraversalSegment(candidate)) {
    throw new Error("Path traversal is not allowed.");
  }

  const allowedRoots = getSpiritFlixAdminAllowedRoots();
  const targetPath = path.resolve(candidate || allowedRoots[0] || "/");
  const allowedRoot = allowedRoots.find((root) => isSubPath(root, targetPath));

  if (!allowedRoot) {
    throw new Error("Path is outside the SpiritFlix admin allowlist.");
  }

  if (hasBlockedSegment(targetPath, allowedRoot)) {
    throw new Error("Hidden or system paths are not available in the SpiritFlix admin explorer.");
  }

  try {
    const [realPath, realRoot] = await Promise.all([fs.realpath(targetPath), fs.realpath(allowedRoot)]);
    if (!isSubPath(realRoot, realPath)) {
      throw new Error("Symlink escape is not allowed.");
    }
    return realPath;
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
    const parent = path.dirname(targetPath);
    const [realParent, realRoot] = await Promise.all([fs.realpath(parent), fs.realpath(allowedRoot)]);
    if (!isSubPath(realRoot, realParent) || !isSubPath(realParent, targetPath)) {
      throw new Error("Symlink escape is not allowed.");
    }
    return targetPath;
  }
}

export async function getAdminRootForPath(candidate?: string): Promise<string> {
  if (!candidate) return fs.realpath(getSpiritFlixAdminAllowedRoots()[0]);
  return resolveSpiritFlixAdminPath(candidate).then((result) => result.allowedRoot);
}

export function isSpiritFlixAdminPathError(error: unknown): error is Error {
  return error instanceof Error && /allowlist|traversal|Hidden|Symlink|protected|Jellyfin system/.test(error.message);
}

import fs from "node:fs/promises";
import path from "node:path";
import { SPIRITFLIX_MEDIA_ROOT } from "./constants";
import type { SpiritFlixAdminReceipt, SpiritFlixAdminReceiptStatus } from "./types";

const RECEIPTS_DIR = path.join(SPIRITFLIX_MEDIA_ROOT, ".spiritflix-admin-receipts");

function receiptFileFor(date = new Date()): string {
  const stamp = date.toISOString().slice(0, 10).replace(/-/g, "");
  return path.join(RECEIPTS_DIR, `${stamp}.jsonl`);
}

export function createReceiptId(): string {
  return `sf-admin-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
}

export async function writeSpiritFlixAdminReceipt(
  input: Omit<SpiritFlixAdminReceipt, "id" | "timestamp" | "actor"> & { id?: string; timestamp?: string },
): Promise<SpiritFlixAdminReceipt> {
  const receipt: SpiritFlixAdminReceipt = {
    id: input.id ?? createReceiptId(),
    timestamp: input.timestamp ?? new Date().toISOString(),
    actor: "spiritflix-admin",
    action: input.action,
    status: input.status,
    sourcePath: input.sourcePath,
    targetPath: input.targetPath,
    affectedPaths: input.affectedPaths,
    jellyfinItemIds: input.jellyfinItemIds,
    reason: input.reason,
    reversible: input.reversible,
    rollbackHint: input.rollbackHint,
    previewId: input.previewId,
  };

  await fs.mkdir(RECEIPTS_DIR, { recursive: true });
  await fs.appendFile(receiptFileFor(new Date(receipt.timestamp)), `${JSON.stringify(receipt)}\n`, "utf8");
  return receipt;
}

export async function updateReceiptStatus(receiptId: string, status: SpiritFlixAdminReceiptStatus, reason?: string): Promise<void> {
  const file = receiptFileFor();
  try {
    const raw = await fs.readFile(file, "utf8");
    const lines = raw.split("\n").filter(Boolean);
    const updated = lines.map((line) => {
      const receipt = JSON.parse(line) as SpiritFlixAdminReceipt;
      if (receipt.id !== receiptId) return line;
      return JSON.stringify({ ...receipt, status, reason: reason ?? receipt.reason });
    });
    await fs.writeFile(file, `${updated.join("\n")}\n`, "utf8");
  } catch {
    // Receipt file may not exist yet for blocked previews.
  }
}

export function getReceiptsDirectory(): string {
  return RECEIPTS_DIR;
}

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import {
  assertSmartAnalysisPathSafe,
  assertSmartVideoPathCandidate,
  createSmartAnalysisPathKey,
  getSmartAnalysisCacheRoot,
  getSmartAnalysisPath,
  getSmartAnalysisRoot,
} from "../analysis-paths";

describe("SpiritFlix smart analysis paths", () => {
  let mediaRoot = "";

  beforeEach(async () => {
    mediaRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-smart-media-"));
    await fs.mkdir(path.join(mediaRoot, "yes", "nested"), { recursive: true });
  });

  afterEach(async () => {
    await fs.rm(mediaRoot, { force: true, recursive: true });
  });

  const sampleVideo = () => path.join(mediaRoot, "yes", "nested", "clip.mp4");

  const sampleInput = (overrides: Partial<{ videoPath: string; fileSizeBytes: number; mtimeMs: number }> = {}) => ({
    videoPath: overrides.videoPath ?? sampleVideo(),
    fileSizeBytes: overrides.fileSizeBytes ?? 1_024,
    mtimeMs: overrides.mtimeMs ?? 1_700_000_000_000,
  });

  it("creates deterministic keys and sidecar paths under the analysis root", () => {
    const input = sampleInput();
    const keyA = createSmartAnalysisPathKey(input);
    const keyB = createSmartAnalysisPathKey(input);
    expect(keyA).toBe(keyB);

    const sidecarPath = getSmartAnalysisPath(input, { mediaRoot });
    expect(sidecarPath).toBe(path.join(getSmartAnalysisRoot({ mediaRoot }), `${keyA}.json`));
    expect(sidecarPath.startsWith(getSmartAnalysisRoot({ mediaRoot }))).toBe(true);
    expect(sidecarPath.endsWith(".json")).toBe(true);
    expect(path.dirname(sidecarPath)).not.toBe(path.dirname(input.videoPath));
  });

  it("changes the key when size or mtime changes", () => {
    const base = sampleInput();
    const changedSize = createSmartAnalysisPathKey({ ...base, fileSizeBytes: base.fileSizeBytes + 1 });
    const changedMtime = createSmartAnalysisPathKey({ ...base, mtimeMs: base.mtimeMs + 1 });
    expect(changedSize).not.toBe(createSmartAnalysisPathKey(base));
    expect(changedMtime).not.toBe(createSmartAnalysisPathKey(base));
  });

  it("exposes the analysis cache root without writing frames in S1", () => {
    expect(getSmartAnalysisCacheRoot({ mediaRoot })).toBe(
      path.join(mediaRoot, ".spiritflix-admin", "analysis-cache"),
    );
  });

  it("rejects traversal and paths outside the media root", () => {
    expect(() => assertSmartVideoPathCandidate(`${mediaRoot}/../outside.mp4`, { mediaRoot })).toThrow(/traversal/i);
    expect(() => assertSmartVideoPathCandidate("/tmp/outside.mp4", { mediaRoot })).toThrow(/outside/i);
  });

  it("rejects Jellyfin config paths", () => {
    const jellyfinPath = path.join(mediaRoot, "yes", "jellyfin-config", "system.xml");
    expect(() => assertSmartVideoPathCandidate(jellyfinPath, { mediaRoot })).toThrow(/Jellyfin/i);
  });

  it("rejects admin storage paths and paths inside the analysis root", () => {
    const adminPath = path.join(mediaRoot, ".spiritflix-admin", "metadata", "abc.json");
    expect(() => assertSmartVideoPathCandidate(adminPath, { mediaRoot })).toThrow(/admin storage/i);

    const analysisPath = path.join(getSmartAnalysisRoot({ mediaRoot }), "abc.json");
    expect(() => assertSmartVideoPathCandidate(analysisPath, { mediaRoot })).toThrow(/analysis store/i);
  });

  it("keeps sidecar paths inside the analysis root and rejects traversal", () => {
    const safe = path.join(getSmartAnalysisRoot({ mediaRoot }), "abc123.json");
    expect(assertSmartAnalysisPathSafe(safe, { mediaRoot })).toBe(path.resolve(safe));

    const traversal = path.join(getSmartAnalysisRoot({ mediaRoot }), "..", "escape.json");
    expect(() => assertSmartAnalysisPathSafe(traversal, { mediaRoot })).toThrow(/analysis root/i);

    const outside = path.join(mediaRoot, "yes", "nested", "beside-video.json");
    expect(() => assertSmartAnalysisPathSafe(outside, { mediaRoot })).toThrow(/analysis root/i);
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { getSmartAnalysisRoot } from "../analysis-paths";
import {
  createEmptySmartAnalysis,
  readSmartAnalysis,
  writeSmartAnalysis,
} from "../analysis-store";
import { validateSpiritFlixSmartAnalysis } from "../types";

describe("SpiritFlix smart analysis store", () => {
  let mediaRoot = "";
  let videoPath = "";

  beforeEach(async () => {
    mediaRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-smart-store-"));
    const videoDir = path.join(mediaRoot, "yes", "nested");
    await fs.mkdir(videoDir, { recursive: true });
    videoPath = path.join(videoDir, "sample.mp4");
    await fs.writeFile(videoPath, "fake-video-bytes");
  });

  afterEach(async () => {
    await fs.rm(mediaRoot, { force: true, recursive: true });
  });

  const pathInput = async () => {
    const stat = await fs.stat(videoPath);
    return {
      videoPath,
      fileSizeBytes: stat.size,
      mtimeMs: stat.mtimeMs,
    };
  };

  it("builds a not_analyzed empty record", () => {
    const analysis = createEmptySmartAnalysis(
      {
        videoPath,
        fileName: "sample.mp4",
        fileSizeBytes: 16,
        mtimeMs: 1_700_000_000_000,
      },
      { mediaRoot },
    );

    expect(analysis.status).toBe("not_analyzed");
    expect(analysis.version).toBe(1);
    expect(analysis.samples).toEqual([]);
    expect(analysis.suggestedTags).toEqual([]);
    expect(analysis.confidence).toBe(0);
  });

  it("returns null when the sidecar is missing", async () => {
    const input = await pathInput();
    const result = await readSmartAnalysis(input, { mediaRoot });
    expect(result).toBeNull();
  });

  it("writes and reads an analysis sidecar atomically under the analysis root", async () => {
    const input = await pathInput();
    const empty = createEmptySmartAnalysis(
      {
        videoPath: input.videoPath,
        fileName: "sample.mp4",
        fileSizeBytes: input.fileSizeBytes,
        mtimeMs: input.mtimeMs,
      },
      { mediaRoot },
    );

    const suggested = validateSpiritFlixSmartAnalysis({
      ...empty,
      status: "suggested",
      suggestedDisplayTitle: "Unknown â€” Indoor Scene",
      suggestedTags: [
        {
          id: "indoor",
          label: "indoor",
          group: "scene",
          confidence: 0.72,
          evidenceTimestamps: [12],
          reviewRequired: false,
        },
      ],
      confidence: 0.72,
    });

    const written = await writeSmartAnalysis(suggested, { mediaRoot });
    expect(written.path.startsWith(getSmartAnalysisRoot({ mediaRoot }))).toBe(true);
    expect(path.dirname(written.path)).not.toBe(path.dirname(videoPath));

    const readBack = await readSmartAnalysis(input, { mediaRoot });
    expect(readBack?.status).toBe("suggested");
    expect(readBack?.suggestedDisplayTitle).toBe("Unknown â€” Indoor Scene");
    expect(readBack?.suggestedTags).toHaveLength(1);
  });

  it("rejects invalid analysis payloads and pathKey mismatches", async () => {
    const input = await pathInput();
    const empty = createEmptySmartAnalysis(
      {
        videoPath: input.videoPath,
        fileName: "sample.mp4",
        fileSizeBytes: input.fileSizeBytes,
        mtimeMs: input.mtimeMs,
      },
      { mediaRoot },
    );

    await expect(
      writeSmartAnalysis(
        validateSpiritFlixSmartAnalysis({
          ...empty,
          pathKey: "deadbeef",
        }),
        { mediaRoot },
      ),
    ).rejects.toThrow(/pathKey/i);

    expect(() =>
      validateSpiritFlixSmartAnalysis({
        ...empty,
        status: "definitely-not-valid",
      }),
    ).toThrow(/status/i);

    expect(() =>
      validateSpiritFlixSmartAnalysis({
        ...empty,
        suggestedTags: [
          {
            id: "indoor",
            label: "indoor",
            group: "scene",
            confidence: 2,
            evidenceTimestamps: [],
            reviewRequired: false,
          },
        ],
      }),
    ).toThrow(/confidence/i);
  });

  it("rejects prototype pollution keys during validation", () => {
    const polluted = {
      constructor: { polluted: true },
      version: 1,
      videoPath: path.join(mediaRoot, "yes", "nested", "sample.mp4"),
      pathKey: "abc",
      fileName: "sample.mp4",
      fileSizeBytes: 1,
      mtimeMs: 1,
      analyzedAt: new Date().toISOString(),
      analyzerVersion: "test",
      status: "not_analyzed",
      safety: { safeToSuggest: true, reasons: [], requiresHumanReview: false },
      media: {},
      samples: [],
      suggestedTags: [],
      confidence: 0,
    };

    expect(() => validateSpiritFlixSmartAnalysis(polluted)).toThrow(/Unsafe key/i);
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createSmartAnalysisPathKey } from "../analysis-paths";
import { previewSpiritFlixSmartBatch, reviewSpiritFlixSmartBatch, runSpiritFlixSmartBatch } from "../batch";
import { readSmartAnalysis } from "../analysis-store";
import { writeSmartAnalysis } from "../analysis-store";
import { validateSpiritFlixSmartAnalysis, type SpiritFlixSmartAnalysis } from "../types";

let tempRoot = "";
let originalRoots: string | undefined;

async function writeVideo(relativePath: string, content = "fake-video") {
  const videoPath = path.join(tempRoot, relativePath);
  await fs.mkdir(path.dirname(videoPath), { recursive: true });
  await fs.writeFile(videoPath, content);
  return videoPath;
}

async function currentAnalysis(videoPath: string, overrides: Partial<SpiritFlixSmartAnalysis> = {}) {
  const stat = await fs.stat(videoPath);
  const analysis = validateSpiritFlixSmartAnalysis({
    version: 1,
    videoPath,
    pathKey: createSmartAnalysisPathKey({ videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs }),
    fileName: path.basename(videoPath),
    fileSizeBytes: stat.size,
    mtimeMs: stat.mtimeMs,
    analyzedAt: "2026-06-18T00:00:00.000Z",
    analyzerVersion: "spiritflix-smart/s5",
    status: "suggested",
    safety: { safeToSuggest: false, reasons: ["test"], requiresHumanReview: true },
    media: { durationSeconds: 60 },
    samples: [],
    suggestedTags: [{ id: "hd", label: "HD", group: "quality", confidence: 0.8, evidenceTimestamps: [], reviewRequired: false }],
    suggestedDisplayTitle: "Clip",
    suggestedFilename: "Clip Better.mp4",
    confidence: 0.8,
    ...overrides,
  });
  await writeSmartAnalysis(analysis, { mediaRoot: tempRoot });
  return analysis;
}

describe("SpiritFlix smart batch analysis", () => {
  beforeEach(async () => {
    originalRoots = process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-smart-batch-"));
    process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = tempRoot;
  });

  afterEach(async () => {
    if (originalRoots === undefined) delete process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    else process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = originalRoots;
    await fs.rm(tempRoot, { force: true, recursive: true });
  });

  it("previews eligible videos in a bounded folder scan", async () => {
    await writeVideo("yes/clip-a.mp4");
    await writeVideo("yes/clip-b.mkv");
    await fs.writeFile(path.join(tempRoot, "yes/readme.txt"), "skip");

    const preview = await previewSpiritFlixSmartBatch({ path: path.join(tempRoot, "yes"), maxItems: 1 });

    expect(preview.schema).toBe("spiritflix-smart-batch/v1");
    expect(preview.mode).toBe("preview");
    expect(preview.items).toHaveLength(1);
    expect(preview.counts.candidates).toBe(1);
    expect(preview.items[0].status).toBe("candidate");
  });

  it("skips current sidecars unless force is requested", async () => {
    const videoPath = await writeVideo("yes/current.mp4");
    await currentAnalysis(videoPath);
    const analyzeVideo = vi.fn();

    const result = await runSpiritFlixSmartBatch({
      path: path.join(tempRoot, "yes"),
      analyzeVideo,
    } as Parameters<typeof runSpiritFlixSmartBatch>[0]);

    expect(result.counts.already_current).toBe(1);
    expect(analyzeVideo).not.toHaveBeenCalled();
  });

  it("returns operator visibility fields when current items still need review", async () => {
    const videoPath = await writeVideo("yes/current-needs-review.mp4");
    await currentAnalysis(videoPath, {
      status: "needs_review",
      suggestedTags: [
        { id: "hd", label: "HD", group: "quality", confidence: 0.9, evidenceTimestamps: [], reviewRequired: false },
        { id: "watermark", label: "Watermark", group: "watermark", confidence: 0.55, evidenceTimestamps: [], reviewRequired: true },
      ],
    });

    const result = await previewSpiritFlixSmartBatch({ path: path.join(tempRoot, "yes") });

    expect(result.counts.rename_preview_available).toBe(0);
    expect(result.items[0]).toMatchObject({
      reviewStatus: "unreviewed",
      renamePreviewStatus: "provisional",
      proposedFilename: "Clip Better",
      renameBlocker: "Review or approve tags/metadata to unlock rename preview.",
      sidecarCurrent: true,
      approvedTagCount: 0,
      rejectedTagCount: 0,
      pendingTagCount: 1,
    });
    expect(result.items[0].tags.map((tag) => tag.label)).toEqual(["Watermark"]);
    expect(result.items[0].qualityBadges.map((tag) => tag.label)).toContain("HD");
    expect(result.items[0].renameWarnings).toContain("Provisional preview, not eligible for apply until reviewed.");
    expect(result.items[0].sidecarRef).toMatch(/^analysis\/[a-f0-9]{12}\.json$/);
    expect(result.visualContentTaggingMessage).toMatch(/local visual model/i);
  });

  it("runs analysis and preserves existing reviewed metadata on refresh", async () => {
    const videoPath = await writeVideo("yes/reviewed.mp4");
    const reviewedMetadata = {
      reviewedAt: "2026-06-18T00:00:00.000Z",
      reviewedBy: "spiritflix-admin" as const,
      reviewStatus: "reviewed" as const,
      approvedTagIds: ["hd"],
      rejectedTagIds: [],
      editedFilenameSuggestion: "Reviewed Name.mp4",
    };
    const existing = await currentAnalysis(videoPath, { reviewedMetadata });
    const analyzeVideo = vi.fn(async () => validateSpiritFlixSmartAnalysis({
      ...existing,
      analyzedAt: "2026-06-18T01:00:00.000Z",
      reviewedMetadata,
      suggestedFilename: "Refreshed Name.mp4",
    }));

    const result = await runSpiritFlixSmartBatch({
      path: path.join(tempRoot, "yes"),
      force: true,
      analyzeVideo,
    } as Parameters<typeof runSpiritFlixSmartBatch>[0]);

    expect(result.counts.analyzed).toBe(1);
    expect(result.counts.rename_preview_available).toBe(1);
    expect(result.items[0].reviewStatus).toBe("reviewed");
    expect(result.items[0].renamePreviewStatus).toBe("ready");
    expect(result.items[0].proposedFilename).toBe("Reviewed Name");
    expect(analyzeVideo).toHaveBeenCalledWith(videoPath, expect.objectContaining({ mediaRoot: tempRoot }));
  });

  it("shows target conflict and duplicate target warnings in batch item details", async () => {
    const first = await writeVideo("yes/first.mp4");
    const second = await writeVideo("yes/second.mp4");
    const third = await writeVideo("yes/third.mp4");
    await writeVideo("yes/Existing.mp4");
    await currentAnalysis(first, {
      reviewedMetadata: {
        reviewedAt: "2026-06-18T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "Same Name.mp4",
      },
    });
    await currentAnalysis(second, {
      reviewedMetadata: {
        reviewedAt: "2026-06-18T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "Existing.mp4",
      },
    });
    await currentAnalysis(third, {
      reviewedMetadata: {
        reviewedAt: "2026-06-18T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "Same Name.mp4",
      },
    });

    const result = await previewSpiritFlixSmartBatch({ path: path.join(tempRoot, "yes") });

    expect(result.items.find((item) => item.name === "second.mp4")?.renameWarnings).toContain("Target path already exists.");
    expect(result.items.find((item) => item.name === "second.mp4")?.renamePreviewStatus).toBe("blocked");
    expect(result.items.find((item) => item.name === "first.mp4")?.renameWarnings).toContain("Duplicate target path in this batch.");
    expect(result.items.find((item) => item.name === "third.mp4")?.renameWarnings).toContain("Duplicate target path in this batch.");
  });

  it("reports per-item failures without throwing the whole batch", async () => {
    await writeVideo("yes/broken.mp4");
    const analyzeVideo = vi.fn(async () => {
      throw new Error("ffprobe failed for test");
    });

    const result = await runSpiritFlixSmartBatch({
      path: path.join(tempRoot, "yes"),
      analyzeVideo,
    } as Parameters<typeof runSpiritFlixSmartBatch>[0]);

    expect(result.counts.failed).toBe(1);
    expect(result.items[0].reason).toMatch(/ffprobe failed/i);
  });

  it("batch approves suggested tags while preserving edited review fields", async () => {
    const videoPath = await writeVideo("yes/to-approve.mp4");
    await currentAnalysis(videoPath, {
      reviewedMetadata: {
        reviewedAt: "2026-06-18T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "partially_reviewed",
        approvedTagIds: [],
        rejectedTagIds: [],
        editedDisplayTitle: "Keep Title",
        editedFilenameSuggestion: "Keep Filename.mp4",
      },
    });

    const result = await reviewSpiritFlixSmartBatch({
      path: path.join(tempRoot, "yes"),
      reviewMode: "approve_all_tags",
    });
    const stat = await fs.stat(videoPath);
    const saved = await readSmartAnalysis({ videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs }, { mediaRoot: tempRoot });

    expect(result.counts.analyzed).toBe(1);
    expect(saved?.reviewedMetadata?.reviewStatus).toBe("reviewed");
    expect(saved?.reviewedMetadata?.approvedTagIds).toEqual(["hd"]);
    expect(saved?.reviewedMetadata?.editedDisplayTitle).toBe("Keep Title");
  });

  it("batch rejects suggested tags and marks the video rejected", async () => {
    const videoPath = await writeVideo("yes/to-reject.mp4");
    await currentAnalysis(videoPath);

    await reviewSpiritFlixSmartBatch({
      path: path.join(tempRoot, "yes"),
      reviewMode: "reject_all_tags",
    });
    const stat = await fs.stat(videoPath);
    const saved = await readSmartAnalysis({ videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs }, { mediaRoot: tempRoot });

    expect(saved?.reviewedMetadata?.reviewStatus).toBe("rejected");
    expect(saved?.reviewedMetadata?.rejectedTagIds).toEqual(["hd"]);
  });

  it("batch mark reviewed skips videos without analysis sidecars", async () => {
    await writeVideo("yes/no-sidecar.mp4");

    const result = await reviewSpiritFlixSmartBatch({
      path: path.join(tempRoot, "yes"),
      reviewMode: "mark_reviewed",
    });

    expect(result.counts.skipped).toBe(1);
    expect(result.items[0].reason).toMatch(/no smart analysis/i);
  });
});

import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  inferFormatTags,
  inferQualityTags,
  inferSourceTokens,
  isPrimarySmartContentTag,
  isRandomOrHashSpiritFlixFilename,
  normalizeSpiritFlixTitle,
  modelIdentityFromPath,
  stripKnownNoiseTokens,
  tokenizeSpiritFlixName,
  type SpiritFlixSmartHeuristicInput,
} from "../heuristics";

function input(overrides: Partial<SpiritFlixSmartHeuristicInput> & Pick<SpiritFlixSmartHeuristicInput, "fileName">): SpiritFlixSmartHeuristicInput {
  const fileName = overrides.fileName;
  const videoPath = overrides.videoPath ?? path.join("/mnt/spirit-8tb/media/yes", fileName);
  return {
    ...overrides,
    videoPath,
    fileName,
    parentPath: overrides.parentPath ?? path.dirname(videoPath),
  };
}

describe("SpiritFlix smart heuristics", () => {
  it("tokenizes filename and path segments", () => {
    const tokens = tokenizeSpiritFlixName("/mnt/media/yes/Example.Site.Name.1080p.x264.mp4");
    expect(tokens).toContain("example");
    expect(tokens).toContain("site");
    expect(tokens).toContain("1080p");
    expect(tokens).toContain("x264");
  });

  it("strips common codec and quality noise", () => {
    expect(stripKnownNoiseTokens("clip.1080p.x264.h264.mkv")).toBe("clip");
    expect(stripKnownNoiseTokens("final.copy.webrip.mp4")).toBe("");
  });

  it("keeps meaningful title tokens", () => {
    expect(normalizeSpiritFlixTitle("Example.Site.Name.1080p.x264.mp4")).toBe("Example Site Name");
    expect(normalizeSpiritFlixTitle("vacation_day_one.mkv")).toBe("vacation day one");
  });

  it("infers container format tags from extension and metadata", () => {
    const tags = inferFormatTags(input({ fileName: "clip.mkv", media: { container: "matroska,webm" } }));
    expect(tags.some((tag) => tag.id === "mkv-container")).toBe(true);
  });

  it("infers vertical from width/height metadata", () => {
    const tags = inferQualityTags(input({ fileName: "clip.mp4", media: { width: 1080, height: 1920 } }));
    expect(tags.some((tag) => tag.id === "vertical")).toBe(true);
  });

  it("infers quality from resolution and filename tokens", () => {
    const fromMeta = inferQualityTags(input({ fileName: "clip.mp4", media: { width: 1920, height: 1080 } }));
    expect(fromMeta.some((tag) => tag.id === "full-hd")).toBe(true);

    const fromName = inferQualityTags(input({ fileName: "clip.720p.mp4" }));
    expect(fromName.some((tag) => tag.id === "hd")).toBe(true);
  });

  it("does not infer visual scene tags from frames", () => {
    const tags = [
      ...inferQualityTags(input({ fileName: "clip.mp4", media: { width: 1920, height: 1080, durationSeconds: 600 } })),
      ...inferFormatTags(input({ fileName: "clip.mp4", media: { durationSeconds: 600 } })),
    ];
    const visualSceneIds = ["oral", "missionary", "doggy", "indoor", "outdoor", "pov"];
    for (const id of visualSceneIds) {
      expect(tags.some((tag) => tag.id === id)).toBe(false);
    }
  });

  it("does not fabricate performer identity", () => {
    const tokens = tokenizeSpiritFlixName("Jane_Doe_Special.1080p.mp4");
    expect(tokens).not.toContain("known-performer");
    expect(inferSourceTokens(input({ fileName: "Jane_Doe_Special.1080p.mp4" }))).toEqual([]);
  });

  it("detects literal source/site tokens only", () => {
    expect(inferSourceTokens(input({ fileName: "onlyfans.leak.clip.mp4" }))).toContain("onlyfans");
    expect(inferSourceTokens(input({ fileName: "random.home.video.mp4" }))).toEqual([]);
  });

  it("handles messy filenames", () => {
    expect(normalizeSpiritFlixTitle("www.site.com___clip.final.copy.1080p.WEB-DL.x265.mp4")).toBe("site clip");
  });

  it("handles short names like 360 1.mp4", () => {
    expect(normalizeSpiritFlixTitle("360 1.mp4")).toBe("360 1");
    expect(stripKnownNoiseTokens("360 1.mp4")).toBe("360 1");
  });

  it("classifies technical/status tags as non-primary smart content", () => {
    const tags = [
      ...inferQualityTags(input({ fileName: "clip.1080p.mp4", media: { width: 1920, height: 1080, durationSeconds: 3600 } })),
      ...inferFormatTags(input({ fileName: "clip.mkv", media: { container: "matroska,webm", durationSeconds: 3600 } })),
      { id: "unknown-performer", label: "unknown performer", group: "performer" as const, confidence: 0.6, evidenceTimestamps: [], reviewRequired: false },
      { id: "needs-title-cleanup", label: "needs title cleanup", group: "safety" as const, confidence: 0.8, evidenceTimestamps: [], reviewRequired: true },
    ];
    const labels = tags.map((tag) => tag.label);
    expect(labels).toEqual(expect.arrayContaining(["full HD", "mkv", "long", "unknown performer", "needs title cleanup"]));
    expect(tags.every((tag) => !isPrimarySmartContentTag(tag))).toBe(true);
  });

  it("detects random/hash filenames and model folder identity", () => {
    expect(isRandomOrHashSpiritFlixFilename(input({ fileName: "HkkzMtwQexuQzwkQMekM.mkv" }))).toBe(true);
    expect(isRandomOrHashSpiritFlixFilename(input({ fileName: "442642.mkv" }))).toBe(true);
    expect(isRandomOrHashSpiritFlixFilename(input({ fileName: "Readable Human Title.mkv" }))).toBe(false);
    expect(modelIdentityFromPath(input({
      fileName: "clip.mkv",
      videoPath: "/mnt/spirit-8tb/media/yes/models/chloe-lamb/clip.mkv",
      parentPath: "/mnt/spirit-8tb/media/yes/models/chloe-lamb",
    }))).toMatchObject({ name: "Chloe Lamb", source: "path" });
  });
});

import { describe, expect, it } from "vitest";
import { projectApprovedSmartMetadata, metadataSidecarPath } from "../metadata-bridge";
import { validateSpiritFlixSmartAnalysis } from "../types";

const baseAnalysis = validateSpiritFlixSmartAnalysis({
  version: 1,
  videoPath: "/mnt/spirit-8tb/media/yes/clip.mp4",
  pathKey: "abc",
  fileName: "clip.mp4",
  fileSizeBytes: 100,
  mtimeMs: 1,
  analyzedAt: "2026-06-16T00:00:00.000Z",
  analyzerVersion: "spiritflix-smart/s5",
  status: "approved",
  safety: { safeToSuggest: false, reasons: ["scanner"], requiresHumanReview: true },
  media: { durationSeconds: 90, width: 1280, height: 720, codec: "h264" },
  samples: [],
  suggestedTags: [
    { id: "hd", label: "HD", group: "quality", confidence: 0.8, evidenceTimestamps: [], reviewRequired: false },
    { id: "short", label: "short", group: "format", confidence: 0.7, evidenceTimestamps: [], reviewRequired: false },
  ],
  suggestedDisplayTitle: "Original Title",
  suggestedFilename: "Original Title.mp4",
  suggestedCategory: "original-cat",
  suggestedCollections: ["collection-a"],
  confidence: 0.75,
  reviewedMetadata: {
    reviewedAt: "2026-06-17T00:00:00.000Z",
    reviewedBy: "spiritflix-admin",
    reviewStatus: "reviewed",
    approvedTagIds: ["hd"],
    rejectedTagIds: ["short"],
    editedDisplayTitle: "Edited Title",
    editedFilenameSuggestion: "Edited Title.mp4",
    editedCategory: "edited-cat",
    editedCollections: ["collection-b"],
    notes: "user note",
  },
});

const unreviewedAnalysis = validateSpiritFlixSmartAnalysis({
  version: 1,
  videoPath: "/mnt/spirit-8tb/media/yes/unreviewed.mp4",
  pathKey: "def",
  fileName: "unreviewed.mp4",
  fileSizeBytes: 200,
  mtimeMs: 2,
  analyzedAt: "2026-06-16T00:00:00.000Z",
  analyzerVersion: "spiritflix-smart/s3",
  status: "suggested",
  safety: { safeToSuggest: true, reasons: [], requiresHumanReview: false },
  media: {},
  samples: [],
  suggestedTags: [
    { id: "hd", label: "HD", group: "quality", confidence: 0.9, evidenceTimestamps: [], reviewRequired: false },
  ],
  suggestedDisplayTitle: "Auto Title",
  suggestedFilename: "Auto Title.mp4",
  suggestedCategory: "auto-cat",
  suggestedCollections: ["auto-coll"],
  confidence: 0.9,
});

describe("SpiritFlix smart metadata bridge", () => {
  it("prefers edited values over suggestions", () => {
    const projection = projectApprovedSmartMetadata(baseAnalysis);
    expect(projection.displayTitle).toBe("Edited Title");
    expect(projection.filenameSuggestion).toBe("Edited Title.mp4");
    expect(projection.category).toBe("edited-cat");
    expect(projection.collections).toEqual(["collection-b"]);
    expect(projection.notes).toBe("user note");
  });

  it("falls back to suggestions when no edits exist", () => {
    const projection = projectApprovedSmartMetadata(unreviewedAnalysis);
    expect(projection.displayTitle).toBe("Auto Title");
    expect(projection.filenameSuggestion).toBe("Auto Title.mp4");
    expect(projection.category).toBe("auto-cat");
    expect(projection.collections).toEqual(["auto-coll"]);
  });

  it("approved tags come only from approvedTagIds and vocabulary", () => {
    const projection = projectApprovedSmartMetadata(baseAnalysis);
    expect(projection.approvedTags).toHaveLength(1);
    expect(projection.approvedTags[0].id).toBe("hd");
  });

  it("rejected tags are recorded but not active", () => {
    const projection = projectApprovedSmartMetadata(baseAnalysis);
    expect(projection.rejectedTagIds).toEqual(["short"]);
    // short is rejected, so it should NOT be in approvedTags
    expect(projection.approvedTags.find((t) => t.id === "short")).toBeUndefined();
  });

  it("reviewStatus comes from reviewedMetadata", () => {
    const projection = projectApprovedSmartMetadata(baseAnalysis);
    expect(projection.reviewStatus).toBe("reviewed");
    expect(projection.reviewedAt).toBe("2026-06-17T00:00:00.000Z");
  });

  it("defaults reviewStatus to unreviewed when no reviewedMetadata", () => {
    const projection = projectApprovedSmartMetadata(unreviewedAnalysis);
    expect(projection.reviewStatus).toBe("unreviewed");
    expect(projection.reviewedAt).toBeUndefined();
  });

  it("sourcePath comes from analysis.videoPath", () => {
    const projection = projectApprovedSmartMetadata(baseAnalysis);
    expect(projection.sourcePath).toBe("/mnt/spirit-8tb/media/yes/clip.mp4");
  });

  it("metadata sidecar path stays under .spiritflix-admin/metadata", () => {
    const sidecarPath = metadataSidecarPath("/mnt/spirit-8tb/media/yes/clip.mp4");
    expect(sidecarPath).toContain(".spiritflix-admin/metadata");
    expect(sidecarPath).not.toContain("/yes/");
    expect(sidecarPath).toMatch(/\.json$/);
  });

  it("metadata sidecar path uses sha256 of normalized path", () => {
    const path1 = metadataSidecarPath("/mnt/spirit-8tb/media/yes/clip.mp4");
    const path2 = metadataSidecarPath("C:\\mnt\\spirit-8tb\\media\\yes\\clip.mp4"); // windows-ish
    const path3 = metadataSidecarPath("/mnt/spirit-8tb/media/yes/clip.mp4");
    // Same path lowercase normalized -> same hash
    expect(path1).toBe(path3);
    // Forward slash normalization should make path1 == path2
    expect(path1).toBe(path2);
  });

  it("metadata sidecar path supports custom mediaRoot", () => {
    const sidecarPath = metadataSidecarPath("/media/test.mp4", "/media");
    expect(sidecarPath).toContain("/media/.spiritflix-admin/metadata");
  });

  it("filename suggestion is metadata-only (not mutating real files)", () => {
    const projection = projectApprovedSmartMetadata(baseAnalysis);
    // The projection contains a filenameSuggestion field â€” it is a suggestion string, not a file operation.
    expect(typeof projection.filenameSuggestion).toBe("string");
    expect(projection.filenameSuggestion).toBe("Edited Title.mp4");
  });
});

import path from "node:path";
import { EventEmitter } from "node:events";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { SpiritFlixSmartProbeError } from "../errors";

const mockSpawn = vi.hoisted(() => vi.fn());

vi.mock("../process", () => ({
  spawn: mockSpawn,
}));

import { parseFfprobeJson, parseRationalFrameRate, probeSpiritFlixVideo } from "../probe";

const SAMPLE_FFPROBE = {
  format: {
    duration: "125.456",
    format_name: "matroska,webm",
    bit_rate: "4500000",
  },
  streams: [
    {
      codec_type: "audio",
      codec_name: "aac",
    },
    {
      codec_type: "video",
      codec_name: "h264",
      width: 1920,
      height: 1080,
      avg_frame_rate: "30000/1001",
      r_frame_rate: "30000/1001",
    },
  ],
};

function mockSpawnEmitter(onReady: (emitter: EventEmitter & { stdout: EventEmitter; stderr: EventEmitter }) => void) {
  mockSpawn.mockImplementation(() => {
    const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
    emitter.stdout = new EventEmitter();
    emitter.stderr = new EventEmitter();
    emitter.kill = vi.fn();
    queueMicrotask(() => onReady(emitter));
    return emitter;
  });
}

describe("SpiritFlix smart probe", () => {
  beforeEach(() => {
    mockSpawn.mockReset();
  });

  it("parses representative ffprobe JSON", () => {
    const result = parseFfprobeJson(SAMPLE_FFPROBE);
    expect(result.durationSeconds).toBeCloseTo(125.456);
    expect(result.width).toBe(1920);
    expect(result.height).toBe(1080);
    expect(result.codec).toBe("h264");
    expect(result.container).toBe("matroska,webm");
    expect(result.bitRate).toBe(4_500_000);
    expect(result.frameRate).toBeCloseTo(29.97, 1);
  });

  it("parses rational frame rate like 30000/1001", () => {
    expect(parseRationalFrameRate("30000/1001")).toBeCloseTo(29.97, 1);
    expect(parseRationalFrameRate("24/1")).toBe(24);
    expect(parseRationalFrameRate("0/0")).toBeUndefined();
  });

  it("handles missing duration", () => {
    const result = parseFfprobeJson({
      format: { format_name: "mp4" },
      streams: [{ codec_type: "video", codec_name: "hevc", width: 1280, height: 720 }],
    });
    expect(result.durationSeconds).toBeUndefined();
    expect(result.codec).toBe("hevc");
  });

  it("rejects non-video extension", async () => {
    const mediaRoot = "/tmp/spiritflix-probe-media";
    const txtPath = path.join(mediaRoot, "yes", "notes.txt");
    await expect(
      probeSpiritFlixVideo(txtPath, { mediaRoot, ffprobePath: "/usr/bin/ffprobe" }),
    ).rejects.toThrow(/video files/i);
  });

  it("rejects traversal/outside root", async () => {
    const mediaRoot = "/tmp/spiritflix-probe-media";
    await expect(probeSpiritFlixVideo("/etc/passwd", { mediaRoot })).rejects.toThrow(/outside/i);
    await expect(
      probeSpiritFlixVideo(`${mediaRoot}/../outside.mp4`, { mediaRoot }),
    ).rejects.toThrow(/traversal/i);
  });

  it("uses shell false / argument array where testable", async () => {
    const mediaRoot = "/tmp/spiritflix-probe-media";
    const videoPath = path.join(mediaRoot, "yes", "clip.mp4");
    mockSpawnEmitter((emitter) => {
      emitter.stdout.emit("data", Buffer.from(JSON.stringify(SAMPLE_FFPROBE)));
      emitter.emit("close", 0);
    });

    const result = await probeSpiritFlixVideo(videoPath, { mediaRoot, ffprobePath: "/usr/bin/ffprobe" });
    expect(result.codec).toBe("h264");
    expect(mockSpawn).toHaveBeenCalledWith(
      "/usr/bin/ffprobe",
      expect.arrayContaining(["-print_format", "json", "-show_format", "-show_streams", videoPath]),
      { shell: false },
    );
  });

  it("handles timeout", async () => {
    const mediaRoot = "/tmp/spiritflix-probe-media";
    const videoPath = path.join(mediaRoot, "yes", "clip.mp4");
    mockSpawn.mockImplementation(() => {
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();
      return emitter;
    });

    await expect(
      probeSpiritFlixVideo(videoPath, { mediaRoot, ffprobePath: "/usr/bin/ffprobe", timeoutMs: 1 }),
    ).rejects.toThrow(/timed out/i);
  });

  it("handles invalid JSON", async () => {
    const mediaRoot = "/tmp/spiritflix-probe-media";
    const videoPath = path.join(mediaRoot, "yes", "clip.mp4");
    mockSpawnEmitter((emitter) => {
      emitter.stdout.emit("data", Buffer.from("not-json"));
      emitter.emit("close", 0);
    });

    await expect(
      probeSpiritFlixVideo(videoPath, { mediaRoot, ffprobePath: "/usr/bin/ffprobe" }),
    ).rejects.toThrow(/invalid JSON/i);
  });

  it("handles missing ffprobe", async () => {
    const mediaRoot = "/tmp/spiritflix-probe-media";
    const videoPath = path.join(mediaRoot, "yes", "clip.mp4");
    mockSpawnEmitter((emitter) => {
      emitter.emit("error", Object.assign(new Error("spawn ENOENT"), { code: "ENOENT" }));
    });

    await expect(
      probeSpiritFlixVideo(videoPath, { mediaRoot, ffprobePath: "/missing/ffprobe" }),
    ).rejects.toThrow(/not available/i);
  });

  it("throws typed probe errors", () => {
    expect(() => parseFfprobeJson(null)).toThrow(SpiritFlixSmartProbeError);
    expect(new SpiritFlixSmartProbeError("x").name).toBe("SpiritFlixSmartProbeError");
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createSmartAnalysisPathKey } from "../analysis-paths";
import { writeSmartAnalysis } from "../analysis-store";
import { buildSpiritFlixSmartRenamePlan } from "../rename-plan";
import { validateSpiritFlixSmartAnalysis, type SpiritFlixSmartAnalysis } from "../types";

let tempRoot = "";
let originalRoots: string | undefined;

async function writeVideo(relativePath: string, content = "fake-video") {
  const videoPath = path.join(tempRoot, relativePath);
  await fs.mkdir(path.dirname(videoPath), { recursive: true });
  await fs.writeFile(videoPath, content);
  return videoPath;
}

async function writeAnalysis(videoPath: string, overrides: Partial<SpiritFlixSmartAnalysis> = {}) {
  const stat = await fs.stat(videoPath);
  const analysis = validateSpiritFlixSmartAnalysis({
    version: 1,
    videoPath,
    pathKey: createSmartAnalysisPathKey({ videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs }),
    fileName: path.basename(videoPath),
    fileSizeBytes: stat.size,
    mtimeMs: stat.mtimeMs,
    analyzedAt: "2026-06-19T00:00:00.000Z",
    analyzerVersion: "spiritflix-smart/s8",
    status: "approved",
    safety: { safeToSuggest: false, reasons: ["test"], requiresHumanReview: true },
    media: {},
    samples: [],
    suggestedTags: [
      { id: "hd", label: "HD", group: "quality", confidence: 0.9, evidenceTimestamps: [], reviewRequired: false },
      { id: "watermark", label: "Watermark", group: "watermark", confidence: 0.7, evidenceTimestamps: [], reviewRequired: true },
    ],
    suggestedDisplayTitle: "Clean Clip",
    suggestedFilename: "suggested-from-scanner.mp4",
    confidence: 0.8,
    reviewedMetadata: {
      reviewedAt: "2026-06-19T00:00:00.000Z",
      reviewedBy: "spiritflix-admin",
      reviewStatus: "reviewed",
      approvedTagIds: ["hd"],
      rejectedTagIds: ["watermark"],
    },
    ...overrides,
  });
  await writeSmartAnalysis(analysis, { mediaRoot: tempRoot });
  return analysis;
}

describe("SpiritFlix smart rename plan", () => {
  beforeEach(async () => {
    originalRoots = process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    tempRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-rename-plan-"));
    process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = tempRoot;
  });

  afterEach(async () => {
    if (originalRoots === undefined) delete process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS;
    else process.env.SPIRITFLIX_ADMIN_ALLOWED_ROOTS = originalRoots;
    await fs.rm(tempRoot, { force: true, recursive: true });
  });

  it("builds a preview-only plan from reviewed approved metadata", async () => {
    const videoPath = await writeVideo("yes/old.mp4");
    await writeAnalysis(videoPath, {
      reviewedMetadata: {
        reviewedAt: "2026-06-19T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: ["watermark"],
        editedFilenameSuggestion: "Better Name.mp4",
      },
    });

    const plan = await buildSpiritFlixSmartRenamePlan({ path: path.join(tempRoot, "yes") });

    expect(plan.schema).toBe("spiritflix-smart-rename-plan/v1");
    expect(plan.applyEnabled).toBe(false);
    expect(plan.counts.ready).toBe(1);
    expect(plan.items[0]).toMatchObject({
      currentName: "old.mp4",
      suggestedName: "Better Name.mp4",
      readyForLevel2Preview: true,
      approvedTags: ["HD"],
      rejectedTagIds: ["watermark"],
    });
  });

  it("excludes rejected tags from generated filename suggestions", async () => {
    const videoPath = await writeVideo("yes/rejected-tag.mp4");
    await writeAnalysis(videoPath);

    const plan = await buildSpiritFlixSmartRenamePlan({ path: path.join(tempRoot, "yes") });

    expect(plan.items[0].suggestedName).toBe("Clean Clip HD.mp4");
    expect(plan.items[0].suggestedName).not.toMatch(/Watermark/i);
  });

  it("blocks unsafe sanitized filename suggestions", async () => {
    const videoPath = await writeVideo("yes/unsafe.mp4");
    await writeAnalysis(videoPath, {
      reviewedMetadata: {
        reviewedAt: "2026-06-19T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "../bad/name.mp4",
      },
    });

    const plan = await buildSpiritFlixSmartRenamePlan({ path: path.join(tempRoot, "yes") });

    expect(plan.items[0].status).toBe("blocked");
    expect(plan.items[0].warnings.join(" ")).toMatch(/slashes|traversal/i);
  });

  it("detects duplicate target names in the same plan", async () => {
    const first = await writeVideo("yes/a.mp4");
    const second = await writeVideo("yes/b.mp4");
    await writeAnalysis(first, {
      reviewedMetadata: {
        reviewedAt: "2026-06-19T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "Same Name.mp4",
      },
    });
    await writeAnalysis(second, {
      reviewedMetadata: {
        reviewedAt: "2026-06-19T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "Same Name.mp4",
      },
    });

    const plan = await buildSpiritFlixSmartRenamePlan({ path: path.join(tempRoot, "yes") });

    expect(plan.counts.collisions).toBe(2);
    expect(plan.items.every((item) => item.readyForLevel2Preview === false)).toBe(true);
  });

  it("detects existing target path conflicts", async () => {
    const videoPath = await writeVideo("yes/source.mp4");
    await writeVideo("yes/Existing.mp4");
    await writeAnalysis(videoPath, {
      reviewedMetadata: {
        reviewedAt: "2026-06-19T00:00:00.000Z",
        reviewedBy: "spiritflix-admin",
        reviewStatus: "reviewed",
        approvedTagIds: ["hd"],
        rejectedTagIds: [],
        editedFilenameSuggestion: "Existing.mp4",
      },
    });

    const plan = await buildSpiritFlixSmartRenamePlan({ path: path.join(tempRoot, "yes") });

    expect(plan.counts.target_conflicts).toBe(1);
    expect(plan.items.find((item) => item.currentName === "source.mp4")?.warnings).toContain("Target path already exists.");
  });

  it("skips unsupported or missing-analysis media instead of mutating files", async () => {
    await writeVideo("yes/no-analysis.mp4");
    await fs.writeFile(path.join(tempRoot, "yes/note.txt"), "not-video");

    const plan = await buildSpiritFlixSmartRenamePlan({ path: path.join(tempRoot, "yes") });

    expect(plan.counts.skipped).toBe(1);
    expect(plan.items[0].warnings).toContain("No smart analysis sidecar exists for this video.");
    expect(plan.applyEnabled).toBe(false);
  });
});

import path from "node:path";
import { describe, expect, it } from "vitest";
import { buildSmartRenamePreviewDraft } from "../rename-preview";

describe("SpiritFlix smart rename preview", () => {
  it("preserves original extension when suggestion has no extension", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mkv",
      filenameSuggestion: "Clean Title",
    });
    expect(draft.suggestedName).toBe("Clean Title.mkv");
  });

  it("preserves extension when suggestion already has matching extension", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mkv",
      filenameSuggestion: "Clean Title.mkv",
    });
    expect(draft.suggestedName).toBe("Clean Title.mkv");
  });

  it("rejects traversal segments in suggested name", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: "..something",
    });
    expect(draft.warnings).toContain("Filename suggestion contains traversal segments.");
    expect(draft.readyForLevel2Preview).toBe(false);
  });

  it("rejects slashes in suggested name", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: "bad/name",
    });
    expect(draft.warnings.some((w) => /slashes/i.test(w))).toBe(true);
  });

  it("warns if filename is unchanged", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: "video.mp4",
    });
    expect(draft.warnings).toContain("Suggested filename is unchanged from current filename.");
    expect(draft.readyForLevel2Preview).toBe(false);
  });

  it("warns if stem is generic", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/old.mp4",
      filenameSuggestion: "untitled",
    });
    expect(draft.warnings.some((w) => /generic/i.test(w))).toBe(true);
  });

  it("returns empty suggestion for empty input", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: "",
    });
    expect(draft.suggestedName).toBe("");
    expect(draft.warnings).toContain("Filename suggestion is empty.");
    expect(draft.readyForLevel2Preview).toBe(false);
  });

  it("target path stays in same folder", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: "New Name",
    });
    expect(draft.targetPath).toBe("/mnt/spirit-8tb/media/folder/New Name.mp4");
    expect(path.dirname(draft.targetPath)).toBe("/mnt/spirit-8tb/media/folder");
  });

  it("sanitizes unsafe filename characters", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: 'bad:name?.mp4',
    });
    expect(draft.suggestedName).toBe("bad name.mp4");
  });

  it("does not execute filesystem action (pure function)", () => {
    // This test confirms the function is pure â€” no fs import, no side effects.
    // If it imported fs or called any filesystem operation, this module would fail
    // to load in the test environment without mocking.
    expect(typeof buildSmartRenamePreviewDraft).toBe("function");
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: "Test",
    });
    expect(draft).toBeDefined();
    expect(draft.readyForLevel2Preview).toBe(true);
  });

  it("is ready for Level 2 preview when valid and changed", () => {
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/old-name.mp4",
      filenameSuggestion: "new-name",
    });
    expect(draft.readyForLevel2Preview).toBe(true);
    expect(draft.warnings).toHaveLength(0);
  });

  it("caps stem length", () => {
    const longStem = "A".repeat(300);
    const draft = buildSmartRenamePreviewDraft({
      sourcePath: "/mnt/spirit-8tb/media/folder/video.mp4",
      filenameSuggestion: longStem,
    });
    const stemOnly = draft.suggestedName.replace(/\.mp4$/, "");
    expect(stemOnly.length).toBeLessThanOrEqual(180);
  });
});

import { describe, expect, it } from "vitest";
import {
  applySmartReviewToAnalysis,
  sanitizeEditedFilenameSuggestion,
  validateSpiritFlixSmartReviewInput,
} from "../review-metadata";
import { validateSpiritFlixSmartAnalysis } from "../types";

const baseAnalysis = validateSpiritFlixSmartAnalysis({
  version: 1,
  videoPath: "/mnt/spirit-8tb/media/yes/clip.mp4",
  pathKey: "abc",
  fileName: "clip.mp4",
  fileSizeBytes: 100,
  mtimeMs: 1,
  analyzedAt: "2026-06-16T00:00:00.000Z",
  analyzerVersion: "spiritflix-smart/s3",
  status: "suggested",
  safety: { safeToSuggest: false, reasons: ["scanner"], requiresHumanReview: true },
  media: { durationSeconds: 90, width: 1280, height: 720, codec: "h264" },
  samples: [
    {
      timestampSeconds: 5,
      timestampLabel: "5s",
      cacheKey: "frame",
      observations: ["sampled frame"],
      tags: [],
      confidence: 0,
    },
  ],
  suggestedTags: [
    { id: "hd", label: "HD", group: "quality", confidence: 0.8, evidenceTimestamps: [], reviewRequired: false },
    { id: "short", label: "short", group: "format", confidence: 0.7, evidenceTimestamps: [], reviewRequired: false },
  ],
  suggestedDisplayTitle: "Clip",
  suggestedFilename: "Clip.mp4",
  suggestedCategory: "yes",
  confidence: 0.75,
  notes: "technical metadata collected | S3 heuristics used filename, path, and technical metadata only.",
});

describe("SpiritFlix smart review metadata", () => {
  it("applies valid review metadata to analysis", () => {
    const updated = applySmartReviewToAnalysis(baseAnalysis, {
      approvedTagIds: ["hd"],
      rejectedTagIds: ["short"],
      editedDisplayTitle: "Reviewed Clip",
      editedFilenameSuggestion: "Reviewed Clip.mp4",
      editedCategory: "yes",
      editedCollections: ["yes"],
      notes: "looks good",
    });

    expect(updated.reviewedMetadata?.reviewStatus).toBe("reviewed");
    expect(updated.reviewedMetadata?.approvedTagIds).toEqual(["hd"]);
    expect(updated.suggestedDisplayTitle).toBe("Clip");
    expect(updated.samples).toEqual(baseAnalysis.samples);
    expect(updated.notes).toContain("technical metadata collected");
  });

  it("rejects unknown tag ids", () => {
    expect(() =>
      validateSpiritFlixSmartReviewInput({ approvedTagIds: ["not-a-real-tag"], rejectedTagIds: [] }),
    ).toThrow(/known tag id/i);
  });

  it("rejects approved/rejected overlap", () => {
    expect(() =>
      validateSpiritFlixSmartReviewInput({ approvedTagIds: ["hd"], rejectedTagIds: ["hd"] }),
    ).toThrow(/overlap/i);
  });

  it("rejects tag ids not present in suggestedTags", () => {
    expect(() =>
      applySmartReviewToAnalysis(baseAnalysis, { approvedTagIds: ["solo"], rejectedTagIds: [] }),
    ).toThrow(/not in suggestedTags/i);
  });

  it("sanitizes edited filename suggestion and preserves extension", () => {
    expect(sanitizeEditedFilenameSuggestion('bad:name?.mp4', "clip.mp4")).toBe("bad name.mp4");
    expect(sanitizeEditedFilenameSuggestion("Title Only", "clip.mp4")).toBe("Title Only.mp4");
  });

  it("marks all rejected tags as rejected review status", () => {
    const updated = applySmartReviewToAnalysis(baseAnalysis, {
      approvedTagIds: [],
      rejectedTagIds: ["hd", "short"],
    });
    expect(updated.reviewedMetadata?.reviewStatus).toBe("rejected");
    expect(updated.status).toBe("rejected");
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { EventEmitter } from "node:events";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { createSmartAnalysisPathKey } from "../analysis-paths";

const mockSpawn = vi.hoisted(() => vi.fn());

vi.mock("../process", () => ({
  spawn: mockSpawn,
}));

import {
  buildSpiritFlixFrameCacheFileName,
  extractSpiritFlixFrameSample,
  getSpiritFlixFrameCachePath,
  planSpiritFlixSampleTimestamps,
} from "../sampler";

describe("SpiritFlix smart sampler", () => {
  let mediaRoot = "";
  let videoPath = "";
  let analysisKey = "";

  beforeEach(async () => {
    mockSpawn.mockReset();
    mediaRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-sampler-"));
    const videoDir = path.join(mediaRoot, "yes", "nested");
    await fs.mkdir(videoDir, { recursive: true });
    videoPath = path.join(videoDir, "clip.mp4");
    await fs.writeFile(videoPath, "fake-video");
    const stat = await fs.stat(videoPath);
    analysisKey = createSmartAnalysisPathKey({
      videoPath,
      fileSizeBytes: stat.size,
      mtimeMs: stat.mtimeMs,
    });
  });

  afterEach(async () => {
    await fs.rm(mediaRoot, { force: true, recursive: true });
  });

  it("plans timestamps for short, medium, and long videos", () => {
    const short = planSpiritFlixSampleTimestamps(12);
    const medium = planSpiritFlixSampleTimestamps(180);
    const long = planSpiritFlixSampleTimestamps(3_600);

    expect(short.length).toBeLessThanOrEqual(3);
    expect(medium.length).toBeLessThanOrEqual(6);
    expect(long.length).toBeLessThanOrEqual(16);
    expect(short.length).toBeGreaterThan(0);
  });

  it("never produces negative or past-duration timestamps", () => {
    const duration = 42;
    const timestamps = planSpiritFlixSampleTimestamps(duration);
    for (const value of timestamps) {
      expect(value).toBeGreaterThanOrEqual(0);
      expect(value).toBeLessThanOrEqual(duration);
    }
  });

  it("de-dupes and stays deterministic", () => {
    const first = planSpiritFlixSampleTimestamps(120);
    const second = planSpiritFlixSampleTimestamps(120);
    expect(first).toEqual(second);
    expect(new Set(first).size).toBe(first.length);
  });

  it("builds deterministic frame cache paths under analysis-cache/frames", () => {
    const framePath = getSpiritFlixFrameCachePath(analysisKey, 12_345, { mediaRoot });
    expect(framePath).toContain(path.join(".spiritflix-admin", "analysis-cache", "frames"));
    expect(path.basename(framePath)).toBe(buildSpiritFlixFrameCacheFileName(analysisKey, 12_345));
    expect(framePath.endsWith("-v1.jpg")).toBe(true);
  });

  it("uses different paths for different timestamps", () => {
    const a = getSpiritFlixFrameCachePath(analysisKey, 1_000, { mediaRoot });
    const b = getSpiritFlixFrameCachePath(analysisKey, 2_000, { mediaRoot });
    expect(a).not.toBe(b);
  });

  it("rejects traversal through invalid analysis keys", () => {
    expect(() => getSpiritFlixFrameCachePath("../evil", 0, { mediaRoot })).toThrow(/sha256/i);
  });

  it("returns cached frame without spawn when cache exists", async () => {
    const framePath = getSpiritFlixFrameCachePath(analysisKey, 5_000, { mediaRoot });
    await fs.mkdir(path.dirname(framePath), { recursive: true });
    await fs.writeFile(framePath, Buffer.from("cached-jpeg"));

    const sample = await extractSpiritFlixFrameSample(videoPath, 5, {
      mediaRoot,
      analysisKey,
    });
    expect(sample.framePath).toBe(framePath);
    expect(mockSpawn).not.toHaveBeenCalled();
  });

  it("extracts via temp file then atomic rename", async () => {
    mockSpawn.mockImplementation((_cmd, args) => {
      const outputPath = args?.[args.length - 1] as string;
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();
      queueMicrotask(async () => {
        await fs.writeFile(outputPath, Buffer.from("fresh-jpeg"));
        emitter.emit("close", 0);
      });
      return emitter;
    });

    const sample = await extractSpiritFlixFrameSample(videoPath, 3.5, {
      mediaRoot,
      ffmpegPath: "/usr/bin/ffmpeg",
      analysisKey,
    });
    const stat = await fs.stat(sample.framePath);
    expect(stat.size).toBeGreaterThan(0);
    expect(sample.framePath).not.toBe(path.dirname(videoPath));
    expect(sample.cacheKey).toContain(analysisKey);
  });

  it("handles ffmpeg timeout and cleans temp file", async () => {
    mockSpawn.mockImplementation(() => {
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();
      return emitter;
    });

    await expect(
      extractSpiritFlixFrameSample(videoPath, 1, { mediaRoot, ffmpegPath: "/usr/bin/ffmpeg", timeoutMs: 1, analysisKey }),
    ).rejects.toThrow(/timed out/i);

    const framesRoot = path.join(mediaRoot, ".spiritflix-admin", "analysis-cache", "frames");
    const entries = await fs.readdir(framesRoot);
    expect(entries.some((entry) => entry.includes(".tmp.jpg"))).toBe(false);
  });

  it("cleans temp file on ffmpeg failure", async () => {
    mockSpawn.mockImplementation(() => {
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();
      queueMicrotask(() => emitter.emit("close", 1));
      return emitter;
    });

    await expect(
      extractSpiritFlixFrameSample(videoPath, 2, { mediaRoot, ffmpegPath: "/usr/bin/ffmpeg", analysisKey }),
    ).rejects.toThrow(/failed/i);
  });

  it("rejects non-video and outside-root paths", async () => {
    const txtPath = path.join(mediaRoot, "yes", "notes.txt");
    await fs.writeFile(txtPath, "nope");
    await expect(extractSpiritFlixFrameSample(txtPath, 1, { mediaRoot })).rejects.toThrow(/video files/i);
    await expect(extractSpiritFlixFrameSample("/tmp/outside.mp4", 1, { mediaRoot })).rejects.toThrow(/outside/i);
  });

  it("does not write beside the video file", async () => {
    mockSpawn.mockImplementation((_cmd, args) => {
      const outputPath = args?.[args.length - 1] as string;
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();
      queueMicrotask(async () => {
        await fs.writeFile(outputPath, Buffer.from("jpeg"));
        emitter.emit("close", 0);
      });
      return emitter;
    });

    const sample = await extractSpiritFlixFrameSample(videoPath, 4, { mediaRoot, analysisKey });
    expect(path.dirname(sample.framePath)).not.toBe(path.dirname(videoPath));
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { EventEmitter } from "node:events";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { getSmartAnalysisRoot } from "../analysis-paths";
import { readSmartAnalysis } from "../analysis-store";

const mockSpawn = vi.hoisted(() => vi.fn());

vi.mock("../process", () => ({
  spawn: mockSpawn,
}));

import { scanOneSpiritFlixVideoEvidence, SPIRITFLIX_SMART_ANALYZER_VERSION_S2 } from "../scanner";

const SAMPLE_FFPROBE = {
  format: { duration: "90.0", format_name: "mp4", bit_rate: "2000000" },
  streams: [{ codec_type: "video", codec_name: "h264", width: 1280, height: 720, avg_frame_rate: "24/1" }],
};

describe("SpiritFlix smart scanner", () => {
  let mediaRoot = "";
  let videoPath = "";

  beforeEach(async () => {
    mockSpawn.mockReset();
    mediaRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-scanner-"));
    const videoDir = path.join(mediaRoot, "yes", "nested");
    await fs.mkdir(videoDir, { recursive: true });
    videoPath = path.join(videoDir, "sample.mp4");
    await fs.writeFile(videoPath, "fake-video-bytes");
  });

  afterEach(async () => {
    await fs.rm(mediaRoot, { force: true, recursive: true });
  });

  function mockProbeAndFrames(frameSuccess = true) {
    mockSpawn.mockImplementation((_cmd, args) => {
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();

      const isFfprobe = Array.isArray(args) && args.includes("-show_streams");
      queueMicrotask(async () => {
        if (isFfprobe) {
          emitter.stdout.emit("data", Buffer.from(JSON.stringify(SAMPLE_FFPROBE)));
          emitter.emit("close", 0);
          return;
        }
        const outputPath = args?.[args.length - 1] as string;
        if (frameSuccess) {
          await fs.writeFile(outputPath, Buffer.from("jpeg"));
          emitter.emit("close", 0);
        } else {
          emitter.emit("close", 1);
        }
      });
      return emitter;
    });
  }

  it("updates media metadata and writes sidecar under temp media root", async () => {
    mockProbeAndFrames();
    const analysis = await scanOneSpiritFlixVideoEvidence(videoPath, {
      mediaRoot,
      ffprobePath: "/usr/bin/ffprobe",
      ffmpegPath: "/usr/bin/ffmpeg",
      maxSamples: 3,
    });

    expect(analysis.media.durationSeconds).toBe(90);
    expect(analysis.media.codec).toBe("h264");
    expect(analysis.analyzerVersion).toBe(SPIRITFLIX_SMART_ANALYZER_VERSION_S2);

    const stat = await fs.stat(videoPath);
    const stored = await readSmartAnalysis(
      { videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs },
      { mediaRoot },
    );
    expect(stored?.pathKey).toBe(analysis.pathKey);
    const sidecarPath = path.join(getSmartAnalysisRoot({ mediaRoot }), `${analysis.pathKey}.json`);
    await expect(fs.stat(sidecarPath)).resolves.toBeDefined();
  });

  it("creates bounded samples with empty tags and needs_review status", async () => {
    mockProbeAndFrames();
    const analysis = await scanOneSpiritFlixVideoEvidence(videoPath, {
      mediaRoot,
      ffprobePath: "/usr/bin/ffprobe",
      ffmpegPath: "/usr/bin/ffmpeg",
      maxSamples: 4,
    });

    expect(analysis.status).toBe("needs_review");
    expect(analysis.samples.length).toBeGreaterThan(0);
    expect(analysis.samples.length).toBeLessThanOrEqual(4);
    for (const sample of analysis.samples) {
      expect(sample.observations).toContain("sampled frame");
      expect(sample.tags).toEqual([]);
      expect(sample.confidence).toBe(0);
      expect(sample.cacheKey).toBeTruthy();
    }
  });

  it("leaves suggested tags/filename/category empty", async () => {
    mockProbeAndFrames();
    const analysis = await scanOneSpiritFlixVideoEvidence(videoPath, {
      mediaRoot,
      ffprobePath: "/usr/bin/ffprobe",
      ffmpegPath: "/usr/bin/ffmpeg",
      maxSamples: 2,
    });

    expect(analysis.suggestedTags).toEqual([]);
    expect(analysis.suggestedFilename).toBeUndefined();
    expect(analysis.suggestedCategory).toBeUndefined();
    expect(analysis.confidence).toBe(0);
    expect(analysis.safety.requiresHumanReview).toBe(true);
  });

  it("does not import Level 2 action executors", async () => {
    const scannerSource = await fs.readFile(path.join(process.cwd(), "src/lib/spiritflix/admin/smart/scanner.ts"), "utf8");
    expect(scannerSource).not.toMatch(/level-?2|executeSpiritFlix|previewAction|confirmAction/i);
  });

  it("handles partial sample failure while keeping metadata sidecar", async () => {
    let ffmpegCalls = 0;
    mockSpawn.mockImplementation((_cmd, args) => {
      const emitter = new EventEmitter() as EventEmitter & { stdout: EventEmitter; stderr: EventEmitter; kill: () => void };
      emitter.stdout = new EventEmitter();
      emitter.stderr = new EventEmitter();
      emitter.kill = vi.fn();
      const isFfprobe = Array.isArray(args) && args.includes("-show_streams");
      queueMicrotask(async () => {
        if (isFfprobe) {
          emitter.stdout.emit("data", Buffer.from(JSON.stringify(SAMPLE_FFPROBE)));
          emitter.emit("close", 0);
          return;
        }
        ffmpegCalls += 1;
        const outputPath = args?.[args.length - 1] as string;
        if (ffmpegCalls % 2 === 0) {
          await fs.writeFile(outputPath, Buffer.from("jpeg"));
          emitter.emit("close", 0);
        } else {
          emitter.emit("close", 1);
        }
      });
      return emitter;
    });

    const analysis = await scanOneSpiritFlixVideoEvidence(videoPath, {
      mediaRoot,
      ffprobePath: "/usr/bin/ffprobe",
      ffmpegPath: "/usr/bin/ffmpeg",
      maxSamples: 4,
    });

    expect(analysis.media.codec).toBe("h264");
    expect(analysis.status).toBe("needs_review");
    expect(analysis.samples.length).toBeGreaterThan(0);
    expect(analysis.samples.length).toBeLessThan(4);
    expect(analysis.notes).toMatch(/frame failures/i);
  });
});

import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { createSmartAnalysisPathKey, getSmartAnalysisRoot } from "../analysis-paths";
import { writeSmartAnalysis } from "../analysis-store";
import {
  applySpiritFlixReviewSuggestionsToAnalysis,
  buildSpiritFlixReviewSuggestions,
  buildSuggestedFilename,
  updateSmartAnalysisWithHeuristicSuggestions,
} from "../suggestions";
import { validateSpiritFlixSmartAnalysis } from "../types";

describe("SpiritFlix smart suggestions", () => {
  let mediaRoot = "";
  let videoPath = "";

  beforeEach(async () => {
    mediaRoot = await fs.mkdtemp(path.join(os.tmpdir(), "spiritflix-s3-"));
    const videoDir = path.join(mediaRoot, "yes", "nested");
    await fs.mkdir(videoDir, { recursive: true });
    videoPath = path.join(videoDir, "360 1.mp4");
    await fs.writeFile(videoPath, "fake-video");
  });

  afterEach(async () => {
    await fs.rm(mediaRoot, { force: true, recursive: true });
  });

  it("builds review-only suggestions for short ambiguous filenames", () => {
    const result = buildSpiritFlixReviewSuggestions({
      videoPath,
      fileName: "360 1.mp4",
      parentPath: path.dirname(videoPath),
    });

    expect(result.suggestedDisplayTitle).toBe("Unknown Model - Untitled 01");
    expect(result.suggestedFilename).toBe("Unknown Model - Untitled 01");
    expect(result.notes.some((note) => /insufficient filename context/i.test(note))).toBe(true);
    expect(result.notes.some((note) => /needs title cleanup status/i.test(note))).toBe(true);
    expect(result.suggestedTags.some((tag) => tag.id === "needs-title-cleanup")).toBe(false);
    expect(result.suggestedTags.some((tag) => tag.id === "unknown-performer")).toBe(false);
    expect(result.performerIdentity.name).toBe("Unknown Model");
  });

  it("preserves readable titles while excluding technical metadata from primary tags", () => {
    const messyPath = path.join(mediaRoot, "yes", "Example.Site.Name.1080p.x264.mp4");
    const result = buildSpiritFlixReviewSuggestions({
      videoPath: messyPath,
      fileName: "Example.Site.Name.1080p.x264.mp4",
      parentPath: path.join(mediaRoot, "yes"),
      media: { width: 1920, height: 1080, durationSeconds: 600 },
    });

    expect(result.suggestedDisplayTitle).toBe("Example Site Name");
    expect(result.suggestedFilename).toBe("Example Site Name");
    expect(result.suggestedTags.some((tag) => tag.id === "full-hd")).toBe(false);
    expect(result.contentTagEvidence.find((entry) => entry.source === "metadata")?.tags).toContain("full-hd");
    expect(result.suggestedCategory).toBe("yes");
    expect(result.confidence).toBeGreaterThan(0);
  });

  it("omits file extension in suggested display filename", () => {
    const mkvPath = path.join(mediaRoot, "movies", "title.mkv");
    const filename = buildSuggestedFilename(
      { videoPath: mkvPath, fileName: "title.mkv" },
      [],
    );
    expect(filename).toBe("title");
  });

  it("sanitizes suggested filename", () => {
    const filename = buildSuggestedFilename(
      { videoPath, fileName: 'bad:name?.mp4' },
      [],
    );
    expect(filename).not.toMatch(/[:?]/);
    expect(filename).not.toMatch(/\.mp4$/);
  });

  it("keeps suggested filename concise", () => {
    const longStem = "a".repeat(200);
    const filename = buildSuggestedFilename(
      { videoPath, fileName: `${longStem}.mp4` },
      [],
    );
    expect(filename.length).toBeLessThanOrEqual(120);
  });

  it("sets reviewRequired on uncertain source tags", () => {
    const result = buildSpiritFlixReviewSuggestions({
      videoPath: path.join(mediaRoot, "yes", "onlyfans.clip.mp4"),
      fileName: "onlyfans.clip.mp4",
      parentPath: path.join(mediaRoot, "yes"),
    });
    expect(result.suggestedTags.find((tag) => tag.id === "site-token")).toBeUndefined();
    expect(result.contentTagEvidence.find((entry) => entry.source === "metadata")?.tags).toContain("site-token");
  });

  it("uses model folder identity for random/hash filenames", () => {
    const randomPath = path.join(mediaRoot, "yes", "models", "aaliyah-yasan", "HkkzMtwQexuQzwkQMekM.mkv");
    const result = buildSpiritFlixReviewSuggestions({
      videoPath: randomPath,
      fileName: "HkkzMtwQexuQzwkQMekM.mkv",
      parentPath: path.dirname(randomPath),
    });

    expect(result.performerIdentity).toMatchObject({ name: "Aaliyah Yasan", source: "path" });
    expect(result.suggestedDisplayTitle).toBe("Aaliyah Yasan - Untitled 01");
    expect(result.suggestedFilename).toBe("Aaliyah Yasan - Untitled 01");
  });

  it("uses model and visual tags for source-spam filenames", () => {
    const spamPath = path.join(mediaRoot, "yes", "models", "aaliyah-yasan", "Visit onlyshare.io for MORE 130.mkv");
    const result = buildSpiritFlixReviewSuggestions({
      videoPath: spamPath,
      fileName: "Visit onlyshare.io for MORE 130.mkv",
      parentPath: path.dirname(spamPath),
    }, {
      analysis: validateSpiritFlixSmartAnalysis({
        version: 1,
        videoPath: spamPath,
        pathKey: "abc",
        fileName: "Visit onlyshare.io for MORE 130.mkv",
        fileSizeBytes: 10,
        mtimeMs: 1,
