// â”€â”€ SpiritFlix Smart Metadata Bridge (S6) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Projects approved smart metadata into admin metadata sidecars.
// Writes under .spiritflix-admin/metadata/ only â€” never beside video.
// Never mutates actual filename. Never calls Level 2 execute.

import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import { SPIRITFLIX_MEDIA_ROOT } from "../constants";
import { isKnownSmartTagId } from "./vocabulary";
import type {
  SpiritFlixSmartAnalysis,
  SpiritFlixSmartReviewStatus,
  SpiritFlixSmartTag,
} from "./types";

// â”€â”€ Projection type â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export interface SpiritFlixApprovedMetadataProjection {
  sourcePath: string;
  displayTitle?: string;
  filenameSuggestion?: string;
  category?: string;
  collections: string[];
  approvedTags: Array<{
    id: string;
    label: string;
    group: string;
    confidence: number;
  }>;
  rejectedTagIds: string[];
  reviewStatus: string;
  reviewedAt?: string;
  notes?: string;
}

// â”€â”€ Metadata sidecar path helper â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Mirrors the exact sha256(normalized-lowercased-forward-slash-path)
// convention used by Level 2 writeMetadata in actions.ts.

export function metadataSidecarPath(
  sourcePath: string,
  mediaRoot?: string,
): string {
  const root = path.resolve(mediaRoot ?? SPIRITFLIX_MEDIA_ROOT);
  const normalizedSourcePath = sourcePath
    .replace(/\\/g, "/")
    .replace(/^[A-Za-z]:(?=\/)/, "")
    .toLowerCase();
  const hash = crypto
    .createHash("sha256")
    .update(normalizedSourcePath)
    .digest("hex");
  return path.join(root, ".spiritflix-admin", "metadata", `${hash}.json`);
}

// â”€â”€ Pure projection â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export function projectApprovedSmartMetadata(
  analysis: SpiritFlixSmartAnalysis,
): SpiritFlixApprovedMetadataProjection {
  const reviewed = analysis.reviewedMetadata;
  const reviewStatus: SpiritFlixSmartReviewStatus =
    reviewed?.reviewStatus ?? "unreviewed";

  // Approved tags: must be in suggestedTags AND approvedTagIds AND vocabulary-valid
  const approvedSet = new Set(reviewed?.approvedTagIds ?? []);
  const approvedTags: SpiritFlixApprovedMetadataProjection["approvedTags"] =
    analysis.suggestedTags
      .filter((tag) => approvedSet.has(tag.id) && isKnownSmartTagId(tag.id))
      .map((tag) => ({
        id: tag.id,
        label: tag.label,
        group: tag.group,
        confidence: tag.confidence,
      }));

  // Edited values override suggestions
  const displayTitle = reviewed?.editedDisplayTitle ?? analysis.suggestedDisplayTitle;
  const filenameSuggestion = reviewed?.editedFilenameSuggestion ?? analysis.suggestedFilename;
  const category = reviewed?.editedCategory ?? analysis.suggestedCategory;
  const collections = reviewed?.editedCollections ?? analysis.suggestedCollections ?? [];
  const notes = reviewed?.notes;

  return {
    sourcePath: analysis.videoPath,
    displayTitle,
    filenameSuggestion,
    category,
    collections,
    approvedTags,
    rejectedTagIds: reviewed?.rejectedTagIds ?? [],
    reviewStatus,
    reviewedAt: reviewed?.reviewedAt,
    notes,
  };
}

// â”€â”€ Write admin metadata sidecar â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Writes to the same Level 2 metadata sidecar store:
//   .spiritflix-admin/metadata/<sha256>.json
// Preserves any existing sidecar fields (read-merge-write).
// Stores the full smart projection under `smartApproved` key.

export async function writeApprovedSmartMetadataSidecar(
  analysis: SpiritFlixSmartAnalysis,
  options?: { mediaRoot?: string },
): Promise<{ path: string; metadata: SpiritFlixApprovedMetadataProjection }> {
  const projection = projectApprovedSmartMetadata(analysis);
  const targetPath = metadataSidecarPath(projection.sourcePath, options?.mediaRoot);

  // Read existing sidecar to preserve non-smart fields
  let existing: Record<string, unknown> = {};
  try {
    const raw = await fs.readFile(targetPath, "utf-8");
    const parsed = JSON.parse(raw) as unknown;
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      existing = parsed as Record<string, unknown>;
    }
  } catch {
    // No existing sidecar â€” that's fine
  }

  // Build merged sidecar: Level 2 fields + smart projection
  const merged: Record<string, unknown> = {
    ...existing,
    sourcePath: projection.sourcePath,
    displayTitle: projection.displayTitle,
    displayNameOverride: projection.displayTitle,
    smartDisplayName: projection.displayTitle,
    customTags: projection.approvedTags.map((tag) => tag.label),
    smartTagIds: projection.approvedTags.map((tag) => tag.id),
    collection: projection.category,
    notes: projection.notes,
    smartApproved: projection,
  };

  // Atomic write: temp file + rename (mirrors actions.ts pattern)
  await fs.mkdir(path.dirname(targetPath), { recursive: true });
  const tmpPath = `${targetPath}.tmp-${Date.now()}`;
  await fs.writeFile(tmpPath, JSON.stringify(merged, null, 2), "utf-8");
  await fs.rename(tmpPath, targetPath);

  return { path: targetPath, metadata: projection };
}

import path from "node:path";
import { assertSmartVideoPathCandidate, type SpiritFlixSmartPathOptions } from "./analysis-paths";
import { SpiritFlixSmartProbeError } from "./errors";
import { spawn } from "./process";

export const SPIRITFLIX_SMART_VIDEO_EXTENSIONS = new Set([".avi", ".m4v", ".mkv", ".mov", ".mp4", ".webm"]);

const DEFAULT_PROBE_TIMEOUT_MS = 10_000;
const MAX_FFPROBE_OUTPUT_BYTES = 512_000;

export interface SpiritFlixProbeResult {
  durationSeconds?: number;
  width?: number;
  height?: number;
  codec?: string;
  container?: string;
  formatName?: string;
  bitRate?: number;
  frameRate?: number;
}

export interface SpiritFlixProbeOptions {
  timeoutMs?: number;
  ffprobePath?: string;
  mediaRoot?: string;
}

export function isSpiritFlixSmartVideoExtension(extension: string): boolean {
  return SPIRITFLIX_SMART_VIDEO_EXTENSIONS.has(extension.toLowerCase());
}

export function parseRationalFrameRate(value: string | undefined): number | undefined {
  if (!value || value === "0/0" || value === "N/A") return undefined;
  if (!value.includes("/")) {
    const parsed = Number(value);
    return Number.isFinite(parsed) && parsed > 0 ? parsed : undefined;
  }
  const [numRaw, denRaw] = value.split("/");
  const num = Number(numRaw);
  const den = Number(denRaw);
  if (!Number.isFinite(num) || !Number.isFinite(den) || den === 0) return undefined;
  const rate = num / den;
  return rate > 0 ? rate : undefined;
}

export function parseFfprobeJson(payload: unknown): SpiritFlixProbeResult {
  if (!payload || typeof payload !== "object") {
    throw new SpiritFlixSmartProbeError("ffprobe returned invalid JSON.");
  }

  const record = payload as {
    format?: { duration?: string; format_name?: string; bit_rate?: string };
    streams?: Array<{
      codec_type?: string;
      codec_name?: string;
      width?: number;
      height?: number;
      duration?: string;
      avg_frame_rate?: string;
      r_frame_rate?: string;
    }>;
  };

  const format = record.format ?? {};
  const videoStream = record.streams?.find((stream) => stream.codec_type === "video");

  const durationSeconds = parsePositiveNumber(format.duration) ?? parsePositiveNumber(videoStream?.duration);
  const width = parsePositiveInt(videoStream?.width);
  const height = parsePositiveInt(videoStream?.height);
  const codec = videoStream?.codec_name?.trim() || undefined;
  const formatName = format.format_name?.trim() || undefined;
  const bitRate = parsePositiveInt(format.bit_rate);
  const frameRate =
    parseRationalFrameRate(videoStream?.avg_frame_rate) ?? parseRationalFrameRate(videoStream?.r_frame_rate);

  if (!durationSeconds && !width && !height && !codec && !formatName) {
    throw new SpiritFlixSmartProbeError("ffprobe did not return usable video metadata.");
  }

  return {
    durationSeconds,
    width,
    height,
    codec,
    container: formatName,
    formatName,
    bitRate,
    frameRate,
  };
}

function parsePositiveNumber(value: string | undefined): number | undefined {
  if (!value) return undefined;
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? parsed : undefined;
}

function parsePositiveInt(value: number | string | undefined): number | undefined {
  if (value === undefined) return undefined;
  const parsed = typeof value === "number" ? value : Number(value);
  if (!Number.isFinite(parsed) || parsed <= 0) return undefined;
  return Math.trunc(parsed);
}

function runFfprobe(
  ffprobePath: string,
  videoPath: string,
  timeoutMs: number,
): Promise<{ stdout: string; stderr: string; code: number | null; timedOut: boolean; spawnError?: Error }> {
  return new Promise((resolve) => {
    const args = ["-v", "error", "-print_format", "json", "-show_format", "-show_streams", videoPath];
    const proc = spawn(ffprobePath, args, { shell: false });
    let stdout = "";
    let stderr = "";
    let timedOut = false;
    let settled = false;

    const finish = (result: { stdout: string; stderr: string; code: number | null; timedOut: boolean; spawnError?: Error }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };

    const timer = setTimeout(() => {
      timedOut = true;
      proc.kill("SIGKILL");
      finish({ stdout, stderr, code: null, timedOut });
    }, timeoutMs);

    proc.stdout.on("data", (chunk: Buffer) => {
      stdout += chunk.toString("utf8");
      if (stdout.length > MAX_FFPROBE_OUTPUT_BYTES) {
        proc.kill("SIGKILL");
      }
    });
    proc.stderr.on("data", (chunk: Buffer) => {
      stderr += chunk.toString("utf8");
      if (stderr.length > 8_192) stderr = stderr.slice(-8_192);
    });

    proc.on("error", (error) => {
      finish({ stdout, stderr, code: null, timedOut, spawnError: error });
    });

    proc.on("close", (code) => {
      finish({ stdout, stderr, code, timedOut });
    });
  });
}

export async function probeSpiritFlixVideo(
  videoPath: string,
  options?: SpiritFlixProbeOptions,
): Promise<SpiritFlixProbeResult> {
  const pathOptions: SpiritFlixSmartPathOptions | undefined = options?.mediaRoot
    ? { mediaRoot: options.mediaRoot }
    : undefined;
  const resolvedPath = assertSmartVideoPathCandidate(videoPath, pathOptions);
  const extension = path.extname(resolvedPath).toLowerCase();
  if (!isSpiritFlixSmartVideoExtension(extension)) {
    throw new SpiritFlixSmartProbeError("SpiritFlix smart probe only supports video files.");
  }

  const ffprobePath = options?.ffprobePath ?? "ffprobe";
  const timeoutMs = options?.timeoutMs ?? DEFAULT_PROBE_TIMEOUT_MS;
  const result = await runFfprobe(ffprobePath, resolvedPath, timeoutMs);

  if (result.spawnError) {
    if ((result.spawnError as NodeJS.ErrnoException).code === "ENOENT") {
      throw new SpiritFlixSmartProbeError("ffprobe is not available on this host.");
    }
    throw new SpiritFlixSmartProbeError("ffprobe failed to start.");
  }
  if (result.timedOut) {
    throw new SpiritFlixSmartProbeError("ffprobe timed out.");
  }
  if (result.code !== 0) {
    throw new SpiritFlixSmartProbeError("ffprobe exited with an error.");
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(result.stdout);
  } catch {
    throw new SpiritFlixSmartProbeError("ffprobe returned invalid JSON.");
  }

  return parseFfprobeJson(parsed);
}

// SpiritFlix smart rename plan (S8)
// Builds preview/export data only. It never renames, moves, or calls Level 2 execute.

import fs from "node:fs/promises";
import path from "node:path";
import { resolveSpiritFlixAdminPath } from "../paths";
import { readSmartAnalysis } from "./analysis-store";
import { buildSmartRenamePreviewDraft } from "./rename-preview";
import { isSpiritFlixSmartVideoExtension } from "./probe";
import { projectApprovedSmartMetadata } from "./metadata-bridge";
import type { SpiritFlixApprovedMetadataProjection } from "./metadata-bridge";
import type { SpiritFlixSmartAnalysis } from "./types";

export type SpiritFlixSmartRenamePlanItemStatus =
  | "ready"
  | "blocked"
  | "needs_review"
  | "skipped";

export interface SpiritFlixSmartRenamePlanItem {
  sourcePath: string;
  currentName: string;
  suggestedName?: string;
  targetPath?: string;
  status: SpiritFlixSmartRenamePlanItemStatus;
  reviewStatus: string;
  approvedTags: string[];
  rejectedTagIds: string[];
  warnings: string[];
  readyForLevel2Preview: boolean;
}

export interface SpiritFlixSmartRenamePlanCounts {
  candidates: number;
  ready: number;
  blocked: number;
  needs_review: number;
  skipped: number;
  collisions: number;
  target_conflicts: number;
}

export interface SpiritFlixSmartRenamePlan {
  schema: "spiritflix-smart-rename-plan/v1";
  generatedAt: string;
  rootPath: string;
  recursive: boolean;
  maxItems: number;
  applyEnabled: false;
  applyGate: string;
  items: SpiritFlixSmartRenamePlanItem[];
  counts: SpiritFlixSmartRenamePlanCounts;
}

export interface SpiritFlixSmartRenamePlanOptions {
  path?: string;
  paths?: string[];
  recursive?: boolean;
  maxItems?: number;
  mediaRoot?: string;
}

interface PlanTarget {
  videoPath: string;
  mediaRoot?: string;
}

const DEFAULT_PLAN_LIMIT = 50;
const MAX_PLAN_LIMIT = 200;

function boundedLimit(value: number | undefined): number {
  if (!Number.isFinite(value ?? NaN)) return DEFAULT_PLAN_LIMIT;
  return Math.max(1, Math.min(MAX_PLAN_LIMIT, Math.floor(value ?? DEFAULT_PLAN_LIMIT)));
}

function emptyCounts(): SpiritFlixSmartRenamePlanCounts {
  return {
    candidates: 0,
    ready: 0,
    blocked: 0,
    needs_review: 0,
    skipped: 0,
    collisions: 0,
    target_conflicts: 0,
  };
}

function summarize(items: SpiritFlixSmartRenamePlanItem[]): SpiritFlixSmartRenamePlanCounts {
  const counts = emptyCounts();
  for (const item of items) {
    counts.candidates += 1;
    if (item.status === "ready") counts.ready += 1;
    if (item.status === "blocked") counts.blocked += 1;
    if (item.status === "needs_review") counts.needs_review += 1;
    if (item.status === "skipped") counts.skipped += 1;
    if (item.warnings.some((warning) => /duplicate target/i.test(warning))) counts.collisions += 1;
    if (item.warnings.some((warning) => /target path already exists/i.test(warning))) counts.target_conflicts += 1;
  }
  return counts;
}

function isHiddenPathPart(name: string): boolean {
  return name.startsWith(".");
}

async function enumerateFolder(folderPath: string, recursive: boolean, maxItems: number, mediaRoot?: string): Promise<PlanTarget[]> {
  const found: PlanTarget[] = [];
  const pending = [folderPath];

  while (pending.length > 0 && found.length < maxItems) {
    const current = pending.shift()!;
    const entries = await fs.readdir(current, { withFileTypes: true });
    for (const entry of entries) {
      if (isHiddenPathPart(entry.name)) continue;
      const childPath = path.join(current, entry.name);
      if (entry.isDirectory()) {
        if (recursive) pending.push(childPath);
        continue;
      }
      if (!entry.isFile()) continue;
      if (!isSpiritFlixSmartVideoExtension(path.extname(entry.name).toLowerCase())) continue;
      found.push({ videoPath: childPath, mediaRoot });
      if (found.length >= maxItems) break;
    }
  }

  return found;
}

async function resolvePlanTargets(options: SpiritFlixSmartRenamePlanOptions, maxItems: number): Promise<{ rootPath: string; targets: PlanTarget[] }> {
  const requestedPaths = (options.paths ?? []).map((entry) => entry.trim()).filter(Boolean);
  if (requestedPaths.length > 0) {
    const targets: PlanTarget[] = [];
    for (const requested of requestedPaths.slice(0, maxItems)) {
      const { allowedRoot, realPath } = await resolveSpiritFlixAdminPath(requested);
      const stat = await fs.stat(realPath);
      if (stat.isFile() && isSpiritFlixSmartVideoExtension(path.extname(realPath).toLowerCase())) {
        targets.push({ videoPath: realPath, mediaRoot: options.mediaRoot ?? allowedRoot });
      }
    }
    return { rootPath: path.dirname(targets[0]?.videoPath ?? requestedPaths[0]), targets };
  }

  const { allowedRoot, realPath } = await resolveSpiritFlixAdminPath(options.path);
  const mediaRoot = options.mediaRoot ?? allowedRoot;
  const stat = await fs.stat(realPath);
  if (stat.isFile()) {
    return {
      rootPath: path.dirname(realPath),
      targets: isSpiritFlixSmartVideoExtension(path.extname(realPath).toLowerCase()) ? [{ videoPath: realPath, mediaRoot }] : [],
    };
  }
  if (!stat.isDirectory()) throw new Error("Smart rename plan requires a folder or video selection.");
  return { rootPath: realPath, targets: await enumerateFolder(realPath, Boolean(options.recursive), maxItems, mediaRoot) };
}

function reviewedFilenameSuggestion(
  analysis: SpiritFlixSmartAnalysis,
  projection: SpiritFlixApprovedMetadataProjection,
): string | undefined {
  const reviewed = analysis.reviewedMetadata;
  if (reviewed?.editedFilenameSuggestion) return reviewed.editedFilenameSuggestion;

  const base = reviewed?.editedDisplayTitle ?? analysis.suggestedDisplayTitle ?? path.parse(analysis.fileName).name;
  const approvedLabels = projection.approvedTags.map((tag) => tag.label).filter(Boolean);
  if (approvedLabels.length === 0) return projection.filenameSuggestion ?? base;

  const suffix = approvedLabels.slice(0, 3).filter((label) => !base.toLowerCase().includes(label.toLowerCase())).join(" ");
  return suffix ? `${base} ${suffix}` : base;
}

async function targetExists(targetPath: string, sourcePath: string): Promise<boolean> {
  if (path.resolve(targetPath) === path.resolve(sourcePath)) return false;
  try {
    await fs.access(targetPath);
    return true;
  } catch {
    return false;
  }
}

async function itemFromTarget(target: PlanTarget): Promise<SpiritFlixSmartRenamePlanItem> {
  const stat = await fs.stat(target.videoPath);
  const analysis = await readSmartAnalysis(
    { videoPath: target.videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs },
    target.mediaRoot ? { mediaRoot: target.mediaRoot } : undefined,
  );
  if (!analysis) {
    return {
      sourcePath: target.videoPath,
      currentName: path.basename(target.videoPath),
      status: "skipped",
      reviewStatus: "missing_analysis",
      approvedTags: [],
      rejectedTagIds: [],
      warnings: ["No smart analysis sidecar exists for this video."],
      readyForLevel2Preview: false,
    };
  }

  const reviewStatus = analysis.reviewedMetadata?.reviewStatus ?? "unreviewed";
  if (reviewStatus === "unreviewed") {
    return {
      sourcePath: target.videoPath,
      currentName: path.basename(target.videoPath),
      status: "needs_review",
      reviewStatus,
      approvedTags: [],
      rejectedTagIds: [],
      warnings: ["Analysis must be reviewed before rename preview."],
      readyForLevel2Preview: false,
    };
  }

  const projection = projectApprovedSmartMetadata(analysis);
  const filenameSuggestion = reviewedFilenameSuggestion(analysis, projection);
  if (!filenameSuggestion || projection.reviewStatus === "rejected") {
    return {
      sourcePath: target.videoPath,
      currentName: path.basename(target.videoPath),
      status: "blocked",
      reviewStatus,
      approvedTags: projection.approvedTags.map((tag) => tag.label),
      rejectedTagIds: projection.rejectedTagIds,
      warnings: ["Reviewed metadata does not contain an approved filename proposal."],
      readyForLevel2Preview: false,
    };
  }

  const draft = buildSmartRenamePreviewDraft({
    sourcePath: target.videoPath,
    filenameSuggestion,
  });
  const warnings = [...draft.warnings];
  if (await targetExists(draft.targetPath, target.videoPath)) {
    warnings.push("Target path already exists.");
  }
  const readyForLevel2Preview = draft.readyForLevel2Preview && warnings.length === 0;

  return {
    sourcePath: target.videoPath,
    currentName: path.basename(target.videoPath),
    suggestedName: draft.suggestedName,
    targetPath: draft.targetPath,
    status: readyForLevel2Preview ? "ready" : "blocked",
    reviewStatus,
    approvedTags: projection.approvedTags.map((tag) => tag.label),
    rejectedTagIds: projection.rejectedTagIds,
    warnings,
    readyForLevel2Preview,
  };
}

export async function buildSpiritFlixSmartRenamePlan(
  options: SpiritFlixSmartRenamePlanOptions = {},
): Promise<SpiritFlixSmartRenamePlan> {
  const maxItems = boundedLimit(options.maxItems);
  const { rootPath, targets } = await resolvePlanTargets(options, maxItems);
  const items = await Promise.all(targets.map((target) => itemFromTarget(target)));

  const targetGroups = new Map<string, SpiritFlixSmartRenamePlanItem[]>();
  for (const item of items) {
    if (!item.targetPath) continue;
    const key = item.targetPath.toLowerCase();
    targetGroups.set(key, [...(targetGroups.get(key) ?? []), item]);
  }

  for (const group of targetGroups.values()) {
    if (group.length < 2) continue;
    for (const item of group) {
      item.warnings.push("Duplicate target path in this plan.");
      item.readyForLevel2Preview = false;
      item.status = "blocked";
    }
  }

  return {
    schema: "spiritflix-smart-rename-plan/v1",
    generatedAt: new Date().toISOString(),
    rootPath,
    recursive: Boolean(options.recursive),
    maxItems,
    applyEnabled: false,
    applyGate: "Real rename/move apply is disabled until Britton explicitly approves a future apply task.",
    items,
    counts: summarize(items),
  };
}

// â”€â”€ SpiritFlix Smart Rename Preview Builder (S6) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Builds a rename preview draft without executing anything.
// No filesystem rename, no Level 2 calls, no execute.

import path from "node:path";

// â”€â”€ Types â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export interface SpiritFlixSmartRenamePreviewInput {
  sourcePath: string;
  filenameSuggestion: string;
}

export interface SpiritFlixSmartRenamePreviewDraft {
  sourcePath: string;
  suggestedName: string;
  targetPath: string;
  warnings: string[];
  readyForLevel2Preview: boolean;
}

// â”€â”€ Constants â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

const UNSAFE_FILENAME_CHARS = /[\\/:*?"<>|]/g;
const MAX_FILENAME_STEM_LENGTH = 180;
const GENERIC_STEMS = new Set([
  "untitled",
  "video",
  "clip",
  "new",
  "copy",
  "download",
  "screen recording",
]);

function normalizeSanitizedSuggestion(value: string): string {
  return value
    .replace(UNSAFE_FILENAME_CHARS, " ")
    .replace(/\s+\./g, ".")
    .replace(/\s+/g, " ")
    .trim();
}

// â”€â”€ Pure builder â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€

export function buildSmartRenamePreviewDraft(
  input: SpiritFlixSmartRenamePreviewInput,
): SpiritFlixSmartRenamePreviewDraft {
  const { sourcePath, filenameSuggestion } = input;
  const warnings: string[] = [];

  // Sanitize the suggested name
  const rawName = filenameSuggestion.trim();
  if (!rawName) {
    return {
      sourcePath,
      suggestedName: "",
      targetPath: sourcePath,
      warnings: ["Filename suggestion is empty."],
      readyForLevel2Preview: false,
    };
  }

  // Strip unsafe characters
  const sanitized = normalizeSanitizedSuggestion(rawName);
  if (!sanitized) {
    return {
      sourcePath,
      suggestedName: "",
      targetPath: sourcePath,
      warnings: ["Filename suggestion is empty after sanitization."],
      readyForLevel2Preview: false,
    };
  }

  // Reject slashes in suggested name (directory separator confusion)
  if (/[/\\]/.test(filenameSuggestion)) {
    warnings.push("Filename suggestion contains slashes; only the basename is used.");
  }
  if (/(^|[\\/])\.\.?($|[\\/])|^\.\./.test(filenameSuggestion)) {
    warnings.push("Filename suggestion contains traversal segments.");
  }

  // Preserve original extension
  const originalExtension = path.extname(sourcePath);
  const suggestionAlreadyHasExt = path.extname(sanitized).toLowerCase() === originalExtension.toLowerCase();
  const suggestedStem = suggestionAlreadyHasExt
    ? sanitized.slice(0, -path.extname(sanitized).length)
    : sanitized;
  const suggestedName = originalExtension
    ? `${suggestedStem}${originalExtension}`
    : sanitized;

  // Cap stem length
  const cappedStem = suggestedStem.length > MAX_FILENAME_STEM_LENGTH
    ? suggestedStem.slice(0, MAX_FILENAME_STEM_LENGTH).trim()
    : suggestedStem;
  const finalName = originalExtension
    ? `${cappedStem}${originalExtension}`
    : cappedStem;

  // Target stays in same folder
  const targetPath = path.join(path.dirname(sourcePath), finalName);

  // Validate: no traversal
  if (finalName.split(/[\\/]+/).some((segment) => segment === "..") || finalName.startsWith("..")) {
    warnings.push("Filename suggestion contains traversal segments.");
  }

  // Validate: not empty
  if (!finalName.trim()) {
    warnings.push("Filename suggestion is empty.");
  }

  // Warn: unchanged
  const originalBasename = path.basename(sourcePath);
  if (finalName === originalBasename) {
    warnings.push("Suggested filename is unchanged from current filename.");
  }

  // Warn: too long
  const stemOnly = path.parse(finalName).name;
  if (stemOnly.length > MAX_FILENAME_STEM_LENGTH) {
    warnings.push("Filename stem is very long; may cause filesystem issues.");
  }

  // Warn: generic
  if (GENERIC_STEMS.has(stemOnly.toLowerCase())) {
    warnings.push("Filename stem is generic and may not be useful for organization.");
  }

  const hasBlockingWarning = warnings.some(
    (w) =>
      /empty|traversal|slashes/i.test(w),
  );
  const isUnchanged = finalName === originalBasename;

  return {
    sourcePath,
    suggestedName: finalName,
    targetPath,
    warnings,
    readyForLevel2Preview: !hasBlockingWarning && !isUnchanged,
  };
}

// â”€â”€ SpiritFlix S4 review orchestration â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Combines S2 scanner + S3 heuristics. Sidecar writes only â€” no Level 2.

import fs from "node:fs/promises";
import path from "node:path";
import { readSmartAnalysis, writeSmartAnalysis } from "./analysis-store";
import { applySmartReviewToAnalysis } from "./review-metadata";
import { scanOneSpiritFlixVideoEvidence } from "./scanner";
import { updateSmartAnalysisWithHeuristicSuggestions } from "./suggestions";
import { applyLocalVisualAnalysisToSpiritFlixAnalysis } from "./visual-analysis";
import { validateSpiritFlixSmartAnalysis, type SpiritFlixSmartAnalysis, type SpiritFlixSmartReviewInput } from "./types";

export const SPIRITFLIX_SMART_ANALYZER_VERSION_S4 = "spiritflix-smart/s4";
export { SPIRITFLIX_SMART_ANALYZER_VERSION_S5 } from "./review-metadata";

export interface SpiritFlixSmartReviewOptions {
  mediaRoot?: string;
  ffprobePath?: string;
  ffmpegPath?: string;
  maxSamples?: number;
  probeTimeoutMs?: number;
  frameTimeoutMs?: number;
  visualAnalysis?: boolean;
  visualModel?: string;
  visualModelTimeoutMs?: number;
}

function pathOptions(mediaRoot?: string) {
  return mediaRoot ? { mediaRoot } : undefined;
}

function mergeNotes(existing: string | undefined, addition: string): string {
  const parts = new Set<string>();
  if (existing?.trim()) parts.add(existing.trim());
  if (addition.trim()) parts.add(addition.trim());
  return [...parts].join(" | ").slice(0, 8_000);
}

export async function runSpiritFlixSmartReviewPipeline(
  videoPath: string,
  options?: SpiritFlixSmartReviewOptions,
): Promise<SpiritFlixSmartAnalysis> {
  const scanned = await scanOneSpiritFlixVideoEvidence(videoPath, options);
  const stat = await fs.stat(videoPath);
  const visual = await applyLocalVisualAnalysisToSpiritFlixAnalysis(scanned, {
    enabled: options?.visualAnalysis ?? true,
    mediaRoot: options?.mediaRoot,
    ollamaModel: options?.visualModel,
    timeoutMs: options?.visualModelTimeoutMs,
  });
  await writeSmartAnalysis(visual, pathOptions(options?.mediaRoot));

  return updateSmartAnalysisWithHeuristicSuggestions(
    {
      videoPath,
      fileName: path.basename(videoPath),
      parentPath: path.dirname(videoPath),
      fileSizeBytes: stat.size,
      mtimeMs: stat.mtimeMs,
      media: scanned.media,
    },
    pathOptions(options?.mediaRoot),
  );
}

export async function markSpiritFlixSmartAnalysisReviewed(
  videoPath: string,
  options?: { mediaRoot?: string },
): Promise<SpiritFlixSmartAnalysis> {
  const pathOpts = pathOptions(options?.mediaRoot);
  const stat = await fs.stat(videoPath);
  const pathInput = { videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs };
  const existing = await readSmartAnalysis(pathInput, pathOpts);
  if (!existing) {
    throw new Error("No smart analysis sidecar exists to mark reviewed.");
  }

  const updated = validateSpiritFlixSmartAnalysis({
    ...existing,
    analyzedAt: new Date().toISOString(),
    analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S4,
    status: "suggested",
    safety: {
      ...existing.safety,
      requiresHumanReview: true,
      safeToSuggest: false,
      reasons: [...new Set([...existing.safety.reasons, "Marked reviewed in admin UI â€” apply actions still gated."])],
    },
    reviewedMetadata: {
      reviewedAt: new Date().toISOString(),
      reviewedBy: "spiritflix-admin",
      reviewStatus: "reviewed",
      approvedTagIds: existing.reviewedMetadata?.approvedTagIds ?? [],
      rejectedTagIds: existing.reviewedMetadata?.rejectedTagIds ?? [],
      editedDisplayTitle: existing.reviewedMetadata?.editedDisplayTitle,
      editedFilenameSuggestion: existing.reviewedMetadata?.editedFilenameSuggestion,
      editedCategory: existing.reviewedMetadata?.editedCategory,
      editedCollections: existing.reviewedMetadata?.editedCollections,
      notes: mergeNotes(existing.reviewedMetadata?.notes, "marked reviewed without tag edits"),
    },
    notes: mergeNotes(existing.notes, "marked reviewed in SpiritFlix admin (S4 UI only, no rename/move applied)"),
  });

  const { analysis } = await writeSmartAnalysis(updated, pathOpts);
  return analysis;
}

export async function saveSpiritFlixSmartAnalysisReview(
  videoPath: string,
  review: SpiritFlixSmartReviewInput,
  options?: { mediaRoot?: string },
): Promise<SpiritFlixSmartAnalysis> {
  const pathOpts = pathOptions(options?.mediaRoot);
  const stat = await fs.stat(videoPath);
  const pathInput = { videoPath, fileSizeBytes: stat.size, mtimeMs: stat.mtimeMs };
  const existing = await readSmartAnalysis(pathInput, pathOpts);
  if (!existing) {
    throw new Error("No smart analysis sidecar exists to save review metadata.");
  }

  const updated = applySmartReviewToAnalysis(existing, review);
  const { analysis } = await writeSmartAnalysis(updated, pathOpts);
  return analysis;
}

// â”€â”€ SpiritFlix S5 reviewed metadata (analysis sidecar only) â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Human review of suggestions â€” never mutates media files.

import { isKnownSmartTagId } from "./vocabulary";
import {
  validateSpiritFlixSmartAnalysis,
  type SpiritFlixSmartAnalysis,
  type SpiritFlixSmartReviewedMetadata,
  type SpiritFlixSmartReviewInput,
  type SpiritFlixSmartReviewStatus,
} from "./types";

export const SPIRITFLIX_SMART_ANALYZER_VERSION_S5 = "spiritflix-smart/s5";

const UNSAFE_FILENAME_CHARS = /[\\/:*?"<>|]/g;
const MAX_FILENAME_STEM_LENGTH = 120;

function fileExtension(fileName: string): string {
  const match = fileName.match(/(\.[^./\\]+)$/);
  return match ? match[1].toLowerCase() : "";
}

const ALLOWED_REVIEW_KEYS = new Set([
  "approvedTagIds",
  "rejectedTagIds",
  "editedDisplayTitle",
  "editedFilenameSuggestion",
  "editedCategory",
  "editedCollections",
  "notes",
]);

export function assertSpiritFlixSmartReviewPayload(value: unknown): SpiritFlixSmartReviewInput {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("review must be an object.");
  }
  const record = value as Record<string, unknown>;
  for (const key of Object.keys(record)) {
    if (!ALLOWED_REVIEW_KEYS.has(key)) {
      throw new Error(`review contains unknown field "${key}".`);
    }
  }

  const serialized = JSON.stringify(record);
  if (serialized.length > 32_768) {
    throw new Error("review payload is too large.");
  }

  return validateSpiritFlixSmartReviewInput(record);
}

function sanitizeText(value: string | undefined, maxLength: number): string | undefined {
  if (value === undefined) return undefined;
  const trimmed = value.replace(/\0/g, "").trim();
  if (!trimmed) return undefined;
  return trimmed.slice(0, maxLength);
}

export function sanitizeEditedFilenameSuggestion(
  value: string | undefined,
  originalFileName: string,
): string | undefined {
  if (value === undefined) return undefined;
  const extension = fileExtension(originalFileName) || ".mp4";
  const raw = value.replace(UNSAFE_FILENAME_CHARS, " ").replace(/\s+/g, " ").trim();
  if (!raw) return undefined;
  const stem = raw.endsWith(extension) ? raw.slice(0, -extension.length).trim() : raw;
  const cleanedStem = stem.slice(0, MAX_FILENAME_STEM_LENGTH).trim() || "untitled";
  return `${cleanedStem}${extension}`;
}

function uniqueIds(ids: string[]): string[] {
  return [...new Set(ids)];
}

function computeReviewStatus(
  analysis: SpiritFlixSmartAnalysis,
  input: SpiritFlixSmartReviewInput,
): SpiritFlixSmartReviewStatus {
  const suggestedIds = analysis.suggestedTags.map((tag) => tag.id);
  const approved = uniqueIds(input.approvedTagIds);
  const rejected = uniqueIds(input.rejectedTagIds);
  const decided = new Set([...approved, ...rejected]);
  const pendingCount = suggestedIds.filter((id) => !decided.has(id)).length;

  const hasEdits = Boolean(
    input.editedDisplayTitle ||
      input.editedFilenameSuggestion ||
      input.editedCategory ||
      (input.editedCollections && input.editedCollections.length > 0) ||
      input.notes,
  );

  if (suggestedIds.length > 0 && rejected.length === suggestedIds.length && !hasEdits) {
    return "rejected";
  }

  if (pendingCount === 0 && (approved.length > 0 || hasEdits)) {
    return "reviewed";
  }

  if (approved.length > 0 || rejected.length > 0 || hasEdits) {
    return "partially_reviewed";
  }

  return "unreviewed";
}

function computeAnalysisStatus(
  analysis: SpiritFlixSmartAnalysis,
  reviewStatus: SpiritFlixSmartReviewStatus,
): SpiritFlixSmartAnalysis["status"] {
  if (reviewStatus === "rejected") return "rejected";
  if (reviewStatus === "reviewed") return "approved";
  if (reviewStatus === "partially_reviewed") return "suggested";
  return analysis.status === "not_analyzed" ? "needs_review" : analysis.status;
}

export function applySmartReviewToAnalysis(
  analysis: SpiritFlixSmartAnalysis,
  input: SpiritFlixSmartReviewInput,
): SpiritFlixSmartAnalysis {
  const validatedInput = validateSpiritFlixSmartReviewInput(input);
  const suggestedIds = new Set(analysis.suggestedTags.map((tag) => tag.id));

  for (const id of [...validatedInput.approvedTagIds, ...validatedInput.rejectedTagIds]) {
    if (!suggestedIds.has(id)) {
      throw new Error(`Tag id "${id}" is not in suggestedTags.`);
    }
  }

  const reviewStatus = computeReviewStatus(analysis, validatedInput);
  const reviewedMetadata: SpiritFlixSmartReviewedMetadata = {
    reviewedAt: new Date().toISOString(),
    reviewedBy: "spiritflix-admin",
    reviewStatus,
    approvedTagIds: validatedInput.approvedTagIds,
    rejectedTagIds: validatedInput.rejectedTagIds,
    editedDisplayTitle: sanitizeText(validatedInput.editedDisplayTitle, 512),
    editedFilenameSuggestion: sanitizeEditedFilenameSuggestion(validatedInput.editedFilenameSuggestion, analysis.fileName),
    editedCategory: sanitizeText(validatedInput.editedCategory, 256),
    editedCollections: validatedInput.editedCollections,
    notes: sanitizeText(validatedInput.notes, 8_192),
  };

  return validateSpiritFlixSmartAnalysis({
    ...analysis,
    analyzedAt: new Date().toISOString(),
    analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S5,
    status: computeAnalysisStatus(analysis, reviewStatus),
    safety: {
      ...analysis.safety,
      safeToSuggest: false,
      requiresHumanReview: true,
      reasons: [
        ...new Set([
          ...analysis.safety.reasons,
          "S5 metadata review saved â€” file rename/move not executed.",
        ]),
      ],
    },
    reviewedMetadata,
    samples: analysis.samples,
    suggestedTags: analysis.suggestedTags,
    suggestedCategory: analysis.suggestedCategory,
    suggestedCollections: analysis.suggestedCollections,
    suggestedDisplayTitle: analysis.suggestedDisplayTitle,
    suggestedFilename: analysis.suggestedFilename,
    notes: analysis.notes,
  });
}

export function buildEmptyReviewDraft(analysis: SpiritFlixSmartAnalysis | null): SpiritFlixSmartReviewInput {
  const reviewed = analysis?.reviewedMetadata;
  return {
    approvedTagIds: [...(reviewed?.approvedTagIds ?? [])],
    rejectedTagIds: [...(reviewed?.rejectedTagIds ?? [])],
    editedDisplayTitle: reviewed?.editedDisplayTitle ?? analysis?.suggestedDisplayTitle ?? "",
    editedFilenameSuggestion: reviewed?.editedFilenameSuggestion ?? analysis?.suggestedFilename ?? "",
    editedCategory: reviewed?.editedCategory ?? analysis?.suggestedCategory ?? "",
    editedCollections: [...(reviewed?.editedCollections ?? analysis?.suggestedCollections ?? [])],
    notes: reviewed?.notes ?? "",
  };
}

export function countReviewTagStates(
  analysis: SpiritFlixSmartAnalysis,
  draft: SpiritFlixSmartReviewInput,
): { approved: number; rejected: number; pending: number } {
  const suggestedIds = analysis.suggestedTags.map((tag) => tag.id);
  const approved = new Set(draft.approvedTagIds);
  const rejected = new Set(draft.rejectedTagIds);
  let approvedCount = 0;
  let rejectedCount = 0;
  let pendingCount = 0;
  for (const id of suggestedIds) {
    if (approved.has(id)) approvedCount += 1;
    else if (rejected.has(id)) rejectedCount += 1;
    else pendingCount += 1;
  }
  return { approved: approvedCount, rejected: rejectedCount, pending: pendingCount };
}

export function tagReviewState(
  tagId: string,
  draft: SpiritFlixSmartReviewInput,
): "approved" | "rejected" | "pending" {
  if (draft.approvedTagIds.includes(tagId)) return "approved";
  if (draft.rejectedTagIds.includes(tagId)) return "rejected";
  return "pending";
}

export function validateSpiritFlixSmartReviewInput(value: unknown): SpiritFlixSmartReviewInput {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error("review must be an object.");
  }
  const record = value as Record<string, unknown>;

  if (!Array.isArray(record.approvedTagIds)) throw new Error("approvedTagIds must be an array.");
  if (!Array.isArray(record.rejectedTagIds)) throw new Error("rejectedTagIds must be an array.");
  if (record.approvedTagIds.length > 200 || record.rejectedTagIds.length > 200) {
    throw new Error("review tag id lists are too large.");
  }

  const approvedTagIds = record.approvedTagIds.map((entry, index) => {
    if (typeof entry !== "string" || !entry.trim()) throw new Error(`approvedTagIds[${index}] must be a non-empty string.`);
    if (!isKnownSmartTagId(entry)) throw new Error(`approvedTagIds[${index}] is not a known tag id.`);
    return entry;
  });

  const rejectedTagIds = record.rejectedTagIds.map((entry, index) => {
    if (typeof entry !== "string" || !entry.trim()) throw new Error(`rejectedTagIds[${index}] must be a non-empty string.`);
    if (!isKnownSmartTagId(entry)) throw new Error(`rejectedTagIds[${index}] is not a known tag id.`);
    return entry;
  });

  const overlap = approvedTagIds.find((id) => rejectedTagIds.includes(id));
  if (overlap) throw new Error("approvedTagIds and rejectedTagIds must not overlap.");

  let editedCollections: string[] | undefined;
  if (record.editedCollections !== undefined) {
    if (!Array.isArray(record.editedCollections)) throw new Error("editedCollections must be an array.");
    if (record.editedCollections.length > 50) throw new Error("editedCollections is too large.");
    editedCollections = record.editedCollections.map((entry, index) => {
      if (typeof entry !== "string" || !entry.trim()) throw new Error(`editedCollections[${index}] must be a non-empty string.`);
      return entry.trim().slice(0, 256);
    });
  }

  const editedDisplayTitle =
    record.editedDisplayTitle === undefined
      ? undefined
      : typeof record.editedDisplayTitle === "string"
        ? record.editedDisplayTitle.trim().slice(0, 512)
        : (() => {
            throw new Error("editedDisplayTitle must be a string.");
          })();

  const editedFilenameSuggestion =
    record.editedFilenameSuggestion === undefined
      ? undefined
      : typeof record.editedFilenameSuggestion === "string"
        ? record.editedFilenameSuggestion.trim().slice(0, 512)
        : (() => {
            throw new Error("editedFilenameSuggestion must be a string.");
          })();

  const editedCategory =
    record.editedCategory === undefined
      ? undefined
      : typeof record.editedCategory === "string"
        ? record.editedCategory.trim().slice(0, 256)
        : (() => {
            throw new Error("editedCategory must be a string.");
          })();

  const notes =
    record.notes === undefined
      ? undefined
      : typeof record.notes === "string"
        ? record.notes.trim().slice(0, 8_192)
        : (() => {
            throw new Error("notes must be a string.");
          })();

  return {
    approvedTagIds: [...new Set(approvedTagIds)],
    rejectedTagIds: [...new Set(rejectedTagIds)],
    editedDisplayTitle: editedDisplayTitle || undefined,
    editedFilenameSuggestion: editedFilenameSuggestion || undefined,
    editedCategory: editedCategory || undefined,
    editedCollections,
    notes: notes || undefined,
  };
}

import fs from "node:fs/promises";
import path from "node:path";
import {
  assertSmartVideoPathCandidate,
  createSmartAnalysisPathKey,
  getSmartAnalysisCacheRoot,
  type SpiritFlixSmartPathInput,
  type SpiritFlixSmartPathOptions,
} from "./analysis-paths";
import { SpiritFlixSmartSamplerError } from "./errors";
import { isSpiritFlixSmartVideoExtension } from "./probe";
import { spawn } from "./process";

const DEFAULT_FRAME_TIMEOUT_MS = 15_000;
const FRAME_CACHE_VERSION = "v1";
const DEFAULT_SCALE_WIDTH = 480;

export interface SpiritFlixSamplePlanOptions {
  maxSamples?: number;
  minSamples?: number;
  avoidStartSeconds?: number;
  avoidEndSeconds?: number;
}

export interface SpiritFlixFrameSample {
  timestampSeconds: number;
  timestampLabel: string;
  cacheKey: string;
  framePath: string;
  width?: number;
  height?: number;
}

export interface SpiritFlixFrameExtractionOptions {
  timeoutMs?: number;
  ffmpegPath?: string;
  mediaRoot?: string;
  scaleWidth?: number;
  analysisKey?: string;
}

function pathOptions(mediaRoot?: string): SpiritFlixSmartPathOptions | undefined {
  return mediaRoot ? { mediaRoot } : undefined;
}

function clampTimestamp(seconds: number, durationSeconds: number): number {
  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) return 0;
  const max = Math.max(0, durationSeconds - 0.05);
  return Math.min(Math.max(0, seconds), max);
}

function roundTimestamp(seconds: number): number {
  return Math.round(seconds * 1000) / 1000;
}

function formatTimestampLabel(seconds: number): string {
  return `${roundTimestamp(seconds)}s`;
}

function defaultSampleCap(durationSeconds: number, maxSamples?: number): number {
  const cap =
    maxSamples ??
    (durationSeconds < 30 ? 3 : durationSeconds < 300 ? 6 : durationSeconds < 1_800 ? 12 : 16);
  return Math.max(1, cap);
}

export function planSpiritFlixSampleTimestamps(
  durationSeconds: number,
  options?: SpiritFlixSamplePlanOptions,
): number[] {
  if (!Number.isFinite(durationSeconds) || durationSeconds <= 0) {
    throw new SpiritFlixSmartSamplerError("durationSeconds must be a positive number.");
  }

  const avoidStart = options?.avoidStartSeconds ?? (durationSeconds >= 12 ? 5 : 1);
  const avoidEnd = options?.avoidEndSeconds ?? (durationSeconds >= 12 ? 5 : 1);
  const minSamples = Math.max(1, options?.minSamples ?? 1);
  const maxSamples = Math.max(minSamples, defaultSampleCap(durationSeconds, options?.maxSamples));

  const start = clampTimestamp(avoidStart, durationSeconds);
  const end = clampTimestamp(durationSeconds - avoidEnd, durationSeconds);

  const timestamps: number[] = [];

  if (durationSeconds < 3 || end <= start) {
    timestamps.push(roundTimestamp(durationSeconds / 2));
  } else if (maxSamples === 1) {
    timestamps.push(roundTimestamp((start + end) / 2));
  } else {
    const step = (end - start) / (maxSamples - 1);
    for (let index = 0; index < maxSamples; index += 1) {
      timestamps.push(roundTimestamp(start + step * index));
    }
  }

  const unique = [...new Set(timestamps.map((value) => roundTimestamp(clampTimestamp(value, durationSeconds))))];
  unique.sort((left, right) => left - right);
  return unique.slice(0, maxSamples);
}

export function buildSpiritFlixFrameCacheFileName(analysisKey: string, timestampMs: number): string {
  if (!/^[a-f0-9]{64}$/.test(analysisKey)) {
    throw new SpiritFlixSmartSamplerError("analysisKey must be a sha256 hex digest.");
  }
  if (!Number.isFinite(timestampMs) || timestampMs < 0) {
    throw new SpiritFlixSmartSamplerError("timestampMs must be a non-negative number.");
  }
  return `${analysisKey}-t${Math.trunc(timestampMs)}-${FRAME_CACHE_VERSION}.jpg`;
}

export function getSpiritFlixFrameCachePath(
  analysisKey: string,
  timestampMs: number,
  options?: SpiritFlixSmartPathOptions,
): string {
  const framesRoot = path.join(getSmartAnalysisCacheRoot(options), "frames");
  const fileName = buildSpiritFlixFrameCacheFileName(analysisKey, timestampMs);
  const framePath = path.join(framesRoot, fileName);
  const resolvedRoot = path.resolve(framesRoot);
  const resolvedFrame = path.resolve(framePath);
  if (!resolvedFrame.startsWith(resolvedRoot + path.sep) && resolvedFrame !== resolvedRoot) {
    throw new SpiritFlixSmartSamplerError("Frame cache path escaped the frames root.");
  }
  return resolvedFrame;
}

function formatSeek(seconds: number): string {
  const hours = Math.floor(seconds / 3600);
  const minutes = Math.floor((seconds % 3600) / 60);
  const secs = seconds % 60;
  const wholeSecs = Math.floor(secs);
  const millis = Math.round((secs - wholeSecs) * 1000);
  return `${String(hours).padStart(2, "0")}:${String(minutes).padStart(2, "0")}:${String(wholeSecs).padStart(2, "0")}.${String(millis).padStart(3, "0")}`;
}

function runFfmpegFrame(
  ffmpegPath: string,
  videoPath: string,
  timestampSeconds: number,
  outputPath: string,
  scaleWidth: number,
  timeoutMs: number,
): Promise<{ ok: boolean; timedOut: boolean; spawnError?: Error }> {
  return new Promise((resolve) => {
    const args = [
      "-hide_banner",
      "-loglevel",
      "error",
      "-ss",
      formatSeek(timestampSeconds),
      "-i",
      videoPath,
      "-frames:v",
      "1",
      "-vf",
      `scale=${scaleWidth}:-1`,
      "-q:v",
      "5",
      "-y",
      outputPath,
    ];
    const proc = spawn(ffmpegPath, args, { shell: false });
    let timedOut = false;
    let settled = false;

    const finish = (result: { ok: boolean; timedOut: boolean; spawnError?: Error }) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      resolve(result);
    };

    const timer = setTimeout(() => {
      timedOut = true;
      proc.kill("SIGKILL");
      finish({ ok: false, timedOut });
    }, timeoutMs);

    proc.on("error", (error) => {
      finish({ ok: false, timedOut, spawnError: error });
    });
    proc.on("close", (code) => {
      finish({ ok: code === 0, timedOut });
    });
  });
}

export async function extractSpiritFlixFrameSample(
  videoPath: string,
  timestampSeconds: number,
  options?: SpiritFlixFrameExtractionOptions,
): Promise<SpiritFlixFrameSample> {
  const mediaRoot = options?.mediaRoot;
  const pathOpts = pathOptions(mediaRoot);
  const resolvedPath = assertSmartVideoPathCandidate(videoPath, pathOpts);
  const extension = path.extname(resolvedPath).toLowerCase();
  if (!isSpiritFlixSmartVideoExtension(extension)) {
    throw new SpiritFlixSmartSamplerError("SpiritFlix frame sampler only supports video files.");
  }
  if (!Number.isFinite(timestampSeconds) || timestampSeconds < 0) {
    throw new SpiritFlixSmartSamplerError("timestampSeconds must be a non-negative number.");
  }

  const stat = await fs.stat(resolvedPath);
  const pathInput: SpiritFlixSmartPathInput = {
    videoPath: resolvedPath,
    fileSizeBytes: stat.size,
    mtimeMs: stat.mtimeMs,
  };
  const analysisKey = options?.analysisKey ?? createSmartAnalysisPathKey(pathInput);
  const timestampMs = Math.trunc(timestampSeconds * 1000);
  const framePath = getSpiritFlixFrameCachePath(analysisKey, timestampMs, pathOpts);
  const cacheKey = path.basename(framePath, ".jpg");

  try {
    const existing = await fs.stat(framePath);
    if (existing.isFile() && existing.size > 0) {
      return {
        timestampSeconds: roundTimestamp(timestampSeconds),
        timestampLabel: formatTimestampLabel(timestampSeconds),
        cacheKey,
        framePath,
        width: options?.scaleWidth ?? DEFAULT_SCALE_WIDTH,
      };
    }
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
  }

  const framesRoot = path.dirname(framePath);
  await fs.mkdir(framesRoot, { recursive: true });
  const tempPath = path.join(framesRoot, `.${cacheKey}.tmp.jpg`);

  const ffmpegPath = options?.ffmpegPath ?? "ffmpeg";
  const timeoutMs = options?.timeoutMs ?? DEFAULT_FRAME_TIMEOUT_MS;
  const scaleWidth = options?.scaleWidth ?? DEFAULT_SCALE_WIDTH;
  const result = await runFfmpegFrame(ffmpegPath, resolvedPath, timestampSeconds, tempPath, scaleWidth, timeoutMs);

  if (result.spawnError) {
    await fs.rm(tempPath, { force: true }).catch(() => undefined);
    if ((result.spawnError as NodeJS.ErrnoException).code === "ENOENT") {
      throw new SpiritFlixSmartSamplerError("ffmpeg is not available on this host.");
    }
    throw new SpiritFlixSmartSamplerError("ffmpeg failed to start.");
  }
  if (result.timedOut) {
    await fs.rm(tempPath, { force: true }).catch(() => undefined);
    throw new SpiritFlixSmartSamplerError("ffmpeg frame extraction timed out.");
  }
  if (!result.ok) {
    await fs.rm(tempPath, { force: true }).catch(() => undefined);
    throw new SpiritFlixSmartSamplerError("ffmpeg frame extraction failed.");
  }

  try {
    await fs.rename(tempPath, framePath);
  } catch {
    await fs.rm(tempPath, { force: true }).catch(() => undefined);
    throw new SpiritFlixSmartSamplerError("Failed to finalize frame cache file.");
  }

  return {
    timestampSeconds: roundTimestamp(timestampSeconds),
    timestampLabel: formatTimestampLabel(timestampSeconds),
    cacheKey,
    framePath,
    width: scaleWidth,
  };
}

// â”€â”€ SpiritFlix smart scanner orchestrator (S2) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// One video only. Analysis sidecar + frame cache writes â€” never mutates media.

import fs from "node:fs/promises";
import path from "node:path";
import { createSmartAnalysisPathKey } from "./analysis-paths";
import {
  createEmptySmartAnalysis,
  readSmartAnalysis,
  writeSmartAnalysis,
} from "./analysis-store";
import { SpiritFlixSmartScannerError } from "./errors";
import { probeSpiritFlixVideo } from "./probe";
import { extractSpiritFlixFrameSample, planSpiritFlixSampleTimestamps } from "./sampler";
import { validateSpiritFlixSmartAnalysis, type SpiritFlixSmartAnalysis, type SpiritFlixSmartSample } from "./types";

export const SPIRITFLIX_SMART_ANALYZER_VERSION_S2 = "spiritflix-smart/s2";

export interface SpiritFlixScanOneVideoOptions {
  mediaRoot?: string;
  ffprobePath?: string;
  ffmpegPath?: string;
  maxSamples?: number;
  probeTimeoutMs?: number;
  frameTimeoutMs?: number;
}

function pathOptions(mediaRoot?: string) {
  return mediaRoot ? { mediaRoot } : undefined;
}

export async function scanOneSpiritFlixVideoEvidence(
  videoPath: string,
  options?: SpiritFlixScanOneVideoOptions,
): Promise<SpiritFlixSmartAnalysis> {
  const pathOpts = pathOptions(options?.mediaRoot);

  let stat;
  try {
    stat = await fs.stat(videoPath);
  } catch {
    throw new SpiritFlixSmartScannerError("Video file is not readable.");
  }
  if (!stat.isFile()) {
    throw new SpiritFlixSmartScannerError("Video path must be a file.");
  }

  const fileName = path.basename(videoPath);
  const pathInput = {
    videoPath,
    fileSizeBytes: stat.size,
    mtimeMs: stat.mtimeMs,
  };

  const existing = await readSmartAnalysis(pathInput, pathOpts);
  const base =
    existing ??
    createEmptySmartAnalysis(
      {
        videoPath,
        fileName,
        fileSizeBytes: stat.size,
        mtimeMs: stat.mtimeMs,
        analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S2,
      },
      pathOpts,
    );

  let probeResult;
  try {
    probeResult = await probeSpiritFlixVideo(videoPath, {
      mediaRoot: options?.mediaRoot,
      ffprobePath: options?.ffprobePath,
      timeoutMs: options?.probeTimeoutMs,
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : "ffprobe failed.";
    throw new SpiritFlixSmartScannerError(message);
  }

  const durationSeconds = probeResult.durationSeconds ?? 1;
  const timestamps = planSpiritFlixSampleTimestamps(durationSeconds, {
    maxSamples: options?.maxSamples,
  });

  const analysisKey = createSmartAnalysisPathKey({
    videoPath: base.videoPath,
    fileSizeBytes: base.fileSizeBytes,
    mtimeMs: base.mtimeMs,
  });

  const samples: SpiritFlixSmartSample[] = [];
  const frameFailures: string[] = [];

  for (const timestampSeconds of timestamps) {
    try {
      const frame = await extractSpiritFlixFrameSample(videoPath, timestampSeconds, {
        mediaRoot: options?.mediaRoot,
        ffmpegPath: options?.ffmpegPath,
        timeoutMs: options?.frameTimeoutMs,
        analysisKey,
      });
      samples.push({
        timestampSeconds: frame.timestampSeconds,
        timestampLabel: frame.timestampLabel,
        cacheKey: frame.cacheKey,
        observations: ["sampled frame"],
        tags: [],
        confidence: 0,
      });
    } catch (error) {
      const message = error instanceof Error ? error.message : "frame extraction failed";
      frameFailures.push(`${timestampSeconds}s: ${message}`);
    }
  }

  const notesParts: string[] = ["technical metadata collected"];
  if (frameFailures.length > 0) {
    notesParts.push(`frame failures: ${frameFailures.slice(0, 12).join("; ")}`);
  }

  const updated = validateSpiritFlixSmartAnalysis({
    ...base,
    analyzedAt: new Date().toISOString(),
    analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S2,
    status: "needs_review",
    safety: {
      safeToSuggest: false,
      reasons: ["Scanner evidence requires human review before suggestions."],
      requiresHumanReview: true,
    },
    media: {
      durationSeconds: probeResult.durationSeconds,
      width: probeResult.width,
      height: probeResult.height,
      codec: probeResult.codec,
      container: probeResult.container ?? probeResult.formatName,
    },
    samples,
    suggestedTags: [],
    suggestedCategory: undefined,
    suggestedFilename: undefined,
    suggestedTargetFolder: undefined,
    confidence: 0,
    notes: notesParts.join(" | "),
  });

  const { analysis } = await writeSmartAnalysis(updated, pathOpts);
  return analysis;
}

// â”€â”€ SpiritFlix S3 review-only suggestion builder â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Writes analysis sidecar suggestions only. Never mutates media.

import fs from "node:fs/promises";
import path from "node:path";
import { assertSmartVideoPathCandidate } from "./analysis-paths";
import {
  createEmptySmartAnalysis,
  readSmartAnalysis,
  writeSmartAnalysis,
} from "./analysis-store";
import {
  buildHeuristicNotes,
  inferCategoryHint,
  inferFormatTags,
  inferQualityTags,
  inferSourceTags,
  isAmbiguousSpiritFlixFilename,
  isPrimarySmartContentTag,
  isRandomOrHashSpiritFlixFilename,
  isTechnicalOrStatusTag,
  modelIdentityFromPath,
  normalizeSpiritFlixTitle,
  stripVideoExtension,
  titleCaseSlug,
  unknownModelIdentity,
  type SpiritFlixSmartHeuristicInput,
} from "./heuristics";
import {
  validateSpiritFlixSmartAnalysis,
  type SpiritFlixSmartAnalysis,
  type SpiritFlixSmartContentTagEvidence,
  type SpiritFlixSmartPerformerIdentity,
  type SpiritFlixSmartTag,
} from "./types";

export const SPIRITFLIX_SMART_ANALYZER_VERSION_S3 = "spiritflix-smart/s3";

const MAX_FILENAME_STEM_LENGTH = 120;
const UNSAFE_FILENAME_CHARS = /[\\/:*?"<>|]/g;
const FACE_VERIFICATION_RELATIVE_PATH = path.join("scripts", "media", "performer_verification.json");

export interface SpiritFlixSmartSuggestionResult {
  suggestedTags: SpiritFlixSmartTag[];
  suggestedCategory?: string;
  suggestedCollections: string[];
  suggestedDisplayTitle?: string;
  suggestedFilename?: string;
  contentTagEvidence: SpiritFlixSmartContentTagEvidence[];
  performerIdentity: SpiritFlixSmartPerformerIdentity;
  suggestedFilenameReason: string;
  confidence: number;
  notes: string[];
}

function pathOptions(mediaRoot?: string) {
  return mediaRoot ? { mediaRoot } : undefined;
}

function dedupeTags(tags: SpiritFlixSmartTag[]): SpiritFlixSmartTag[] {
  const byId = new Map<string, SpiritFlixSmartTag>();
  for (const tag of tags) {
    const existing = byId.get(tag.id);
    if (!existing || tag.confidence > existing.confidence) {
      byId.set(tag.id, tag);
    }
  }
  return [...byId.values()];
}

function averageConfidence(tags: SpiritFlixSmartTag[]): number {
  if (tags.length === 0) return 0.2;
  const total = tags.reduce((sum, tag) => sum + tag.confidence, 0);
  return Math.min(1, Math.max(0, total / tags.length));
}

function sanitizeFilenameStem(value: string): string {
  const cleaned = value
    .replace(UNSAFE_FILENAME_CHARS, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, MAX_FILENAME_STEM_LENGTH);
  return cleaned || "untitled";
}

function topContentLabels(tags: SpiritFlixSmartTag[]): string[] {
  return tags
    .filter(isPrimarySmartContentTag)
    .sort((left, right) => right.confidence - left.confidence)
    .slice(0, 3)
    .map((tag) => tag.label.toLowerCase());
}

function readableTitle(input: SpiritFlixSmartHeuristicInput): string {
  const title = normalizeSpiritFlixTitle(input.fileName) || stripVideoExtension(input.fileName);
  return sanitizeFilenameStem(title);
}

function shouldUseFallbackName(input: SpiritFlixSmartHeuristicInput): boolean {
  const title = readableTitle(input);
  const compact = title.replace(/[^a-z0-9]/gi, "");
  const normalized = title.toLowerCase();
  if (/\bvisit\b.*\bmore\b/.test(normalized)) return true;
  if (/\bonlyshare\b|\bonlyfans\b|\bfansly\b/.test(normalized)) return true;
  if (isRandomOrHashSpiritFlixFilename(input)) return true;
  if (!compact || compact.length < 3) return true;
  if (/^\d+$/.test(compact)) return true;
  return false;
}

export function buildSuggestedFilename(
  input: SpiritFlixSmartHeuristicInput,
  tags: SpiritFlixSmartTag[],
  performerIdentity: SpiritFlixSmartPerformerIdentity = modelIdentityFromPath(input) ?? unknownModelIdentity(),
): string {
  if (!shouldUseFallbackName(input)) {
    return readableTitle(input);
  }

  const modelName = sanitizeFilenameStem(performerIdentity.name || "Unknown Model");
  const content = topContentLabels(tags).join(" ");
  const fallbackTitle = content ? `${modelName} - ${content} 01` : `${modelName} - Untitled 01`;
  return sanitizeFilenameStem(fallbackTitle);
}

function filenameReason(input: SpiritFlixSmartHeuristicInput, tags: SpiritFlixSmartTag[], performerIdentity: SpiritFlixSmartPerformerIdentity): string {
  if (!shouldUseFallbackName(input)) {
    return "Readable title preserved; extension is kept only for target-path preview.";
  }
  if (topContentLabels(tags).length > 0) {
    return `${performerIdentity.name} fallback uses strongest available content tags; extension is kept only for target-path preview.`;
  }
  return `${performerIdentity.name} fallback uses model identity with Untitled 01 because the filename is random or ambiguous.`;
}

function tagsFromSamples(analysis: SpiritFlixSmartAnalysis | undefined): SpiritFlixSmartTag[] {
  return dedupeTags((analysis?.samples ?? []).flatMap((sample) => sample.tags).filter(isPrimarySmartContentTag));
}

function contentEvidenceFor(
  input: SpiritFlixSmartHeuristicInput,
  tags: SpiritFlixSmartTag[],
  technicalTags: SpiritFlixSmartTag[],
  analysis: SpiritFlixSmartAnalysis | undefined,
  performerIdentity: SpiritFlixSmartPerformerIdentity,
): SpiritFlixSmartContentTagEvidence[] {
  const frameEvidenceTags = tagsFromSamples(analysis).map((tag) => tag.id);
  const firstFrameRef = analysis?.samples.find((sample) => sample.cacheKey)?.cacheKey ?? null;
  const existingVisualEvidence = (analysis?.contentTagEvidence ?? []).filter((entry) => entry.source === "vlm" || entry.source === "ocr");
  return [
    {
      source: "filename",
      tags: tags.filter((tag) => tag.evidenceTimestamps.length === 0).map((tag) => tag.id),
      confidence: tags.length > 0 ? averageConfidence(tags) : 0.2,
      evidenceRef: path.basename(input.fileName),
      requiresReview: true,
    },
    {
      source: "path",
      tags: performerIdentity.source === "path" ? [performerIdentity.name] : [],
      confidence: performerIdentity.source === "path" ? performerIdentity.confidence : 0.2,
      evidenceRef: performerIdentity.evidenceRef ?? input.parentPath ?? null,
      requiresReview: true,
    },
    {
      source: "metadata",
      tags: technicalTags.map((tag) => tag.id),
      confidence: technicalTags.length > 0 ? averageConfidence(technicalTags) : 0.2,
      evidenceRef: null,
      requiresReview: true,
    },
    {
      source: "frame_sample",
      tags: frameEvidenceTags,
      confidence: frameEvidenceTags.length > 0 ? averageConfidence(tagsFromSamples(analysis)) : 0,
      evidenceRef: firstFrameRef,
      requiresReview: true,
    },
    ...existingVisualEvidence,
  ];
}

function suggestionsFromExistingFrameEvidence(analysis: SpiritFlixSmartAnalysis | undefined): SpiritFlixSmartTag[] {
  return tagsFromSamples(analysis);
}

function hasAmbiguousFilename(input: SpiritFlixSmartHeuristicInput): boolean {
  return isAmbiguousSpiritFlixFilename(input);
}

function normalizeIdentityPath(value: string): string {
  return value
    .replace(/\\/g, "/")
    .replace(/^\/mnt\/spirit-8tb\/media\/yes(?=\/|$)/i, "/DATA/yes")
    .replace(/^\/media\/yes(?=\/|$)/i, "/DATA/yes")
    .replace(/^\/home\/source\/SpiritOS\/DATA\/yes(?=\/|$)/i, "/DATA/yes")
    .toLowerCase();
}

function safeEvidenceSource(source: string | undefined): boolean {
  return Boolean(source && /manual|confirmed|face/i.test(source));
}

async function findReadOnlyFacePerformerIdentity(input: SpiritFlixSmartHeuristicInput): Promise<SpiritFlixSmartPerformerIdentity | undefined> {
  const evidencePath = path.join(process.cwd(), FACE_VERIFICATION_RELATIVE_PATH);
  let raw: string;
  try {
    raw = await fs.readFile(evidencePath, "utf8");
  } catch {
    return undefined;
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    return undefined;
  }

  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) return undefined;
  const performers = (parsed as { performers?: unknown }).performers;
  if (!performers || typeof performers !== "object" || Array.isArray(performers)) return undefined;

  const target = normalizeIdentityPath(input.videoPath);
  let best: SpiritFlixSmartPerformerIdentity | undefined;
  for (const performer of Object.values(performers as Record<string, unknown>)) {
    if (!performer || typeof performer !== "object" || Array.isArray(performer)) continue;
    const record = performer as { name?: unknown; slug?: unknown; evidence?: unknown };
    const name = typeof record.name === "string" && record.name.trim()
      ? record.name.trim()
      : typeof record.slug === "string"
        ? titleCaseSlug(record.slug)
        : "";
    if (!name || !Array.isArray(record.evidence)) continue;

    for (const evidence of record.evidence) {
      if (!evidence || typeof evidence !== "object" || Array.isArray(evidence)) continue;
      const evidenceRecord = evidence as { video_path?: unknown; source?: unknown; confidence?: unknown; frame_path?: unknown; sidecar_path?: unknown };
      if (typeof evidenceRecord.video_path !== "string") continue;
      if (normalizeIdentityPath(evidenceRecord.video_path) !== target) continue;
      if (!safeEvidenceSource(typeof evidenceRecord.source === "string" ? evidenceRecord.source : undefined)) continue;
      const confidence = typeof evidenceRecord.confidence === "number" && Number.isFinite(evidenceRecord.confidence)
        ? Math.max(0, Math.min(1, evidenceRecord.confidence))
        : 0.7;
      const candidate: SpiritFlixSmartPerformerIdentity = {
        name,
        source: "face_rec",
        confidence,
        evidenceRef:
          (typeof evidenceRecord.sidecar_path === "string" && evidenceRecord.sidecar_path) ||
          (typeof evidenceRecord.frame_path === "string" && evidenceRecord.frame_path) ||
          FACE_VERIFICATION_RELATIVE_PATH,
        requiresReview: confidence < 0.95,
      };
      if (!best || candidate.confidence > best.confidence) best = candidate;
    }
  }

  return best;
}

export function buildSpiritFlixReviewSuggestions(
  input: SpiritFlixSmartHeuristicInput,
  options?: { analysis?: SpiritFlixSmartAnalysis; performerIdentity?: SpiritFlixSmartPerformerIdentity },
): SpiritFlixSmartSuggestionResult {
  const performerIdentity = options?.performerIdentity ?? modelIdentityFromPath(input) ?? unknownModelIdentity();
  const technicalTags = dedupeTags([
    ...inferQualityTags(input),
    ...inferFormatTags(input),
    ...inferSourceTags(input),
  ]).filter(isTechnicalOrStatusTag);
  const suggestedTags = dedupeTags(suggestionsFromExistingFrameEvidence(options?.analysis).filter(isPrimarySmartContentTag));
  const suggestedCategory = inferCategoryHint(input);
  const suggestedDisplayTitle = buildSuggestedFilename(input, suggestedTags, performerIdentity);
  const suggestedFilename = suggestedDisplayTitle;
  const confidence = suggestedTags.length > 0 ? averageConfidence(suggestedTags) : Math.max(0.2, performerIdentity.confidence * 0.6);
  const notes = buildHeuristicNotes(input);
  const suggestedFilenameReason = filenameReason(input, suggestedTags, performerIdentity);
  notes.push(suggestedFilenameReason);
  if (suggestedTags.length > 0) {
    notes.push("Visual content tags came from sampled-frame evidence and require operator review before confirm.");
  } else {
    notes.push("No sampled-frame content tags were produced; recommendations fall back to title, path, metadata, and face-rec evidence.");
  }
  if (technicalTags.length > 0) {
    notes.push(`technical metadata kept out of primary smart tags: ${technicalTags.map((tag) => tag.label).join(", ")}`);
  }
  if (performerIdentity.source === "face_rec") {
    notes.push(`performer identity from read-only face evidence: ${performerIdentity.name}`);
  } else if (performerIdentity.source === "path") {
    notes.push(`performer identity from model folder: ${performerIdentity.name}`);
  }

  if (hasAmbiguousFilename(input)) {
    notes.push("needs title cleanup status set; not emitted as a primary smart tag");
  }

  return {
    suggestedTags,
    suggestedCategory,
    suggestedCollections: suggestedCategory ? [suggestedCategory] : [],
    suggestedDisplayTitle,
    suggestedFilename,
    contentTagEvidence: contentEvidenceFor(input, suggestedTags, technicalTags, options?.analysis, performerIdentity),
    performerIdentity,
    suggestedFilenameReason,
    confidence,
    notes,
  };
}

function mergeNotes(existing: string | undefined, additions: string[]): string {
  const parts = new Set<string>();
  if (existing?.trim()) parts.add(existing.trim());
  for (const note of additions) {
    if (note.trim()) parts.add(note.trim());
  }
  return [...parts].join(" | ").slice(0, 8_000);
}

export function applySpiritFlixReviewSuggestionsToAnalysis(
  analysis: SpiritFlixSmartAnalysis,
  suggestions: SpiritFlixSmartSuggestionResult,
): SpiritFlixSmartAnalysis {
  const ambiguous = suggestions.suggestedTags.some((tag) => tag.reviewRequired) || suggestions.confidence < 0.55;
  const status = ambiguous ? "needs_review" : "suggested";

  return validateSpiritFlixSmartAnalysis({
    ...analysis,
    analyzedAt: new Date().toISOString(),
    analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S3,
    status,
    safety: {
      safeToSuggest: false,
      reasons: ["Heuristic suggestions require human review before any Level 2 action."],
      requiresHumanReview: true,
    },
    media: analysis.media,
    samples: analysis.samples,
    contentTagEvidence: suggestions.contentTagEvidence,
    performerIdentity: suggestions.performerIdentity,
    suggestedTags: suggestions.suggestedTags,
    pendingSmartTags: suggestions.suggestedTags,
    suggestedCategory: suggestions.suggestedCategory,
    suggestedCollections: suggestions.suggestedCollections.length > 0 ? suggestions.suggestedCollections : undefined,
    suggestedDisplayTitle: suggestions.suggestedDisplayTitle,
    suggestedFilename: suggestions.suggestedFilename,
    pendingDisplayName: suggestions.suggestedDisplayTitle,
    confidence: suggestions.confidence,
    notes: mergeNotes(analysis.notes, suggestions.notes),
  });
}

export async function updateSmartAnalysisWithHeuristicSuggestions(
  input: SpiritFlixSmartHeuristicInput,
  options?: { mediaRoot?: string },
): Promise<SpiritFlixSmartAnalysis> {
  const pathOpts = pathOptions(options?.mediaRoot);
  const videoPath = assertSmartVideoPathCandidate(input.videoPath, pathOpts);

  let fileSizeBytes = input.fileSizeBytes;
  let mtimeMs = input.mtimeMs;
  if (fileSizeBytes === undefined || mtimeMs === undefined) {
    const stat = await fs.stat(videoPath);
    fileSizeBytes = stat.size;
    mtimeMs = stat.mtimeMs;
  }

  const pathInput = { videoPath, fileSizeBytes, mtimeMs };
  const existing = await readSmartAnalysis(pathInput, pathOpts);
  const base =
    existing ??
    createEmptySmartAnalysis(
      {
        videoPath,
        fileName: input.fileName,
        fileSizeBytes,
        mtimeMs,
        analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S3,
      },
      pathOpts,
    );

  const heuristicInput: SpiritFlixSmartHeuristicInput = {
    ...input,
    videoPath,
    fileName: input.fileName,
    parentPath: input.parentPath ?? path.dirname(videoPath),
    fileSizeBytes,
    mtimeMs,
    media: input.media ?? base.media,
  };

  const performerIdentity =
    await findReadOnlyFacePerformerIdentity(heuristicInput) ??
    modelIdentityFromPath(heuristicInput) ??
    unknownModelIdentity();
  const suggestions = buildSpiritFlixReviewSuggestions(heuristicInput, {
    analysis: base,
    performerIdentity,
  });
  const updated = applySpiritFlixReviewSuggestionsToAnalysis(base, suggestions);
  const { analysis } = await writeSmartAnalysis(updated, pathOpts);
  return analysis;
}

// â”€â”€ SpiritFlix Smart Analysis types (S1) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Schema + validators only. Scanner lane writes these; never mutates media.

export type SpiritFlixSmartStatus =
  | "not_analyzed"
  | "analyzing"
  | "needs_review"
  | "suggested"
  | "approved"
  | "rejected"
  | "blocked";

export type SpiritFlixSmartTagGroup =
  | "format"
  | "source"
  | "performer"
  | "scene"
  | "activity"
  | "position"
  | "style"
  | "quality"
  | "watermark"
  | "safety"
  | "unknown";

export type SpiritFlixSmartConfidenceBand = "high" | "medium" | "weak" | "ignore";

export type SpiritFlixSmartReviewStatus = "unreviewed" | "partially_reviewed" | "reviewed" | "rejected";

export type SpiritFlixSmartContentEvidenceSource =
  | "filename"
  | "path"
  | "metadata"
  | "face_rec"
  | "frame_sample"
  | "ocr"
  | "vlm";

export interface SpiritFlixSmartContentTagEvidence {
  source: SpiritFlixSmartContentEvidenceSource;
  tags: string[];
  confidence: number;
  evidenceRef: string | null;
  requiresReview: boolean;
}

export type SpiritFlixSmartPerformerIdentitySource =
  | "reviewed"
  | "face_rec"
  | "path"
  | "unknown";

export interface SpiritFlixSmartPerformerIdentity {
  name: string;
  source: SpiritFlixSmartPerformerIdentitySource;
  confidence: number;
  evidenceRef?: string;
  requiresReview: boolean;
}

export interface SpiritFlixSmartReviewedMetadata {
  reviewedAt: string;
  reviewedBy: "spiritflix-admin";
  reviewStatus: SpiritFlixSmartReviewStatus;
  approvedTagIds: string[];
  rejectedTagIds: string[];
  editedDisplayTitle?: string;
  editedFilenameSuggestion?: string;
  editedCategory?: string;
  editedCollections?: string[];
  notes?: string;
}

export interface SpiritFlixSmartReviewInput {
  approvedTagIds: string[];
  rejectedTagIds: string[];
  editedDisplayTitle?: string;
  editedFilenameSuggestion?: string;
  editedCategory?: string;
  editedCollections?: string[];
  notes?: string;
}

export interface SpiritFlixSmartTag {
  id: string;
  label: string;
  group: SpiritFlixSmartTagGroup;
  confidence: number;
  evidenceTimestamps: number[];
  reviewRequired: boolean;
}

export interface SpiritFlixSmartSample {
  timestampSeconds: number;
  timestampLabel: string;
  cacheKey?: string;
  observations: string[];
  tags: SpiritFlixSmartTag[];
  confidence: number;
}

export type SpiritFlixSmartVisualAnalysisStatus = "not_run" | "complete" | "partial" | "failed";

export interface SpiritFlixSmartVisualAnalysisFrame {
  timestampSeconds: number;
  timestampLabel: string;
  cacheKey?: string;
  status: "complete" | "failed";
  tags: string[];
  observations: string[];
  error?: string;
}

export interface SpiritFlixSmartVisualAnalysis {
  status: SpiritFlixSmartVisualAnalysisStatus;
  modelName: string;
  analyzedAt: string;
  sampledFrameCount: number;
  analyzedFrameCount: number;
  tags: string[];
  frames: SpiritFlixSmartVisualAnalysisFrame[];
  error?: string;
}

export interface SpiritFlixSmartAnalysis {
  version: 1;
  videoPath: string;
  pathKey: string;
  fileName: string;
  fileSizeBytes: number;
  mtimeMs: number;
  analyzedAt: string;
  analyzerVersion: string;
  status: SpiritFlixSmartStatus;
  safety: {
    safeToSuggest: boolean;
    reasons: string[];
    requiresHumanReview: boolean;
  };
  media: {
    durationSeconds?: number;
    width?: number;
    height?: number;
    codec?: string;
    container?: string;
  };
  samples: SpiritFlixSmartSample[];
  visualAnalysis?: SpiritFlixSmartVisualAnalysis;
  contentTagEvidence?: SpiritFlixSmartContentTagEvidence[];
  performerIdentity?: SpiritFlixSmartPerformerIdentity;
  suggestedTags: SpiritFlixSmartTag[];
  pendingSmartTags?: SpiritFlixSmartTag[];
  suggestedCategory?: string;
  suggestedCollections?: string[];
  suggestedDisplayTitle?: string;
  suggestedFilename?: string;
  pendingDisplayName?: string;
  suggestedTargetFolder?: string;
  confidence: number;
  notes?: string;
  reviewedMetadata?: SpiritFlixSmartReviewedMetadata;
}

const SMART_REVIEW_STATUSES = new Set<SpiritFlixSmartReviewStatus>([
  "unreviewed",
  "partially_reviewed",
  "reviewed",
  "rejected",
]);

const SMART_CONTENT_EVIDENCE_SOURCES = new Set<SpiritFlixSmartContentEvidenceSource>([
  "filename",
  "path",
  "metadata",
  "face_rec",
  "frame_sample",
  "ocr",
  "vlm",
]);

const SMART_VISUAL_ANALYSIS_STATUSES = new Set<SpiritFlixSmartVisualAnalysisStatus>([
  "not_run",
  "complete",
  "partial",
  "failed",
]);

const SMART_PERFORMER_IDENTITY_SOURCES = new Set<SpiritFlixSmartPerformerIdentitySource>([
  "reviewed",
  "face_rec",
  "path",
  "unknown",
]);

const SMART_STATUSES = new Set<SpiritFlixSmartStatus>([
  "not_analyzed",
  "analyzing",
  "needs_review",
  "suggested",
  "approved",
  "rejected",
  "blocked",
]);

const SMART_TAG_GROUPS = new Set<SpiritFlixSmartTagGroup>([
  "format",
  "source",
  "performer",
  "scene",
  "activity",
  "position",
  "style",
  "quality",
  "watermark",
  "safety",
  "unknown",
]);

const POLLUTION_KEYS = new Set(["__proto__", "constructor", "prototype"]);

export const SMART_ANALYSIS_LIMITS = {
  maxSamples: 100,
  maxTagsPerList: 200,
  maxObservationsPerSample: 50,
  maxEvidenceTimestamps: 50,
  maxSafetyReasons: 20,
  maxCollections: 50,
  maxNotesLength: 8_192,
  maxPathLength: 4_096,
  maxLabelLength: 256,
  maxIdLength: 128,
  maxPayloadBytes: 512_000,
} as const;

function assertNoPollutionKeys(record: Record<string, unknown>, context: string): void {
  for (const key of Object.keys(record)) {
    if (POLLUTION_KEYS.has(key)) {
      throw new Error(`Unsafe key "${key}" in ${context}.`);
    }
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function assertConfidence(value: unknown, field: string): number {
  if (typeof value !== "number" || !Number.isFinite(value) || value < 0 || value > 1) {
    throw new Error(`${field} must be a number between 0 and 1.`);
  }
  return value;
}

function assertNonEmptyString(value: unknown, field: string, maxLength: number = SMART_ANALYSIS_LIMITS.maxPathLength): string {
  if (typeof value !== "string" || !value.trim()) {
    throw new Error(`${field} must be a non-empty string.`);
  }
  if (value.length > maxLength) {
    throw new Error(`${field} is too long.`);
  }
  if (value.includes("\0")) {
    throw new Error(`${field} contains invalid characters.`);
  }
  return value;
}

function assertOptionalString(value: unknown, field: string, maxLength: number = SMART_ANALYSIS_LIMITS.maxLabelLength): string | undefined {
  if (value === undefined) return undefined;
  return assertNonEmptyString(value, field, maxLength);
}

function assertSafePathString(value: unknown, field: string): string {
  const pathValue = assertNonEmptyString(value, field);
  if (pathValue.split(/[\\/]+/).some((segment) => segment === "..")) {
    throw new Error(`${field} must not contain traversal segments.`);
  }
  return pathValue;
}

export function validateSpiritFlixSmartTag(value: unknown): SpiritFlixSmartTag {
  if (!isPlainObject(value)) throw new Error("Tag must be an object.");
  assertNoPollutionKeys(value, "tag");

  const id = assertNonEmptyString(value.id, "tag.id", SMART_ANALYSIS_LIMITS.maxIdLength);
  const label = assertNonEmptyString(value.label, "tag.label", SMART_ANALYSIS_LIMITS.maxLabelLength);
  const group = value.group;
  if (typeof group !== "string" || !SMART_TAG_GROUPS.has(group as SpiritFlixSmartTagGroup)) {
    throw new Error("tag.group is invalid.");
  }
  const confidence = assertConfidence(value.confidence, "tag.confidence");
  if (!Array.isArray(value.evidenceTimestamps)) {
    throw new Error("tag.evidenceTimestamps must be an array.");
  }
  if (value.evidenceTimestamps.length > SMART_ANALYSIS_LIMITS.maxEvidenceTimestamps) {
    throw new Error("tag.evidenceTimestamps is too large.");
  }
  const evidenceTimestamps = value.evidenceTimestamps.map((entry, index) => {
    if (typeof entry !== "number" || !Number.isFinite(entry) || entry < 0) {
      throw new Error(`tag.evidenceTimestamps[${index}] must be a non-negative number.`);
    }
    return entry;
  });
  if (typeof value.reviewRequired !== "boolean") {
    throw new Error("tag.reviewRequired must be a boolean.");
  }

  return { id, label, group: group as SpiritFlixSmartTagGroup, confidence, evidenceTimestamps, reviewRequired: value.reviewRequired };
}

export function validateSpiritFlixSmartSample(value: unknown): SpiritFlixSmartSample {
  if (!isPlainObject(value)) throw new Error("Sample must be an object.");
  assertNoPollutionKeys(value, "sample");

  const timestampSeconds =
    typeof value.timestampSeconds === "number" && Number.isFinite(value.timestampSeconds) && value.timestampSeconds >= 0
      ? value.timestampSeconds
      : (() => {
          throw new Error("sample.timestampSeconds must be a non-negative number.");
        })();
  const timestampLabel = assertNonEmptyString(value.timestampLabel, "sample.timestampLabel", 64);
  const cacheKey = value.cacheKey === undefined ? undefined : assertNonEmptyString(value.cacheKey, "sample.cacheKey", 128);
  if (!Array.isArray(value.observations)) throw new Error("sample.observations must be an array.");
  if (value.observations.length > SMART_ANALYSIS_LIMITS.maxObservationsPerSample) {
    throw new Error("sample.observations is too large.");
  }
  const observations = value.observations.map((entry, index) =>
    assertNonEmptyString(entry, `sample.observations[${index}]`, SMART_ANALYSIS_LIMITS.maxLabelLength),
  );
  if (!Array.isArray(value.tags)) throw new Error("sample.tags must be an array.");
  if (value.tags.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) {
    throw new Error("sample.tags is too large.");
  }
  const tags = value.tags.map((entry) => validateSpiritFlixSmartTag(entry));
  const confidence = assertConfidence(value.confidence, "sample.confidence");

  return { timestampSeconds, timestampLabel, cacheKey, observations, tags, confidence };
}

export function validateSpiritFlixSmartContentTagEvidence(value: unknown): SpiritFlixSmartContentTagEvidence {
  if (!isPlainObject(value)) throw new Error("contentTagEvidence entry must be an object.");
  assertNoPollutionKeys(value, "contentTagEvidence");

  const source = value.source;
  if (typeof source !== "string" || !SMART_CONTENT_EVIDENCE_SOURCES.has(source as SpiritFlixSmartContentEvidenceSource)) {
    throw new Error("contentTagEvidence.source is invalid.");
  }

  if (!Array.isArray(value.tags)) throw new Error("contentTagEvidence.tags must be an array.");
  if (value.tags.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) {
    throw new Error("contentTagEvidence.tags is too large.");
  }
  const tags = value.tags.map((entry, index) =>
    assertNonEmptyString(entry, `contentTagEvidence.tags[${index}]`, SMART_ANALYSIS_LIMITS.maxIdLength),
  );
  const confidence = assertConfidence(value.confidence, "contentTagEvidence.confidence");
  const evidenceRef =
    value.evidenceRef === null || value.evidenceRef === undefined
      ? null
      : assertNonEmptyString(value.evidenceRef, "contentTagEvidence.evidenceRef", 512);
  if (typeof value.requiresReview !== "boolean") {
    throw new Error("contentTagEvidence.requiresReview must be a boolean.");
  }

  return {
    source: source as SpiritFlixSmartContentEvidenceSource,
    tags,
    confidence,
    evidenceRef,
    requiresReview: value.requiresReview,
  };
}

function validateSpiritFlixSmartVisualAnalysisFrame(value: unknown): SpiritFlixSmartVisualAnalysisFrame {
  if (!isPlainObject(value)) throw new Error("visualAnalysis.frame must be an object.");
  assertNoPollutionKeys(value, "visualAnalysis.frame");
  const timestampSeconds =
    typeof value.timestampSeconds === "number" && Number.isFinite(value.timestampSeconds) && value.timestampSeconds >= 0
      ? value.timestampSeconds
      : (() => {
          throw new Error("visualAnalysis.frame.timestampSeconds must be a non-negative number.");
        })();
  const timestampLabel = assertNonEmptyString(value.timestampLabel, "visualAnalysis.frame.timestampLabel", 64);
  const cacheKey = value.cacheKey === undefined ? undefined : assertNonEmptyString(value.cacheKey, "visualAnalysis.frame.cacheKey", 128);
  if (value.status !== "complete" && value.status !== "failed") {
    throw new Error("visualAnalysis.frame.status is invalid.");
  }
  if (!Array.isArray(value.tags)) throw new Error("visualAnalysis.frame.tags must be an array.");
  const tags = value.tags.map((entry, index) =>
    assertNonEmptyString(entry, `visualAnalysis.frame.tags[${index}]`, SMART_ANALYSIS_LIMITS.maxIdLength),
  );
  if (!Array.isArray(value.observations)) throw new Error("visualAnalysis.frame.observations must be an array.");
  const observations = value.observations.map((entry, index) =>
    assertNonEmptyString(entry, `visualAnalysis.frame.observations[${index}]`, SMART_ANALYSIS_LIMITS.maxLabelLength),
  );
  const error = value.error === undefined ? undefined : assertNonEmptyString(value.error, "visualAnalysis.frame.error", 512);
  return {
    timestampSeconds,
    timestampLabel,
    cacheKey,
    status: value.status,
    tags,
    observations,
    error,
  };
}

export function validateSpiritFlixSmartVisualAnalysis(value: unknown): SpiritFlixSmartVisualAnalysis {
  if (!isPlainObject(value)) throw new Error("visualAnalysis must be an object.");
  assertNoPollutionKeys(value, "visualAnalysis");
  const status = value.status;
  if (typeof status !== "string" || !SMART_VISUAL_ANALYSIS_STATUSES.has(status as SpiritFlixSmartVisualAnalysisStatus)) {
    throw new Error("visualAnalysis.status is invalid.");
  }
  const modelName = assertNonEmptyString(value.modelName, "visualAnalysis.modelName", 128);
  const analyzedAt = assertNonEmptyString(value.analyzedAt, "visualAnalysis.analyzedAt", 64);
  const sampledFrameCount =
    typeof value.sampledFrameCount === "number" && Number.isFinite(value.sampledFrameCount) && value.sampledFrameCount >= 0
      ? Math.floor(value.sampledFrameCount)
      : (() => {
          throw new Error("visualAnalysis.sampledFrameCount must be a non-negative number.");
        })();
  const analyzedFrameCount =
    typeof value.analyzedFrameCount === "number" && Number.isFinite(value.analyzedFrameCount) && value.analyzedFrameCount >= 0
      ? Math.floor(value.analyzedFrameCount)
      : (() => {
          throw new Error("visualAnalysis.analyzedFrameCount must be a non-negative number.");
        })();
  if (!Array.isArray(value.tags)) throw new Error("visualAnalysis.tags must be an array.");
  const tags = value.tags.map((entry, index) =>
    assertNonEmptyString(entry, `visualAnalysis.tags[${index}]`, SMART_ANALYSIS_LIMITS.maxIdLength),
  );
  if (!Array.isArray(value.frames)) throw new Error("visualAnalysis.frames must be an array.");
  const frames = value.frames.map((entry) => validateSpiritFlixSmartVisualAnalysisFrame(entry));
  const error = value.error === undefined ? undefined : assertNonEmptyString(value.error, "visualAnalysis.error", 512);
  return {
    status: status as SpiritFlixSmartVisualAnalysisStatus,
    modelName,
    analyzedAt,
    sampledFrameCount,
    analyzedFrameCount,
    tags,
    frames,
    error,
  };
}

export function validateSpiritFlixSmartPerformerIdentity(value: unknown): SpiritFlixSmartPerformerIdentity {
  if (!isPlainObject(value)) throw new Error("performerIdentity must be an object.");
  assertNoPollutionKeys(value, "performerIdentity");

  const name = assertNonEmptyString(value.name, "performerIdentity.name", 256);
  const source = value.source;
  if (typeof source !== "string" || !SMART_PERFORMER_IDENTITY_SOURCES.has(source as SpiritFlixSmartPerformerIdentitySource)) {
    throw new Error("performerIdentity.source is invalid.");
  }
  const confidence = assertConfidence(value.confidence, "performerIdentity.confidence");
  const evidenceRef = assertOptionalString(value.evidenceRef, "performerIdentity.evidenceRef", 512);
  if (typeof value.requiresReview !== "boolean") {
    throw new Error("performerIdentity.requiresReview must be a boolean.");
  }

  return {
    name,
    source: source as SpiritFlixSmartPerformerIdentitySource,
    confidence,
    evidenceRef,
    requiresReview: value.requiresReview,
  };
}

export function validateSpiritFlixSmartReviewedMetadata(value: unknown): SpiritFlixSmartReviewedMetadata {
  if (!isPlainObject(value)) throw new Error("reviewedMetadata must be an object.");
  assertNoPollutionKeys(value, "reviewedMetadata");

  const reviewedAt = assertNonEmptyString(value.reviewedAt, "reviewedMetadata.reviewedAt", 64);
  if (value.reviewedBy !== "spiritflix-admin") {
    throw new Error("reviewedMetadata.reviewedBy must be spiritflix-admin.");
  }
  const reviewStatus = value.reviewStatus;
  if (typeof reviewStatus !== "string" || !SMART_REVIEW_STATUSES.has(reviewStatus as SpiritFlixSmartReviewStatus)) {
    throw new Error("reviewedMetadata.reviewStatus is invalid.");
  }

  if (!Array.isArray(value.approvedTagIds)) throw new Error("reviewedMetadata.approvedTagIds must be an array.");
  if (!Array.isArray(value.rejectedTagIds)) throw new Error("reviewedMetadata.rejectedTagIds must be an array.");
  if (value.approvedTagIds.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) {
    throw new Error("reviewedMetadata.approvedTagIds is too large.");
  }
  if (value.rejectedTagIds.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) {
    throw new Error("reviewedMetadata.rejectedTagIds is too large.");
  }

  const approvedTagIds = value.approvedTagIds.map((entry, index) =>
    assertNonEmptyString(entry, `reviewedMetadata.approvedTagIds[${index}]`, SMART_ANALYSIS_LIMITS.maxIdLength),
  );
  const rejectedTagIds = value.rejectedTagIds.map((entry, index) =>
    assertNonEmptyString(entry, `reviewedMetadata.rejectedTagIds[${index}]`, SMART_ANALYSIS_LIMITS.maxIdLength),
  );
  const overlap = approvedTagIds.find((id) => rejectedTagIds.includes(id));
  if (overlap) throw new Error("reviewedMetadata approved/rejected tag ids must not overlap.");

  const editedDisplayTitle = assertOptionalString(value.editedDisplayTitle, "reviewedMetadata.editedDisplayTitle", 512);
  const editedFilenameSuggestion = assertOptionalString(value.editedFilenameSuggestion, "reviewedMetadata.editedFilenameSuggestion", 512);
  const editedCategory = assertOptionalString(value.editedCategory, "reviewedMetadata.editedCategory", 256);

  let editedCollections: string[] | undefined;
  if (value.editedCollections !== undefined) {
    if (!Array.isArray(value.editedCollections)) throw new Error("reviewedMetadata.editedCollections must be an array.");
    if (value.editedCollections.length > SMART_ANALYSIS_LIMITS.maxCollections) {
      throw new Error("reviewedMetadata.editedCollections is too large.");
    }
    editedCollections = value.editedCollections.map((entry, index) =>
      assertNonEmptyString(entry, `reviewedMetadata.editedCollections[${index}]`, SMART_ANALYSIS_LIMITS.maxLabelLength),
    );
  }

  const notes = value.notes === undefined ? undefined : assertNonEmptyString(value.notes, "reviewedMetadata.notes", SMART_ANALYSIS_LIMITS.maxNotesLength);

  return {
    reviewedAt,
    reviewedBy: "spiritflix-admin",
    reviewStatus: reviewStatus as SpiritFlixSmartReviewStatus,
    approvedTagIds,
    rejectedTagIds,
    editedDisplayTitle,
    editedFilenameSuggestion,
    editedCategory,
    editedCollections,
    notes,
  };
}

export function validateSpiritFlixSmartAnalysis(value: unknown): SpiritFlixSmartAnalysis {
  if (!isPlainObject(value)) throw new Error("Analysis must be an object.");
  assertNoPollutionKeys(value, "analysis");

  if (value.version !== 1) throw new Error("analysis.version must be 1.");

  const videoPath = assertSafePathString(value.videoPath, "videoPath");
  const pathKey = assertNonEmptyString(value.pathKey, "pathKey", 128);
  const fileName = assertNonEmptyString(value.fileName, "fileName", 512);
  const fileSizeBytes =
    typeof value.fileSizeBytes === "number" && Number.isFinite(value.fileSizeBytes) && value.fileSizeBytes >= 0
      ? value.fileSizeBytes
      : (() => {
          throw new Error("fileSizeBytes must be a non-negative number.");
        })();
  const mtimeMs =
    typeof value.mtimeMs === "number" && Number.isFinite(value.mtimeMs) && value.mtimeMs >= 0
      ? value.mtimeMs
      : (() => {
          throw new Error("mtimeMs must be a non-negative number.");
        })();
  const analyzedAt = assertNonEmptyString(value.analyzedAt, "analyzedAt", 64);
  const analyzerVersion = assertNonEmptyString(value.analyzerVersion, "analyzerVersion", 128);

  const status = value.status;
  if (typeof status !== "string" || !SMART_STATUSES.has(status as SpiritFlixSmartStatus)) {
    throw new Error("status is invalid.");
  }

  if (!isPlainObject(value.safety)) throw new Error("safety must be an object.");
  assertNoPollutionKeys(value.safety, "safety");
  if (typeof value.safety.safeToSuggest !== "boolean") throw new Error("safety.safeToSuggest must be a boolean.");
  if (!Array.isArray(value.safety.reasons)) throw new Error("safety.reasons must be an array.");
  if (value.safety.reasons.length > SMART_ANALYSIS_LIMITS.maxSafetyReasons) {
    throw new Error("safety.reasons is too large.");
  }
  const reasons = value.safety.reasons.map((entry, index) =>
    assertNonEmptyString(entry, `safety.reasons[${index}]`, SMART_ANALYSIS_LIMITS.maxLabelLength),
  );
  if (typeof value.safety.requiresHumanReview !== "boolean") {
    throw new Error("safety.requiresHumanReview must be a boolean.");
  }

  if (!isPlainObject(value.media)) throw new Error("media must be an object.");
  assertNoPollutionKeys(value.media, "media");
  const media: SpiritFlixSmartAnalysis["media"] = {};
  if (value.media.durationSeconds !== undefined) {
    if (typeof value.media.durationSeconds !== "number" || !Number.isFinite(value.media.durationSeconds) || value.media.durationSeconds < 0) {
      throw new Error("media.durationSeconds must be a non-negative number.");
    }
    media.durationSeconds = value.media.durationSeconds;
  }
  if (value.media.width !== undefined) {
    if (typeof value.media.width !== "number" || !Number.isFinite(value.media.width) || value.media.width <= 0) {
      throw new Error("media.width must be a positive number.");
    }
    media.width = value.media.width;
  }
  if (value.media.height !== undefined) {
    if (typeof value.media.height !== "number" || !Number.isFinite(value.media.height) || value.media.height <= 0) {
      throw new Error("media.height must be a positive number.");
    }
    media.height = value.media.height;
  }
  if (value.media.codec !== undefined) media.codec = assertNonEmptyString(value.media.codec, "media.codec", 64);
  if (value.media.container !== undefined) media.container = assertNonEmptyString(value.media.container, "media.container", 64);

  if (!Array.isArray(value.samples)) throw new Error("samples must be an array.");
  if (value.samples.length > SMART_ANALYSIS_LIMITS.maxSamples) throw new Error("samples is too large.");
  const samples = value.samples.map((entry) => validateSpiritFlixSmartSample(entry));

  const visualAnalysis =
    value.visualAnalysis === undefined ? undefined : validateSpiritFlixSmartVisualAnalysis(value.visualAnalysis);

  let contentTagEvidence: SpiritFlixSmartContentTagEvidence[] | undefined;
  if (value.contentTagEvidence !== undefined) {
    if (!Array.isArray(value.contentTagEvidence)) throw new Error("contentTagEvidence must be an array.");
    if (value.contentTagEvidence.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) {
      throw new Error("contentTagEvidence is too large.");
    }
    contentTagEvidence = value.contentTagEvidence.map((entry) => validateSpiritFlixSmartContentTagEvidence(entry));
  }

  const performerIdentity =
    value.performerIdentity === undefined ? undefined : validateSpiritFlixSmartPerformerIdentity(value.performerIdentity);

  if (!Array.isArray(value.suggestedTags)) throw new Error("suggestedTags must be an array.");
  if (value.suggestedTags.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) throw new Error("suggestedTags is too large.");
  const suggestedTags = value.suggestedTags.map((entry) => validateSpiritFlixSmartTag(entry));
  let pendingSmartTags: SpiritFlixSmartTag[] | undefined;
  if (value.pendingSmartTags !== undefined) {
    if (!Array.isArray(value.pendingSmartTags)) throw new Error("pendingSmartTags must be an array.");
    if (value.pendingSmartTags.length > SMART_ANALYSIS_LIMITS.maxTagsPerList) throw new Error("pendingSmartTags is too large.");
    pendingSmartTags = value.pendingSmartTags.map((entry) => validateSpiritFlixSmartTag(entry));
  }

  const suggestedCategory = assertOptionalString(value.suggestedCategory, "suggestedCategory");
  let suggestedCollections: string[] | undefined;
  if (value.suggestedCollections !== undefined) {
    if (!Array.isArray(value.suggestedCollections)) throw new Error("suggestedCollections must be an array.");
    if (value.suggestedCollections.length > SMART_ANALYSIS_LIMITS.maxCollections) {
      throw new Error("suggestedCollections is too large.");
    }
    suggestedCollections = value.suggestedCollections.map((entry, index) =>
      assertNonEmptyString(entry, `suggestedCollections[${index}]`, SMART_ANALYSIS_LIMITS.maxLabelLength),
    );
  }

  const suggestedDisplayTitle = assertOptionalString(value.suggestedDisplayTitle, "suggestedDisplayTitle", 512);
  const suggestedFilename = assertOptionalString(value.suggestedFilename, "suggestedFilename", 512);
  const pendingDisplayName = assertOptionalString(value.pendingDisplayName, "pendingDisplayName", 512);
  const suggestedTargetFolder =
    value.suggestedTargetFolder === undefined ? undefined : assertSafePathString(value.suggestedTargetFolder, "suggestedTargetFolder");

  const confidence = assertConfidence(value.confidence, "confidence");

  let notes: string | undefined;
  if (value.notes !== undefined) {
    notes = assertNonEmptyString(value.notes, "notes", SMART_ANALYSIS_LIMITS.maxNotesLength);
  }

  const reviewedMetadata =
    value.reviewedMetadata === undefined ? undefined : validateSpiritFlixSmartReviewedMetadata(value.reviewedMetadata);

  const serialized = JSON.stringify({
    version: 1,
    videoPath,
    pathKey,
    fileName,
    samples,
    visualAnalysis,
    contentTagEvidence,
    performerIdentity,
    suggestedTags,
    pendingSmartTags,
    pendingDisplayName,
    notes,
    reviewedMetadata,
  });
  if (serialized.length > SMART_ANALYSIS_LIMITS.maxPayloadBytes) {
    throw new Error("Analysis payload is too large.");
  }

  return {
    version: 1,
    videoPath,
    pathKey,
    fileName,
    fileSizeBytes,
    mtimeMs,
    analyzedAt,
    analyzerVersion,
    status: status as SpiritFlixSmartStatus,
    safety: {
      safeToSuggest: value.safety.safeToSuggest,
      reasons,
      requiresHumanReview: value.safety.requiresHumanReview,
    },
    media,
    samples,
    visualAnalysis,
    contentTagEvidence,
    performerIdentity,
    suggestedTags,
    pendingSmartTags,
    suggestedCategory,
    suggestedCollections,
    suggestedDisplayTitle,
    suggestedFilename,
    pendingDisplayName,
    suggestedTargetFolder,
    confidence,
    notes,
    reviewedMetadata,
  };
}

export function parseSpiritFlixSmartAnalysisJson(raw: string): SpiritFlixSmartAnalysis {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw);
  } catch {
    throw new Error("Analysis sidecar is not valid JSON.");
  }
  return validateSpiritFlixSmartAnalysis(parsed);
}

import fs from "node:fs/promises";
import path from "node:path";
import { findSmartTagDefinition, getSmartTagVocabulary, normalizeSmartTagId } from "./vocabulary";
import type { SpiritFlixSmartAnalysis, SpiritFlixSmartSample, SpiritFlixSmartTag, SpiritFlixSmartVisualAnalysisFrame } from "./types";

export const SPIRITFLIX_SMART_ANALYZER_VERSION_S9 = "spiritflix-smart/s9";

const DEFAULT_OLLAMA_MODEL = "gemma3n:e4b";
const DEFAULT_OLLAMA_URL = "http://127.0.0.1:11434/api/generate";
const DEFAULT_TIMEOUT_MS = 90_000;
const MAX_VISUAL_SAMPLES = 4;
const MIN_TAG_CONFIDENCE = 0.45;

const VISUAL_TAG_IDS = getSmartTagVocabulary()
  .filter((entry) => ["scene", "activity", "position", "style", "watermark"].includes(entry.group))
  .map((entry) => entry.id);

export interface SpiritFlixVisualAnalysisOptions {
  enabled?: boolean;
  mediaRoot?: string;
  ollamaModel?: string;
  ollamaUrl?: string;
  timeoutMs?: number;
  maxSamples?: number;
}

interface VisualModelTag {
  id?: unknown;
  label?: unknown;
  confidence?: unknown;
  evidence?: unknown;
}

interface VisualModelResponse {
  tags?: unknown;
  observations?: unknown;
  confidence?: unknown;
}

function clampConfidence(value: unknown, fallback = 0.55): number {
  if (typeof value !== "number" || !Number.isFinite(value)) return fallback;
  return Math.max(0, Math.min(1, value));
}

function extractJsonObject(value: string): VisualModelResponse | null {
  const fenced = value.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1];
  const raw = (fenced ?? value).trim();
  const start = raw.indexOf("{");
  const end = raw.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(raw.slice(start, end + 1)) as VisualModelResponse;
  } catch {
    return null;
  }
}

function makeVisualTag(entry: VisualModelTag, timestampSeconds: number): SpiritFlixSmartTag | null {
  const id = typeof entry.id === "string"
    ? normalizeSmartTagId(entry.id)
    : typeof entry.label === "string"
      ? normalizeSmartTagId(entry.label)
      : null;
  if (!id || !VISUAL_TAG_IDS.includes(id)) return null;
  const definition = findSmartTagDefinition(id);
  if (!definition) return null;
  const confidence = clampConfidence(entry.confidence);
  if (confidence < MIN_TAG_CONFIDENCE) return null;
  return {
    id: definition.id,
    label: definition.label,
    group: definition.group,
    confidence,
    evidenceTimestamps: [timestampSeconds],
    reviewRequired: true,
  };
}

function promptForFrame(sample: SpiritFlixSmartSample): string {
  return [
    "You are tagging one sampled video frame for a private local media library.",
    "Return JSON only. Do not include markdown.",
    `Frame timestamp: ${sample.timestampLabel}.`,
    `Allowed tag ids: ${VISUAL_TAG_IDS.join(", ")}.`,
    "Use only visible evidence. If unsure, return unclear with low confidence.",
    "Schema: {\"tags\":[{\"id\":\"tag-id\",\"confidence\":0.0,\"evidence\":\"short visible cue\"}],\"observations\":[\"short cue\"],\"confidence\":0.0}",
  ].join("\n");
}

async function postOllamaImage(
  framePath: string,
  prompt: string,
  options: Required<Pick<SpiritFlixVisualAnalysisOptions, "ollamaModel" | "ollamaUrl" | "timeoutMs">>,
): Promise<VisualModelResponse> {
  const image = await fs.readFile(framePath, "base64");
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), options.timeoutMs);
  try {
    const response = await fetch(options.ollamaUrl, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model: options.ollamaModel,
        prompt,
        images: [image],
        stream: false,
        options: { temperature: 0 },
      }),
      signal: controller.signal,
    });
    if (!response.ok) {
      throw new Error(`local visual model returned HTTP ${response.status}`);
    }
    const payload = await response.json() as { response?: unknown };
    const parsed = typeof payload.response === "string" ? extractJsonObject(payload.response) : null;
    if (!parsed) throw new Error("local visual model did not return parseable JSON");
    return parsed;
  } finally {
    clearTimeout(timeout);
  }
}

function mergeSampleTags(sample: SpiritFlixSmartSample, tags: SpiritFlixSmartTag[]): SpiritFlixSmartSample {
  const byId = new Map<string, SpiritFlixSmartTag>();
  for (const tag of [...sample.tags, ...tags]) {
    const existing = byId.get(tag.id);
    if (!existing || tag.confidence > existing.confidence) byId.set(tag.id, tag);
  }
  const mergedTags = [...byId.values()].sort((left, right) => right.confidence - left.confidence);
  return {
    ...sample,
    tags: mergedTags,
    confidence: mergedTags.length ? Math.max(...mergedTags.map((tag) => tag.confidence)) : sample.confidence,
  };
}

export async function applyLocalVisualAnalysisToSpiritFlixAnalysis(
  analysis: SpiritFlixSmartAnalysis,
  options: SpiritFlixVisualAnalysisOptions = {},
): Promise<SpiritFlixSmartAnalysis> {
  if (options.enabled === false) return analysis;
  const samplesWithFrames = analysis.samples.filter((sample) => sample.cacheKey).slice(0, options.maxSamples ?? MAX_VISUAL_SAMPLES);
  if (samplesWithFrames.length === 0) {
    return {
      ...analysis,
      visualAnalysis: {
        status: "not_run",
        modelName: options.ollamaModel ?? process.env.SPIRITFLIX_SMART_VISION_MODEL ?? DEFAULT_OLLAMA_MODEL,
        analyzedAt: new Date().toISOString(),
        sampledFrameCount: 0,
        analyzedFrameCount: 0,
        tags: [],
        frames: [],
        error: "No sampled frames were available.",
      },
      notes: [analysis.notes, "S9 local visual analysis skipped: no sampled frames were available."].filter(Boolean).join(" | "),
    };
  }

  const modelOptions = {
    ollamaModel: options.ollamaModel ?? process.env.SPIRITFLIX_SMART_VISION_MODEL ?? DEFAULT_OLLAMA_MODEL,
    ollamaUrl: options.ollamaUrl ?? process.env.SPIRITFLIX_SMART_OLLAMA_URL ?? DEFAULT_OLLAMA_URL,
    timeoutMs: options.timeoutMs ?? DEFAULT_TIMEOUT_MS,
  };

  const samples = [...analysis.samples];
  const notes: string[] = [];
  const evidenceTags = new Set<string>();
  const frames: SpiritFlixSmartVisualAnalysisFrame[] = [];
  let analyzedFrames = 0;

  for (const sample of samplesWithFrames) {
    const frameCachePath = await findFramePathForSample(analysis, sample, options.mediaRoot);
    if (!frameCachePath) {
      notes.push(`S9 local visual analysis skipped ${sample.timestampLabel}: cached frame not found.`);
      continue;
    }
    try {
      const response = await postOllamaImage(frameCachePath, promptForFrame(sample), modelOptions);
      const modelTags = Array.isArray(response.tags) ? response.tags as VisualModelTag[] : [];
      const tags = modelTags
        .map((entry) => makeVisualTag(entry, sample.timestampSeconds))
        .filter((tag): tag is SpiritFlixSmartTag => tag != null);
      const observations = Array.isArray(response.observations)
        ? response.observations.filter((entry): entry is string => typeof entry === "string" && entry.trim().length > 0).slice(0, 3)
        : [];
      const index = samples.findIndex((entry) => entry.timestampSeconds === sample.timestampSeconds && entry.cacheKey === sample.cacheKey);
      if (index >= 0) {
        samples[index] = mergeSampleTags(
          {
            ...samples[index],
            observations: [...new Set([...samples[index].observations, ...observations.map((entry) => `vlm: ${entry.trim()}`)])],
          },
          tags,
        );
      }
      tags.forEach((tag) => evidenceTags.add(tag.id));
      frames.push({
        timestampSeconds: sample.timestampSeconds,
        timestampLabel: sample.timestampLabel,
        cacheKey: sample.cacheKey,
        status: "complete",
        tags: tags.map((tag) => tag.id),
        observations,
      });
      analyzedFrames += 1;
    } catch (error) {
      const message = error instanceof Error ? error.message : "local visual model failed";
      notes.push(`S9 local visual analysis failed ${sample.timestampLabel}: ${message}`);
      frames.push({
        timestampSeconds: sample.timestampSeconds,
        timestampLabel: sample.timestampLabel,
        cacheKey: sample.cacheKey,
        status: "failed",
        tags: [],
        observations: [],
        error: message,
      });
    }
  }

  const contentTagEvidence = [
    ...(analysis.contentTagEvidence ?? []).filter((entry) => entry.source !== "vlm"),
    {
      source: "vlm" as const,
      tags: [...evidenceTags],
      confidence: evidenceTags.size > 0 ? 0.65 : 0,
      evidenceRef: modelOptions.ollamaModel,
      requiresReview: true,
    },
  ];

  notes.push(`S9 local visual analysis used ${modelOptions.ollamaModel} on ${analyzedFrames}/${samplesWithFrames.length} sampled frames; all VLM tags require review.`);

  return {
    ...analysis,
    analyzerVersion: SPIRITFLIX_SMART_ANALYZER_VERSION_S9,
    samples,
    visualAnalysis: {
      status: evidenceTags.size > 0 ? "complete" : analyzedFrames > 0 ? "partial" : "failed",
      modelName: modelOptions.ollamaModel,
      analyzedAt: new Date().toISOString(),
      sampledFrameCount: samplesWithFrames.length,
      analyzedFrameCount: analyzedFrames,
      tags: [...evidenceTags],
      frames,
      error: evidenceTags.size > 0 ? undefined : notes.find((note) => /failed/i.test(note)),
    },
    contentTagEvidence,
    notes: [analysis.notes, ...notes].filter(Boolean).join(" | ").slice(0, 8_000),
  };
}

async function findFramePathForSample(analysis: SpiritFlixSmartAnalysis, sample: SpiritFlixSmartSample, mediaRoot?: string): Promise<string | null> {
  if (!sample.cacheKey) return null;
  const root = mediaRoot ?? await findMediaRoot(analysis.videoPath);
  const framesRoot = path.join(root, ".spiritflix-admin", "analysis-cache", "frames");
  const expected = path.join(framesRoot, `${sample.cacheKey}.jpg`);
  try {
    const stat = await fs.stat(expected);
    return stat.isFile() && stat.size > 0 ? expected : null;
  } catch {
    return null;
  }
}

async function findMediaRoot(videoPath: string): Promise<string> {
  let current = path.resolve(path.dirname(videoPath));
  while (true) {
    if (path.basename(current) === "media") return current;
    const parent = path.dirname(current);
    if (parent === current) return path.resolve(path.dirname(videoPath));
    current = parent;
  }
}

// â”€â”€ SpiritFlix controlled tag vocabulary (S1) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
// Broad private tags only. Nothing auto-applies in S1.

import type { SpiritFlixSmartConfidenceBand, SpiritFlixSmartTagGroup } from "./types";

export interface SpiritFlixSmartTagDefinition {
  id: string;
  label: string;
  group: SpiritFlixSmartTagGroup;
  /** Vocabulary default â€” suggested tags still carry their own flag at runtime. */
  reviewRequired: boolean;
}

const EXPLICIT_ACTIVITY_IDS = new Set([
  "toy",
  "oral",
  "manual",
  "intercourse",
  "anal",
  "lesbian",
  "massage",
  "riding",
  "missionary",
