export interface SpiritFlixHomeData {
  libraries: JellyfinLibrary[];
  playlists: JellyfinItem[];
  selectedLibraryId: string | null;
  featuredItems: JellyfinItem[];
  libraryItems: JellyfinItem[];
  continueWatching: JellyfinItem[];
  latestAdded: JellyfinItem[];
  favorites: JellyfinItem[];
}

import { afterEach, describe, expect, it, vi } from "vitest";
import { JellyfinClient } from "./spiritflix-jellyfin-client";

const originalViewport = {
  devicePixelRatio: window.devicePixelRatio,
  innerHeight: window.innerHeight,
  innerWidth: window.innerWidth,
};

function setViewport(width: number, height: number, devicePixelRatio: number) {
  Object.defineProperty(window, "innerWidth", { configurable: true, writable: true, value: width });
  Object.defineProperty(window, "innerHeight", { configurable: true, writable: true, value: height });
  Object.defineProperty(window, "devicePixelRatio", { configurable: true, writable: true, value: devicePixelRatio });
}

describe("JellyfinClient playback URLs", () => {
  afterEach(() => {
    vi.restoreAllMocks();
    setViewport(originalViewport.innerWidth, originalViewport.innerHeight, originalViewport.devicePixelRatio);
  });

  it("uses same-origin stream and HLS proxies on HTTPS pages", () => {
    vi.spyOn(window, "location", "get").mockReturnValue({
      ...window.location,
      protocol: "https:",
      hostname: "100.111.32.31",
      href: "https://100.111.32.31:3000/spiritflix",
    } as Location);
    const client = new JellyfinClient("http://spirit.tailb69ea6.ts.net:8096", "token-1", "user-1");

    const streamUrl = new URL(client.getStreamUrl("item-1"), "https://100.111.32.31:3000/spiritflix");
    expect(streamUrl.pathname).toBe("/api/spiritflix/stream");
    expect(streamUrl.searchParams.get("serverUrl")).toBe("http://100.111.32.31:8096");
    expect(streamUrl.searchParams.get("itemId")).toBe("item-1");
    expect(streamUrl.searchParams.get("token")).toBe("token-1");

    const hlsUrl = new URL(client.getHlsUrl("item-1"), "https://100.111.32.31:3000/spiritflix");
    expect(hlsUrl.pathname).toBe("/api/spiritflix/hls");
    expect(hlsUrl.searchParams.get("serverUrl")).toBe("http://100.111.32.31:8096");
    expect(hlsUrl.searchParams.get("token")).toBe("token-1");
    expect(hlsUrl.searchParams.get("path")).toContain("/Videos/item-1/master.m3u8");
    expect(hlsUrl.searchParams.get("path")).toContain("VideoBitrate=4000000");
  });

  it("requests a higher HLS profile on unfolded high-density screens", () => {
    setViewport(842, 1030, 2.6);
    vi.spyOn(window, "location", "get").mockReturnValue({
      ...window.location,
      protocol: "https:",
      hostname: "100.111.32.31",
      href: "https://100.111.32.31:3000/spiritflix",
    } as Location);
    const client = new JellyfinClient("http://spirit.tailb69ea6.ts.net:8096", "token-1", "user-1");

    const hlsUrl = new URL(client.getHlsUrl("item-1"), "https://100.111.32.31:3000/spiritflix");
    const path = hlsUrl.searchParams.get("path");

    expect(path).toContain("VideoBitrate=10000000");
    expect(path).toContain("AudioBitrate=256000");
    expect(path).toContain("MaxWidth=1920");
    expect(path).toContain("MaxHeight=1080");
  });

  it("keeps narrow high-density phone screens on the baseline HLS profile", () => {
    setViewport(360, 800, 3);
    vi.spyOn(window, "location", "get").mockReturnValue({
      ...window.location,
      protocol: "https:",
      hostname: "100.111.32.31",
      href: "https://100.111.32.31:3000/spiritflix",
    } as Location);
    const client = new JellyfinClient("http://spirit.tailb69ea6.ts.net:8096", "token-1", "user-1");

    const hlsUrl = new URL(client.getHlsUrl("item-1"), "https://100.111.32.31:3000/spiritflix");
    const path = hlsUrl.searchParams.get("path");

    expect(path).toContain("VideoBitrate=4000000");
    expect(path).toContain("MaxWidth=1280");
    expect(path).toContain("MaxHeight=720");
  });

  it("keeps direct Jellyfin URLs on HTTP pages", () => {
    vi.spyOn(window, "location", "get").mockReturnValue({
      ...window.location,
      protocol: "http:",
      hostname: "100.111.32.31",
      href: "http://100.111.32.31:3000/spiritflix",
    } as Location);
    const client = new JellyfinClient("http://spirit.tailb69ea6.ts.net:8096", "token-1", "user-1");

    expect(client.getStreamUrl("item-1")).toContain("http://100.111.32.31:8096/Videos/item-1/Stream");
    expect(client.getHlsUrl("item-1")).toContain("http://100.111.32.31:8096/Videos/item-1/master.m3u8");
  });

  it("uses the LAN Jellyfin host when the app is opened from the LAN address", () => {
    vi.spyOn(window, "location", "get").mockReturnValue({
      ...window.location,
      protocol: "https:",
      hostname: "10.0.0.186",
      href: "https://10.0.0.186:3000/spiritflix",
    } as Location);
    const client = new JellyfinClient("http://spirit.tailb69ea6.ts.net:8096", "token-1", "user-1");

    const streamUrl = new URL(client.getStreamUrl("item-1"), "https://10.0.0.186:3000/spiritflix");
    const hlsUrl = new URL(client.getHlsUrl("item-1"), "https://10.0.0.186:3000/spiritflix");

    expect(streamUrl.searchParams.get("serverUrl")).toBe("http://10.0.0.186:8096");
    expect(hlsUrl.searchParams.get("serverUrl")).toBe("http://10.0.0.186:8096");
  });
});

import type {
  JellyfinAuthResponse,
  JellyfinItem,
  JellyfinItemsResponse,
  JellyfinLibrary,
  FaceOrganizerMetadataResponse,
  SpiritFlixGalleryResponse,
  SpiritFlixServerInfo,
  SpiritFlixSession,
} from "./spiritflix-types";

export const SPIRITFLIX_DEFAULT_SERVER = "http://spirit.tailb69ea6.ts.net:8096";
export const SPIRITFLIX_FALLBACK_SERVER = "http://100.111.32.31:8096";

const CLIENT_NAME = "SpiritFlix";
const CLIENT_VERSION = "0.1.0";
const DEVICE_NAME = "SpiritFlix Web";
const DEVICE_ID_KEY = "spiritflix_device_id";
const SESSION_KEY = "spiritflix_private_gooner_session";
const GOONER_ITEM_FIELDS =
  "Path,SeriesName,DateCreated,IndexNumber,ParentIndexNumber,Overview,ProductionYear,RunTimeTicks,Genres,People,UserData,PrimaryImageAspectRatio,MediaStreams,MediaSources,ChildCount";

export interface HlsPlaybackProfile {
  maxWidth: number;
  maxHeight: number;
  videoBitrate: number;
  audioBitrate: number;
}

export function getStoredSession(): SpiritFlixSession | null {
  if (typeof window === "undefined") return null;
  const raw = window.localStorage.getItem(SESSION_KEY);
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as SpiritFlixSession;
    if (!parsed.accessToken || !parsed.userId || !parsed.serverUrl) return null;
    return parsed;
  } catch {
    return null;
  }
}

export function storeSession(session: SpiritFlixSession): void {
  window.localStorage.setItem(SESSION_KEY, JSON.stringify(session));
}

export function clearStoredSession(): void {
  window.localStorage.removeItem(SESSION_KEY);
}

function getDeviceId(): string {
  if (typeof window === "undefined") return "spiritflix-server-render";
  const existing = window.localStorage.getItem(DEVICE_ID_KEY);
  if (existing) return existing;
  const generated =
    typeof crypto !== "undefined" && "randomUUID" in crypto
      ? `spiritflix-${crypto.randomUUID()}`
      : `spiritflix-${Math.random().toString(36).slice(2)}`;
  window.localStorage.setItem(DEVICE_ID_KEY, generated);
  return generated;
}

function authHeader(token?: string): string {
  const parts = [
    `MediaBrowser Client="${CLIENT_NAME}"`,
    `Device="${DEVICE_NAME}"`,
    `DeviceId="${getDeviceId()}"`,
    `Version="${CLIENT_VERSION}"`,
  ];
  if (token) parts.push(`Token="${token}"`);
  return parts.join(", ");
}

export function normalizeJellyfinServerUrl(serverUrl: string): string {
  const trimmed = serverUrl.trim().replace(/\/+$/, "");
  try {
    const parsed = new URL(trimmed);
    const path = parsed.pathname.replace(/\/+$/, "");
    if (!path || path === "/" || path === "/web" || path.startsWith("/web/")) {
      return parsed.origin;
    }
    return `${parsed.origin}${path}`;
  } catch {
    return trimmed;
  }
}

function toQuery(params: Record<string, string | number | boolean | undefined>): string {
  const query = new URLSearchParams();
  Object.entries(params).forEach(([key, value]) => {
    if (value !== undefined && value !== "") query.set(key, String(value));
  });
  return query.toString();
}

function isHttpsPage(): boolean {
  return typeof window !== "undefined" && window.location.protocol === "https:";
}

function getDirectServerUrl(serverUrl: string): string {
  return typeof window !== "undefined" && window.location.hostname && !["localhost", "127.0.0.1"].includes(window.location.hostname)
    ? `http://${window.location.hostname}:8096`
    : serverUrl;
}

export function getHlsPlaybackProfile(): HlsPlaybackProfile {
  const baseProfile: HlsPlaybackProfile = {
    maxWidth: 1280,
    maxHeight: 720,
    videoBitrate: 4000000,
    audioBitrate: 192000,
  };
  if (typeof window === "undefined") return baseProfile;

  const dpr = Math.max(1, Math.min(3, window.devicePixelRatio || 1));
  const cssLongEdge = Math.max(window.innerWidth || 0, window.innerHeight || 0);
  const cssShortEdge = Math.min(window.innerWidth || 0, window.innerHeight || 0);
  const longEdge = cssLongEdge * dpr;
  const shortEdge = cssShortEdge * dpr;

  if (cssShortEdge >= 720 && longEdge >= 1800 && shortEdge >= 900) {
    return {
      maxWidth: 1920,
      maxHeight: 1080,
      videoBitrate: 10000000,
      audioBitrate: 256000,
    };
  }

  if (cssShortEdge >= 600 && longEdge >= 1400 && shortEdge >= 760) {
    return {
      maxWidth: 1600,
      maxHeight: 900,
      videoBitrate: 6500000,
      audioBitrate: 224000,
    };
  }

  return baseProfile;
}

export class JellyfinClient {
  readonly serverUrl: string;
  readonly token?: string;
  readonly userId?: string;

  constructor(serverUrl: string, token?: string, userId?: string) {
    this.serverUrl = normalizeJellyfinServerUrl(serverUrl || SPIRITFLIX_DEFAULT_SERVER);
    this.token = token;
    this.userId = userId;
  }

  withSession(session: SpiritFlixSession): JellyfinClient {
    return new JellyfinClient(session.serverUrl, session.accessToken, session.userId);
  }

  private async request<T>(path: string, init: RequestInit = {}): Promise<T> {
    const method = init.method ?? "GET";
    const response = await fetch("/api/spiritflix/jellyfin", {
      method: "POST",
      keepalive: init.keepalive,
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        serverUrl: this.serverUrl,
        path,
        method,
        authorization: authHeader(this.token),
        body: init.body ? JSON.parse(String(init.body)) : undefined,
      }),
    });

    if (!response.ok) {
      if (response.status === 401) {
        throw new Error("Jellyfin rejected that username or password.");
      }
      if (response.status === 404) {
        throw new Error("That Jellyfin server URL did not expose the expected API path.");
      }
      if (response.status >= 500) {
        throw new Error(`Jellyfin server returned ${response.status}.`);
      }
      throw new Error(`Jellyfin request failed with status ${response.status}.`);
    }

    if (response.status === 204) return undefined as T;
    return (await response.json()) as T;
  }

  async checkPublicInfo(): Promise<SpiritFlixServerInfo> {
    return this.request<SpiritFlixServerInfo>("/System/Info/Public");
  }

  async login(username: string, password: string): Promise<SpiritFlixSession> {
    const data = await this.request<JellyfinAuthResponse>("/Users/AuthenticateByName", {
      method: "POST",
      body: JSON.stringify({ Username: username, Pw: password }),
    });

    return {
      serverUrl: this.serverUrl,
      accessToken: data.AccessToken,
      userId: data.User.Id,
      username: data.User.Name,
    };
  }

  async getLibraries(): Promise<JellyfinLibrary[]> {
    if (!this.userId) return [];
    const data = await this.request<JellyfinItemsResponse<JellyfinLibrary>>(
      `/Users/${this.userId}/Views`,
    );
    return data.Items ?? [];
  }

  async getLibraryItems(parentId: string, searchTerm = "", limit?: number): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      ParentId: parentId,
      Recursive: true,
      IncludeItemTypes: "Movie,Series,Season,Episode,Video,Folder",
      Fields: GOONER_ITEM_FIELDS,
      ImageTypeLimit: 1,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      SortBy: "SortName",
      SortOrder: "Ascending",
      SearchTerm: searchTerm,
      Limit: limit,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${query}`,
    );
    if (data.Items?.length || searchTerm) return data.Items ?? [];

    const fallbackQuery = toQuery({
      ParentId: parentId,
      Recursive: true,
      Fields: GOONER_ITEM_FIELDS,
      ImageTypeLimit: 1,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      SortBy: "SortName",
      SortOrder: "Ascending",
      Limit: limit,
    });
    const fallbackData = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${fallbackQuery}`,
    );
    return fallbackData.Items ?? [];
  }

  async getItem(itemId: string): Promise<JellyfinItem | null> {
    if (!this.userId || !itemId) return null;
    const query = toQuery({
      Fields: GOONER_ITEM_FIELDS,
      ImageTypeLimit: 3,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
    });
    return this.request<JellyfinItem>(
      `/Users/${this.userId}/Items/${encodeURIComponent(itemId)}?${query}`,
    );
  }

  async getPlaylistItems(playlistId: string): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      userId: this.userId,
      Fields: "Overview,ProductionYear,RunTimeTicks,Genres,UserData,PrimaryImageAspectRatio,MediaStreams,MediaSources",
      ImageTypeLimit: 1,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Playlists/${playlistId}/Items?${query}`,
    );
    return data.Items ?? [];
  }

  async getPlaylists(): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      Recursive: true,
      IncludeItemTypes: "Playlist",
      Fields: "Overview,ProductionYear,RunTimeTicks,Genres,UserData,PrimaryImageAspectRatio,MediaStreams,MediaSources,ChildCount",
      ImageTypeLimit: 1,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      SortBy: "SortName",
      SortOrder: "Ascending",
      Limit: 100,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${query}`,
    );
    return data.Items ?? [];
  }

  async getContinueWatching(parentId?: string): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      Recursive: true,
      ParentId: parentId,
      Fields: GOONER_ITEM_FIELDS,
      ImageTypeLimit: 3,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      Limit: 18,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items/Resume?${query}`,
    );
    return data.Items ?? [];
  }

  async getLibraryResumeItems(parentId: string): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      ParentId: parentId,
      Recursive: true,
      IncludeItemTypes: "Movie,Episode,Video",
      Fields: GOONER_ITEM_FIELDS,
      Filters: "IsResumable",
      ImageTypeLimit: 3,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      SortBy: "DatePlayed",
      SortOrder: "Descending",
      Limit: 24,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${query}`,
    );
    return data.Items ?? [];
  }

  async getWatchHistory(parentId?: string): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      ParentId: parentId,
      Recursive: true,
      IncludeItemTypes: "Movie,Episode,Video",
      Fields: GOONER_ITEM_FIELDS,
      Filters: "IsPlayed",
      ImageTypeLimit: 3,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      SortBy: "DatePlayed",
      SortOrder: "Descending",
      Limit: 60,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${query}`,
    );
    return data.Items ?? [];
  }

  async getLatestAdded(): Promise<JellyfinItem[]> {
    return this.getItemsByQuery({ SortBy: "DateCreated", SortOrder: "Descending", Limit: 18 });
  }

  async getFavorites(): Promise<JellyfinItem[]> {
    return this.getItemsByQuery({ Filters: "IsFavorite", SortBy: "SortName", Limit: 200 });
  }

  async getLibraryFavoriteItems(parentId: string): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      ParentId: parentId,
      Recursive: true,
      IncludeItemTypes: "Movie,Episode,Video",
      Fields: GOONER_ITEM_FIELDS,
      Filters: "IsFavorite",
      ImageTypeLimit: 3,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      SortBy: "SortName",
      SortOrder: "Ascending",
      Limit: 200,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${query}`,
    );
    return data.Items ?? [];
  }

  async setFavorite(itemId: string, isFavorite: boolean): Promise<void> {
    if (!this.userId) return;
    await this.request<void>(`/Users/${this.userId}/FavoriteItems/${itemId}`, {
      method: isFavorite ? "POST" : "DELETE",
    });
  }

  async getFaceOrganizerMetadata(items: JellyfinItem[]): Promise<FaceOrganizerMetadataResponse> {
    if (!items.length) {
      return {
        knownPerformers: [],
        videos: {},
        scannedCount: 0,
        generatedAt: new Date().toISOString(),
      };
    }

    const response = await fetch("/api/spiritflix/face-metadata", {
      method: "POST",
      cache: "no-store",
      headers: {
        Accept: "application/json",
        "Content-Type": "application/json",
        "Cache-Control": "no-cache",
      },
      body: JSON.stringify({
        items: items.map((item) => ({
          id: item.Id,
          name: item.Name,
          path: item.Path,
        })),
      }),
    });

    if (!response.ok) {
      throw new Error("Face Organizer metadata is unavailable.");
    }

    return (await response.json()) as FaceOrganizerMetadataResponse;
  }

  async getGallery(): Promise<SpiritFlixGalleryResponse> {
    const response = await fetch("/api/spiritflix/gallery", {
      method: "GET",
      cache: "no-store",
      headers: {
        Accept: "application/json",
        "Cache-Control": "no-cache",
      },
    });

    if (!response.ok) {
      throw new Error("SpiritFlix gallery is unavailable.");
    }

    return (await response.json()) as SpiritFlixGalleryResponse;
  }

  private async getItemsByQuery(extra: Record<string, string | number>): Promise<JellyfinItem[]> {
    if (!this.userId) return [];
    const query = toQuery({
      Recursive: true,
      IncludeItemTypes: "Movie,Episode,Video",
      Fields: GOONER_ITEM_FIELDS,
      ImageTypeLimit: 3,
      EnableImageTypes: "Primary,Backdrop,Thumb,Logo",
      Limit: 18,
      ...extra,
    });
    const data = await this.request<JellyfinItemsResponse<JellyfinItem>>(
      `/Users/${this.userId}/Items?${query}`,
    );
    return data.Items ?? [];
  }

  getImageUrl(item: JellyfinItem, type: "Primary" | "Backdrop" | "Thumb" = "Primary", width = 500): string {
    const tag =
      type === "Backdrop"
        ? item.BackdropImageTags?.[0]
        : item.ImageTags?.[type as keyof JellyfinItem["ImageTags"]];
    const query = toQuery({
      maxWidth: width,
      quality: 88,
      tag,
    });
    return `${this.serverUrl}/Items/${item.Id}/Images/${type}?${query}`;
  }

  async getImageObjectUrl(item: JellyfinItem, type: "Primary" | "Backdrop" | "Thumb" = "Primary", width = 500): Promise<string> {
    const response = await fetch("/api/spiritflix/jellyfin-image", {
      method: "POST",
      headers: {
        Accept: "image/*",
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        serverUrl: this.serverUrl,
        path: new URL(this.getImageUrl(item, type, width)).pathname + new URL(this.getImageUrl(item, type, width)).search,
        authorization: authHeader(this.token),
      }),
    });
    if (!response.ok) throw new Error("Image unavailable");
    return URL.createObjectURL(await response.blob());
  }

  getStreamUrl(itemId: string): string {
    const directServerUrl = getDirectServerUrl(this.serverUrl);
    const query = toQuery({
      serverUrl: directServerUrl,
      itemId,
      token: this.token,
    });
    if (isHttpsPage()) return `/api/spiritflix/stream?${query}`;

    const directQuery = toQuery({
      Static: "true",
      api_key: this.token,
      PlaySessionId: `spiritflix-${itemId}`,
    });
    return `${directServerUrl}/Videos/${encodeURIComponent(itemId)}/Stream?${directQuery}`;
  }

  getHlsUrl(itemId: string): string {
    const directServerUrl = getDirectServerUrl(this.serverUrl);
    const playbackProfile = getHlsPlaybackProfile();
    const query = toQuery({
      api_key: this.token,
      PlaySessionId: `spiritflix-${itemId}`,
      MediaSourceId: itemId,
      VideoCodec: "h264",
      AudioCodec: "aac,mp3,ac3",
      SegmentContainer: "ts",
      MinSegments: 1,
      VideoBitrate: playbackProfile.videoBitrate,
      AudioBitrate: playbackProfile.audioBitrate,
      MaxWidth: playbackProfile.maxWidth,
      MaxHeight: playbackProfile.maxHeight,
    });
    const path = `/Videos/${encodeURIComponent(itemId)}/master.m3u8?${query}`;
    if (isHttpsPage()) {
      const proxyQuery = toQuery({
        serverUrl: directServerUrl,
        token: this.token,
        path,
      });
      return `/api/spiritflix/hls?${proxyQuery}`;
    }
    return `${directServerUrl}${path}`;
  }

  async reportPlayback(
    itemId: string,
    event: "Start" | "Progress" | "Stopped",
    positionTicks: number,
    isPaused = false,
    options: { keepalive?: boolean } = {},
  ): Promise<void> {
    if (!this.token) return;
    const path =
      event === "Start"
        ? "/Sessions/Playing"
        : event === "Progress"
          ? "/Sessions/Playing/Progress"
          : "/Sessions/Playing/Stopped";
    const playSessionId = `spiritflix-${itemId}`;

    await this.request<void>(path, {
      method: "POST",
      keepalive: options.keepalive,
      body: JSON.stringify({
        ItemId: itemId,
        MediaSourceId: itemId,
        PlaySessionId: playSessionId,
        PositionTicks: positionTicks,
        IsPaused: isPaused,
        PlayMethod: "DirectStream",
        CanSeek: true,
      }),
    }).catch(() => undefined);
  }
}

export function isPlayableItem(item: JellyfinItem): boolean {
  return item.MediaType === "Video" || ["Movie", "Episode", "Video"].includes(item.Type);
}

export function isPlaylistItem(item: JellyfinItem): boolean {
  return item.Type === "Playlist";
}

export function ticksToSeconds(ticks?: number): number {
  return ticks ? Math.max(0, Math.floor(ticks / 10000000)) : 0;
}

export function formatRuntime(ticks?: number): string {
  const totalMinutes = Math.round(ticksToSeconds(ticks) / 60);
  if (!totalMinutes) return "Unknown runtime";
  const hours = Math.floor(totalMinutes / 60);
  const minutes = totalMinutes % 60;
  return hours ? `${hours}h ${minutes}m` : `${minutes}m`;
}

import type { JellyfinItem } from "./spiritflix-types";
import { ticksToSeconds } from "./spiritflix-jellyfin-client";

export function formatResumeTime(seconds: number): string {
  if (!Number.isFinite(seconds)) return "0:00";
  const whole = Math.max(0, Math.floor(seconds));
  const hours = Math.floor(whole / 3600);
  const minutes = Math.floor((whole % 3600) / 60);
  const rest = whole % 60;
  return hours
    ? `${hours}:${String(minutes).padStart(2, "0")}:${String(rest).padStart(2, "0")}`
    : `${minutes}:${String(rest).padStart(2, "0")}`;
}

export function getResumePositionTicks(item: JellyfinItem): number {
  return Math.max(0, item.UserData?.PlaybackPositionTicks ?? 0);
}

export function getResumeProgressPercent(item: JellyfinItem): number {
  const positionTicks = getResumePositionTicks(item);
  const runtimeTicks = item.RunTimeTicks ?? 0;
  if (item.UserData?.PlayedPercentage && item.UserData.PlayedPercentage > 0) {
    return Math.max(0, Math.min(100, item.UserData.PlayedPercentage));
  }
  if (!positionTicks || !runtimeTicks) return 0;
  return Math.max(0, Math.min(100, (positionTicks / runtimeTicks) * 100));
}

export function hasResumeProgress(item: JellyfinItem): boolean {
  const positionSeconds = ticksToSeconds(getResumePositionTicks(item));
  const durationSeconds = ticksToSeconds(item.RunTimeTicks);
  if (item.UserData?.Played) return false;
  if (positionSeconds <= 0) return false;
  if (durationSeconds > 0 && positionSeconds >= durationSeconds - 20) return false;
  return true;
}

export function getResumeSlotLabel(item: JellyfinItem): string {
  const positionSeconds = ticksToSeconds(getResumePositionTicks(item));
  const durationSeconds = ticksToSeconds(item.RunTimeTicks);
  if (durationSeconds > 0) {
    return `${formatResumeTime(positionSeconds)} / ${formatResumeTime(durationSeconds)}`;
  }
  return `Resume from ${formatResumeTime(positionSeconds)}`;
}

export function getTimeLeftLabel(item: JellyfinItem): string {
  const positionSeconds = ticksToSeconds(getResumePositionTicks(item));
  const durationSeconds = ticksToSeconds(item.RunTimeTicks);
  if (!durationSeconds || durationSeconds <= positionSeconds) return "";
  const minutesLeft = Math.max(1, Math.ceil((durationSeconds - positionSeconds) / 60));
  return `${minutesLeft}m left`;
}

