    string,
    {
      name: string;
      slug?: string;
      candidateVideos: number;
      enrolledScreens?: number;
      recommendationSourceVideos?: string[];
      refreshedAt?: string;
      source?: "enrolled" | "model_index";
    }
  >;
  videos: Record<string, FaceOrganizerVideoMatch>;
  scannedCount: number;
  generatedAt: string;
}

