.spiritflix-shell {
  --sf-bg: #05050a;
  --sf-panel: rgba(14, 14, 24, 0.72);
  --sf-border: rgba(255, 255, 255, 0.12);
  --sf-purple: #8b5cf6;
  --sf-pink: #ff3d8b;
  --sf-cyan: #22d3ee;
  --sf-text: #f8fafc;
  --sf-muted: rgba(226, 232, 240, 0.68);
  min-height: 100dvh;
  overflow-x: hidden;
  background:
    radial-gradient(circle at 18% 10%, rgba(139, 92, 246, 0.18), transparent 30rem),
    radial-gradient(circle at 88% 18%, rgba(34, 211, 238, 0.14), transparent 26rem),
    radial-gradient(circle at 64% 84%, rgba(255, 61, 139, 0.12), transparent 30rem),
    linear-gradient(180deg, #090912 0%, var(--sf-bg) 48%, #020204 100%);
  color: var(--sf-text);
  font-family: var(--font-inter), ui-sans-serif, system-ui, sans-serif;
}

.spiritflix-shell *,
.spiritflix-shell *::before,
.spiritflix-shell *::after {
  box-sizing: border-box;
}

.spiritflix-shell button,
.spiritflix-shell input {
  font: inherit;
}

.spiritflix-shell button {
  transition: transform 160ms ease, border-color 160ms ease, background 160ms ease, color 160ms ease, box-shadow 160ms ease;
}

.spiritflix-shell button:hover {
  transform: translateY(-1px);
}

