  opacity: 0.28;
  filter: blur(34px) saturate(1.25);
  transform: scale(1.08);
}

.spiritflix-hero__image {
  z-index: -2;
  width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0.62;
  filter: brightness(0.82) contrast(1.04) saturate(1.06);
}

.spiritflix-hero__shade {
  z-index: -1;
  background:
    linear-gradient(90deg, rgba(5, 5, 10, 0.96) 0%, rgba(5, 5, 10, 0.62) 42%, rgba(5, 5, 10, 0.18) 76%),
    linear-gradient(0deg, var(--sf-bg) 0%, rgba(5, 5, 10, 0.46) 22%, rgba(5, 5, 10, 0.1) 58%),
    radial-gradient(circle at 24% 52%, rgba(139, 92, 246, 0.2), transparent 24rem);
}

.spiritflix-hero__content {
