  overflow: hidden;
  border: 1px solid rgba(139, 92, 246, 0.34);
  border-radius: 999px;
  padding: 0.42rem 0.72rem;
  background: rgba(139, 92, 246, 0.12);
  color: #c4b5fd;
  font-size: 0.72rem;
  font-weight: 850;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.spiritflix-hero h1 {
  display: -webkit-box;
  max-width: 13ch;
  margin: 0.85rem 0 0.55rem;
  overflow: hidden;
