  -webkit-line-clamp: 2;
  font-size: clamp(2.5rem, 6.6vw, 5.5rem);
  line-height: 0.98;
  letter-spacing: 0;
  text-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.72);
}

.spiritflix-hero__meta {
  color: rgba(226, 232, 240, 0.82);
  font-size: 0.9rem;
  font-weight: 750;
}

.spiritflix-hero p {
