  max-width: 44rem;
  margin: 0.85rem 0 0;
  overflow: hidden;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 3;
  color: rgba(248, 250, 252, 0.78);
  line-height: 1.62;
}

.spiritflix-hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 1.35rem;
}

.spiritflix-rail__track::-webkit-scrollbar {
  display: none;
}

.spiritflix-rows {
  position: relative;
  z-index: 2;
  display: grid;
  gap: 2rem;
  margin-top: -4.25rem;
  padding: 0 clamp(1rem, 5vw, 4rem);
}

.spiritflix-rail {
  min-width: 0;
}

.spiritflix-rail__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 0.75rem;
}

.spiritflix-rail h2 {
  margin: 0;
  color: #fff;
  font-size: clamp(1rem, 2vw, 1.2rem);
  letter-spacing: 0;
}

.spiritflix-rail__controls {
  display: flex;
  gap: 0.35rem;
  opacity: 0.72;
}

.spiritflix-rail__controls button {
  min-width: 2rem;
  min-height: 2rem;
}

.spiritflix-rail__track {
  display: grid;
  grid-auto-flow: column;
  gap: 0.95rem;
  overflow-x: auto;
  overflow-y: visible;
  padding: 0.25rem 0.2rem 0.9rem;
  scroll-snap-type: x proximity;
  scrollbar-width: none;
}

.spiritflix-rail--poster .spiritflix-rail__track {
  grid-auto-columns: clamp(9rem, 15vw, 12.5rem);
}

.spiritflix-rail--landscape .spiritflix-rail__track {
  grid-auto-columns: clamp(13.5rem, 25vw, 22rem);
}

.spiritflix-card {
  min-width: 0;
  scroll-snap-align: start;
}

.spiritflix-card__poster {
  position: relative;
  display: block;
  width: 100%;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.095);
  border-radius: 0.65rem;
  background: #11111b;
  box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.24);
}

.spiritflix-card--poster .spiritflix-card__poster {
  aspect-ratio: 2 / 3;
}

.spiritflix-card--landscape .spiritflix-card__poster {
  aspect-ratio: 16 / 9;
}

.spiritflix-card__poster:hover {
  border-color: rgba(139, 92, 246, 0.5);
  box-shadow: 0 1rem 2.6rem rgba(0, 0, 0, 0.34), 0 0 2rem rgba(139, 92, 246, 0.18);
}

.spiritflix-card__poster img,
.spiritflix-image-fallback {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.spiritflix-card__poster img {
  transition: transform 220ms ease, filter 220ms ease;
}

.spiritflix-card:hover .spiritflix-card__poster img {
  transform: scale(1.045);
  filter: saturate(1.08) brightness(1.05);
}

.spiritflix-card__veil {
  position: absolute;
