  color: rgba(248, 250, 252, 0.82);
  font-size: clamp(2rem, 7vw, 4rem);
  font-weight: 900;
}

.spiritflix-card__progress {
  position: absolute;
  left: 0.45rem;
  right: 0.45rem;
  bottom: 0.5rem;
  height: 0.2rem;
