  border-radius: 999px;
  padding: 0 0.55rem;
  background: rgba(0, 0, 0, 0.64);
  color: #fff;
  font-size: 0.72rem;
  font-weight: 900;
  backdrop-filter: blur(12px);
}

.spiritflix-card__face-badge {
