  font-weight: 750;
}

.spiritflix-resume-section {
  display: grid;
  gap: 0.65rem;
  min-width: 0;
}

.spiritflix-resume-section__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.8rem;
  min-width: 0;
}

