.spiritflix-player {
  --spiritflix-fill-scale: 1.12;
  --spiritflix-video-aspect: 1.777778;
  display: grid;
  width: 100vw;
  min-height: 100dvh;
  overflow: hidden;
  background:
    radial-gradient(circle at 24% 18%, rgba(139, 92, 246, 0.2), transparent 34rem),
    radial-gradient(circle at 78% 80%, rgba(34, 211, 238, 0.12), transparent 30rem),
    #000;
  touch-action: none;
  user-select: none;
}

.spiritflix-player__stage {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  overflow: hidden;
  touch-action: none;
}

.spiritflix-player video {
  width: 100%;
  height: 100%;
  max-width: 100%;
  max-height: 100%;
  object-position: center;
  background: #000;
  touch-action: none;
  transition: transform 180ms ease, opacity 180ms ease;
}

.spiritflix-player.is-fit-fit video {
  width: min(100vw, calc(100dvh * var(--spiritflix-video-aspect)));
  height: min(100dvh, calc(100vw / var(--spiritflix-video-aspect)));
  aspect-ratio: var(--spiritflix-video-aspect);
  object-fit: contain;
  transform: none;
}

.spiritflix-player.is-fit-fill video {
  width: min(100vw, calc(100dvh * var(--spiritflix-video-aspect)));
  height: min(100dvh, calc(100vw / var(--spiritflix-video-aspect)));
  aspect-ratio: var(--spiritflix-video-aspect);
  object-fit: contain;
  transform: scale(var(--spiritflix-fill-scale));
}

.spiritflix-player__top,
.spiritflix-player__controls {
  position: absolute;
  left: 0;
  right: 0;
  z-index: 2;
  opacity: 0;
  pointer-events: none;
  transition: opacity 160ms ease, transform 160ms ease;
}

.spiritflix-player.is-awake .spiritflix-player__top,
.spiritflix-player.is-awake .spiritflix-player__controls,
.spiritflix-player:focus-within .spiritflix-player__top,
.spiritflix-player:focus-within .spiritflix-player__controls {
  opacity: 1;
  pointer-events: auto;
}

.spiritflix-player__top {
  top: 0;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.75rem;
  padding: max(0.9rem, env(safe-area-inset-top)) max(0.9rem, env(safe-area-inset-right)) 3.2rem max(0.9rem, env(safe-area-inset-left));
  background: linear-gradient(180deg, rgba(0, 0, 0, 0.82), rgba(0, 0, 0, 0));
}

.spiritflix-player__title {
  display: grid;
