}

.spiritflix-player__controls {
  bottom: 0;
  display: grid;
  gap: 0.7rem;
  padding: 4rem max(0.9rem, env(safe-area-inset-right)) max(0.95rem, env(safe-area-inset-bottom)) max(0.9rem, env(safe-area-inset-left));
  background: linear-gradient(0deg, rgba(0, 0, 0, 0.9), rgba(0, 0, 0, 0.54) 48%, rgba(0, 0, 0, 0));
  transform: translateY(0.5rem);
}

.spiritflix-player.is-awake .spiritflix-player__controls,
.spiritflix-player:focus-within .spiritflix-player__controls {
  transform: translateY(0);
}

.spiritflix-player.is-controls-hidden .spiritflix-player__top,
.spiritflix-player.is-controls-hidden .spiritflix-player__controls,
.spiritflix-player.is-controls-hidden:focus-within .spiritflix-player__top,
.spiritflix-player.is-controls-hidden:focus-within .spiritflix-player__controls {
