.spiritflix-player__diagnostics dt,
.spiritflix-player__diagnostics dd {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.spiritflix-player__diagnostics dt {
  color: rgba(203, 213, 225, 0.72);
  font-size: 0.68rem;
  font-weight: 850;
  text-transform: uppercase;
}

.spiritflix-player__diagnostics dd {
  margin-top: 0.12rem;
  color: #fff;
  font-size: 0.84rem;
  font-weight: 850;
}

.spiritflix-player__scrub-row,
.spiritflix-player__button-row,
.spiritflix-player__transport,
.spiritflix-player__tools,
.spiritflix-player__volume,
.spiritflix-player__up-next,
.spiritflix-player__error div,
.spiritflix-player__ended div {
  display: flex;
  align-items: center;
}

.spiritflix-player__scrub-row {
  gap: 0.7rem;
}

.spiritflix-player__button-row {
  justify-content: space-between;
  gap: 0.8rem;
  min-width: 0;
}

.spiritflix-player__transport,
.spiritflix-player__tools {
  gap: 0.55rem;
  min-width: 0;
}

.spiritflix-player__transport {
  flex: 0 0 auto;
}

.spiritflix-player__tools {
  flex: 1 1 auto;
  justify-content: flex-end;
}

.spiritflix-player__button-row button {
  flex: 0 0 auto;
}

.spiritflix-player button.is-active {
  border-color: rgba(167, 139, 250, 0.62);
  background: rgba(139, 92, 246, 0.28);
  color: #fff;
  box-shadow: 0 0 1.2rem rgba(139, 92, 246, 0.22);
}

.spiritflix-player__play {
  min-width: 3.5rem;
  min-height: 3.5rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.95) !important;
  color: #070710 !important;
  box-shadow: 0 0 2rem rgba(34, 211, 238, 0.22);
}

.spiritflix-player__scrub,
.spiritflix-player__volume input {
  flex: 1;
  min-width: 5rem;
  accent-color: var(--sf-purple);
}

.spiritflix-player__scrub {
  min-width: 0;
}

.spiritflix-player__volume {
  gap: 0.45rem;
  min-width: 8rem;
}

.spiritflix-player__volume input {
  width: 5.5rem;
  min-width: 4rem;
  touch-action: pan-x;
}

.spiritflix-player button:disabled {
  cursor: default;
  opacity: 0.42;
}

.spiritflix-player button span {
  font-size: 0.72rem;
  font-weight: 850;
}

.spiritflix-player__time {
  min-width: 3.3rem;
  color: rgba(248, 250, 252, 0.82);
  font-variant-numeric: tabular-nums;
  font-size: 0.82rem;
}

.spiritflix-player__up-next {
  gap: 0.55rem;
  min-width: 0;
  color: #fff;
}

.spiritflix-player__up-next strong {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.spiritflix-player__queue {
  position: absolute;
  top: max(0.75rem, env(safe-area-inset-top));
  right: max(0.75rem, env(safe-area-inset-right));
  bottom: max(0.75rem, env(safe-area-inset-bottom));
  z-index: 4;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  width: min(24rem, calc(100vw - 1.5rem));
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 0.7rem;
  background: rgba(5, 7, 13, 0.9);
  box-shadow: 0 1.5rem 5rem rgba(0, 0, 0, 0.58);
  backdrop-filter: blur(22px);
}

.spiritflix-player__queue-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  padding: 0.8rem;
}

.spiritflix-player__queue-header div {
  display: grid;
  min-width: 0;
  gap: 0.15rem;
}

.spiritflix-player__queue-header span {
  overflow: hidden;
  color: rgba(226, 232, 240, 0.68);
  font-size: 0.75rem;
  font-weight: 800;
  text-overflow: ellipsis;
  text-transform: uppercase;
  white-space: nowrap;
}

.spiritflix-player__queue-header strong {
  color: #fff;
  font-size: 1rem;
}

.spiritflix-player__queue-header button {
  width: 2.4rem;
  min-width: 2.4rem;
  height: 2.4rem;
  min-height: 2.4rem;
}

.spiritflix-player__queue-list {
  display: grid;
  align-content: start;
  gap: 0.35rem;
  overflow-y: auto;
  padding: 0.6rem;
}

.spiritflix-player__queue-list button {
  display: grid;
  grid-template-columns: 2.2rem minmax(0, 1fr);
  align-items: center;
  gap: 0.55rem;
  width: 100%;
  min-height: 3.1rem;
  border-radius: 0.5rem;
  background: rgba(255, 255, 255, 0.055);
  text-align: left;
}

.spiritflix-player__queue-list button.is-current {
  border-color: rgba(34, 211, 238, 0.55);
  background: rgba(34, 211, 238, 0.16);
  box-shadow: 0 0 1.4rem rgba(34, 211, 238, 0.14);
}

.spiritflix-player__queue-list span {
  color: rgba(226, 232, 240, 0.54);
  font-size: 0.74rem;
  font-weight: 900;
  text-align: center;
}

.spiritflix-player__queue-list strong {
  min-width: 0;
  overflow: hidden;
  color: #fff;
  font-size: 0.86rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.spiritflix-player__loading,
.spiritflix-player__tap-feedback,
.spiritflix-player__error,
.spiritflix-player__ended {
  position: absolute;
  left: 50%;
  top: 50%;
  z-index: 3;
  transform: translate(-50%, -50%);
}

.spiritflix-player__tap-feedback {
  display: grid;
  grid-auto-flow: column;
  gap: 0.55rem;
  width: 6.8rem;
  height: 6.8rem;
  align-items: center;
  place-items: center;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.48);
  color: #fff;
  pointer-events: none;
  animation: spiritflix-tap-feedback 850ms ease forwards;
  backdrop-filter: blur(14px);
  box-shadow: 0 1rem 3rem rgba(0, 0, 0, 0.38), 0 0 2rem rgba(255, 255, 255, 0.12);
}

.spiritflix-player__tap-feedback.is-seek-back,
.spiritflix-player__tap-feedback.is-seek-forward {
  width: auto;
  min-width: 6.7rem;
  height: 4.8rem;
  padding: 0 1.05rem;
  background: rgba(2, 6, 23, 0.62);
}

.spiritflix-player__tap-feedback.is-seek-back {
  left: 29%;
}

.spiritflix-player__tap-feedback.is-seek-forward {
  left: 71%;
}

.spiritflix-player__tap-feedback strong {
  color: #fff;
  font-size: 1.05rem;
  font-weight: 900;
  letter-spacing: 0;
}

.spiritflix-player__loading {
  display: grid;
  width: 5rem;
  height: 5rem;
  place-items: center;
  border-radius: 999px;
  background: rgba(0, 0, 0, 0.36);
  backdrop-filter: blur(12px);
}

.spiritflix-player__loading span {
  width: 2.3rem;
  height: 2.3rem;
  border: 3px solid rgba(255, 255, 255, 0.25);
  border-top-color: #22d3ee;
  border-radius: 999px;
  animation: spiritflix-spin 820ms linear infinite;
}

.spiritflix-player__error,
.spiritflix-player__ended {
  width: min(90vw, 32rem);
  border: 1px solid rgba(251, 113, 133, 0.3);
  border-radius: 0.75rem;
  padding: 1.1rem;
  background: rgba(10, 10, 18, 0.9);
  color: #fff;
  text-align: center;
  backdrop-filter: blur(18px);
  box-shadow: 0 1.5rem 5rem rgba(0, 0, 0, 0.5);
}

.spiritflix-player__error p {
  margin: 0.45rem 0 0.9rem;
  color: rgba(254, 205, 211, 0.9);
}

.spiritflix-player__error div,
.spiritflix-player__ended div {
  justify-content: center;
  gap: 0.65rem;
}

.spiritflix-player__ended {
  border-color: rgba(34, 211, 238, 0.28);
}

@keyframes spiritflix-spin {
  to {
    transform: rotate(360deg);
  }
}

@keyframes spiritflix-tap-feedback {
  0% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(0.82);
  }

  18% {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }

  64% {
    opacity: 0.92;
    transform: translate(-50%, -50%) scale(1);
  }

  100% {
    opacity: 0;
    transform: translate(-50%, -50%) scale(1.08);
  }
}

