.spiritflix-admin-shell {
  display: grid;
  grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr);
  gap: 0;
  min-height: 100dvh;
  background: linear-gradient(180deg, #08090d 0%, #0d0f14 100%);
}

.spiritflix-admin-shell.has-details {
  grid-template-columns: minmax(12rem, 16rem) minmax(0, 1fr) minmax(18rem, 24rem);
}

.spiritflix-admin-sidebar,
.spiritflix-admin-details {
  min-width: 0;
  border-color: rgba(255, 255, 255, 0.1);
  background: rgba(8, 9, 13, 0.86);
}

.spiritflix-admin-sidebar {
  display: flex;
  flex-direction: column;
  gap: 1rem;
